അബ്ദുല്ലാഹിബ്നു സ്വാമിത്(റ) പറയുന്നു: ഇക്കാര്യം ഞാൻ ഹകമുബ്നു അംറുൽ ഗിഫാരി(റ)വിന്റെ സഹേദരനായ റാഫിഉബ്നു അംറ്(റ)വിനോട് പറഞ്ഞു. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാനും അത് റസൂൽ(സ)യിൽനിന്ന് കേട്ടിട്ടുണ്ട്. (മു,ജ)', 'عَبْدِ الله بْنِ الصَّامت، عَنْ أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 805, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
