قَالَ عَبْدُ الله بْنُ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا: مَا غَبَطْتُ نَفْسِي بِمَجْلِسٍ تَخَلَّفْتُ فِيه عَنْ رَسُول الله صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ مَا غَبَطْتُ نَفْسِي بِذَلِكَ الْمَجْلِسِ وَتَخَلُّفِي عَنْهُ. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തന്റെ അനുചരന്മാർ ഖദ്‌റിന്റെ കാര്യത്തിൽ തർക്കിച്ചു കൊണ്ടിരിക്കുമ്പോൾ റസൂൽ(സ) പുറത്തേക്കു വന്നു. ദേഷ്യം കാരണത്താൽ അവിടുത്തെ മുഖം റുമ്മാൻ പഴത്തിന്റെ കുരു പൊട്ടിച്ചതു പോലെ ചുവന്നിരുന്നു. റസൂൽ(സ) പറഞ്ഞു: "ഇതാണോ നിങ്ങളോട് കൽപിക്കപ്പെട്ടത്, ഇതിനു വേണ്ടിയാണോ നിങ്ങൾ സൃഷ്ടക്കപ്പെട്ടത്? ഖുർആനിലെ ചില ഭാഗത്തെ മറ്റൊരു ഭാഗത്തിനെതിരെയുള്ള തെളിവായി നിങ്ങൾ കൊണ്ടുവരുന്നുവോ, ഇതു കാരണത്താലാണ് നിങ്ങൾക്കു മുമ്പുള്ള സമുദായങ്ങൾ നശിച്ചത്." അബ്ദുല്ലാഹിബ്നു അംറ്(റ) പറയുന്നു: ആ സദസ്സിൽ പങ്കെടുക്കാതിരുന്നത് കാരണത്താൽ ഞാൻ ആനന്ദം കൊണ്ടതുപോലെ നബി(സ)യുടെ മറ്റൊരു സദസ്സിലും പങ്കെടുക്കാത്തത് കാരണത്താൽ ഞാൻ ആനന്ദം കൊണ്ടിട്ടില്ല. (ജ)', 'عَبْد الله عَمْرو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 831, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
