insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "افْتَرَقَتِ الْيَهُودُ عَلَى - إِحْدَى أَوْ - ثِنْتَيْنِ وَسَبْعِينَ فِرْقَةً، وَتَفَرَّقَتِ النَّصَارَى عَلَى - إِحْدَى أَوْ - ثِنْتَيْنِ وَسَبْعِينَ فِرْقَةً، وَتَفْتَرِقُ أُمَّتِي عَلَى ثَلَاثٍ وَسَبْعِينَ فِرْقَةً". (د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജൂതർ എഴുപത്തി ഒന്നോ - രണ്ടോ - വിഭാഗമായി പിരിഞ്ഞു. ക്രിസ്ത്യാനികൾ എഴുപത്തി ഒന്നോ - രണ്ടോ - വിഭാഗമായി പിരിഞ്ഞു. എന്റെ സമുദായം എഴുപത്തി മൂന്ന് വിഭാഗമായി പിരിയും." (ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 781, 781, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ مُعَاوِيَةَ بْنِ أَبِي سُفْيَانَ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ قَالَ: أَلَا إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فِينَا فَقَالَ: "أَلَا، إِنَّ مَنْ قَبْلَكُمْ مِنْ أَهْلِ الْكِتَابِ افْتَرَقُوا عَلَى ثِنْتَيْنِ وَسَبْعِينَ مِلَّةً، وَإِنَّ هَذِهِ الْمِلَّةَ سَتَفْتَرِقُ عَلَى ثَلَاثٍ وَسَبْعِينَ: ثِنْتَانِ وَسَبْعُونَ فِي النَّارِ، وَوَاحِدَةٌ فِي الْجَنَّةِ، وَهِيَ الْجَمَاعَةُ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=2), 1, 'وَفِي رِوَايَةٍ: "وَإِنَّهُ سَيَخْرُجُ مِنْ أُمَّتِي أَقْوَامٌ تَجَارَى بِهِمْ تِلْكَ الْأَهْوَاءُ كَمَا يَتَجَارَى الْكَلْبُ لِصَاحِبِهِ -', 'മറ്റൊരു നിവേദനം: "പേരോഗം ബാധിച്ചവന്, തന്റെ മുഴുവൻ ഞെരമ്പിലേക്കും കെണിപ്പിലേക്കും എത്ര വേഗത്തിലാണോ ആ രോഗം ബാധിക്കുന്നത് അത്രയും വേഗത്തിൽ ഈ ആഗ്രഹങ്ങൾ (ഐഹികമായ ആഗ്രഹങ്ങൾ) ഉള്ളിൽ പ്രവേശിക്കുന്ന ചിലയാളുകൾ എന്റെ സമുദായത്തിൽനിന്ന് വരും." (ദ)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=2), 2, 'وَفِي رِوَايَةٍ: الْكَلْبُ بِصَاحِبِهِ - لَا يَبْقَى مِنْهُ عِرْقٌ وَلَا مَفْصِلٌ إِلَّا دَخَلَهُ". (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "أَلَا إِنِّي أُوتِيتُ الْكِتَابَ وَمِثْلَهُ مَعَهُ، أَلَا يُوشِكُ رَجُلٌ شَبْعَانُ عَلَى أَرِيكَتِه يَقُولُ: عَلَيْكُمْ بِهَذَا الْقُرْآنِ، فَمَا وَجَدْتُمْ فِيهِ مِنْ حَلَال فَأَحِلُّوهُ، وَمَا وَجَدْتُمْ فِيهِ مِنْ حَرَامٍ فَحَرِّمُوهُ، أَلَا لَا يَحِلُّ لَكُمْ لَحْمُ الْحِمَارِ الْأَهْلِيِّ، وَلَا كُلُّ ذِي نَابٍ مِنَ السَّبُعِ، وَلَا لُقَطَةُ مُعَاهِد إِلَّا أَنْ يَسْتَغْنِيَ عَنْهَا صَاحِبُهَا. وَمَنْ نَزَلَ بِقَوْمٍ فَعَلَيْهِمْ أَنْ يَقْرُوهُ، فَإِنْ لَمْ يَقْرُوهُ فَلَهُ أَنْ يُعْقِبَهُمْ بِمِثْلِ قِرَاهُ". (د,ت,جه)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അറിയുക, എനിക്ക് ഗ്രന്ഥവും അതോടൊപ്പം അതുപോലെയുള്ള മറ്റൊന്നും നൽകപ്പെട്ടു. അറിയുക, വയറ് നിറച്ച വ്യക്തി തന്റെ കട്ടിലിന് മുകളിലിരുന്ന് ''നിങ്ങൾ ഈ ഖുർആനെ മുറുകെപ്പിടിക്കുക, അവയിൽ നിങ്ങൾ കാണുന്ന അനുവദനീയമായ കാര്യങ്ങളെ നിങ്ങൾ അനുവദനീയമാക്കുക, അതിൽ കാണുന്ന നിഷിദ്ധമായ കാര്യങ്ങളെ നിങ്ങൾ നിഷിദ്ധമാക്കുക'' എന്ന് പറയുന്ന കാലം വരാനടുത്തിരിക്കുന്നു. അറിയുക, നാട്ടുകഴുതയുടെ മാംസവും പിടിമൃഗങ്ങളിൽനിന്ന് തേറ്റയുള്ളവയും നിങ്ങൾക്ക് അനുവദനീയമാവുകയില്ല. മുസ്ലിംകളോട് കരാറിൽ കഴിയുന്നവന്റെ (അമുസ്ലിമിന്റെ) നഷ്ടപ്പെട്ട മുതലും അനുവദനീയമാവുകയില്ല, ഉടമക്ക് അത് ആവശ്യമില്ലെങ്കിലൊഴികെ. ഒരാൾ ഒരു കൂട്ടരുടെ അടുത്ത് ചെന്നാൽ അവനെ സൽകരിക്കൽ അവരുടെമേൽ നിർബന്ധമാണ്. അവർ അവനെ സൽകരിക്കുന്നില്ലെങ്കിൽ തനിക്ക് ആവശ്യമായതനുസരിച്ച് അവരുടെ മുതലിൽനിന്ന് എടുക്കാൻ അവന് അർഹതയുണ്ട്." (ദ,തു,,ജ)', 'الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ്(റ)', null, null, array['د','ت','جه']::text[], '{}'::text[], null, null, 781, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ عَبْد اللَّه بْنِ مَسْعُود رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَلَا هَلَكَ الْمُتَنَطِّعُونَ" ثَلَاث مَرَّاتٍ. (م,د)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): "കാര്യങ്ങളിൽ അതിരുകടക്കുന്നവൻ നശിച്ചിരിക്കുന്നു" എന്ന് നബി(സ) മൂന്നു പ്രാവശ്യം പറഞ്ഞു. (മു,ദ)', 'عَبْد اللَّه بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 782, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ سَعْد بْنِ أَبِي وَقَاصٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ أَعْظَمَ الْمُسْلِمِينَ فِي الْمُسْلِمِينَ جُرْمًا: مَنْ سَأَلَ عَنْ أَمْرٍ لَمْ يُحَرَّمْ، فَحُرِّمَ عَلَى النَّاسِ مِنْ أَجْلِ مَسْأَلَته". (ق,د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിഷിദ്ധമാക്കപ്പെടാത്ത ഒരു കാര്യത്തെക്കുറിച്ച് ഒരാൾ ചോദിക്കുകയും, ആ ചോദ്യം കാരണമായി അത് ജനങ്ങൾക്ക് നിഷിദ്ധമാക്കപ്പെടുകയും ചെയ്താൽ, ആ വ്യക്തിയാണ് മുസ്ലിംകളിൽ ഏറ്റവും വലിയ പാപം ചെയ്തവൻ." (ബു,മു,ദ)', 'سَعْد بْنِ أَبِي وَقَاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 782, 782, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ يَزِيدَ بْنِ عُمَيْرَةَ - وَكَانَ مِنْ أَصْحَابِ مُعَاذِ بْنِ جَبَلٍ - قَالَ: كَانَ لَا يَجْلِسُ مَجْلِسًا لِلذِّكْرِ حِينَ يَجْلِسُ إِلَّا قَالَ: اللَّهُ حَكَمٌ قِسْطٌ، هَلَكَ الْمُرْتَابُونَ. فَقَالَ مُعَاذُ بْنُ جَبَلٍ يَوْمًا: إِنَّ مِنْ وَرَائِكُمْ فِتَنًا يَكْثُرُ فِيهَا الْمَالُ، وَيُفْتَحُ فِيهَا الْقُرْآنُ: حَتَّى يَأْخُذَهُ الْمُؤْمِنُ وَالْمُنَافِقُ، وَالرَّجُلُ وَالْمَرْأَةُ، وَالصَّغِيرُ وَالْكَبِيرُ، وَالْعَبْدُ وَالْحُرُّ. فَيُوشِكُ قَائِلٌ أَنْ يَقُولَ: مَا لِلنَّاسِ لَا يَتَّبِعُونِي وَقَدْ قَرَأْتُ الْقُرْآنَ؟ مَا هُمْ بِمُتَّبِعِيَّ حَتَّى أَبْتَدِعَ لَهُمْ غَيْرَهُ. فَإِيَّاكُمْ وَمَا ابْتُدِعَ، فَإِنَّ مَا ابْتُدِعَ ضَلَالَةٌ. وَأُحَذِّرُكُمْ زَيْغَةَ الْحَكِيمِ، فَإِنَّ الشَّيْطَانَ قَدْ يَقُولُ كَلِمَةَ الضَّلَالَةِ عَلَى لِسَانِ الْحَكِيمِ، وَقَدْ يَقُولُ الْمُنَافِقُ كَلِمَةَ الْحَقِّ. قَالَ: قُلْتُ لِمُعَاذٍ: مَا يُدْرِينِي - رَحِمَكَ اللَّهُ - أَنَّ الْحَكِيمَ قَدْ يَقُولُ كَلِمَةَ الضَّلَالَةِ، وَأَنَّ الْمُنَافِقَ قَدْ يَقُولُ كَلِمَةَ الْحَقِّ؟ قَالَ: بَلَى، اجْتَنِبْ مِنْ كَلَامِ الْحَكِيمِ الْمُشْتَهِرَاتِ الَّتِي يُقَالُ لَهَا مَا هَذِهِ؟ وَلَا يُثْنِينَّكَ ذَلِكَ عَنْهُ، فَإِنَّهُ لَعَلَّهُ أَنْ يُرَاجِعَ، وَتَلَقَّ الْحَقَّ إِذَا سَمِعْتَهُ، فَإِنَّ عَلَى الْحَقِّ نُورًا.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=6), 1, 'وَفِي رِوَايَةٍ: (وَلَا يُنْئِيَنَّكَ) مَكَانَ (يُثْنِيَنَّكَ). (الْمُشَبِّهَاتِ) مَكَانَ (الْمُشْتَهِرَاتِ). وَ(بَلَى، مَا تَشَابَهَ عَلَيْكَ مِنْ قَوْلِ الْحَكِيمِ حَتَّى تَقُولَ مَا أَرَادَ بِهَذِهِ الْكَلِمَةِ). [موقوف] (د)', 'മറ്റൊരു നിവേദനത്തിൽ ''നിന്നെ അകറ്റാതിരിക്കട്ടെ'' എന്ന സ്ഥാനത്ത് ''നിന്നെ വിദൂരത്താക്കാതിരിക്കട്ടെ'' എന്നും ''തെറ്റാണെന്ന് അറിയപ്പെടുന്ന വാക്കുകൾ'' എന്ന സ്ഥാനത്ത് ''സംശയകരമായ കാര്യങ്ങൾ'' എന്നും ''അതെ, അറിവുള്ളവന്റെ സംസാരത്തിൽ, ഇതുകൊണ്ട് എന്താണവൻ ഉദ്ദേശിച്ചതെന്ന് നീ ചോദിക്കുംവിധം സംശയകരമായ വാക്ക്'' എന്നുമെല്ലാം ഉണ്ട്. ഹദീസ് മൗഖൂഫാണ്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ سُفْيَانَ الثَّوْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَتَبَ رَجُلٌ إِلَى عُمَرَ بْنِ عَبْدِ الْعَزِيزِ يَسْأَلُهُ عَنِ الْقَدَرِ، فَكَتَبَ: أَمَّا بَعْدُ، أُوصِيكَ بِتَقْوَى اللَّهِ، وَالِاقْتِصَادِ فِي أَمْرِهِ، وَاتِّبَاعِ سُنَّةِ نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَتَرْكِ مَا أَحْدَثَ الْمُحْدِثُونَ بَعْدَ مَا جَرَتْ بِهِ سُنَّتُهُ وَكُفُوا مُؤْنَتَهُ، فَعَلَيْكَ بِلُزُومِ السُّنَّةِ فَإِنَّهَا لَكَ - بِإِذْنِ اللَّهِ - عِصْمَةٌ، ثُمَّ اعْلَمْ: أَنَّهُ لَمْ يَبْتَدِعِ النَّاسُ بِدْعَةً إِلَّا قَدْ مَضَى قَبْلَهَا مَا هُوَ دَلِيلٌ عَلَيْهَا أَوْ عِبْرَةٌ فِيهَا، فَإِنَّ السُّنَّةَ إِنَّمَا سَنَّهَا مَنْ قَدْ عَلِمَ مَا فِي خِلَافِهَا مِنَ الْخَطَأِ وَالزَّلَلِ وَالْحُمْقِ وَالتَّعَمُّقِ، فَارْضَ لِنَفْسِكَ مَا رَضِيَ بِهِ الْقَوْمُ لِأَنْفُسِهِمْ، فَإِنَّهُمْ عَلَى عِلْمٍ وَقَفُوا، وَبِبَصَرٍ نَافِذٍ كَفُّوا، وَهُمْ عَلَى كَشْفِ الْأُمُورِ كَانُوا أَقْوَى، وَبِفَضْلِ مَا كَانُوا فِيهِ أَوْلَى، فَإِنْ كَانَ الْهُدَى مَا أَنْتُمْ عَلَيْهِ لَقَدْ سَبَقْتُمُوهُمْ إِلَيْهِ، وَلَئِنْ قُلْتُمْ: إِنَّمَا حَدَثَ بَعْدَهُمْ مَا أَحْدَثَهُ إِلَّا مَنِ اتَّبَعَ غَيْرَ سَبِيلِهِمْ وَرَغِبَ بِنَفْسِهِ عَنْهُمْ، فَإِنَّهُمْ هُمُ السَّابِقُونَ، فَقَدْ تَكَلَّمُوا فِيهِ بِمَا يَكْفِي، وَوَصَفُوا مِنْهُ مَا يَشْفِي، فَمَا دُونَهُمْ مِنْ مَقْصَرٍ، وَمَا فَوْقَهُمْ مِنْ مَحْسَرٍ، وَقَدْ قَصَّرَ قَوْمٌ دُونَهُمْ فَجَفَوْا، وَطَمَحَ عَنْهُمْ أَقْوَامٌ فَغَلَوْا، وَإِنَّهُمْ بَيْنَ ذَلِكَ لَعَلَى هُدًى مُسْتَقِيمٍ. كَتَبْتَ تَسْأَلُ عَنِ الْإِقْرَارِ بِالْقَدَرِ، فَعَلَى الْخَبِيرِ - بِإِذْنِ اللَّهِ - وَقَعْتَ، مَا أَعْلَمُ مَا أُحْدِثَ النَّاسُ مِنْ مُحْدَثَةٍ، وَلَا ابْتَدَعُوا مِنْ بِدْعَةٍ هِيَ أَبْيَنُ أَثَرًا وَلَا أَثْبَتُ أَمْرًا مِنَ الْإِقْرَارِ بِالْقَدَرِ، لَقَدْ كَانَ ذِكْرُهُ فِي الْجَاهِلِيَّةِ الْجُهَلَاءِ، يَتَكَلَّمُونَ بِهِ فِي كَلَامِهِمْ وَفِي شِعْرِهِمْ، يَعْزُونَ بِهِ أَنْفُسَهُمْ عَلَى مَا فَاتَهُمْ، ثُمَّ لَمْ يَزِدْهُ الْإِسْلَامُ بَعْدُ إِلَّا شِدَّةً، وَلَقَدْ ذَكَرَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَيْرِ حَدِيثٍ وَلَا حَدِيثَيْنِ، وَقَدْ سَمِعَهُ مِنْهُ الْمُسْلِمُونَ فَتَكَلَّمُوا بِهِ فِي حَيَاتِهِ وَبَعْدَ وَفَاتِهِ، يَقِينًا وَتَسْلِيمًا لِرَبِّهِمْ، وَتَضْعِيفًا لِأَنْفُسِهِمْ: أَنْ يَكُونَ شَيْءٌ لَمْ يُحِطْ بِهِ عِلْمُهُ، وَلَمْ يُحْصِهِ كِتَابُهُ، وَلَمْ يَمْضِ فِيهِ قَدَرُهُ. وَإِنَّهُ مَعَ ذَلِكَ لَفِي مُحْكَمِ كِتَابِه، مِنْهُ اقْتَبَسُوهُ، وَمِنْهُ تَعَلَّمُوهُ، وَلَئِنْ قُلْتُمْ: لَمَ أَنْزَلَ اللَّهُ آيَةَ كَذَا؟ وَلِمَ قَالَ كَذَا؟ لَقَدْ قَرَءُوا مِنْهُ مَا قَرَأْتُمْ، وَعَلِمُوا مِنْ تَأْوِيله مَا جَهِلْتُمْ، وَقَالُوا بَعْدَ ذَلِكَ: كُلُّهُ بِكِتَاب وَقَدَر، وَكُتِبَت الشَّقَاوَةُ، وَمَا يُقْدَرْ يَكُنْ، وَمَا شَاءَ اللَّهُ كَانَ، وَمَا لَمْ يَشَأْ لَمْ يَكُنْ، وَلَا نَمْلِكُ لِأَنْفُسِنَا ضَرًّا وَلَا نَفْعًا، ثُمَّ رَغِبُوا بَعْدَ ذَلِكَ وَرَهِبُوا. (د)', 'സുഫ്യാനുസ്സൗരി(റ): ഖദ്റിനെ സംബന്ധിച്ച് സംശയം ചോദിച്ചുകൊണ്ട് ഒരാൾ ഉമറുബ്നു അബ്ദിൽഅസീസ്(റ)വിന് കത്തയച്ചു. ഉമറുബ്നു അബ്ദിൽഅസീസ്(റ) ഇപ്രകാരം മറുപടി അയച്ചു: ആമുഖത്തിനു ശേഷം, അല്ലാഹുവിന് തഖ്വ ചെയ്യണമെന്നും, അവന്റെ കാര്യത്തിൽ മിതത്വം സ്വീകരിക്കണമെന്നും, അവന്റെ പ്രവാചകന്റെ ചര്യ പിന്തുടരണമെന്നും, പ്രവാചകന്റെ ചര്യ വന്നതിനു ശേഷം പുത്തനാശയക്കാർ പടച്ചുണ്ടാക്കുകയും അതിന്റെ ദുഷിച്ച ഫലം അവർക്കുതന്നെ ലഭിക്കുകയും ചെയ്ത കാര്യങ്ങളെ ഉപേക്ഷിക്കണമെന്നും ഞാൻ നിന്നെ ഉപദേശിക്കുന്നു. അതുകൊണ്ട് നീ നബിചര്യയെ മുറുകെ പിടിക്കുക. അത് - അല്ലാഹുവിന്റെ അനുവാദ പ്രകാരം - നിനക്ക് സംരക്ഷണമാണ്. പിന്നെ നീ അറിയുക, ജനങ്ങൾ ഏതെങ്കിലുമൊരു പുതിയ കാര്യം തുടങ്ങിയിട്ടുണ്ടെങ്കിൽ അതിനുള്ള തെളിവോ സൂചനയോ ആയ കാര്യം മുമ്പ് വന്നിട്ടുണ്ടാകും. നബിചര്യയെ നടപ്പിൽ വരുത്തിയത് അതിന്റെ എതിരിലുള്ള പിഴവുകളെയും വീഴ്ചകളെയും ബുദ്ധിശൂന്യതകളെയും അതിർലംഘനങ്ങളെയും മനസ്സിലാക്കിയവർ തന്നെയാണ്. അതിനാൽ (പഴയകാല) ജനങ്ങൾ തങ്ങൾക്കുവേണ്ടി തെരഞ്ഞെടുത്തത് നീ നിനക്കു വേണ്ടിയും തെരഞ്ഞെടുക്കുക. കാരണം, വ്യക്തമായ ജ്ഞാനത്തിനു മേലാണ് അവർ നിലകൊണ്ടത്, അതിശക്തമായ ഉൾകാഴ്ച കൊണ്ടാണ് (വിലക്കപ്പെട്ട കാര്യങ്ങളെ) അവർ ഒഴിവാക്കിയിട്ടത്. കാര്യങ്ങളിൽ വെളിപാട് ലഭിക്കുന്നതിൽ അവർ അതിശക്തരായിരുന്നു. തങ്ങൾക്ക് ലഭിച്ച ശ്രേഷ്ഠതയോട് ഏറ്റവും ബന്ധപ്പെട്ടവരായിരുന്നു അവർ. ഇനി നിങ്ങൾ സ്വീകരിച്ച വഴിയാണ് സന്മാർഗ്ഗമെങ്കിൽ അവരേക്കാൾ മുന്നെ നിങ്ങൾ അതിൽ എത്തിപ്പെട്ടെന്നോ? ഇനി അവർക്കു ശേഷമുണ്ടായതെല്ലാം, അവരുടേതല്ലാത്ത മാർഗ്ഗം സ്വീകരിച്ചവരും അവരിൽനിന്ന് അകന്നവരുമായ ജനങ്ങൾ പടച്ചുണ്ടാക്കിയതാണ് എന്നാണ് നിങ്ങൾ പറയുന്നതെങ്കിൽ, അവരല്ലേ മുൻഗാമികൾ? അവർ ആ വിഷയത്തിൽ വേണ്ടവിധം സംസാരിക്കുകയും ആശ്വാസം നൽകുംവിധം വിശദീകരിക്കുകയും ചെയ്തിട്ടുണ്ട്. അവരേക്കാൾ കൂടുതലായി കാര്യത്തെ പർവ്വതീകരിക്കാനോ കുറച്ചു കാണിക്കാനോ മാർഗ്ഗമില്ല. ചിലർ കാര്യങ്ങളെ അവരേക്കാൾ കുറച്ചുകാണിക്കുകയും അങ്ങനെ അവരിൽനിന്ന് അകലുകയും ചെയ്തു. മറ്റു ചിലർ കാര്യത്തെ അവരേക്കാൾ പർവ്വതീകരിക്കുകയും അങ്ങനെ അതിർലംഘനം നടത്തുകയും ചെയ്തു. അവർ (മുൻഗാമികൾ) ഇതിനെല്ലാം മധ്യേയുള്ള നേരായ മാർഗ്ഗത്തിലായിരുന്നു. ദൈവനിശ്ചയത്തെ (ഖദ്ർ) അംഗീകരിക്കുന്നതിനെ കുറിച്ച് ചോദിച്ചാണ് നീ കത്തയച്ചത്. അല്ലാഹുവിന്റെ അനുവാദപ്രകാരം അതിനെക്കുറിച്ച് കൂടുതൽ അറിയുന്നവനെ തന്നെയാണ് നീ സമീപിച്ചിരിക്കുന്നത്. ദൈവനിശ്ചയത്തെ അംഗീകരിക്കുന്നതിനേക്കാൾ സുവ്യക്തവും ഉറച്ചതുമായ ഒരു കാര്യത്തെ ജനങ്ങൾ പുതുതായി നിർമ്മിക്കുകയോ പടച്ചുണ്ടാക്കുകയോ ചെയ്തിട്ടില്ല എന്ന് എനിക്കറിയാം. അത്യജ്ഞാന കാലത്തുപോലും (ഇസ്ലാമിനും മുമ്പ്) അതിനെക്കുറിച്ചുള്ള സംസാരമുണ്ടായിരുന്നു. തങ്ങളുടെ കാവ്യ കാവ്യേതര സംസാരങ്ങളിൽ അവർ അതിനെ പരാമർശിച്ചിരുന്നു. തങ്ങൾക്ക് നഷ്ടമാകുന്ന കാര്യങ്ങളിൽ ഇതുകൊണ്ട് അവർ സ്വന്തത്തിന് ആശ്വാസമേകുമായിരുന്നു. ശേഷം ഇസ്ലാമും അതിന് ശക്തിയേ പകർന്നുള്ളൂ. ഒന്നുരണ്ടു ഹദീസുകളിൽ മാത്രമല്ല റസൂൽ(സ) ഇക്കാര്യം പരാമർശിച്ചത്. മുസ്ലിംകൾ റസൂൽ(സ)യിൽനിന്ന് ഇക്കാര്യം കേൾക്കുകയും അവിടുത്തെ ജീവിതകാലത്തും വഫാത്തിനു ശേഷവും ഇക്കാര്യത്തെക്കുറിച്ച് സംസാരിക്കുകയും ചെയ്തിട്ടുണ്ട്. അല്ലാഹുവിന്റെ വിധിയിൽ കഴിഞ്ഞു പോകാത്ത, അവന്റെ ഗ്രന്ഥത്തിൽ ഉൾക്കൊള്ളാത്ത, അവന്റെ വിജ്ഞാനത്തിൽ ഉൾപെടാത്ത ഒരു വസ്തു ഉണ്ടാവുക എന്ന കാര്യത്തിൽ തങ്ങളുടെ അശക്തത വ്യക്തമാക്കിക്കൊണ്ടും തങ്ങളുടെ നാഥനു മുന്നിൽ കീഴടങ്ങിക്കൊണ്ടും ഉറച്ച വിശ്വാസത്തോടെയുമാണ് അവർ അപ്രകാരം ചെയ്തത്. ഇതോടൊപ്പം അത് അല്ലാഹുവിന്റെ ദൃഢമായ ഗ്രന്ഥത്തിൽതന്നെ ഉള്ളതാണ്. അതിൽ നിന്നാണ് അവർ അതിനെ സ്വീകരിച്ചതും പഠിച്ചുണ്ടാക്കിയതും. ഇനി നിങ്ങൾ ചോദിക്കുന്നത് ''എന്തിനാണ് അല്ലാഹു ഇത്തരമൊരു സൂക്തമിറക്കിയത്? എന്തിനാണവൻ ഇപ്രകാരം പറഞ്ഞത്?'' എന്നെല്ലാമാണെങ്കിൽ, നിങ്ങൾ പാരായണം ചെയ്തതെല്ലാം അവരും പാരായണം ചെയ്തിട്ടുണ്ടല്ലോ? മാത്രമല്ല, ഖുർആന്റെ നിങ്ങൾക്കറിയാത്ത വ്യാഖ്യാനംപോലും അവർക്കറിയാം. എന്നിട്ടും അവർ പറഞ്ഞത്: ''കാര്യങ്ങളെല്ലാം മുൻനിശ്ചയ പ്രകാരവും ദൈവവിധി പ്രകാരവുമാണ് (സംഭവിക്കുന്നത്), പരാജയം മുന്നെ നിശ്ചയിക്കപ്പെട്ടതാണ്, നിശ്ചയിക്കപ്പെട്ടതെല്ലാം സംഭവിക്കും, അല്ലാഹു ഉദ്ദേശിച്ചത് സംഭവിക്കും, അവൻ ഉദ്ദേശിക്കാത്തത് സംഭവിക്കുകയില്ല, നമുക്ക് സ്വന്തത്തിന് ഉപകാരമോ ഉപദ്രവമോ ചെയ്യാൻ സാധ്യമല്ല'' എന്നെല്ലാമാണ്. ഇതോടൊപ്പം അവർ (അല്ലാഹുവിന്റെ അനുഗ്രഹത്തിൽ) പ്രതീക്ഷ വെക്കുകയും (അവന്റെ കോപത്തെ) ഭയപ്പെടുകയും ചെയ്തു. (ദ)', 'سُفْيَانَ الثَّوْرِيِّ', 'സുഫ്യാനുസ്സൗരി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 783, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ نَافِع قَالَ: كَانَ لابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا صَدِيقٌ مِنْ أَهْلِ الشَّامِ يُكَاتِبُهُ، فَكَتَبَ إِلَيْه عَبْدُ اللَّه بْنُ عُمَرَ: إِنَّهُ بَلَغَنِي أَنَّكَ تَكَلَّمْتَ فِي شَيْءٍ مِنَ الْقَدَرِ، فَإِيَّاكَ أَنْ تَكْتُبَ إِلَيَّ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّهُ سَيَكُونُ فِي أُمَّتِي أَقْوَامٌ يُكَذِّبُونَ بِالْقَدَرِ". (د)', 'നാഫിഅ്(റ): ഇബ്നുഉമർ(റ)വിന്, തന്നോട് കത്തിടപാട് നടത്തുന്ന, ശാമുകാരനായ ഒരു സുഹൃത്തുണ്ടായിരുന്നു. ഒരിക്കൽ അബ്ദുല്ലാഹിബ്നുഉമർ(റ) അദ്ദേഹത്തിന് ഇപ്രകാരമെഴുതി: ഖദ്റിന്റെ (ദൈവനിശ്ചയത്തിന്റെ) വിഷയത്തിൽ നീ എന്തോ സംസാരിച്ചിട്ടുണ്ടെന്ന വിവരം ഞാനറിഞ്ഞു. അതിനാൽ എനിക്ക് കത്തയക്കുന്നതിനെ നീ സൂക്ഷിക്കുക. കാരണം, റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് നിശ്ചയം ഞാൻ കേട്ടു: "ഖദ്റിനെ നിഷേധിക്കുന്ന ചിലയാളുകൾ ശേഷം എന്റെ സമുദായത്തിൽ ഉടലെടുക്കും." (ദ)', 'نَافِع قَالَ', 'നാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنْ خَالِدٍ الْحَذَّاءِ قَالَ: قُلْتُ لِلْحَسَنِ: يَا أَبَا سَعِيدٍ، أَخْبِرْنِي عَنْ آدَمَ، أَلِلسَّمَاءِ خُلِقَ أَمْ لِلْأَرْضِ؟ قَالَ: لَا، بَلْ لِلْأَرْضِ. قُلْتُ: أَرَأَيْتَ لَوِ اعْتَصَمَ فَلَمْ يَأْكُلْ مِنَ الشَّجَرَةِ؟ قَالَ: لَمْ يَكُنْ لَهُ مِنْهُ بُدٌّ، قُلْتُ: أَخْبِرْنِي عَنْ قَوْلِهِ تَعَالَى: {مَا أَنْتُمْ عَلَيْهِ بِفَاتِنِينَ إِلَّا مَنْ هُوَ صَالِ الْجَحِيمِ} [الصافات: ١٦٢, ١٦٣]. قَالَ: إِنَّ الشَّيَاطِينَ لَا يَفْتِنُونَ بِضَلَالَتِهِمْ إِلَّا مَنْ أَوْجَبَ اللَّهُ عَلَيْهِ - أَنَّهُ يَصْلِي - الْجَحِيمَ. (د)', 'ഖാലിദുൽ ഹദ്ദാഅ്(റ): ഞാൻ ഹസൻ(റ)വിനോട് പറഞ്ഞു: അബൂസഈദേ, ആദം(അ)മിനെ സംബന്ധിച്ച് എനിക്ക് പറഞ്ഞുതരിക. സ്വർഗ്ഗത്തിലേക്ക് വേണ്ടിയാണോ ഭൂമിയിലേക്ക് വേണ്ടിയാണോ അവർ സൃഷ്ടിക്കപ്പെട്ടത്? ഹസൻ(റ) പറഞ്ഞു: അല്ല, ഭൂമിയിലേക്കു വേണ്ടി തന്നെയാണ്. ഞാൻ ചോദിച്ചു: ആദം(അ) പാപസുരക്ഷിതനായി, ആ മരത്തിൽനിന്ന് ഒന്നും (ഒരു കനിയും) ഭക്ഷിച്ചിട്ടില്ലായെങ്കിൽ എങ്ങിനെയായിരിക്കും? ഹസൻ(റ) പറഞ്ഞു: ആദം(അ)മിന് അത് ഭക്ഷിക്കാതെ കഴിയുമായിരുന്നില്ല. ഞാൻ പറഞ്ഞു: ''നരകത്തിൽ പ്രവേശിക്കാനുള്ളവനെ അല്ലാതെ അല്ലാഹുവിനെതിരായി നിങ്ങൾക്ക് കുഴപ്പത്തിലാക്കാൻ സാധ്യമല്ല'' (സ്വാഫാത്: 162, 163) എന്ന സൂക്തത്തെക്കുറിച്ച് നിങ്ങൾ എനിക്ക് പറഞ്ഞുതരിക. ഹസൻ(റ) പറഞ്ഞു: നരകത്തിൽ പ്രവേശിക്കുമെന്ന് അല്ലാഹു നിശ്ചയിച്ചവനെ അല്ലാതെ പിശാചുകൾ തങ്ങളുടെ തിന്മകളെക്കൊണ്ട് കുഴപ്പത്തിലാക്കുകയില്ല. (ദ)', 'خَالِدٍ الْحَذَّاءِ قَالَ', 'ഖാലിദുൽ ഹദ്ദാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الصافات: ١٦٢, ١٦٣', null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنِ الْحَسَنِ في قَوْله تَعَالَى: {وَلِذَلِكَ خَلَقَهُمْ} [هود: ١١٩] قَالَ: خَلَقَ هَؤُلَاء لِهَذه، وَهَؤُلَاء لِهَذه. (د)', 'ഹസൻ(റ): ''അതിനുവേണ്ടിയാണ് അവരെ സൃഷ്ടിച്ചത്'' (ഹൂദ്: 119) എന്ന സൂക്തത്തെക്കുറിച്ച് അദ്ദേഹം പറയുന്നു: ഈ വിഭാഗം ഇതിനുവേണ്ടിയും മറ്റേ വിഭാഗം ഇതിനുവേണ്ടിയും¹ സൃഷ്ടിക്കപ്പെട്ടു. (ദ)', 'الْحَسَنِ في قَوْله تَعَالَى', 'ഹസൻ(റ)', '¹. ഒരു വിഭാഗത്തെ നരകത്തിനു വേണ്ടിയും മറ്റൊരു വിഭാഗത്തെ സ്വർഗ്ഗത്തിനു വേണ്ടിയും എന്നർത്ഥം', null, array['د']::text[], array['ദ']::text[], 'هود: ١١٩', null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنِ الْحَسَنِ قَالَ: لَأَنْ يُسْقَطَ مِنَ السَّمَاءِ إِلَى الْأَرْضِ أَحَبُّ إِلَيْهِ مِنْ أَنْ يَقُولَ: الْأَمْرُ بِيَدِي. (د)', 'ഹസൻ(റ): കാര്യം (നിയന്ത്രണം) എന്റെ കയ്യിലാണെന്ന് പറയുന്നതിനേക്കാൾ അദ്ദേഹത്തിനിഷ്ടം (ഭേതം) ആകാശത്തുനിന്ന് അദ്ദേഹം ഭൂമിയിലേക്ക് വീഴ്ത്തപ്പെടുന്നതാണ്. (ദ)', 'الْحَسَنِ قَالَ', 'ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 785, 785, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ حُمَيْد قَالَ: قَدِمَ عَلَيْنَا الْحَسَنُ مَكَّةَ، فَكَلَّمَنِي فُقَهَاءُ أَهْلِ مَكَّةَ أَنْ أُكَلِّمَهُ فِي أَنْ يَجْلِسَ لَهُمْ يَوْمًا يَعِظُهُمْ فِيه، فَقَالَ: نَعَمْ، فَاجْتَمَعُوا فَخَطَبَهُمْ، فَمَا رَأَيْتُ أَخْطَبَ مِنْهُ، فَقَالَ رَجُلٌ: يَا أَبَا سَعِيد، مَنْ خَلَقَ الشَّيْطَانَ؟ فَقَالَ: سُبْحَانَ اللَّهِ! هَلْ مِنْ خَالِق غَيْرُ اللَّهِ؟ خَلَقَ اللَّهُ الشَّيْطَانَ، وَخَلَقَ الْخَيْرَ، وَخَلَقَ الشَّرَّ. قَالَ الرَّجُلُ: قَاتَلَهُمُ اللَّهُ! كَيْفَ يَكْذِبُونَ عَلَى هَذَا الشَّيْخ؟ (د)', 'ഹുമൈദ്(റ): മക്കയിൽവെച്ച് ഹസൻ(റ) ഒരിക്കൽ ഞങ്ങളുടെ അടുത്ത് വന്നു. അപ്പോൾ മക്കയിലെ കർമ്മശാസ്ത്ര പണ്ഡിതർ തങ്ങൾക്ക് ഉപദേശം നൽകുന്നതിനു വേണ്ടി, ഒരു ദിവസം ഇരിക്കാൻ ഹസൻ(റ)വിനോട് അഭ്യർത്ഥിക്കണമെന്ന് എന്നോടാവശ്യപ്പെട്ടു. അപ്പോൾ ഹസൻ(റ) ''അതെ'' എന്ന് പറഞ്ഞു. അങ്ങനെ അവർ ഒരുമിച്ചുകൂടുകയും ഹസൻ(റ) അവരെ ഉപദേശിക്കുകയും ചെയ്തു. അദ്ദേഹത്തേക്കാൾ വലിയ പ്രസംഗകനെ ഞാൻ കണ്ടിട്ടില്ല. അപ്പോൾ ഒരാൾ ചോദിച്ചു: അബൂസഈദേ, ആരാണ് പിശാചിനെ സൃഷ്ടിച്ചത്? ഹസൻ(റ) പറഞ്ഞു: ഞാൻ അല്ലാഹുവിന്റെ മഹത്വത്തെ വാഴ്തുന്നു. അല്ലാഹുവല്ലാതെ മറ്റൊരു സ്രഷ്ടാവുണ്ടോ? അല്ലാഹു പിശാചിനെ സൃഷ്ടിച്ചു. അവൻ നന്മയെയും തിന്മയെയും സൃഷ്ടിച്ചു. അപ്പോൾ ആ വ്യക്തി പറഞ്ഞു: അല്ലാഹു അവരെ നശിപ്പിക്കട്ടെ. ഈ മഹൽവ്യക്തിയെക്കുറിച്ച് നുണ പറഞ്ഞുണ്ടാക്കാൻ എങ്ങിനെയാണവർക്ക് കഴിയുന്നത്? (ദ)', 'حُمَيْد قَالَ', 'ഹുമൈദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 785, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ الْحَسَنِ: {كَذَلِكَ نَسْلُكُهُ فِي قُلُوبِ الْمُجْرِمِينَ} [الحجر: ١٢] قَالَ: الشِّرْكُ. (د)', 'ഹസൻ(റ): ''അപ്രകാരം കുറ്റവാളികളുടെ ഹൃദയങ്ങളിൽനാം അതിനെ കോർത്തിടുന്നു'' (അൽഹിജ്ർ: 12). ഹസൻ(റ) പറയുന്നു: അഥവാ ബഹുദൈവാരാധനയെ (കോർത്തിടുന്നു). (ദ)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الحجر: ١٢', null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ الْحَسَنِ فِي قَوْلِ اللَّهِ عَزَّ وَجَلَّ: {وَحِيلَ بَيْنَهُمْ وَبَيْنَ مَا يَشْتَهُونَ} [سبأ: ٥٤] قَالَ: بَيْنَهُمْ وَبَيْنَ الْإِيمَانِ. (د)', 'ഹസൻ(റ): ''അവർക്കും അവർ ആഗ്രഹിക്കുന്ന കാര്യത്തിനുമിടയിൽ തടസ്സം സൃഷ്ടിക്കപ്പെട്ടു'' (സബഅ്: 54). ഹസൻ(റ) പറഞ്ഞു: അഥവാ അവർക്കും സത്യവിശ്വാസത്തിനുമിടയിൽ. (ദ)', 'الْحَسَنِ فِي قَوْلِ اللَّهِ عَزَّ وَجَلَّ', 'ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'سبأ: ٥٤', null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنِ ابْن عَوْن قَالَ: كُنْتُ أَسِيرُ بِالشَّام، فَنَادَانِي رَجُلٌ مِنْ خَلْفِي، فَالْتَفَتُّ فَإِذَا رَجَاءُ بْنُ حَيْوَةَ، فَقَالَ: يَا أَبَا عَوْن، مَا هَذَا الَّذِي يَذْكُرُونَ عَنِ الْحَسَنِ؟ قَالَ: قُلْتُ: إِنَّهُمْ يَكْذِبُونَ عَلَى الْحَسَنِ كَثِيرًا. (د)', 'ഇബ്നുഔൻ(റ): ഞാൻ ശാമിലൂടെ നടന്നു പോവുകയായിരുന്നു. അപ്പോൾ എന്റെ പിന്നിൽ നിന്നൊരാൾ എന്നെ വിളിച്ചു. തിരിഞ്ഞു നോക്കിയപ്പോൾ അത് റജാഉബ്നു ഹൈവയായിരുന്നു. അദ്ദേഹം ചോദിച്ചു: അബൂഔനേ, ഹസൻ(റ)വിനെക്കുറിച്ച് ഇവരെല്ലാം പറഞ്ഞുകൊണ്ടിരിക്കുന്ന ഇക്കാര്യം (അതിന്റെ യാഥാർത്ഥ്യം) എന്താണ്? ഞാൻ പറഞ്ഞു: ജനങ്ങൾ ഹസൻ(റ)വിനെക്കുറിച്ച് ധാരാളം നുണ പറയുന്നുണ്ട്. (ദ)', 'ابْن عَوْن قَالَ', 'ഇബ്നുഔൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَيُّوبَ السَّخْتِيَانِي قَالَ: كَذَبَ عَلَى الْحَسَنِ ضَرْبَانِ مِنَ النَّاسِ: قَوْمٌ الْقَدَرُ رَأْيُهُمْ، وَهُمْ يُرِيدُونَ أَنْ يُنَفِّقُوا بِذَلِكَ رَأْيَهُمْ. وَقَوْمٌ لَهُ فِي قُلُوبِهِمْ شَنَآنٌ وَبُغْضٌ، يَقُولُونَ: أَلَيْسَ مِنْ قَوْلِهِ كَذَا؟ أَلَيْسَ مِنْ قَوْلِهِ كَذَا؟ (د)', 'അയ്യൂബുസ്സഖ്തിയാനി(റ): ഹസൻ(റ)വിന്റെ പേരിൽ രണ്ടു വിഭാഗം ജനങ്ങൾ നുണ പറഞ്ഞുണ്ടാക്കി. ഒരു വിഭാഗം ദൈവനിശ്ചയം ഇല്ലായെന്ന് അഭിപ്രായപ്പെടുന്നവരാണ് (ഖദ്രിയ്യാക്കൾ). അതുകൊണ്ട് അവർ ഉദ്ദേശിച്ചത് തങ്ങളുടെ അഭിപ്രായങ്ങൾക്ക് ആളുകളെ ഉണ്ടാക്കലാണ്. മറ്റൊരു വിഭാഗം ഹസൻ(റ)വിനോട് വിദ്വേഷവും കോപവുമുള്ളവരാണ്. അവർ ചോദിക്കുന്നു: ഹസൻ(റ) ഇപ്രകാരം പറഞ്ഞിട്ടില്ലേ? അദ്ദേഹം ഇപ്രകാരം പറഞ്ഞിട്ടില്ലേ? (ദ)', 'أَيُّوبَ السَّخْتِيَانِي قَالَ', 'അയ്യൂബുസ്സഖ്തിയാനി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 786, 786, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ يَحْيَى بْنَ كَثِيرِ الْعَنْبَرِيَّ قَالَ: كَانَ قُرَّةُ بْنُ خَالِد يَقُولُ لَنَا: يَا فَتْيَانُ، لَا تُغْلَبُوا عَلَى الْحَسَنِ، فَإِنَّهُ كَانَ رَأْيُهُ السُّنَّةَ وَالصَّوَابَ. (د)', 'യഹ്യബ്നു കസീറുൽ അമ്പരീ(റ): ഖുർരതുബ്നു ഖാലിദ്(റ) ഞങ്ങളോട് ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: യുവാക്കളേ, ഹസൻ(റ)വിന്റെ കാര്യത്തിൽ നിങ്ങൾ പരാജയപ്പെടരുത് (ഹസൻ(റ) തങ്ങളുടെ കൂട്ടത്തിൽ പെട്ടതാണെന്ന ഖദ്രിയ്യാക്കളുടെ വാദം അംഗീകരിക്കരുത്), തീർച്ചയായും ഹസൻ(റ)വിന്റെ അഭിപ്രായം നബിചര്യയും സത്യവുമായിരുന്നു. (ദ)', 'يَحْيَى بْنَ كَثِيرِ الْعَنْبَرِيَّ قَالَ', 'യഹ്യബ്നു കസീറുൽ അമ്പരീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 786, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنِ ابْنِ عَوْن قَالَ: لَوْ عَلمْنَا أَنَّ كَلمَةَ الْحَسَنِ تَبْلُغُ مَا بَلَغَتْ، لَكَتَبْنَا بِرُجُوعِه كِتَابًا وَأَشْهَدْنَا عَلَيْه شُهُودًا، وَلَكِنَّا قُلْنَا: كَلِمَةٌ خَرَجَتْ لَا تُحْمَلُ. (د)', 'ഇബ്നുഔൻ(റ): ഹസൻ(റ)വിന്റെ വാക്കിന് ഇത്രമാത്രം വിപരീത ഫലമുണ്ടാകുമെന്ന് ഞങ്ങൾ അറിഞ്ഞിരുന്നെങ്കിൽ അദ്ദേഹം പിന്തിരിഞ്ഞുവെന്നതിന് ഞങ്ങൾ രേഖയുണ്ടാക്കുകയും അതിൽ സാക്ഷികളെ നിരത്തുകയും ചെയ്യുമായിരുന്നു. പക്ഷേ, ഞങ്ങൾ പറയുന്നത്: അത് അദ്ദേഹത്തിന്റെ വായിൽനിന്ന് വന്നതാണെങ്കിലും ജനങ്ങൾക്കിടയിൽ സുപരിചിതമായ അർത്ഥത്തിനുമേൽ ചുമത്തപ്പെടാൻ പറ്റാത്ത വാക്കാണ്. (ദ)', 'ابْنِ عَوْن قَالَ', 'ഇബ്നുഔൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَيُّوبَ قَالَ: قَالَ الْحَسَنُ: مَا أَنَا بِعَائِد إِلَى شَيْءٍ مِنْهُ أَبَدًا. (د)', 'അയ്യൂബ്(റ): ഹസൻ(റ) പറഞ്ഞു: അവയിൽനിന്ന് ഒന്നിലേക്കും ഇനി ഞാൻ മടങ്ങുകയില്ല. (ദ)', 'أَيُّوبَ قَالَ', 'അയ്യൂബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ عُثْمَانَ الْبَتِّيِّ قَالَ: مَا فَسَّرَ الْحَسَنُ آيَةً قَطُّ إِلَّا عَنِ الْأَثْبَاتِ. (د)', 'ഉസ്മാനുൽ ബത്തീ(റ): വിശ്വസ്തരിൽനിന്ന് (നിവേദനം ചെയ്തുകൊണ്ട്) അല്ലാതെ ഹസൻ(റ) ഒരു സൂക്തത്തെയും വ്യാഖ്യാനിച്ചിട്ടില്ല. (ദ)', 'عُثْمَانَ الْبَتِّيِّ قَالَ', 'ഉസ്മാനുൽ ബത്തീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَمَرْتُكُمْ بِهِ فَخُذُوهُ، وَمَا نَهَيْتُكُمْ عَنْهُ فَانْتَهُوا". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ കൽപിക്കുന്ന കാര്യങ്ങളെ നിങ്ങൾ കൈകൊള്ളുക, ഞാൻ നിരോധിക്കുന്നതിനെ വെടിയുക." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ذَرُونِي مَا تَرَكْتُكُمْ، فَإِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ بِسُؤَالِهِمْ وَاخْتِلَافِهِمْ عَلَى أَنْبِيَائِهِمْ. فَإِذَا أَمَرْتُكُمْ بِشَيْءٍ فَخُذُوا مِنْهُ مَا اسْتَطَعْتُمْ، وَإِذَا نَهَيْتُكُمْ عَنْ شَيْءٍ فَانْتَهُوا". (ق,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഞാൻ നിങ്ങളെ ഒഴിവാക്കുന്ന കാലത്തോളം നിങ്ങൾ എന്നെ വിട്ടേക്കുക (ഞാൻ കൽപിക്കാത്തിടത്തോളം നിങ്ങൾ എന്നോട് ചോദിക്കാതിരിക്കുക). തങ്ങളുടെ പ്രവാചകന്മാരോടുള്ള അഭിപ്രായ വൃത്യാസവും ചോദ്യവുമാണ് നിങ്ങളുടെ മുൻഗാമികളെ നശിപ്പിച്ചത്. ഞാൻ വല്ലതും കൽപിച്ചാൽ കഴിയുംവിധം നിങ്ങൾ അത് കൈകൊള്ളുക. ഞാൻ വല്ലതും നിരോധിച്ചാൽ നിങ്ങളത് വെടിയുക." (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَطَاعَنِي فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَانِي فَقَدْ عَصَى اللَّهَ". (خ,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്നെ അനുസരിച്ചവൻ അല്ലാഹുവിനെ അനുസരിച്ചിരിക്കുന്നു. എന്നെ ധിക്കരിച്ചവൻ അല്ലാഹുവിനെയും ധിക്കരിച്ചിരിക്കുന്നു." (ബു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 787, 787, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: كَانَ إِذَا سَمِعَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا لَمْ يَعْدُهُ، وَلَمْ يُقَصِّرْ دُونَهُ. (جه)', 'ഇബ്നുഉമർ(റ): അവർ റസൂൽ(സ)യിൽനിന്ന് ഒരു ഹദീസ് കേട്ടാൽ അതിനേക്കാൾ അധികരിപ്പിക്കുകയോ അതിനേക്കാൾ കുറക്കുകയോ ചെയ്യുമായിരുന്നില്ല. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 787, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ أَبِي الدَّرْدَاء رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ وَنَحْنُ نَذْكُرُ الْفَقْرَ وَنَتَخَوَّفُهُ، فَقَالَ: "أَالْفَقْرَ تَخَافُونَ؟ وَالَّذِي نَفْسِي بِيَده لَتُصَبَّنَّ عَلَيْكُمُ الدُّنْيَا صَبًّا، حَتَّى لَا يُزِيغَ قَلْبَ أَحَدِكُمْ إِزَاغَةً إِلَّا هِيهْ. وَايْمُ اللَّه، لَقَدْ تَرَكْتُكُمْ عَلَى مِثْلِ الْبَيْضَاء، لَيْلُهَا وَنَهَارُهَا سَوَاءٌ". قَالَ أَبُو الدَّرْدَاء: صَدَقَ - وَاللَّه - رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، تَرَكَنَا - وَاللَّه - عَلَى مِثْلِ الْبَيْضَاء، لَيْلُهَا وَنَهَارُهَا سَوَاءٌ. (جه)', 'അബുദ്ദർദാഅ്(റ): ഞങ്ങൾ ദാരിദ്ര്യത്തെ കുറിച്ച് പറയുകയും അതിൽ ഭയം പ്രകടിപ്പിച്ചു കൊണ്ടിരിക്കുകയും ചെയ്യുന്ന സമയത്ത് റസൂൽ(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു. അവിടുന്ന് ചോദിച്ചു: "ദാരിദ്ര്യത്തെയാണോ നിങ്ങൾ ഭയപ്പെടുന്നത്? എന്റെ ആത്മാവ് ആരുടെ നിയന്ത്രണത്തിലാണോ അവൻ തന്നെ സത്യം, ഐഹിക സുഖങ്ങൾ നിങ്ങളിലേക്ക് ചൊരിയപ്പെടുക തന്നെ ചെയ്യും. അവ മാത്രമായിരിക്കും നിങ്ങളുടെ ഹൃദയങ്ങളെ സത്യത്തിൽനിന്ന് അകറ്റുക. അല്ലാഹു തന്നെ സത്യം, പ്രകാശപൂരിതമായ ഭൂമി പോലുള്ള മാർഗ്ഗത്തിലാണ് ഞാൻ നിങ്ങളെ ഉപേക്ഷിച്ചിരിക്കുന്നത്. അതിലെ രാപകലുകളെല്ലാം സമമാണ്." അബുദ്ദർദാഅ്(റ) പറയുന്നു: അല്ലാഹു തന്നെ സത്യം, റസൂൽ(സ) പറഞ്ഞത് സത്യമാണ്. അല്ലാഹു തന്നെ സത്യം, പ്രകാശപൂരിതമായ ഭൂമി പോലുള്ള മാർഗ്ഗത്തിലാണ് റസൂൽ(സ) ഞങ്ങളെ ഉപേക്ഷിച്ച് പോയിരിക്കുന്നത്. അതിലെ രാപകലുകളെല്ലാം സമമാണ്. (ജ)', 'أَبِي الدَّرْدَاء', 'അബുദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ مُعَاوِيَةَ بْنِ قُرَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي مَنْصُورِينَ، لَا يَضُرُّهُمْ مَنْ خَذَلَهُمْ حَتَّى تَقُومَ السَّاعَةُ". (ت,جه)', 'മുആവിയതുബ്നു ഖുർറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാൾ സംഭവിക്കുംവരെ എന്റെ സമുദായത്തിൽപെട്ട ഒരു കൂട്ടർ സഹായിക്കപ്പെട്ടു കൊണ്ടേയിരിക്കും. തങ്ങളെ നിന്ദിക്കുന്നവർപോലും അവർക്ക് ഒരു പോറലുമേൽപിക്കുകയില്ല." (തു,ജ)', 'مُعَاوِيَةَ بْنِ قُرَّةَ', 'മുആവിയതുബ്നു ഖുർറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي قَوَّامَةً عَلَى أَمْرِ اللَّهِ، لَا يَضُرُّهَا مَنْ خَالَفَهَا". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽപെട്ട ഒരു സംഘം അല്ലാഹുവിന്റെ കാര്യത്തിനുമേൽ ശക്തമായി നിലനിന്നു കൊണ്ടേയിരിക്കും. തങ്ങളെ എതിർക്കുന്നവർ പോലും അവർക്ക് ഒരു പോറലുമേൽപിക്കുകയില്ല." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "كُلُّ أُمَّتِي يَدْخُلُونَ الْجَنَّةَ إِلَّا مَنْ أَبَى". قَالُوا: يَا رَسُولَ اللَّهِ، وَمَنْ يَأْبَى؟ قَالَ: "مَنْ أَطَاعَنِي دَخَلَ الْجَنَّةَ، وَمَنْ عَصَانِي فَقَدْ أَبَى". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിഷേധിച്ചവരൊഴികെ, എന്റെ സമുദായം മുഴുവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കും." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ആരാണ് നിഷേധിച്ചവർ? റസൂൽ(സ) പറഞ്ഞു: "എന്നെ അനുസരിച്ചവർ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കും, എന്നെ ധിക്കരിച്ചവരാരോ അവരാണ് നിഷേധിച്ചവർ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 788, 788, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّه رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَتْ مَلَائِكَةٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ نَائِمٌ، فَقَالَ بَعْضُهُمْ: إِنَّهُ نَائِمٌ، وَقَالَ بَعْضُهُمْ: إِنَّ الْعَيْنَ نَائِمَةٌ، وَالْقَلْبَ يَقْظَانُ، فَقَالُوا: إِنَّ لِصَاحِبِكُمْ هَذَا مَثَلًا، فَاضْرِبُوا لَهُ مَثَلًا. فَقَالَ بَعْضُهُمْ: إِنَّهُ نَائِمٌ. وَقَالَ بَعْضُهُمْ: إِنَّ الْعَيْنَ نَائِمَةٌ، وَالْقَلْبَ يَقْظَانُ. فَقَالُوا: مَثَلُهُ كَمَثَلِ رَجُلٍ بَنَى دَارًا، وَجَعَلَ فِيهَا مَأْدُبَةً وَبَعَثَ دَاعِيًا، فَمَنْ أَجَابَ الدَّاعِيَ دَخَلَ الدَّارَ وَأَكَلَ مِنَ الْمَأْدُبَةِ، وَمَنْ لَمْ يُجِبِ الدَّاعِيَ لَمْ يَدْخُلِ الدَّارَ وَلَمْ يَأْكُلْ مِنَ الْمَأْدُبَة. فَقَالُوا: أَوِّلُوهَا لَهُ يَفْقَهْهَا، فَقَالَ بَعْضُهُمْ: إِنَّهُ نَائِمٌ، وَقَالَ بَعْضُهُمْ: إِنَّ الْعَيْنَ نَائِمَةٌ، وَالْقَلْبَ يَقْظَانُ. فَقَالُوا: فَالدَّارُ الْجَنَّةُ، وَالدَّاعِي مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَمَنْ أَطَاعَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَدْ أَطَاعَ اللَّهَ، وَمَنْ عَصَى مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَدْ عَصَى اللَّهَ، وَمُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَّقَ بَيْنَ النَّاسِ. (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) ഉറങ്ങിക്കൊണ്ടിരിക്കെ ചില മലക്കുകൾ അവിടുത്തെ സമീപത്ത് വന്നു. അവരിലൊരാൾ പറഞ്ഞു: അവിടുന്ന് ഉറങ്ങുകയാണ്. മറ്റൊരാൾ പറഞ്ഞു: കണ്ണ് ഉറങ്ങുന്നെങ്കിലും ഹൃദയം ഉണർന്നിരിക്കുകയാണ്. അപ്പോൾ അവർ പറഞ്ഞു: നിങ്ങളുടെ ഈ കൂട്ടുകാരന് ഒരു ഉപമയുണ്ട്. നിങ്ങൾ ആ ഉപമ പറയുക. അപ്പോൾ ഒരാൾ പറഞ്ഞു: അവിടുന്ന് ഉറങ്ങകയാണ്. മറ്റൊരാൾ പറഞ്ഞു: കണ്ണ് ഉറങ്ങുകയാണെങ്കിലും ഹൃദയം ഉണർന്നിരിക്കുകയാണ്. അപ്പോൾ അവർ പറഞ്ഞു: അവിടുത്തെ ഉപമ ഒരു വ്യക്തിയെപ്പോലെയാണ്. ആ വ്യക്തി ഒരു വീട് നിർമ്മിച്ചു. ആ വീട്ടിൽ ഒരു സദ്യ നിശ്ചയിക്കുകയും അതിലേക്ക് ക്ഷണിക്കാൻ ഒരാളെ നിയോഗിക്കുകയും ചെയ്തു. ആ ക്ഷണത്തിനുത്തരം ചെയ്തവൻ വീട്ടിൽ പ്രവേശിക്കുകയും സദ്യയിൽനിന്ന് ഭക്ഷിക്കുകയും ചെയ്യും. ക്ഷണത്തിനുത്തരം ചെയ്യാത്തവൻ വീട്ടിൽ പ്രവേശിക്കുകയോ സദ്യയിൽനിന്ന് ഭക്ഷിക്കുകയോ ചെയ്യില്ല. മലക്കുകൾ പറഞ്ഞു: അവിടുത്തേക്ക് മനസ്സിലാകും വിധം ഈ ഉദാഹരണത്തെ വ്യാഖ്യാനിക്കുക. അപ്പോൾ അവരിലൊരാൾ പറഞ്ഞു: അവിടുന്ന് ഉറങ്ങുകയാണ്. മറ്റൊരാൾ പറഞ്ഞു: കണ്ണ് ഉറങ്ങുന്നെങ്കിലും ഹൃദയം ഉണർന്നിരിക്കുകയാണ്. അവർ (മലക്കുകൾ) പറഞ്ഞു: ആ വീട് സ്വർഗ്ഗമാണ്. അതിലേക്ക് ക്ഷണിക്കുന്നയാൾ മുഹമ്മദ്(സ)യാണ്. മുഹമ്മദ്(സ)യെ അനുസരിച്ചവൻ അല്ലാഹുവിനെയും അനുസരിച്ചിരിക്കുന്നു. മുഹമ്മദ്(സ)യെ ധിക്കരിച്ചവൻ അല്ലാഹുവിനെയും ധിക്കരിച്ചിരിക്കുന്നു. മുഹമ്മദ്(സ)യാണ് ജനങ്ങളെ വേർതിരിച്ചത്². (ബു)', 'جَابِرِ بْنِ عَبْدِاللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', '². മുഹമ്മദ്(സ)യെ അംഗീകരിക്കുക എന്നതാണ് സത്യവിശ്വാസത്തിനുള്ള മാനദണ്ഡം എന്നർത്ഥം', null, array['خ']::text[], array['ബു']::text[], null, null, 788, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ أَبِي عِنَبَةَ الْخَوْلَانِيِّ رَضِيَ اللهُ عَنْهُ - وَكَانَ قَدْ صَلَّى الْقِبْلَتَيْنِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ - قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا يَزَالُ اللَّهُ يَغْرِسُ فِي هَذَا الدِّينِ غَرْسًا يَسْتَعْمِلُهُمْ فِي طَاعَتِه". (جه)', 'അബൂഇനബതുൽ ഖൗലാനി(റ) പറയുന്നു: - റസൂൽ(സ)യോടൊപ്പം രണ്ടു ഖിബ്ലയിലേക്കും തിരിഞ്ഞ് നമസ്കരിച്ചയാളായിരുന്നു അദ്ദേഹം - റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഈ ദീനിൽ ഒരു കൂട്ടരെ അല്ലാഹു വളർത്തിക്കൊണ്ടേയിരിക്കും. അവരെ തന്റെ അനുസരണയ്ക്കുവേണ്ടി ഉപയോഗിക്കുകയും ചെയ്യും." (ജ)', 'أَبِي عِنَبَةَ الْخَوْلَانِيِّ', 'അബൂഇനബതുൽ ഖൗലാനി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ: قَامَ خَطِيبًا فَقَالَ: أَيْنَ عُلَمَاؤُكُمْ؟ أَيْنَ عُلَمَاؤُكُمْ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَقُومُ السَّاعَةُ إِلَّا وَطَائِفَةٌ مِنْ أُمَّتِي ظَاهِرُونَ عَلَى النَّاسِ، لَا يُبَالُونَ مَنْ خَذَلَهُمْ وَلَا مَنْ نَصَرَهُمْ". (ق,جه)', 'മുആവിയ(റ) പ്രസംഗിക്കാൻവേണ്ടി എഴുന്നേറ്റു നിന്നുകൊണ്ട് ചോദിച്ചു: നിങ്ങളിലെ പണ്ഡിതന്മാരെവിടെ? നിങ്ങളിലെ പണ്ഡിതന്മാരെവിടെ? റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ സമുദായത്തിൽപെട്ട ഒരു കൂട്ടർ ജനങ്ങളുടെമേൽ വിജയം കൈവരിക്കുംവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല. തങ്ങളെ സഹായിക്കുന്നവരാരെന്നോ നിസാരമാക്കുന്നവരാരെന്നോ അവർ ഗൗനിക്കുകയില്ല." (ബു,മു,ജ)', 'مُعَاوِيَةَ', 'മുആവിയ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 789, 789, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَزَالُ طَائِفَةٌ مِنْ أُمَّتِي عَلَى الْحَقِّ مَنْصُورِينَ، لَا يَضُرُّهُمْ مَنْ خَالَفَهُمْ، حَتَّى يَأْتِيَ أَمْرُ اللَّهِ عَزَّ وَجَلَّ". (م,ت,جه)', 'സൗബാൻ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിശ്ചയിച്ച കാര്യം സംഭവിക്കുംവരെ എന്റെ സമുദായത്തിൽപെട്ട ഒരു കൂട്ടർ സത്യത്തിന്റെ പേരിൽ സഹായിക്കപ്പെട്ടു കൊണ്ടേയിരിക്കും. തങ്ങളെ എതിർക്കുന്നവർ അവർക്കൊരു പോറലുമേൽപിക്കുകയില്ല." (മു,തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 789, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّه رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَخَطَّ خَطًّا، وَخَطَّ خَطَّيْنِ عَنْ يَمِينِه، وَخَطَّ خَطَّيْنِ عَنْ يَسَارِه، ثُمَّ وَضَعَ يَدَهُ فِي الْخَطِّ الْأَوْسَطِ فَقَالَ: "هَذَا سَبِيلُ اللَّهِ". ثُمَّ تَلَا هَذِهِ الْآيَةَ: {وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيله} [الأنعام: ١٥٣]. (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ നബി(സ)യുടെ അടുത്തായിരിക്കുമ്പോൾ അവിടുന്ന് ഒരു വര വരച്ചു. അതിന്റെ വലതു വശത്തേക്ക് രണ്ട് വരകൾ വരച്ചു. ഇടതു വശത്തേക്കും രണ്ടു വരകൾ വരച്ചു. ശേഷം അവിടുന്ന് നടുവിലുള്ള വരയിൽ തന്റെ കൈ വെച്ചുകൊണ്ട് പറഞ്ഞു: "ഇത് അല്ലാഹുവിന്റെ മാർഗ്ഗമാണ്." ശേഷം അവിടുന്ന് ഈ സൂക്തമോതി: ''നിശ്ചയം ഇതാണ് എന്റെ നേരായ പാത, നിങ്ങളത് പിന്തുടരുക, ഇതര മാർഗ്ഗങ്ങളെ നിങ്ങൾ പിന്തുടരരുത്. പിന്തുടർന്നാൽ നിങ്ങൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽനിന്ന് വേർപെട്ടവരായി മാറും'' (അൻആം: 153). (ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'الأنعام: ١٥٣', null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنِ الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ الْكِنْدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يُوشِكُ الرَّجُلُ مُتَّكِئًا عَلَى أَرِيكَتِه يُحَدَّثُ بِحَدِيثٍ مِنْ حَدِيثِي فَيَقُولُ: بَيْنَنَا وَبَيْنَكُمْ كِتَابُ اللَّهِ عَزَّ وَجَلَّ، فَمَا وَجَدْنَا فِيه مِنْ حَلَالٍ اسْتَحْلَلْنَاهُ، وَمَا وَجَدْنَا فِيه مِنْ حَرَامٍ حَرَّمْنَاهُ. أَلَا وَإِنَّ مَا حَرَّمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِثْلُ مَا حَرَّمَ اللَّهُ". (ت,جه)', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ അൽകിൻദി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ അലങ്കൃതമായ തന്റെ കട്ടിലിന്മേലിരുന്ന് എന്റെ ഹദീസുകളിലൊന്ന് പറയുന്ന കാലം അടുത്തിരിക്കുന്നു. എന്നിട്ടവൻ പറയും: നമുക്കും നിങ്ങൾക്കുമിടയിൽ നിലനിൽക്കുന്നത് അല്ലാഹുവിന്റെ ഗ്രന്ഥമാണ്. അതിൽ ഏതു കാര്യത്തെയാണോ അനുവദനീയമായി കാണുന്നത് അവയെ നാം അനുവദനീയമാക്കും. ഏതു കാര്യത്തെയാണോ നിഷിദ്ധമായി കാണുന്നത് അവയെ നാം നിഷിദ്ധമാക്കും. അറിയുക, നിശ്ചയം റസൂൽ(സ) നിഷിദ്ധമാക്കിയ കാര്യങ്ങൾ അല്ലാഹു നിഷിദ്ധമാക്കിയ കാര്യങ്ങളെപ്പോലെ തന്നെയാണ്." (തു,ജ)', 'الْمِقْدَامِ بْنِ مَعْدِيكَرِبَ الْكِنْدِيِّ', 'മിഖ്ദാമുബ്നു മഅ്ദീകരിബ അൽകിൻദി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي رَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا أُلْفِيَنَّ أَحَدَكُمْ مُتَّكِئًا عَلَى أَرِيكَتِه، يَأْتِيه الْأَمْرُ مِمَّا أَمَرْتُ بِه أَوْ نَهَيْتُ عَنْهُ، فَيَقُولُ: لَا أَدْرِي، مَا وَجَدْنَا فِي كِتَابِ اللَّهِ اتَّبَعْنَاهُ". (د,ت,جه)', 'അബൂറാഫിഅ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ കട്ടിലിന് മുകളിൽ ചാരിയിരിക്കുകയും, എന്നിട്ട് ഞാൻ കൽപിക്കുകയോ നിരോധിക്കുകയോ ചെയ്ത ഒരു കാര്യത്തെ സംബന്ധിച്ച് അറിയുമ്പോൾ; എനിക്കറിയില്ല, അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ കണ്ടതിനെ ഞങ്ങൾ പിന്തുടരും എന്ന് പറയുന്ന അവസ്ഥയിൽ നിങ്ങളിലൊരുത്തനെയും ഞാൻ എത്തിക്കാതിരിക്കട്ടെ." (ദ,തു,ജ)', 'أَبِي رَافِعٍ', 'അബൂറാഫിഅ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أَحْدَثَ فِي أَمْرِنَا هَذَا مَا لَيْسَ فِيهِ فَهُوَ رَدٌّ". وَفِي رِوَايَةٍ: "مَنْ صَنَعَ أَمْرًا عَلَى غَيْرِ أَمْرِنَا فَهُوَ رَدٌّ". (ق,د,جه)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "നമ്മുടെ ഇക്കാര്യത്തിൽ അതിലില്ലാത്ത വല്ലതും ഒരാൾ പുതുതായി ഉണ്ടാക്കിയാൽ അത് തള്ളപ്പെടേണ്ടതാണ്." മറ്റൊരു നിവേദനം: "നമ്മുടെ അടിസ്ഥാനത്തിലുള്ളതല്ലാത്ത കാര്യത്തെ ഒരാൾ പടച്ചുണ്ടാക്കിയാൽ അത് തള്ളപ്പെടേണ്ടതാണ്." (ബു,മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 790, 790, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=36), 1, 'وَفِي رِوَايَةٍ: "مَنْ صَنَعَ أَمْرًا عَلَى غَيْرِ أَمْرِنَا فَهُوَ رَدٌّ". (ق,د,جه)', 'മറ്റൊരു നിവേദനം: "നമ്മുടെ അടിസ്ഥാനത്തിലുള്ളതല്ലാത്ത കാര്യത്തെ ഒരാൾ പടച്ചുണ്ടാക്കിയാൽ അത് തള്ളപ്പെടേണ്ടതാണ്." (ബു,മു,ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ اللَّه بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا مِنَ الْأَنْصَار خَاصَمَ الزُّبَيْرَ عِنْدَ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فِي شِرَاجِ الْحَرَّة الَّتِي يَسْقُونَ بِهَا النَّخْلَ. فَقَالَ الْأَنْصَارِيُّ: سَرِّحِ الْمَاءَ يَمُرُّ. فَأَبَى عَلَيْه، فَاخْتَصَمَا عِنْدَ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ، فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "اسْقِ يَا زُبَيْرُ، ثُمَّ أَرْسِلِ الْمَاءَ إِلَى جَارِكَ". فَغَضِبَ الْأَنْصَارِيُّ، فَقَالَ: يَا رَسُولَ اللَّه، أَنْ كَانَ ابْنَ عَمَّتِكَ؟ فَتَلَوَّنَ وَجْهُ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ، ثُمَّ قَالَ: "يَا زُبَيْرُ، اسْقِ، ثُمَّ احْبِسِ الْمَاءَ حَتَّى يَرْجِعَ إِلَى الْجَدْرِ". قَالَ: فَقَالَ الزُّبَيْرُ: وَاللَّه، إِنِّي لَأَحْسِبُ هَذِه الْآيَةَ نَزَلَتْ فِي ذَلِكَ: {فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّى يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنْفُسِهِمْ حَرَجًا مِمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا} [النساء: ٦٥]. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ഈത്തപ്പനകൾ നനയ്ക്കാനുപയോഗിക്കുന്ന ഹർറയിലെ നീർചാലുകളുടെ കാര്യത്തിൽ റസൂൽ(സ)യുടെ സമീപത്തുവെച്ച് അൻസാരികളിലൊരാൾ സുബൈർ(റ)വിനോട് തർക്കിച്ചു. അൻസാരി പറഞ്ഞു: താങ്കൾ വെള്ളം ഒഴിക്കിവിടുക. പക്ഷേ, സുബൈർ(റ) സമ്മതിച്ചില്ല. അങ്ങനെ രണ്ടുപേരും റസൂൽ(സ)യോട് പരാതി പറഞ്ഞു. റസൂൽ(സ) പറഞ്ഞു: "സുബൈറേ, നീ നനയ്ക്കുക. ശേഷം വെള്ളം നിന്റെ അയൽക്കാരനുവേണ്ടി ഒഴുക്കിവിടുക." അപ്പോൾ അൻസാരി ദേഷ്യപ്പെട്ടുകൊണ്ട് ചോദിച്ചു: റസൂലേ, സുബൈർ(റ) അങ്ങയുടെ പിതൃവ്യപുത്രനായതു കൊണ്ടാണോ ഇപ്രാകാരം ചെയ്തത്? ഉടനെ റസൂൽ(സ)യുടെ മുഖം വിവർണ്ണമായി, എന്നിട്ട് പറഞ്ഞു: "സുബൈറേ, നീ നനയ്ക്കുക, ശേഷം മതിലിനു സമമായി എത്തുംവരെ വെള്ളം തടഞ്ഞുവെക്കുകയും ചെയ്യുക." നിവേദകൻ പറഞ്ഞു: സുബൈർ(റ) പറയുന്നു: അല്ലാഹുവാണ, ''അങ്ങയുടെ നാഥൻതന്നെയാണ് സത്യം, തങ്ങൾക്കിടയിൽ ഉടലെടുക്കുന്ന പ്രശ്നങ്ങളിൽ അങ്ങയെ തീർപുകാരനാക്കുകയും അങ്ങ് വിധിക്കുന്ന കാര്യങ്ങൾ ഒരു മനഃക്ലേശവുമില്ലാതെ പൂർണ്ണമായി അംഗീകരിക്കുകയും ചെയ്യുംവരെ അവർ സത്യവിശ്വാസികളാവുകയില്ല'' (നിസാഅ്: 65) എന്ന സൂക്തം ഈ വിഷയത്തിലാണ് അവതരിക്കപ്പെട്ടത് എന്ന് ഞാൻ കരുതുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللَّه بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], 'النساء: ٦٥', null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَمْنَعُوا إِمَاءَ اللَّهِ أَنْ يُصَلِّينَ فِي الْمَسْجِدِ". فَقَالَ ابْنٌ لَهُ: إِنَّا لَنَمْنَعُهُنَّ. فَغَضِبَ غَضَبًا شَدِيدًا وَقَالَ: أُحَدِّثُكَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَقُولُ: إِنَّا لَنَمْنَعُهُنَّ؟ (خ,جه)', 'ഇബ്നുഉമർ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ അടിമസ്ത്രീകൾ, പള്ളിയിൽ നമസ്കരിക്കുന്നതിനെ നിങ്ങൾ തടയരുത്." അപ്പോൾ ഇബ്നുഉമർ(റ)വിന്റെ മകൻ ചോദിച്ചു: നാം അവരെ തടയാറുണ്ടല്ലോ? ഉടനെ ഇബ്നുഉമർ(റ) ദേഷ്യപ്പെട്ടുകൊണ്ട് പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യുടെ ഹദീസ് പറഞ്ഞു തരുമ്പോൾ, ''നാം അവരെ തടയാറുണ്ടല്ലോ'' എന്ന് നീ ചോദിക്കുന്നുവോ? (ബു,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 791, 791, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ جَالِسًا إِلَى جَنْبِه ابْنُ أَخٍ لَهُ، فَخَذَفَ فَنَهَاهُ، وَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهَا، وَقَالَ: "إِنَّهَا لَا تَصِيدُ صَيْدًا وَلَا تَنْكِي عَدُوًّا، وَإِنَّهَا تَكْسِرُ السِّنَّ وَتَفْقَأُ الْعَيْنَ". قَالَ: فَعَادَ ابْنُ أَخِيه يَخْذِفُ، فَقَالَ: أُحَدِّثُكَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْهَا، ثُمَّ عُدْتَ تَخْذِفُ؟ لَا أُكَلِّمُكَ أَبَدًا. (م,جه)', 'അബ്ദുല്ലാഹിബ്നു മുഗഫൽ(റ): അദ്ദേഹത്തിന്റെ സമീപം ഇരുന്നുകൊണ്ട് തന്റെ സഹോദര പുത്രൻ ചരൽ വാരിയെറിഞ്ഞു. ഉടനെ അദ്ദേഹം അവനെ വിലക്കുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: അപ്രകാരം ചെയ്യുന്നത് റസൂൽ(സ) നിരോധിച്ചിട്ടുണ്ട്. റസൂൽ(സ) പറഞ്ഞു: "അത് ഒരു മൃഗത്തെയും വേട്ടയാടാൻ ഉപകരിക്കുകയോ ശത്രുവിന് പരിക്കേൽപിക്കുകയോ ചെയ്യില്ല. നിശ്ചയമത് പല്ല് പൊട്ടിക്കുകയും കണ്ണിന്റെ കാഴ്ച നശിപ്പിക്കുകയും ചെയ്യും.'''' നവേദകൻ പറയുന്നു: വീണ്ടും തന്റെ സഹോദരപുത്രൻ അപ്രകാരം ചെയ്തു. അപ്പോൾ അബ്ദുല്ല(റ) പറഞ്ഞു: റസൂൽ(സ) നിരോധിച്ചെന്ന് ഞാൻ പറഞ്ഞു തന്നിട്ടും നീ ചരൽ എറിയുന്നുവോ? ഇനി ഞാൻ നിന്നോട് സംസാരിക്കുകയില്ല. (മു,ജ)', 'عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ', 'അബ്ദുല്ലാഹിബ്നു മുഗഫൽ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 791, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ عُبَادَةَ بْنِ الصَّامِت الْأَنْصَارِيِّ رَضِيَ اللهُ عَنْهُ: غَزَا مَعَ مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ أَرْضَ الرُّومِ، فَنَظَرَ إِلَى النَّاسِ وَهُمْ يَتَبَايَعُونَ كِسَرَ الذَّهَب بِالدَّنَانِير، وَكِسَرَ الْفِضَّة بِالدَّرَاهِمِ، فَقَالَ: يَا أَيُّهَا النَّاسُ، إِنَّكُمْ تَأْكُلُونَ الرِّبَا، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَا تَبْتَاعُوا الذَّهَبَ بِالذَّهَب إِلَّا مِثْلًا بِمِثْلٍ، لَا زِيَادَةَ بَيْنَهُمَا وَلَا نَظِرَةً". فَقَالَ لَهُ مُعَاوِيَةُ: يَا أَبَا الْوَلِيد، لَا أَرَى الرِّبَا فِي هَذَا إِلَّا مَا كَانَ مِنْ نَظِرَة. فَقَالَ عُبَادَةُ: أُحَدِّثُكَ عَنْ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ وَتُحَدِّثُنِي عَنْ رَأْيِكَ! لَئِنْ أَخْرَجَنِي اللَّهُ لَا أُسَاكِنُكَ بِأَرْضٍ لَكَ عَلَيَّ فِيهَا إِمْرَةٌ. فَلَمَّا قَفَلَ لَحِقَ بِالْمَدِينَة، فَقَالَ لَهُ عُمَرُ بْنُ الْخَطَّاب رَضِيَ اللهُ عَنْهُ: مَا أَقْدَمَكَ يَا أَبَا الْوَلِيد؟ فَقَصَّ عَلَيْه الْقِصَّةَ، وَمَا قَالَ مِنْ مُسَاكَنَته. فَقَالَ: ارْجِعْ يَا أَبَا الْوَلِيد إِلَى أَرْضِكَ، فَقَبَحَ اللَّهُ أَرْضًا لَسْتَ فِيهَا وَأَمْثَالُكَ. وَكَتَبَ إِلَى مُعَاوِيَةَ: لَا إِمْرَةَ لَكَ عَلَيْه، وَاحْمِلِ النَّاسَ عَلَى مَا قَالَ، فَإِنَّهُ هُوَ الْأَمْرُ. (جه)', 'ഉബാദതുബ്നു സ്വാമിതുൽ അൻസ്വാരി(റ): അദ്ദേഹം മുആവിയ(റ)വിനോടൊപ്പം റോമിനോട് യുദ്ധംചെയ്യാൻ പോയി. അപ്പോൾ, ദീനാറുകൾ കൊടുത്ത് ജനങ്ങൾ സ്വർണ്ണക്കഷ്ണങ്ങൾ വാങ്ങുന്നതും ദിർഹമുകൾ കൊടുത്ത് വെള്ളിക്കഷ്ണങ്ങൾ വാങ്ങുന്നതും അദ്ദേഹം കണ്ടു. അദ്ദേഹം പറഞ്ഞു: ജനങ്ങളേ, നിങ്ങൾ ഭക്ഷിക്കുന്നത് പലിശയാണ്. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "പരസ്പരം ഏറ്റക്കുറച്ചിലോ കാലതാമസമോ ഉണ്ടാവാത്തവിധം സമാസമം ആയിട്ടല്ലാതെ നിങ്ങൾ സ്വർണ്ണത്തിനു പകരം സ്വർണ്ണം വാങ്ങരുത്." അപ്പോൾ മുആവിയ(റ) അദ്ദേഹത്തോട് പറഞ്ഞു: അബുൽവലീദേ, കാലതാമസം ഉണ്ടായാൽ മാത്രമേ ഇതിൽ പലിശയുണ്ടാകൂ എന്നാണ് എന്റെ അഭിപ്രായം. ഉബാദ(റ) പറഞ്ഞു: ഞാൻ റസൂൽ(സ)യുടെ ഹദീസ് പറഞ്ഞു തരുമ്പോൾ താങ്കൾ എന്നോട് സ്വന്തം അഭിപ്രായമാണ് പറയുന്നത്! അല്ലാഹു എനിക്ക് പുറത്തുപോകാൻ അവസരം തന്നാൽ താങ്കൾക്ക് എന്റെമേൽ അധികാരമുള്ള ഒരു പ്രദേശത്തും ഞാൻ താങ്കളോടൊപ്പം വസിക്കുകയില്ല. അങ്ങനെ അവർ മടങ്ങിയെത്തിയപ്പോൾ ഉബാദ(റ) മദീനയിലേക്ക് പോയി. അപ്പോൾ ഉമറുബ്നുൽ ഖത്വാബ്(റ) ചോദിച്ചു: അബുൽവലീദേ, താങ്കൾ എന്തുകൊണ്ടാണ് ഇങ്ങോട്ട് വന്നത്? ഉടനെ ഉബാദ(റ) സംഭവിച്ച കാര്യവും കൂടെ താമസിക്കുന്നതിനെ സംബന്ധിച്ച് താൻ പറഞ്ഞതുമെല്ലാം പറഞ്ഞുകൊടുത്തു. ഉമർ(റ) പറഞ്ഞു: അബുൽവലീദേ, താങ്കൾ നാട്ടിലേക്ക് മടങ്ങുക. താങ്കളും താങ്കളെപ്പോലുള്ളവരും ഇല്ലാത്ത നാടിനെ അല്ലാഹു പരാജയപ്പെടുത്തും. ശേഷം ഉമർ(റ) മുആവിയ(റ)വിന് ഇപ്രകാരം എഴുതി: താങ്കൾക്ക് ഉബാദ(റ)വിനുമേൽ ഒരു അധികാരവുമില്ല, ഉബാദ(റ) പറഞ്ഞതനുസരിച്ച് ജനങ്ങളെ പ്രവർത്തിപ്പിക്കുക, നിശ്ചയം അതു തന്നെയാണ് യാഥാർത്ഥ്യം. (ജ)', 'عُبَادَةَ بْنِ الصَّامِت الْأَنْصَارِيِّ', 'ഉബാദതുബ്നു സ്വാമിതുൽ അൻസ്വാരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 792, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِب رَضِيَ اللهُ عَنْهُ قَالَ: إِذَا حَدَّثْتُكُمْ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا فَظُنُّوا بِهِ الَّذِي هُوَ أَهْنَاهُ وَأَهْدَاهُ وَأَتْقَاهُ. (جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): ഞാൻ നിങ്ങൾക്ക് റസൂൽ(സ)യുടെ ഒരു ഹദീസ് പറഞ്ഞുതരുമ്പോൾ ഏറ്റവും അനുയോജ്യവും സാന്മാർഗ്ഗികവും ഭക്തിപരവുമായ കാര്യങ്ങളെ റസൂൽ(സ)യിൽ നിങ്ങൾ ഭാവിക്കുക. (ജ)', 'عَلِيِّ بْنِ أَبِي طَالِب', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 792, 792, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: "لَا أَعْرِفَنَّ مَا يُحَدَّثُ أَحَدُكُمْ عَنِّي الْحَدِيثَ وَهُوَ مُتَّكِئٌ عَلَى أَرِيكَتِه، فَيَقُولُ: اقْرَأْ قُرْآنًا. مَا قِيلَ مِنْ قَوْلٍ حَسَنٍ فَأَنَا قُلْتُهُ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "അലങ്കൃതമായ തന്റെ കട്ടിലിലിരിക്കുന്ന നിങ്ങളിൽ ഒരുത്തനോട് ഞാൻ പറഞ്ഞ ഹദീസ് പറയപ്പെടുമ്പോൾ, നീ ഖുർആൻ പാരായണം ചെയ്യുക എന്ന് അവൻ പറയുന്ന ഒരു അവസ്ഥയെ ഞാൻ അറിയാതിരിക്കട്ടെ. എന്നാൽ നന്മയടങ്ങുന്ന സർവ്വ വാക്കുകളും പറഞ്ഞത് ഞാനാണ്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 792, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ لِرَجُلٍ: يَا ابْنَ أَخِي، إِذَا حَدَّثْتُكَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا فَلَا تَضْرِبْ لَهُ الْأَمْثَالَ. (جه)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം ഒരാളോട് പറഞ്ഞു: സഹോദര പുത്രാ, റസൂൽ(സ)യുടെ വല്ല ഹദീസും ഞാൻ നിനക്ക് പറഞ്ഞുതരുമ്പോൾ നീ അതിന് മറ്റു ഉപമകൾ കൊണ്ടുവരരുത്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ عَمْرِو بْنِ مَيْمُونٍ قَالَ: مَا أَخْطَأَنِي ابْنُ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ عَشِيَّةَ خَمِيسٍ إِلَّا أَتَيْتُهُ فِيه، فَمَا سَمِعْتُهُ يَقُولُ بِشَيْءٍ قَطُّ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا كَانَ ذَاتَ عَشِيَّةٍ قَالَ: قَالَ رَسُولُ اللَّه قَالَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَنَكَسَ، فَنَظَرْتُ إِلَيْه فَهُوَ قَائِمٌ مُحَلَّلَةً أَزْرَارُ قَمِيصِه، قَد اغْرَوْرَقَتْ عَيْنَاهُ، وَانْتَفَخَتْ أَوْدَاجُهُ. قَالَ: أَوْ دُونَ ذَلِكَ، أَوْ: فَوْقَ ذَلِكَ، أَوْ: قَرِيبًا مِنْ ذَلِكَ، أَوْ: شَبِيهًا بِذَلِكَ. (جه)', 'അംറുബ്നു മൈമൂൻ(റ): ഞാൻ എല്ലാ വ്യാഴാഴ്ചയും വൈകുന്നേര സമയം ഇബ്നുമസ്ഊദ്(റ)വിന്റെ അടുത്ത് പോകാറുണ്ടായിരുന്നു. ഒരിക്കൽപോലും ''റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞു''വെന്ന് അദ്ദേഹം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ടായിരുന്നില്ല. അങ്ങനെയിരിക്കെ, ഒരു വൈകുന്നേരം ''റസൂൽ(സ) ഇപ്രകാരം പറഞ്ഞു''വെന്ന് അദ്ദേഹം പറഞ്ഞു. ശേഷം അദ്ദേഹം തന്റെ തല താഴ്ത്തി. ഞാൻ നോക്കുമ്പോൾ അദ്ദേഹം തന്റെ വസ്ത്രത്തിന്റെ കുടുക്കഴിച്ചിട്ട് എഴുന്നേറ്റ് നിൽക്കുകയായിരുന്നു. അദ്ദേഹത്തിന്റെ കണ്ണുകൾ നിറയുകയും പിരടിയിലെ ഞെരമ്പുകൾ വീർക്കുകയും ചെയ്തിരുന്നു. ശേഷം അദ്ദേഹം പറഞ്ഞു: അല്ലെങ്കിൽ അതിനേക്കാൾ കുറവ്, അല്ലെങ്കിൽ അതിനേക്കാൾ കൂടുതൽ, അല്ലെങ്കിൽ അതിനോടടുത്ത്, അല്ലെങ്കിൽ അതുപോലെ (താൻ റസൂൽ(സ)യെക്കുറിച്ച് പറയുന്നത് കളവാകാതിരിക്കാൻ വേണ്ടിയാണിത്). (ജ)', 'عَمْرِو بْنِ مَيْمُونٍ قَالَ', 'അംറുബ്നു മൈമൂൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ مُحَمَّدِ بْنِ سِيرِينَ قَالَ: كَانَ أَنَسُ بْنُ مَالِك رَضِيَ اللهُ عَنْهُ إِذَا حَدَّثَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا فَفَرَغَ مِنْهُ قَالَ: أَوْ كَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (جه)', 'മുഹമ്മദുബ്നു സീരീൻ(റ): അനസുബ്നു മാലിക്(റ) റസൂൽ(സ)യുടെ ഹദീസ് പറഞ്ഞുതന്ന് അതിൽനിന്ന് വിരമിച്ചാൽ ഇപ്രകാരം പറയുമായിരുന്നു: ''അല്ലെങ്കിൽ റസൂൽ(സ) പറഞ്ഞതുപോലെ.'' (ജ)', 'مُحَمَّدِ بْنِ سِيرِينَ قَالَ', 'മുഹമ്മദുബ്നു സീരീൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى قَالَ: قُلْنَا لِزَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ: حَدِّثْنَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: كَبِرْنَا وَنَسِينَا، وَالْحَدِيثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَدِيدٌ. (جه)', 'അബ്ദുറഹ്മാനുബ്നു അബീലൈല(റ): ഞങ്ങൾ സൈദുബ്നു അർഖം(റ)വിനോട് പറഞ്ഞു: അങ്ങ് ഞങ്ങൾക്ക് റസൂൽ(സ)യുടെ ഹദീസ് പറഞ്ഞു തരിക. അദ്ദേഹം പറഞ്ഞു: നമുക്ക് പ്രായമാവുകയും മറവി അധികരിക്കുകയും ചെയ്തു. റസൂൽ(സ)യുടെ ഹദീസ് പറഞ്ഞുതരിക എന്നത് ഗൗരവമേറിയ വിഷയമാണ്. (ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى قَالَ', 'അബ്ദുറഹ്മാനുബ്നു അബീലൈല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنِ الشَّعْبِيِّ قَالَ: جَالَسْتُ ابْنَ عُمَرَ سَنَةً، فَمَا سَمِعْتُهُ يُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَيْئًا. (ق,جه)', 'ശഅ്ബി(റ): ഒരു വർഷത്തോളം ഞാൻ ഇബ്നുഉമർ(റ)വിന്റെ കൂടെ കഴിഞ്ഞു. എന്നിട്ടും റസൂൽ(സ)യിൽ നിന്ന് അദ്ദേഹം ഒന്നും ഉദ്ധരിക്കുന്നത് ഞാൻ കേട്ടിട്ടില്ല. (ബു,മു,ജ)', 'الشَّعْبِيِّ قَالَ', 'ശഅ്ബി(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 793, 793, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إِنَّمَا كُنَّا نَحْفَظُ الْحَدِيثَ، وَالْحَدِيثُ يُحْفَظُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَمَّا إِذَا رَكِبْتُمُ الصَّعْبَ وَالذَّلُولَ، فَهَيْهَاتَ. (م,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞങ്ങൾ ഹദീസ് മനഃപ്പാഠമാക്കുമായിരുന്നു. റസൂൽ(സ)യിൽ നിന്നുള്ള ഹദീസ് സൂക്ഷിക്കപ്പെടേണ്ടതു തന്നെയാണ്. എന്നാൽ നിങ്ങൾ ഏറ്റക്കുറച്ചിലുകൾ വരുത്തിയാൽ അത് സാധ്യമല്ല. (മു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ قَرَظَةَ بْنِ كَعْب قَالَ: بَعَثَنَا عُمَرُ بْنُ الْخَطَّاب رَضِيَ اللهُ عَنْهُ إِلَى الْكُوفَة وَشَيَّعَنَا، فَمَشَى مَعَنَا إِلَى مَوْضِعٍ يُقَالُ لَهُ صِرَارٌ، فَقَالَ: أَتَدْرُونَ لِمَ مَشَيْتُ مَعَكُمْ؟ قَالَ: قُلْنَا: لِحَقِّ صُحْبَة رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِحَقِّ الْأَنْصَار. قَالَ: لَكِنِّي مَشَيْتُ مَعَكُمْ لِحَدِيث أَرَدْتُ أَنْ أُحَدِّثَكُمْ بِه، وَأَرَدْتُ أَنْ تَحْفَظُوهُ لِمَمْشَايَ مَعَكُمْ. إِنَّكُمْ تَقْدَمُونَ عَلَى قَوْمٍ، لِلْقُرْآنِ فِي صُدُورِهِمْ هَزِيزٌ كَهَزِيزِ الْمِرْجَل، فَإِذَا رَأَوْكُمْ مَدُّوا إِلَيْكُمْ أَعْنَاقَهُمْ، وَقَالُوا: أَصْحَابُ مُحَمَّد. فَأَقِلُّوا الرِّوَايَةَ عَنْ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ أَنَا شَرِيكُكُمْ. (جه)', 'ഖറളതുബ്നു കഅ്ബ്(റ): ഉമറുബ്നുൽ ഖത്വാബ്(റ) ഞങ്ങളെ കൂഫയിലേക്ക് പറഞ്ഞയക്കുകയും യാത്രാ സാമഗ്രികൾ ഒരുക്കിത്തരികയും ചെയ്തു. ശേഷം സ്വിറാർ എന്ന സ്ഥലംവരെ ഞങ്ങളോടൊപ്പം നടന്നുവന്നു, എന്നിട്ട് ചോദിച്ചു: എന്തിനാണ് ഞാൻ നിങ്ങളോടൊപ്പം നടന്നുവന്നതെന്ന് നിങ്ങൾക്കറിയുമോ? നിവേദകൻ പറയുന്നു: ഞങ്ങൾ പറഞ്ഞു: റസൂൽ(സ)യുടെ സ്വാഹാബികളും അൻസാരികളും (സഹായികൾ) ആണെന്ന ബാധ്യത കാരണത്താലല്ലേ? ഉമർ(റ) പറഞ്ഞു: എന്നാൽ ഞാൻ നിങ്ങളോടൊപ്പം നടന്നുവന്നത് നിങ്ങൾക്ക് ഒരു ഹദീസ് പറഞ്ഞുതരണമെന്ന് ആഗ്രഹിച്ചതിനാലാണ്. ഞാൻ നിങ്ങളോടൊപ്പം നടക്കുന്നത് കാരണത്താൽ നിങ്ങളത് മനഃപ്പാഠമാക്കണമെന്ന് ഞാൻ ആഗ്രഹിച്ചു. ഖുർആൻ കാരണത്താൽ തങ്ങളുടെ നെഞ്ചുകൾക്ക് കലം തിളക്കുമ്പോൾ ഉണ്ടാകുന്നതു പോലെയുള്ള ശബ്ദമുള്ള ഒരു സമൂഹത്തിന്റെ അടുത്തേക്കാണ് നിങ്ങൾ പോകുന്നത്. നിങ്ങളെ കണ്ടാൽ അവർ എത്തിനോക്കി മുഹമ്മദ്(സ)യുടെ അനുചരരാണല്ലോ എന്ന് പറയും. അതിനാൽ റസൂൽ(സ)യിൽനിന്ന് ഹദീസ് നിവേദനം ചെയ്യുന്നതിനെ നിങ്ങൾ കുറയ്ക്കുക. പിന്നെ ഞാൻ നിങ്ങളുടെ സഹചാരി തന്നെയാണ്. (ജ)', 'قَرَظَةَ بْنِ كَعْب قَالَ', 'ഖറളതുബ്നു കഅ്ബ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنِ السَّائِبِ بْنِ يَزِيدَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: صَحِبْتُ سَعْدَ بْنَ مَالِكٍ – رَضِيَ اللَّهُ عَنْهُ – مِنَ الْمَدِينَةِ إِلَى مَكَّةَ، فَمَا سَمِعْتُهُ يُحَدِّثُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَدِيثٍ وَاحِدٍ. (جه)', 'സാഇബുബ്നു യസീദ്(റ): മദീന മുതൽ മക്കവരെ ഞാൻ സഅ്ദുബ്നു മാലിക്(റ)വിന്റെ കൂടെ ഉണ്ടായിരുന്നു. എന്നിട്ടും അദ്ദേഹം റസൂൽ(സ)യിൽ നിന്നുള്ള ഒരു ഹദീസ് പോലും പറയുന്നത് ഞാൻ കേട്ടില്ല. (ജ)', 'السَّائِبِ بْنِ يَزِيدَ', 'സാഇബുബ്നു യസീദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും മനഃപ്പൂർവ്വം എന്റെ പേരിൽ കളവ് പറഞ്ഞാൽ നരകത്തിലെ തന്റെ ഇരിപ്പിടം അവൻ ഒരുക്കിക്കൊള്ളട്ടെ." (തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 794, 794, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا تَكْذِبُوا عَلَيَّ، فَإِنَّ الْكَذِبَ عَلَيَّ يُولِجُ النَّارَ". (ق,ت,جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ പേരിൽ നിങ്ങൾ കളവ് പറയരുത്, എന്റെ പേരിൽ കളവ് പറയൽ നരകത്തിൽ പ്രവേശിപ്പിക്കുന്ന കാര്യമാണ്." (ബു,മു,തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 794, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ عَلَى هَذَا الْمِنْبَرِ: "إِيَّاكُمْ وَكَثْرَةَ الْحَدِيثِ عَنِّي، فَمَنْ قَالَ عَلَيَّ فَلْيَقُلْ حَقًّا أَوْ صِدْقًا، وَمَنْ تَقَوَّلَ عَلَيَّ مَا لَمْ أَقُلْ فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (جه)', 'അബൂഖതാദ(റ): ഈ മിമ്പറിൽ കയറി റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "എന്നെക്കുറിച്ച് കൂടുതൽ ഹദീസ് ഉദ്ധരിക്കുന്നത് നിങ്ങൾ സൂക്ഷിക്കുക. ആരെങ്കിലും എന്റെ പേരിൽ വല്ലതും പറയുന്നുവെങ്കിൽ യാഥാർത്ഥ്യമോ സത്യമോ മാത്രമേ പറയാവൂ. ഞാൻ പറഞ്ഞിട്ടില്ലാത്ത കാര്യം ഒരാൾ എന്റെ പേരിൽ ഉണ്ടാക്കിപ്പറഞ്ഞാൽ നരകത്തിലെ തന്റെ ഇരിപ്പിടം അവൻ തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا قَالَ: قُلْتُ لِلزُّبَيْرِ بْنِ الْعَوَّامِ: مَا لِيَ لَا أَسْمَعُكَ تُحَدِّثُ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَمَا أَسْمَعُ ابْنَ مَسْعُود وَفُلَانًا وَفُلَانًا؟ قَالَ: أَمَا إِنِّي لَمْ أُفَارِقْهُ مُنْذُ أَسْلَمْتُ، وَلَكِنِّي سَمِعْتُ مِنْهُ كَلِمَةً يَقُولُ: "مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ". (خ,د,جه)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): ഞാൻ സുബൈറുബ്നുൽ അവ്വാം(റ)വിനോട് ചോദിച്ചു: ഇബ്നുമസ്ഊദ്(റ)വിനെയും ഇന്നാലിന്ന വ്യക്തികളെയും പോലെ താങ്കൾ റസൂൽ(സ)യുടെ ഹദീസ് ഉദ്ധരിക്കുന്നത് എന്താണ് ഞാൻ കേൾക്കാത്തത്? അദ്ദേഹം പറഞ്ഞു: ഞാൻ മുസ്ലിമായതുതൊട്ട് റസൂൽ(സ)യെ പിരിഞ്ഞിട്ടില്ല. പക്ഷേ, റസൂൽ(സ)യിൽനിന്ന് ഞാൻ ഒരു വാക്ക് കേട്ടു; അവിടുന്ന് പറയുന്നു: "മനഃപ്പൂർവ്വം ആരെങ്കിലും എന്റെ പേരിൽ കളവ് പറഞ്ഞാൽ നരകത്തിലെ തന്റെ ഇരിപ്പിടം അവൻ തയ്യാറാക്കിക്കൊള്ളട്ടെ." (ബു,ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ حَدَّثَ عَنِّي حَدِيثًا، وَهُوَ يَرَى أَنَّهُ كَذِبٌ، فَهُوَ أَحَدُ الْكَاذِبَيْنِ". (م,ت,جه)', 'അലി(റ): നബി(സ) പറഞ്ഞു: "കളവാണെന്നറിഞ്ഞിട്ടും ഒരാൾ എന്റെ പേരിലുള്ള ഹദീസ് ഉദ്ധരിച്ചാൽ അവൻ രണ്ട് നുണയന്മാരിൽ ഒരുവനാണ്." (മു,തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 795, 795, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللَّهُ عَنْهُ – وَهُوَ مِمَّنْ نَزَلَ فِيهِ: {وَلَا عَلَى الَّذِينَ إِذَا مَا أَتَوْكَ لِتَحْمِلَهُمْ قُلْتَ لَا أَجِدُ مَا أَحْمِلُكُمْ عَلَيْهِ} [التوبة: ٩٢] – قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ، ثُمَّ أَقْبَلَ عَلَيْنَا، فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً ذَرَفَتْ مِنْهَا الْعُيُونُ وَوَجِلَتْ مِنْهَا الْقُلُوبُ، فَقَالَ قَائِلٌ: يَا رَسُولَ اللَّهِ، كَأَنَّ هَذِهِ مَوْعِظَةُ مُوَدِّعٍ، فَمَاذَا تَعْهَدُ إِلَيْنَا؟ فَقَالَ: "أُوصِيكُمْ بِتَقْوَى اللَّهِ، وَالسَّمْعِ وَالطَّاعَةِ وَإِنْ عَبْدًا حَبَشِيًّا، فَإِنَّهُ مَنْ يَعِشْ مِنْكُمْ بَعْدِي فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِسُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الْمَهْدِيِّينَ الرَّاشِدِينَ، تَمَسَّكُوا بِهَا وَعَضُّوا عَلَيْهَا بِالنَّوَاجِذِ. وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ، فَإِنَّ كُلَّ مُحْدَثَةٍ بِدْعَةٌ، وَكُلَّ بِدْعَةٍ ضَلَالَةٌ". (د,ت,جه)', 'ഇർബാളുബ്നു സാരിയ(റ): - ''തങ്ങളെയും കൂടെ കൊണ്ടുപോകാൻവേണ്ടി അങ്ങയുടെ അടുത്ത് വരുമ്പോൾ, നിങ്ങളെ കൊണ്ടുപോകാൻ ആവശ്യമായ സാമഗ്രികൾ എന്റെ അടുത്തില്ല എന്ന് അങ്ങ് പറയുന്ന വിഭാഗത്തിനും'' (തൗബ: 92) എന്ന സൂക്തമിറങ്ങിയ കൂട്ടരിൽപെട്ട ആളാണ് നിവേദകൻ - അദ്ദേഹം പറയുന്നു: ഒരു ദിവസം റസൂൽ(സ) ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. ശേഷം ഞങ്ങളിലേക്ക് തിരിഞ്ഞുകൊണ്ട് ഹൃദയങ്ങൾ വേധനിക്കുംവിധം, കണ്ണുകൾ നിറഞ്ഞൊലിക്കും വിധം ഒരു പ്രസംഗം പ്രസംഗിച്ചു. അപ്പോൾ ഒരാൾ ചോദിച്ചു: റസൂലേ, യാത്രചോദിക്കുന്നവന്റെ പ്രസംഗം പോലെയുണ്ടല്ലോ ഇത്, അതിനാൽ എന്താണ് അങ്ങ് ഞങ്ങളോട് കരാർ ചെയ്യുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന് തഖ്വ ചെയ്യണമെന്നും, അബ്സീനിയക്കാരനായ അടിമയോടാണെങ്കിലും അനുസരണ കാണിക്കണമെന്നും ഞാൻ നിങ്ങളോട് വസ്വിയ്യത് ചെയ്യുന്നു. എന്റെ കാലശേഷം നിങ്ങളിലാരെങ്കിലും ജീവിച്ചിരിക്കുന്നുവെങ്കിൽ അവന് ധാരാളം അഭിപ്രായ വ്യത്യാസങ്ങൾ കാണാൻ കഴിയും. അപ്പോൾ നിങ്ങൾ എന്റെ ചര്യയെയും, സന്മാർഗ്ഗം സിദ്ധിച്ചവരും നേർമാർഗ്ഗികളുമായ എന്റെ പ്രതിനിധികളുടെ ചര്യയെയും കൈകൊള്ളുക. അത് മുറുകെ പിടിക്കുകയും അണപ്പല്ലുകൊണ്ട് അതിൽ കടിച്ചുപിടിക്കുകയും ചെയ്യുക. പുതുതായുണ്ടാകുന്ന കാര്യങ്ങളെ നിങ്ങൾ സൂക്ഷിക്കുക. കാരണം പുതുതായുണ്ടാകുന്ന മുഴുവൻ കാര്യങ്ങളും അനാചാരമാണ്. മുഴുവൻ അനാചാരവും പിഴച്ചതാണ്." (ദ,തു,ജ)', 'الْعِرْبَاضِ بْنِ سَارِيَةَ', 'ഇർബാളുബ്നു സാരിയ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], 'التوبة: ٩٢', null, 795, 796, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ الْعِرْبَاضِ بْنِ سَارِيَةَ رَضِيَ اللهُ عَنْهُ قَالَ: وَعَظَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَوْعِظَةً ذَرَفَتْ مِنْهَا الْعُيُونُ وَوَجِلَتْ مِنْهَا الْقُلُوبُ، فَقُلْنَا: يَا رَسُولَ اللَّه، إِنَّ هَذِه لَمَوْعِظَةُ مُوَدِّعٍ، فَمَاذَا تَعْهَدُ إِلَيْنَا؟ قَالَ: "قَدْ تَرَكْتُكُمْ عَلَى الْبَيْضَاءِ، لَيْلُهَا كَنَهَارِهَا، لَا يَزِيغُ عَنْهَا بَعْدِي إِلَّا هَالِكٌ. مَنْ يَعِشْ مِنْكُمْ فَسَيَرَى اخْتِلَافًا كَثِيرًا، فَعَلَيْكُمْ بِمَا عَرَفْتُمْ مِنْ سُنَّتِي وَسُنَّةِ الْخُلَفَاءِ الرَّاشِدِينَ الْمَهْدِيِّينَ، عَضُّوا عَلَيْهَا بِالنَّوَاجِذ. وَعَلَيْكُمْ بِالطَّاعَةِ وَإِنْ عَبْدًا حَبَشِيًّا، فَإِنَّمَا الْمُؤْمِنُ كَالْجَمَلِ الْأَنِفِ، حَيْثُمَا قِيدَ انْقَادَ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=57), 1, 'وَفِي رِوَايَةٍ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْحِ، ثُمَّ أَقْبَلَ عَلَيْنَا بِوَجْهِه فَوَعَظَنَا مَوْعِظَةً بَلِيغَةً.... فَذَكَرَ نَحْوَهُ. (د,ت,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) ഞങ്ങൾക്ക് ഇമാമായി നിന്ന് സ്വുബ്ഹ് നമസ്കരിച്ചു. ശേഷം ഞങ്ങളിലേക്ക് തിരിഞ്ഞ് സാഹിത്യ സമ്പുഷ്ടമായ ഒരു പ്രഭാഷണം നടത്തി....... ശേഷം ഇതേപോലെ ഉദ്ധരിച്ചു. (ദ,തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا خَطَبَ احْمَرَّتْ عَيْنَاهُ، وَعَلَا صَوْتُهُ، وَاشْتَدَّ غَضَبُهُ، كَأَنَّهُ مُنْذِرُ جَيْشٍ يَقُولُ: صَبَّحَكُمْ مَسَّاكُمْ. وَيَقُولُ: "بُعِثْتُ أَنَا وَالسَّاعَةَ كَهَاتَيْنِ". وَيَقْرِنُ بَيْنَ إِصْبَعَيْه السَّبَّابَة وَالْوُسْطَى. ثُمَّ يَقُولُ: "أَمَّا بَعْدُ، فَإِنَّ خَيْرَ الْأُمُورِ كِتَابُ اللَّه، وَخَيْرُ الْهَدْيِ هَدْيُ مُحَمَّد. وَشَرُّ الْأُمُورِ مُحْدَثَاتُهَا، وَكُلُّ بِدْعَة ضَلَالَةٌ". وَكَانَ يَقُولُ: "مَنْ تَرَكَ مَالًا فَلِأَهْلِه، وَمَنْ تَرَكَ دَيْنًا أَوْ ضَيَاعًا فَعَلَيَّ وَإِلَيَّ". (م,ن,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പ്രസംഗിക്കുമ്പോൾ അവിടുത്തെ കണ്ണുകൾ ചുവക്കുകയും ശബ്ദം ഉയരുകയും ദേഷ്യം ശക്തമാവുകയും ചെയ്യുമായിരുന്നു. ഒരു സൈന്യം പ്രഭാതത്തിൽ നിങ്ങളെ അക്രമിക്കും, വൈകുന്നേരം അക്രമിക്കും എന്നെല്ലാം പറഞ്ഞ് അതിനെക്കുറിച്ച് മുന്നറിയിപ്പ് നൽകുന്ന വ്യക്തിയെപ്പോലെയായിരുന്നു അവിടുന്ന്. തന്റെ ചൂണ്ടുവിരലും നടുവിരലും അടുപ്പിച്ചു വെച്ച് അവിടുന്ന് ഇപ്രകാരം പറയുമായിരുന്നു: "ഞാനും അന്ത്യനാളും ഇപ്രകാരമാണ് നിയോഗിക്കപ്പെട്ടത്." ശേഷം പറയും: "ആമുഖത്തിനു ശേഷം, കാര്യങ്ങളിൽ ഏറ്റവും ഉത്തമം അല്ലാഹുവിന്റെ ഗ്രന്ഥമാണ്. ചര്യകളിൽ ഏറ്റവും ഉത്തമം മുഹമ്മദ്(സ)യുടെ ചര്യയാണ്. ഏറ്റവും മോശമായ കാര്യം പുതുതായി ഉണ്ടായവയാണ്. എല്ലാ പുത്തൻവാദവും വഴികേടാണ്." അവിടുന്ന് ഇപ്രകാരം പറയുമായിരുന്നു: "ഒരാൾ (മരിക്കുമ്പോൾ) സമ്പത്ത് ഉപേക്ഷിച്ചിട്ടാൽ അത് അവന്റെ കുടുംബത്തിനുള്ളതാണ്, കടത്തെയോ ആശ്രിതരെയോ ഉപേക്ഷിച്ചിട്ടാൽ അത് എനിക്കുള്ളതാണ്, എന്റെ ഉത്തരവാദിത്തത്തിലാണ്." (മു,ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللَّهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 796, 797, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّمَا هُمَا اثْنَتَانِ: الْكَلَامُ وَالْهَدْيُ، فَأَحْسَنُ الْكَلَامِ كَلَامُ اللَّهِ، وَأَحْسَنُ الْهَدْيِ هَدْيُ مُحَمَّدٍ. أَلَا وَإِيَّاكُمْ وَمُحْدَثَاتِ الْأُمُورِ، فَإِنَّ شَرَّ الْأُمُورِ مُحْدَثَاتُهَا، وَكُلُّ مُحْدَثَةٍ بِدْعَةٌ، وَكُلُّ بِدْعَةٍ ضَلَالَةٌ. أَلَا لَا يَطُولَنَّ عَلَيْكُمُ الْأَمَدُ فَتَقْسُوَ قُلُوبُكُمْ. أَلَا إِنَّ مَا هُوَ آتٍ قَرِيبٌ، وَإِنَّمَا الْبَعِيدُ مَا لَيْسَ بِآتٍ. أَلَا أَنَّمَا الشَّقِيُّ مَنْ شَقِيَ فِي بَطْنِ أُمِّهِ، وَالسَّعِيدُ مَنْ وُعِظَ بِغَيْرِهِ. أَلَا إِنَّ قِتَالَ الْمُؤْمِنِ كُفْرٌ، وَسِبَابَهُ فُسُوقٌ، وَلَا يَحِلُّ لِمُسْلِمٍ أَنْ يَهْجُرَ أَخَاهُ فَوْقَ ثَلَاثٍ. أَلَا وَإِيَّاكُمْ وَالْكَذِبَ، فَإِنَّ الْكَذِبَ لَا يَصْلُحُ بِالْجِدِّ وَلَا بِالْهَزْلِ، وَلَا يَعِدُ الرَّجُلُ صَبِيَّهُ ثُمَّ لَا يَفِيَ لَهُ، فَإِنَّ الْكَذِبَ يَهْدِي إِلَى الْفُجُورِ، وَإِنَّ الْفُجُورَ يَهْدِي إِلَى النَّارِ، وَإِنَّ الصِّدْقَ يَهْدِي إِلَى الْبِرِّ، وَإِنَّ الْبِرَّ يَهْدِي إِلَى الْجَنَّةِ، وَإِنَّهُ يُقَالُ لِلصَّادِقِ: صَدَقَ وَبَرَّ، وَيُقَالُ لِلْكَاذِبِ: كَذَبَ وَفَجَرَ، أَلَا وَإِنَّ الْعَبْدَ يَكْذِبُ حَتَّى يُكْتَبَ عِنْدَ اللَّهِ كَذَّابًا". (جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം സംസാരം, ചര്യ എന്നിവ രണ്ടു കാര്യങ്ങളാണ്. സംസാരങ്ങളിൽ ഏറ്റവും ഉത്തമം അല്ലാഹുവിന്റെ സംസാരമാണ്. ചര്യകളിൽ ഏറ്റവും ഉത്തമം മുഹമ്മദ്(സ)യുടെ ചര്യയാണ്. അറിയുക, പുതുതായി ഉണ്ടാക്കപ്പെട്ട കാര്യങ്ങളെ നിങ്ങൾ സൂക്ഷിക്കുക. കാര്യങ്ങളിൽ ഏറ്റവും മോശമായവ പുതുതായി ഉണ്ടാക്കപ്പെട്ടവയാണ്. പുതുതായി ഉണ്ടാക്കപ്പെട്ടവ എല്ലാം പുത്തൻവാദമാണ്. എല്ലാ പുത്തൻവാദവും വഴികേടാണ്. അറിയുക, സംഭവിക്കാനുള്ളതെല്ലാം അടുത്തതാണ്. സംഭിവക്കാത്തവ മാത്രമാണ് വിദൂരത്തായുള്ളത്. അറിയുക, തന്റെ മാതാവിന്റെ വയറ്റിൽ വെച്ചു തന്നെ പരാജയപ്പെട്ടവനാണ് പരാജിതൻ. മറ്റുള്ളവരാൽ ഉപദേശിക്കപ്പെടുന്നവനാണ് വിജയി. അറിയുക, സത്യവിശ്വാസിയോട് യുദ്ധംചെയ്യൽ സത്യനിഷേധമാണ്. അവനെ അസഭ്യം പറയൽ തെമ്മാടിത്തമാണ്. ഒരു മുസ്ലിമും തന്റെ സഹോദരനോട് മൂന്ന് ദിവസത്തിലധികം പിണങ്ങി നിൽക്കുന്നത് അനുവദനീയമല്ല. അറിയുക, കളവ് പറയുന്നതിനെ നിങ്ങൾ സൂക്ഷിക്കുക. കാര്യത്തിലും തമാശയിലും കളവ് പറയൽ നന്നാവുകയില്ല. ഒരാൾ തന്റെ കുട്ടിയോട് പോലും കരാർചെയ്ത് ലംഘിക്കുന്ന അവസ്ഥയുണ്ടാവരുത്. നിശ്ചയം കളവ് അസന്മാർഗികതയിലേക്ക് നയിക്കും. അസന്മാർഗികത നരകത്തിലേക്കും നയിക്കും. നിശ്ചയം സത്യം നന്മയിലേക്ക് നയിക്കും, നന്മ സ്വർഗ്ഗത്തിലേക്കും നയിക്കും. നിശ്ചയമായും സത്യം പറയുന്നവനെക്കുറിച്ച്; അവൻ സത്യം പറഞ്ഞു, നന്മ ചെയ്തു എന്നും, കളവ് പറയുന്നവനെക്കുറിച്ച്; അവൻ കളവ് പറഞ്ഞു, അസന്മാർഗിക കാര്യങ്ങൾ ചെയ്തു എന്നുമെല്ലാം പറയപ്പെടും. അറിയുക, ഒരു അടിമ കളവു പറഞ്ഞുകൊണ്ടേയിരിക്കുക വഴി അല്ലാഹുവിന്റെയടുക്കൽ കളവ് പറയുന്നവൻ എന്ന് രേഖപ്പെടുത്തപ്പെടും." (ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 797, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا ضَلَّ قَوْمٌ بَعْدَ هُدًى كَانُوا عَلَيْهِ إِلَّا أُوتُوا الْجَدَلَ". ثُمَّ تَلَا هَذِهِ الْآيَةَ: {بَلْ هُمْ قَوْمٌ خَصِمُونَ} [الزخرف: ٥٨]. (ت,جه)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "തങ്ങൾ നിലനിന്നിരുന്ന സന്മാർഗ്ഗത്തിൽ നിന്ന് വഴിതെറ്റുന്ന ഏതൊരു സമൂഹത്തിനും തർക്കം നൽകപ്പെടുന്നതാണ്." ശേഷം റസൂൽ(സ) ഈ സൂക്തം ഓതി: ''എന്നല്ല, അവർ തർക്കിക്കുന്ന സമൂഹമാണ്''. (സുഖ്റുഫ്: 58). (തു,ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'الزخرف: ٥٨', null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَقْبَلُ اللَّهُ لِصَاحِبِ بِدْعَة صَوْمًا، وَلَا صَلَاةً، وَلَا صَدَقَةً، وَلَا حَجًّا، وَلَا عُمْرَةً، وَلَا جِهَادًا، وَلَا صَرْفًا، وَلَا عَدْلًا. يَخْرُجُ مِنَ الْإِسْلَامِ كَمَا تَخْرُجُ الشَّعَرَةُ مِنَ الْعَجِينِ". (جه)', 'ഹുദൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "പുത്തൻ ആശയക്കാരന്റെ നോമ്പോ നമസ്കാരമോ ദാനമോ ഹജ്ജോ ഉംറയോ വിശുദ്ധ യുദ്ധമോ നിർബന്ധവും സുന്നത്തുമായ കർമ്മമോ അല്ലാഹു സ്വീകരിക്കുകയില്ല. കുഴച്ച മാവിൽനിന്ന് മുടി പുറത്ത് പോകുംപോലെ അവൻ ഇസ്ലാമിൽനിന്ന് പുറത്തു പോകും." (ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنْ عَبْدِ اللَّهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَبَى اللَّهُ أَنْ يَقْبَلَ عَمَلَ صَاحِبِ بِدْعَة حَتَّى يَدَعَ بِدْعَتَهُ". (جه)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "പുത്തൻ ആശയക്കാരൻ തന്റെ പുത്തൻ ആശയം ഒഴിവാക്കുംവരെ അവന്റെ ഒരു കർമ്മവും അല്ലാഹു സ്വീകരിക്കുന്നതല്ല." (ജ)', 'عَبْدِ اللَّهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ تَرَكَ الْكَذِبَ وَهُوَ بَاطِلٌ، بُنِيَ لَهُ قَصْرٌ فِي رَبَضِ الْجَنَّةِ. وَمَنْ تَرَكَ الْمِرَاءَ وَهُوَ مُحِقٌّ، بُنِيَ لَهُ فِي وَسَطِهَا. وَمَنْ حَسَّنَ خُلُقَهُ، بُنِيَ لَهُ فِي أَعْلَاهَا". (ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അസത്യത്തിന്റെ ആളായിരിക്കെ ഒരാൾ കളവിനെ ഒഴിവാക്കിയാൽ സ്വർഗ്ഗത്തിന്റെ പാർശ്വ ഭാഗങ്ങളിൽ അവന് കൊട്ടാരം പണിയപ്പെടുന്നതാണ്. സത്യത്തിന്റെ ആളായിരിക്കെ ഒരാൾ തർക്കത്തെ ഒഴിവാക്കിയാൽ സ്വർഗ്ഗത്തിന്റെ മധ്യഭാഗത്ത് അവന് കൊട്ടാരം പണിയപ്പെടുന്നതാണ്. ഒരാൾ തന്റെ സ്വഭാവം നന്നാക്കിയാൽ സ്വർഗ്ഗത്തിന്റെ ഏറ്റവും ഉന്നതിയിൽ അവന് കൊട്ടാരം പണിയപ്പെടുന്നതാണ്." (തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ الْآيَةَ: {هُوَ الَّذِي أَنْزَلَ عَلَيْكَ الْكِتَابَ مِنْهُ آيَاتٌ مُحْكَمَاتٌ} إِلَى {أُولُو الْأَلْبَابِ} [آل عمران: ٧] قَالَتْ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "فَإِذَا رَأَيْتُمُ الَّذِينَ يَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ، فَأُولَئِكَ الَّذِينَ سَمَّى اللَّهُ، فَاحْذَرُوهُمْ". (ق,د,ت)', 'ആഇശ(റ): ''അവനാണ് അങ്ങയുടെ മേൽ ഗ്രന്ഥമിറക്കിയത്, അതിൽ വ്യക്തമായ സൂക്തങ്ങളുണ്ട്'' എന്നു തുടങ്ങി ''ബുദ്ധിയുള്ളവർ'' (ആലുഇംറാൻ: 7) എന്ന് അവസാനിക്കുന്ന സൂക്തം റസൂൽ(സ) പാരായണം ചെയ്തു, ശേഷം പറഞ്ഞു: "ആ ഗ്രന്ഥത്തിലെ സംശയകരമായ കാര്യങ്ങളെ പിന്തുടരുന്നവരെ നിങ്ങൾ കണ്ടാൽ, അവരെക്കുറിച്ചാണ് അല്ലാഹു ഇപ്രകാരം പറഞ്ഞിട്ടുള്ളത്. അതുകൊണ്ട് നിങ്ങൾ അവരെ സൂക്ഷിക്കുക." (ബു,മു,ദ,തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], 'آل عمران: ٧', null, 798, 798, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَفْضَلُ الْأَعْمَالِ الْحُبُّ فِي اللَّهِ وَالْبُغْضُ فِي اللَّهِ". (د)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അത്യുത്തമമായ കർമ്മം അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സ്നേഹിക്കലും, അവന്റെ മാർഗ്ഗത്തിൽ ദേഷ്യംവെക്കലുമാണ്." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ كَعْبِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ – وَذَكَرَ قِصَّةَ تَخَلُّفِهِ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةِ تَبُوكَ – قَالَ: وَنَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُسْلِمِينَ عَنْ كَلَامِنَا أَيُّهَا الثَّلَاثَةُ، حَتَّى إِذَا طَالَ عَلَيَّ، تَسَوَّرْتُ جِدَارَ حَائِطِ أَبِي قَتَادَةَ، وَهُوَ ابْنُ عَمِّي، فَسَلَّمْتُ عَلَيْهِ، فَوَاللَّهِ مَا رَدَّ عَلَيَّ السَّلَامَ..... ثُمَّ سَاقَ خَبَرَ تَنْزِيلِ تَوْبَتِهِ. (ق,د,ت,ن)', 'കഅ്ബുബ്നുമാലിക്(റ): - തബൂഖ് യുദ്ധത്തിന് നബി(സ)യോടൊപ്പം പോകാതെ പിന്തിനിന്ന സംഭവം വിശദീകരിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ മൂന്നു പേരോടും മുസ്ലിംകൾ സംസാരിക്കുന്നതിനെ റസൂൽ(സ) നിരോധിച്ചു. അങ്ങനെ കുറേ കാലമായപ്പോൾ അബൂഖതാദ(റ)വിന്റെ തോട്ടത്തിന്റെ മതിലിന് മുകളിൽ കയറി ഞാൻ അദ്ദേഹത്തോട് സലാം പറഞ്ഞു. അദ്ദേഹം എന്റെ പിതൃവ്യപുത്രനായിരുന്നു. അല്ലാഹു തന്നെ സത്യം, എന്നിട്ടും അദ്ദേഹം എന്റെ സലാം മടക്കിയില്ല..... ശേഷം തന്റെ തൗബ സ്വീകരിച്ചുകൊണ്ട് ഖുർആൻ അവതരിച്ച സംഭവം അദ്ദേഹം വിശദീകരിച്ചു. (ബു,മു,ദ,തു,ന)', 'كَعْبِ بْنِ مَالِكٍ', 'കഅ്ബുബ്നുമാലിക്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ عَمَّارِ بْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَدِمْتُ عَلَى أَهْلِي وَقَدْ تَشَقَّقَتْ يَدَايَ، فَخَلَّقُونِي بِزَعْفَرَانٍ، فَغَدَوْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَلَّمْتُ عَلَيْه، فَلَمْ يَرُدَّ عَلَيَّ، وَقَالَ: "اذْهَبْ فَاغْسِلْ هَذَا عَنْكَ". (د)', 'അമ്മാറുബ്നു യാസിർ(റ): എന്റെ കൈകൾ കീറിയ അവസ്ഥയിൽ ഞാനെന്റെ കുടുംബത്തിന്റെ അടുത്ത് വന്നു. അവർ എനിക്ക് കുങ്കുമം പൂശിത്തന്നു. അങ്ങനെ ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്ന് സലാം ചൊല്ലി. അവിടുന്ന് എന്റെ സലാം മടക്കിയില്ല. നബി(സ) പറഞ്ഞു: "നീ പോയി ഇത് കഴുകിക്കളയുക." (ദ)', 'عَمَّارِ بْنِ يَاسِرٍ', 'അമ്മാറുബ്നു യാസിർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّهُ اعْتَلَّ بَعِيرٌ لِصَفِيَّةَ بِنْتِ حُيَيٍّ، وَعِنْدَ زَيْنَبَ فَضْلُ ظَهْرٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِزَيْنَبَ: "أَعْطِيهَا بَعِيرًا". فَقَالَتْ: أَنَا أُعْطِي تِلْكَ الْيَهُودِيَّةَ؟ فَغَضِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَهَجَرَهَا ذَا الْحِجَّةِ وَالْمُحَرَّمَ وَبَعْضَ صَفَرٍ. (د)', 'ആഇശ(റ): സ്വഫിയ്യ ബിൻതു ഹുയയ്യ്(റ)യുടെ ഒട്ടകത്തിന് രോഗം ബാധിച്ചു. സൈനബ്(റ)യുടെ പക്കൽ ആവശ്യത്തിലധികം വാഹനമുണ്ടായിരുന്നു. അപ്പോൾ റസൂൽ(സ) സൈനബ്(റ)യോട് പറഞ്ഞു: "നീ അവൾക്ക് ആ ഒട്ടകത്തെ നൽകുക." സൈനബ്(റ) ചോദിച്ചു: ഞാൻ ആ ജൂതസ്ത്രീക്ക് നൽകുകയോ? അപ്പോൾ റസൂൽ(സ)ക്ക് ദേഷ്യം വന്നു. അങ്ങനെ ദുൽഹിജ്ജ, മുഹർറം എന്നീ മാസങ്ങളിലും സഫറിലെ കുറച്ച് ദിവസവും നബി(സ) സൈനബ്(റ)യോട് തെറ്റിനിന്നു. (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْمِرَاءُ فِي الْقُرْآنِ كُفْرٌ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഖുർആനിന്റെ കാര്യത്തിലുള്ള തർക്കം ദൈവനിഷേധമാണ്." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 799, 799, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَقُومُ السَّاعَةُ حَتَّى تَأْخُذَ أُمَّتِي بِأَخْذِ الْقُرُونِ قَبْلَهَا، شِبْرًا بِشِبْرٍ، وَذِرَاعًا بِذِرَاعٍ". فَقِيلَ: يَا رَسُولَ اللَّهِ، كَفَارِسَ وَالرُّومِ؟ فَقَالَ: "وَمَنِ النَّاسُ إِلَّا أُولَئِكَ؟". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ചാണിനു ചാൺ, മുഴത്തിനു മുഴം എന്ന നിലയിൽ തങ്ങളുടെ മുൻഗാമികളുടെ പ്രവർത്തനങ്ങളെ എന്റെ സമുദായം പിന്തുടരുന്നതുവരെ അന്ത്യനാൾ സംഭവിക്കുകയില്ല." റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, പേർഷ്യക്കാരെയും റോമക്കാരെയും പോലെയോ? റസൂൽ(സ) ചോദിച്ചു: "ജനങ്ങളെന്നാൽ അവരല്ലാതെ മറ്റാരാണ്?" (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ عُمَرَ رَضِيَ اللَّهُ عَنْهُ قَالَ: إِنَّ اللَّهَ بَعَثَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْحَقِّ، وَأَنْزَلَ عَلَيْهِ الْكِتَابَ، فَكَانَ فِيمَا أُنْزِلَ آيَةُ الرَّجْمِ. (خ)', 'ഉമർ(റ): അല്ലാഹു മുഹമ്മദ്നബി(സ)യെ സത്യവുമായി നിയോഗിക്കുകയും അവിടുത്തേക്ക് ഗ്രന്ഥം അവതരിപ്പിക്കുകയും ചെയ്തു. എറിഞ്ഞു കൊല്ലണമെന്ന് പറയുന്ന സൂക്തം അവിടുത്തേക്ക് അവതരിക്കപ്പെട്ടതിലുണ്ടായിരുന്നു. (ബു)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنْ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا حَكَمَ الْحَاكِمُ فَاجْتَهَدَ ثُمَّ أَصَابَ فَلَهُ أَجْرَانِ، وَإِذَا حَكَمَ فَاجْتَهَدَ ثُمَّ أَخْطَأَ فَلَهُ أَجْرٌ". (خ)', 'അംറുബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "വിധികർത്താവ് ഗവേഷണം ചെയ്ത് ഒരു വിധി പറയുകയും അത് ശരിയാവുകയും ചെയ്താൽ അവന് രണ്ടു പ്രതിഫലമുണ്ട്. ഇനി അവൻ ഗവേഷണം ചെയ്ത് വിധി പറയുകയും അത് തെറ്റുകയും ചെയ്താൽ അവന് ഒരു പ്രതിഫലമുണ്ട്." (ബു)', 'عَمْرِو بْنِ الْعَاصِ', 'അംറുബ്നുൽ ആസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ جَابِرِ بْنِ عَبْدِاللَّه رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ كَانَ يَحْلِفُ بِاللَّه: إِنَّ ابْنَ الصَّائِد الدَّجَّالُ، فَقُلْتُ: تَحْلِفُ بِاللَّه؟ قَالَ: إِنِّي سَمِعْتُ عُمَرَ رَضِيَ اللَّهُ عَنْهُ يَحْلِفُ عَلَى ذَلِكَ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمْ يُنْكِرْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഇബ്നുസ്സ്വയ്യാദ് ദജ്ജാലാണെന്ന് അദ്ദേഹം അല്ലാഹുവിൽ സത്യംചെയ്ത് പറയുമായിരുന്നു. ഞാൻ ചോദിച്ചു: അക്കാര്യം നിങ്ങൾ അല്ലാഹുവിൽ സത്യം ചെയ്ത് പറയുന്നുവോ? ജാബിർ(റ) പറഞ്ഞു: നബി(സ)യുടെ സമീപത്തു വെച്ച് ഉമർ(റ) ഇക്കാര്യത്തിൽ അല്ലാഹുവിൽ സത്യംചെയ്യുന്നത് ഞാൻ കണ്ടു. അപ്പോൾ റസൂൽ(സ) അദ്ദേഹത്തെ എതിർത്തില്ല. (ബു)', 'جَابِرِ بْنِ عَبْدِاللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 800, 800, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ اللَّهَ لَا يَقْبِضُ الْعِلْمَ انْتِزَاعًا يَنْتَزِعُهُ مِنَ النَّاسِ، وَلَكِنْ يَقْبِضُ الْعِلْمَ بِقَبْضِ الْعُلَمَاءِ، فَإِذَا لَمْ يُبْقِ عَالِمًا اتَّخَذَ النَّاسُ رُءُوسًا جُهَّالًا، فَسُئِلُوا فَأَفْتَوْا بِغَيْرِ عِلْمٍ، فَضَلُّوا وَأَضَلُّوا". (ق,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ജനങ്ങളിൽനിന്ന് വിജ്ഞാനത്തെ ഒറ്റയടിക്ക് ഊരിയെടുക്കുകയില്ല. ജ്ഞാനികളെ പിടിച്ചുകൊണ്ടാണ് (അവരുടെ മരണത്തിലൂടെ) അവൻ വിജ്ഞാനത്തെ ഊരിയെടുക്കുന്നത്. അങ്ങനെ ഒരു ജ്ഞാനിപോലും അവശേഷിക്കാതിരിക്കുമ്പോൾ ജനങ്ങൾ വിഡ്ഢികളെ നായകരായി സ്വീകരിക്കും. ജനങ്ങൾ അവരോട് ചോദിക്കുകയും ജ്ഞാനമില്ലാതെ അവർ വിധി പറയുകയും ചെയ്യും. അങ്ങനെ അവർ വഴികേടിലാവുകയും (മറ്റുള്ളവരെ) വഴികേടിലാക്കുകയും ചെയ്യും." (ബു,മു,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 800, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ أُفْتِيَ بِفُتْيَا غَيْرَ ثَبَتٍ، فَإِنَّمَا إِثْمُهُ عَلَى مَنْ أَفْتَاهُ". (د,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾക്ക് ഉറപ്പില്ലാത്ത (തെറ്റായ) വിധി നൽകപ്പെട്ടാൽ അതിന്റെ ശിക്ഷ അവന് വിധി നൽകിയവനാണ്." (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْعِلْمُ ثَلَاثَةٌ، فَمَا وَرَاءَ ذَلِكَ فَهُوَ فَضْلٌ: آيَةٌ مُحْكَمَةٌ، أَوْ سُنَّةٌ قَائِمَةٌ، أَوْ فَرِيضَةٌ عَادِلَةٌ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വിജ്ഞാനം മൂന്നു വിധമാണ്: അതിന് അപ്പുറത്തുള്ളതെല്ലാം അധികമാണ്. ദൃഢമായ (തിരുത്തപ്പെടാത്ത) സൂക്തം, സ്തിരമായ നബിചര്യ, നീതിയുക്തമായ വിഹിത ജ്ഞാനം (എന്നിവയാണവ)." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْيَمَنِ قَالَ: "لَا تَقْضِيَنَّ وَلَا تَفْصِلَنَّ إِلَّا بِمَا تَعْلَمُ، فَإِنْ أَشْكَلَ عَلَيْكَ أَمْرٌ فَقِفْ حَتَّى تَبَيَّنَهُ أَوْ تَكْتُبَ إِلَيَّ فِيه". (جه)', 'മുആദുബ്നു ജബൽ(റ): എന്നെ യമനിലേക്ക് അയച്ചപ്പോൾ റസൂൽ(സ) എന്നോട് പറഞ്ഞു: "നിനക്കറിയുന്ന രീതിയിലല്ലാതെ നീ വിധി പറയുകയോ തീർപ്പാക്കുകയോ ചെയ്യരുത്. വല്ല കാര്യവും അവ്യക്തമായി തോന്നിയാൽ അത് നിനക്ക് വ്യക്തമാകും വരെയോ അക്കാര്യം ചോദിച്ച് എനിക്ക് സന്ദേശം അയക്കും വരെയോ നീ അതിനെ നിർത്തിവെക്കുക." (ജ)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَمْ يَزَلْ أَمْرُ بَنِي إِسْرَائِيلَ مُعْتَدِلًا حَتَّى نَشَأَ فِيهِمُ الْمُوَلَّدُونَ، أَبْنَاءُ سَبَايَا الْأُمَمِ، فَقَالُوا بِالرَّأْيِ، فَضَلُّوا وَأَضَلُّوا". [ز: في إسناده ضعيف]. (جه)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "തങ്ങളുടെ സമൂഹത്തിലേക്ക് കടന്നുവന്നവർ; അഥവാ മറ്റു സമുദായങ്ങളിൽനിന്ന് ബന്ധികളായി പിടിക്കപ്പെട്ടവരുടെ സന്താനങ്ങൾ വളർന്നു വരുന്നതുവരെ ഇസ്റാഈലുകാരുടെ അവസ്ഥ ശാന്തമിരുന്നു. ശേഷം അക്കൂട്ടർ സ്വന്തം അഭിപ്രായങ്ങൾ പറയുകയും വഴികേടിലാവുകയും (മറ്റുള്ളവരെ) വഴികേടിലാക്കുകയും ചെയ്തു." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ جَرِيرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَنَّ سُنَّةً حَسَنَةً فَعُمِلَ بِهَا كَانَ لَهُ أَجْرُهَا وَمِثْلُ أَجْرِ مَنْ عَمِلَ بِهَا، لَا يَنْقُصُ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنْ سَنَّ سُنَّةً سَيِّئَةً فَعُمِلَ بِهَا كَانَ عَلَيْهِ وِزْرُهَا وَوِزْرُ مَنْ عَمِلَ بِهَا، لَا يَنْقُصُ مِنْ أَوْزَارِهِمْ شَيْئًا". (م,ن,جه)', 'ജരീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നല്ല ചര്യയെ കൊണ്ടുവരികയും അതു പ്രകാരം കർമ്മം ചെയ്യപ്പെടുകയും ചെയ്താൽ അവന് അതിന്റെ പ്രതിഫലവും അതനുസരിച്ച് കർമ്മം ചെയ്തവന്റെ പ്രതിഫലവും ലഭിക്കുന്നതാണ്. (ഇവനും പ്രതിഫലം ലഭിക്കുന്നുവെന്നത്) അവരുടെ പ്രതിഫലത്തിൽ നിന്ന് ഒന്നിനെയും കുറയ്ക്കുന്നതല്ല. ഒരാൾ മോശമായ ചര്യയെ കൊണ്ടുവരികയും അതനുസരിച്ച് കർമ്മം ചെയ്യപ്പെടുകയും ചെയ്താൽ അവന് അതിന്റെ ശിക്ഷയും അതനുസരിച്ച് പ്രവർത്തിച്ചവരുടെ ശിക്ഷയും ഉണ്ടായിരിക്കും. അത് അവരുടെ ശിക്ഷയിൽനിന്ന് ഒന്നിനെയും കുറയ്ക്കുന്നതല്ല." (മു,ന,ജ)', 'جَرِيرٍ', 'ജരീർ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 801, 801, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَثَّ عَلَيْهِ، فَقَالَ رَجُلٌ: عِنْدِي كَذَا وَكَذَا. قَالَ: فَمَا بَقِيَ فِي الْمَجْلِسِ رَجُلٌ إِلَّا تَصَدَّقَ عَلَيْهِ بِمَا قَلَّ أَوْ كَثُرَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنِ اسْتَنَّ خَيْرًا فَاسْتُنَّ بِه كَانَ لَهُ أَجْرُهُ كَامِلًا، وَمِنْ أُجُورِ مَنِ اسْتَنَّ بِه، وَلَا يَنْقُصُ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنِ اسْتَنَّ سُنَّةً سَيِّئَةً فَاسْتُنَّ بِه فَعَلَيْهِ وِزْرُهُ كَامِلًا، وَمِنْ أَوْزَارِ الَّذِي اسْتَنَّ بِه، وَلَا يَنْقُصُ مِنْ أَوْزَارِهِمْ شَيْئًا". (جه)', 'അബൂഹുറൈറ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് അവിടുത്തേക്ക് (ധാരാളം മുതൽ) ചൊരിഞ്ഞു കൊടുത്തു. അപ്പോൾ മറ്റൊരാൾ പറഞ്ഞു: എന്റടുത്ത് ഇത്ര മുതലുണ്ട് (ഞാനതു തരാം). നിവേദകൻ പറയുന്നു: ആ സദസ്സിലുള്ള എല്ലാവരും അൽപമോ കൂടുതലോ ആയി ദാനം ചെയ്തു. അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നല്ല ചര്യ കൊണ്ടുവരികയും അത് പിന്തുടരപ്പെടുകയും ചെയ്താൽ അതിന്റെ മുഴുവൻ പ്രതിഫലവും അവനെ പിന്തുടർന്നവരുടെ പ്രതിഫലവും അവന് ലഭിക്കുന്നതാണ്. അത് അവരുടെ (പിന്തുടർന്നവരുടെ) പ്രതിഫലത്തിൽ നിന്ന് ഒന്നിനെയും കുറയ്ക്കുന്നതല്ല. ഒരാൾ മോശമായ ചര്യ കൊണ്ടുവരികയും അത് പിന്തുടരപ്പെടുകയും ചെയ്താൽ അതിന്റെ മുഴുവൻ ശിക്ഷയും അവനെ പിന്തുടർന്നവരുടെ ശിക്ഷയും അവന് ലഭിക്കുന്നതാണ്. അത് അവരുടെ (പിന്തുടർന്നവരുടെ) ശിക്ഷയിൽനിന്ന് ഒന്നിനെയും കുറയ്ക്കുന്നതല്ല." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ قَالَ: "أَيُّمَا دَاعٍ دَعَا إِلَى ضَلَالَةٍ فَاتُّبِعَ، فَإِنَّ لَهُ مِثْلَ أَوْزَارِ مَنِ اتَّبَعَهُ، وَلَا يَنْقُصُ مِنْ أَوْزَارِهِمْ شَيْئًا. وَأَيُّمَا دَاعٍ دَعَا إِلَى هُدًى فَاتُّبِعَ، فَإِنَّ لَهُ مِثْلَ أُجُورِ مَنِ اتَّبَعَهُ، وَلَا يَنْقُصُ مِنْ أُجُورِهِمْ شَيْئًا". [ز: في إسناده ضعيف]. (م,د,ت,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏതെങ്കിലുമൊരാൾ തിന്മയിലേക്ക് ക്ഷണിക്കുകയും അവനെ പിന്തുടരപ്പെടുകയും ചെയ്താൽ, തന്നെ പിന്തുടർന്നവരുടെ ശിക്ഷ അവനുണ്ടായിരിക്കും. അത് അവരുടെ ശിക്ഷയിൽനിന്ന് ഒന്നിനെയും കുറയ്ക്കുന്നതല്ല. ഏതെങ്കിലുമൊരാൾ സന്മാർഗ്ഗത്തിലേക്ക് ക്ഷണിക്കുകയും അത് പിന്തുടരപ്പെടുകയും ചെയ്താൽ, തന്നെ പിന്തുടരുന്നവരുടെ പ്രതിഫലം അവനുണ്ടായിരിക്കും. അത് അവരുടെ പ്രതിഫലത്തിൽനിന്ന് ഒന്നിനെയും കുറയ്ക്കുന്നതല്ല." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (മു,ദ,തു,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], 'ز: في إسناده ضعيف', null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الْأَجْرِ مِثْلُ أُجُورِ مَنِ اتَّبَعَهُ، لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنْ دَعَا إِلَى ضَلَالَةٍ فَعَلَيْهِ مِنَ الْإِثْمِ مِثْلُ آثَامِ مَنِ اتَّبَعَهُ، لَا يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا". (م,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും ഒരു സൽകർമ്മത്തിലേക്ക് ക്ഷണിച്ചാൽ, തന്നെ പിന്തുടർന്നവരുടെ പ്രതിഫലം പോലെയുള്ള പ്രതിഫലം അവനുമുണ്ടാകും. ഇത് (ക്ഷണിച്ചവനും ലഭിക്കുന്നുവെന്നത്) അവരുടെ പ്രതിഫലത്തിൽനിന്ന് ഒന്നിനെയും ചുരുക്കുകയില്ല. ആരെങ്കിലും ഒരു തിന്മയിലേക്ക് ക്ഷണിച്ചാൽ, തന്നെ പിന്തുടർന്നവരുടെ പാപം പോലെയുള്ള പാപം അവനുമുണ്ടാകും. ഇത് അവരുടെ (പിന്തുടർന്നവരുടെ) പാപത്തിൽനിന്ന് ഒന്നിനെയും ചുരുക്കുകയില്ല." (മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','جه']::text[], array['മു','ദ','തു','ജ']::text[], null, null, 802, 802, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ سَنَّ سُنَّةً حَسَنَةً – فَعُمِلَ بِهَا بَعْدَهُ – كَانَ لَهُ أَجْرُهُ وَمِثْلُ أُجُورِهِمْ، مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنْ سَنَّ سُنَّةً سَيِّئَةً – فَعُمِلَ بِهَا بَعْدَهُ – كَانَ عَلَيْهِ وِزْرُهُ وَمِثْلُ أَوْزَارِهِمْ، مِنْ غَيْرِ أَنْ يَنْقُصَ مِنْ أَوْزَارِهِمْ شَيْئًا". [ز: في إسناده ضعيف]. (جه)', 'അബൂജുഹൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ നല്ല ചര്യ കൊണ്ടുവരികയും തനിക്കു ശേഷം ആ കാര്യം പ്രവർത്തിക്കപ്പെടുകയും ചെയ്താൽ, പിന്തുടർന്നവരുടെ പ്രതിഫലത്തിൽനിന്ന് ഒന്നും കുറയാതെ, അവരുടെ പ്രതിഫലവും തന്റെ പ്രതിഫലവും അവന് ലഭിക്കും. ഒരാൾ മോശമായ ചര്യ കൊണ്ടുവരികയും തനിക്കു ശേഷം ആ കാര്യം പ്രവർത്തിക്കപ്പെടുകയും ചെയ്താൽ, പിന്തുടർന്നവരുടെ ശിക്ഷയിൽനിന്ന് ഒന്നും കുറയാതെ, അവരുടെ ശിക്ഷയും തന്റെ ശിക്ഷയും അവന് ലഭിക്കും." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 802, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا مِنْ دَاعٍ يَدْعُو إِلَى شَيْءٍ، إِلَّا وُقِفَ يَوْمَ الْقِيَامَةِ لَازِمًا لِدَعْوَتِه مَا دَعَا إِلَيْهِ، وَإِنْ دَعَا رَجُلٌ رَجُلًا". [ز: في إسناده ضعيف]. (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഏതൊരു കാര്യത്തിലേക്കും ക്ഷണിക്കുന്നവനെ അന്ത്യനാളിൽ താൻ ക്ഷണിച്ച കാര്യത്തിലേക്ക് ക്ഷണിക്കുന്ന അവസ്ഥയിൽ നിർത്തപ്പെടുന്നതാണ്. ഒരാൾ മറ്റൊരാളെ ക്ഷണിച്ചാൽ പോലും (ഇപ്രകാരമായിരിക്കും)." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ عَمْرِو بْنِ عَوْفٍ الْمُزَنِيِّ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحْيَا سُنَّةً مِنْ سُنَّتِي، فَعَمِلَ بِهَا النَّاسُ، كَانَ لَهُ مِثْلُ أَجْرِ مَنْ عَمِلَ بِهَا، لَا يَنْقُصُ مِنْ أُجُورِهِمْ شَيْئًا. وَمَنِ ابْتَدَعَ بِدْعَةً فَعُمِلَ بِهَا، كَانَ عَلَيْهِ أَوْزَارُ مَنْ عَمِلَ بِهَا، لَا يَنْقُصُ مِنْ أَوْزَارِ مَنْ عَمِلَ بِهَا شَيْئًا".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=85), 1, 'وَفِي رِوَايَةٍ: "مَنْ أَحْيَا سُنَّةً مِنْ سُنَّتِي، قَدْ أُمِيتَتْ بَعْدِي، فَإِنَّ لَهُ مِنَ الْأَجْرِ مِثْلَ أَجْرِ مَنْ عَمِلَ بِهَا مِنَ النَّاسِ، لَا يَنْقُصُ مِنْ أُجُورِ النَّاسِ شَيْئًا. وَمَنِ ابْتَدَعَ بِدْعَةً، لَا يَرْضَاهَا اللَّهُ وَرَسُولُهُ، فَإِنَّ عَلَيْهِ مِثْلَ إِثْمِ مَنْ عَمِلَ بِهَا مِنَ النَّاسِ، لَا يَنْقُصُ مِنْ آثَامِ النَّاسِ شَيْئًا". (ت,جه)', 'മറ്റൊരു നിവേദനം: "എനിക്കു ശേഷം നിർജ്ജീവമായ എന്റെ ചര്യയെ ഒരാൾ ജീവിപ്പിച്ചാൽ അതനുസരിച്ച് പ്രവർത്തിക്കുന്ന ജനങ്ങളുടെ പ്രതിഫലം അവന് ലഭിക്കുന്നതാണ്. അത് ആ ജനങ്ങളുടെ പ്രതിഫലത്തിൽ ഒരു കുറവും വരുത്തുന്നതല്ല. അല്ലാഹുവും അവന്റെ റസൂലും തൃപ്തിപ്പെടാത്ത പുതിയ കാര്യത്തെ ആരെങ്കിലും നടപ്പാക്കിയാൽ അതനുസരിച്ച് പ്രവർത്തിക്കുന്ന ജനങ്ങളുടെ ശിക്ഷ അവന് ലഭിക്കുന്നതാണ്. അത് ആ ജനങ്ങളുടെ ശിക്ഷകളിൽ ഒരു കുറവും വരുത്തുന്നതല്ല." (തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَنْ فَارَقَ الْجَمَاعَةَ شِبْرًا فَقَدْ خَلَعَ رِبْقَةَ الْإِسْلَامِ مِنْ عُنُقِه". (د)', 'അബൂദർറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ കൂട്ടത്തിൽ നിന്ന് ഒരു ചാൺ വിട്ടുനിന്നാൽ തന്റെ കഴുത്തിലുള്ള ഇസ്ലാമിന്റെ കെട്ടിനെ അവൻ ഊരിയിരിക്കുന്നു." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 803, 803, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ أَبِي ذَرٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَيْفَ أَنْتُمْ وَأَئِمَّةٌ مِنْ بَعْدِي يَسْتَأْثِرُونَ بِهَذَا الْفَيْءِ". قُلْتُ: إِذَنْ – وَالَّذِي بَعَثَكَ بِالْحَقِّ – أَضَعُ سَيْفِي عَلَى عَاتِقِي، ثُمَّ أَضْرِبُ بِهِ حَتَّى أَلْقَاكَ، أَوْ أَلْحَقَكَ. قَالَ: "أَوَلَا أَدُلُّكَ عَلَى خَيْرٍ مِنْ ذَلِكَ؟ تَصْبِرُ حَتَّى تَلْقَانِي". (د)', 'അബൂദർറ്(റ): റസൂൽ(സ) ചോദിച്ചു: "എനിക്കുശേഷം വരുന്ന ചില ഭരണാധികാരികൾ ഈ യുദ്ധമുതലിനെ സ്വന്തമാക്കി വെക്കുമ്പോൾ നിങ്ങളുടെ അവസ്ഥ എന്തായിരിക്കും?" ഞാൻ പറഞ്ഞു: അങ്ങയെ സത്യവുമായി നിയോഗിച്ചവൻ തന്നെ സത്യം, അങ്ങനെ വരുമ്പോൾ അങ്ങയെ കണ്ടുമുട്ടുംവരെ - അല്ലെങ്കിൽ അങ്ങയോട് ചേരുംവരെ - എന്റെ തോളിൽ വാളുവെച്ചുകൊണ്ട് ഞാൻ പോരാടും. റസൂൽ(സ) പറഞ്ഞു: "അതിനേക്കാൾ ശ്രേഷ്ഠമായ കാര്യം ഞാൻ നിനക്കു പറഞ്ഞുതരട്ടെയോ, എന്നെ കണ്ടുമുട്ടുംവരെ നീ ക്ഷമിക്കുക." (ദ)', 'أَبِي ذَرٍّ', 'അബൂദർറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 803, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللَّهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "سَتَكُونُ عَلَيْكُمْ أَئِمَّةٌ تَعْرِفُونَ مِنْهُمْ وَتُنْكِرُونَ، فَمَنْ أَنْكَرَ بِلِسَانِه فَقَدْ بَرِئَ، وَمَنْ كَرِهَ بِقَلْبِه فَقَدْ سَلِمَ، وَلَكِنْ مَنْ رَضِيَ وَتَابَعَ". فَقِيلَ: يَا رَسُولَ اللَّهِ، أَفَلَا نَقْتُلُهُمْ؟ وَفِي رِوَايَةٍ: أَفَلَا نُقَاتِلُهُمْ؟ قَالَ: "لَا، مَا صَلَّوْا". وَفِي رِوَايَةٍ: "فَمَنْ كَرِهَ فَقَدْ بَرِئَ، وَمَنْ أَنْكَرَ فَقَدْ سَلِمَ". (م,د,ت)', 'നബി(സ)യുടെ പത്നിയായ ഉമ്മുസലമ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾക്ക് ചില ഭരണാധികാരികൾ വരാനുണ്ട്. അവരിൽനിന്ന് ധാരാളം കാര്യങ്ങൾ നിങ്ങൾ മനസ്സിലാക്കുകയും വെറുക്കുകയും ചെയ്യും. തന്റെ നാവുകൊണ്ട് എതിർത്തവൻ നിർഭയനായിരിക്കുന്നു, തന്റെ ഹൃദയംകൊണ്ട് വെറുത്തവൻ രക്ഷപ്പെട്ടിരിക്കുന്നു. പക്ഷേ, അവയെ തൃപ്തിപ്പെടുകയും പിന്തുടരുകയും ചെയ്തവൻ." ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ അവരെ വധിക്കട്ടെയോ? മറ്റൊരു നിവേദനം: ഞങ്ങൾ അവരോട് യുദ്ധം ചെയ്യട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അവർ നമസ്കരിക്കുന്ന കാലത്തോളം യുദ്ധം ചെയ്യേണ്ട." മറ്റൊരു നിവേദനം: "അവയെ വെറുത്തവൻ നിർഭയനായിരിക്കുന്നു, എതിർത്തവൻ രക്ഷപ്പെട്ടിരിക്കുന്നു." (മു,ദ,തു)', 'أُمِّ سَلَمَةَ', 'നബി(സ)യുടെ പത്നിയായ ഉമ്മുസലമ(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=88), 1, 'وَفِي رِوَايَةٍ: أَفَلَا نُقَاتِلُهُمْ؟ قَالَ: "لَا، مَا صَلَّوْا".', 'മറ്റൊരു നിവേദനം: ഞങ്ങൾ അവരോട് യുദ്ധം ചെയ്യട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അവർ നമസ്കരിക്കുന്ന കാലത്തോളം യുദ്ധം ചെയ്യേണ്ട."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=88), 2, 'وَفِي رِوَايَةٍ: "فَمَنْ كَرِهَ فَقَدْ بَرِئَ، وَمَنْ أَنْكَرَ فَقَدْ سَلِمَ". (م,د,ت)', 'മറ്റൊരു നിവേദനം: "അവയെ വെറുത്തവൻ നിർഭയനായിരിക്കുന്നു, എതിർത്തവൻ രക്ഷപ്പെട്ടിരിക്കുന്നു." (മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ عَرْفَجَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "سَتَكُونُ فِي أُمَّتِي هَنَاتٌ وَهَنَاتٌ، فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ الْمُسْلِمِينَ وَهُمْ جَمِيعٌ فَاضْرِبُوهُ بِالسَّيْفِ، كَائِنًا مَنْ كَانَ". (م,د)', 'അർഫജ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ സമുദായത്തിൽ ധാരാളം കുഴപ്പങ്ങളുണ്ടാകും. അപ്പോൾ ആരെങ്കിലും ഒരുമയോടെ നിൽക്കുന്ന മുസ്ലിംകളുടെ കാര്യത്തിൽ ഭിന്നതയുണ്ടാക്കാൻ ആഗ്രഹിച്ചാൽ എന്തു പ്രശ്നമുണ്ടായാലും അവനെ നിങ്ങൾ വാളുകൊണ്ട് വെട്ടുക." (മു,ദ)', 'عَرْفَجَةَ', 'അർഫജ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 804, 804, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي سَلَمَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ لِأَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ: هَلْ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُ فِي الْحَرُورِيَّةِ شَيْئًا؟ فَقَالَ: سَمِعْتُهُ يَذْكُرُ قَوْمًا يَتَعَبَّدُونَ: "يَحْقِرُ أَحَدُكُمْ صَلَاتَهُ مَعَ صَلَاتِهِمْ، وَصَوْمَهُ مَعَ صَوْمِهِمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ. أَخَذَ سَهْمَهُ فَنَظَرَ فِي نَصْلِه فَلَمْ يَرَ شَيْئًا، فَنَظَرَ فِي رِصَافِه فَلَمْ يَرَ شَيْئًا، فَنَظَرَ فِي قِدْحِه فَلَمْ يَرَ شَيْئًا، فَنَظَرَ فِي الْقُذَذِ فَتَمَارَى هَلْ يَرَى شَيْئًا أَمْ لَا". (ق,جه)', 'അബൂസലമ(റ): ഞാൻ അബൂസഈദ്(റ)വിനോട് ചോദിച്ചു: ഹറൂരിയ്യാക്കളുടെ (ഖവാരിജുകൾ) കാര്യത്തിൽ റസൂൽ(സ) വല്ലതും പറയുന്നത് നിങ്ങൾ കേട്ടിട്ടുണ്ടോ? അബൂസഈദ്(റ) പറഞ്ഞു: ആരാധനയിൽ കഴിയുന്ന ഒരു കൂട്ടരെ സംബന്ധിച്ച് റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അവരുടെ നിസ്കാരത്തോട് ചേർത്തുനോക്കുമ്പോൾ നിങ്ങളിൽ ഒരാളുടെ നിസ്കാരവും, അവരുടെ നോമ്പിനോട് ചേർത്തു നോക്കുമ്പോൾ നിങ്ങളിൽ ഒരാളുടെ നോമ്പും നിസാരമാണെന്ന് അവന്ന് തോന്നും (അത്രയും അധികം നമസ്കരിക്കുന്നവരും നോമ്പെടുക്കുന്നവരുമായിരിക്കും). വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകുംപോലെ ദീനിൽ നിന്ന് അവർ പുറത്തുപോകും. ഒരാൾ തന്റെ അമ്പെടുത്ത് അതിന്റെ ഇരുമ്പു മുനയിൽ നോക്കുന്നു, പക്ഷേ, ഒന്നും കണ്ടില്ല. ശേഷം അതിന്റെ മുന കെട്ടുന്ന നാരിൽ നോക്കുന്നു, പക്ഷേ, ഒന്നും കാണുന്നില്ല. ശേഷം അതിന്റെ തണ്ടിൽ നോക്കുന്നു. അപ്പോഴും ഒന്നും കാണുന്നില്ല. ശേഷം അമ്പിലെ തൂവലുകളിലേക്ക് നോക്കുമ്പോൾ അതിനുമേൽ വല്ല അവശിഷ്ടങ്ങളും ഉണ്ടോ ഇല്ലെയോ എന്ന് അവൻ സംശയിക്കുന്നു." (ബു,മു,ജ)', 'أَبِي سَلَمَةَ', 'അബൂസലമ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 804, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ عَبْدِ الله بْنِ الصَّامت، عَنْ أَبِي ذَرٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إنَّ بَعْدِي مِنْ أُمَّتِي – أَوْ سَيَكُونُ بَعْدِي مِنْ أُمَّتِي – قَوْمٌ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حُلُوقَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، ثُمَّ لَا يَعُودُونَ فيه. هُمْ شرَارُ الْخلْقِ وَالْخَلِيقَةِ". قَالَ عَبْدُ اللهِ بْنُ الصَّامتِ: فَذَكَرْتُ ذَلِكَ لِرَافِعِ بْنِ عَمْرٍو – أَخِي الْحَكَمِ بْنِ عَمْرٍو وَالْغِفَارِيِّ – فَقَالَ: وَأَنَا أَيْضًا قَدْ سَمِعْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,جه)', 'അബൂദർറ്(റ)വിൽനിന്ന് അബ്ദുല്ലാഹിബ്നു സ്വാമിത്(റ): റസൂൽ(സ) പറഞ്ഞു: "എനിക്കുശേഷം എന്റെ സമുദായത്തിൽ ഒരു കൂട്ടരുണ്ടാകും. അവർ ഖുർആൻ പാരായണം ചയ്യുമെങ്കിലും തങ്ങളുടെ തൊണ്ടകൾക്കപ്പുറം അത് ഇറങ്ങുകയില്ല. വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകുംപോലെ ദീനിൽനിന്ന് അവർ പുറത്തുപോകും. ശേഷം അതിലേക്കവർ മടങ്ങി വരികയില്ല. അവരാണ് സൃഷ്ടികളിലും മൃഗങ്ങളിലും ഏറ്റവും മോശപ്പെട്ടവർ."
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ جَابِر بْنِ عَبْد الله رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ الله صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْجِعْرَانَة وَهُوَ يَقْسِمُ التِّبْرَ وَالْغَنَائِمَ، وَهُوَ في حِجْرِ بِلَال، فَقَالَ رَجُلٌ: اعْدِلْ يَا مُحَمَّدُ، فَإِنَّكَ لَمْ تَعْدِلْ. فَقَالَ: "وَيْلَكَ! وَمَنْ يَعْدِلُ بَعْدِي إذَا لَمْ أَعْدِلْ". فَقَالَ عُمَرُ: دَعْنِي – يَا رَسُولَ الله – حَتَّى أَضْرِبَ عُنُقَ هَذَا الْمُنَافِق. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إنَّ هَذَا فِي أَصْحَابٍ – أَوْ أُصَيْحَابٍ لَهُ – يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ تَرَاقِيَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ". (جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ജിഇർറാന എന്ന സ്ഥലത്തുവെച്ച് ബിലാൽ(റ)വിന്റെ കുടിലിൽ ഇരുന്ന് റസൂൽ(സ) സ്വർണ്ണവും യുദ്ധമുതലും വീതിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ പറഞ്ഞു: മുഹമ്മദേ, താങ്കൾ നീതി പാലിക്കുക, നിശ്ചയം താങ്കൾ നീതി പാലിച്ചിട്ടില്ല. റസൂൽ(സ) പറഞ്ഞു: "നിനക്കു നാശം, ഞാൻ നീതി പാലിച്ചിട്ടില്ലെങ്കിൽ എനിക്കുശേഷം ആരാണ് നീതി പാലിക്കുക." അപ്പോൾ ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഈ കപടവിശ്വാസിയുടെ കഴുത്ത് വെട്ടാൻ എന്നെ അനുവദിച്ചാലും. റസൂൽ(സ) പറഞ്ഞു: "ഇവനും കുറച്ചു കൂട്ടരും - അല്ലെങ്കിൽ: ഇവന്റെ കുറച്ചു കൂട്ടരും - ഖുർആൻ പാരായണം ചെയ്യുന്നവരാണ്. പക്ഷേ, അത് അവരുടെ തൊണ്ടക്കുഴിക്കപ്പുറം ഇറങ്ങുകയില്ല. വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകുംപോലെ അവർ ദീനിൽനിന്ന് പുറത്തുപോകും." (ജ)', 'جَابِر بْنِ عَبْد الله', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 805, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنِ ابْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْخَوَارِجُ كِلَابُ النَّارِ". [ز: في إسناده منقطع]. (جه)', 'ഇബ്നു അബീഔഫാ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖവാരിജുകൾ നരകത്തിലെ നായകളാണ്." ഇതിന്റെ പരമ്പരയിൽ മുൻഖതിആയ നിവേദകനുണ്ട്. (ജ)', 'ابْنِ أَبِي أَوْفَى', 'ഇബ്നു അബീഔഫാ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده منقطع', null, 805, 805, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَنْشَأُ نَشْءٌ يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ تَرَاقِيَهُمْ، كُلَّمَا خَرَجَ قَرْنٌ قُطِعَ". قَالَ ابْنُ عُمَرَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "كُلَّمَا خَرَجَ قَرْنٌ قُطِعَ" أَكْثَرَ مِنْ عِشْرِينَ مَرَّةً "حَتَّى يَخْرُجَ فِي عِرَاضِهِمُ الدَّجَّالُ". (جه)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു തലമുറ വളർന്നു വരും. അവർ ഖുർആൻ പാരായണം ചെയ്യുമെങ്കിലും തങ്ങളുടെ തൊണ്ടക്കുഴികൾക്കപ്പുറം അത് ഇറങ്ങുകയില്ല. അവരിൽ ഓരോ വിഭാഗം വരുമ്പോഴും അവർ നശിപ്പിക്കപ്പെടും." ഇബ്നുഉമർ(റ) പറയുന്നു: "അവരിൽ ഓരോ വിഭാഗം വരുമ്പോഴും അവർ നശിപ്പിക്കപ്പെടും" എന്ന് ഇരുപതിലധികം പ്രാവശ്യം റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു. (ശേഷം അവിടുന്ന് പറഞ്ഞു:) "അങ്ങനെ അവരുടെ അവസാന ഭാഗത്തായി ദജ്ജാൽ പുറപ്പെടും." (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 805, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَخْرُجُ قَوْمٌ فِي آخِرِ الزَّمَان – أَوْ فِي هَذِهِ الْأُمَّةِ – يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ تَرَاقِيَهُمْ، أَوْ حُلُوقَهُمْ. سِيمَاهُمُ التَّحْلِيقُ، إِذَا رَأَيْتُمُوهُمْ – أَوْ: إِذَا لَقِيتُمُوهُمْ – فَاقْتُلُوهُمْ". (د,جه)', 'അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ - അല്ലെങ്കിൽ ഈ സമുദായത്തിൽ - ഒരു സമൂഹം പുറപ്പെടും. അവർ ഖുർആൻ പാരായണം ചെയ്യുമെങ്കിലും അത് അവരുടെ തൊണ്ടക്കുഴിക്കപ്പുറം, അല്ലെങ്കിൽ തൊണ്ടകൾക്കപ്പുറത്തേക്ക് ഇറങ്ങുകയില്ല. അവരുടെ അടയാളം മുണ്ഡനം ചെയ്യലാണ്. നിങ്ങൾ അവരെ കണ്ടാൽ - അല്ലെങ്കിൽ: കണ്ടുമുട്ടിയാൽ - വധിക്കുക." (ദ,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: "شَرُّ قَتْلَى قُتِلُوا تَحْتَ أَدِيمِ السَّمَاءِ، وَخَيْرُ قَتِيلٍ مَنْ قَتَلُوا، كِلَابُ أَهْلِ النَّارِ، قَدْ كَانَ هَؤُلَاءِ مُسْلِمِينَ فَصَارُوا كُفَّارًا". قِيلَ: يَا أَبَا أُمَامَةَ، هَذَا شَيْءٌ تَقُولُهُ؟ قَالَ: بَلْ سَمِعْتُهُ مِنْ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (ت,جه)', 'അബൂഉമാമ(റ): "ആകാശത്തിനു ചുവട്ടിൽ കൊല്ലപ്പെട്ടവരിൽ ഏറ്റവും മോശക്കാർ നരകത്തിലെ നായകളും (ഖവാരിജുകൾ) കൊല്ലപ്പെട്ടവരിൽ ഏറ്റവും ഉത്തമർ അവർ വധിച്ചവരുമാണ്. അക്കൂട്ടർ മുസ്ലിംകളായിരുന്നു. പിന്നീടവർ സത്യനിഷേധികളായി മാറി." അബൂഉമാമ(റ)വിനോട് ചോദിക്കപ്പെട്ടു: അബൂഉമാമ! ഇത് താങ്കൾ സ്വന്തമായി പറയുകയാണോ? അബൂഉമാമ(റ) പറഞ്ഞു: അല്ല, റസൂൽ(സ)യിൽ നിന്ന് ഞാനിത് കേട്ടു. (തു,ജ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِب رَضِيَ اللَّهُ عَنْهُ، وَذَكَرَ الْخَوَارِجَ، فَقَالَ: "فِيهِمْ رَجُلٌ مُخْدَجُ الْيَدِ، أَوْ: مَوْدُونُ الْيَدِ، أَوْ: مَثْدُونُ الْيَدِ". وَلَوْلَا أَنْ تَبْطَرُوا لَحَدَّثْتُكُمْ بِمَا وَعَدَ اللَّهُ الَّذِينَ يَقْتُلُونَهُمْ، عَلَى لِسَانِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قُلْتُ: أَنْتَ سَمِعْتَهُ مِنْ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: إِي، وَرَبِّ الْكَعْبَةِ. ثَلَاثَ مَرَّاتٍ. (م,د,جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): ഖവാരിജുകളെ പരാമർശിച്ചുകൊണ്ട് അവർ പറഞ്ഞു: "അവരിൽ ചെറിയ കയ്യുള്ള ഒരു വ്യക്തിയുണ്ട്." നിങ്ങൾ അത്യാഹ്ലാദം പ്രകടിപ്പിക്കില്ലായിരുന്നുവെങ്കിൽ അവരെ വധിക്കുന്നവർക്ക് മുഹമ്മദ് നബി(സ) മുഖേന അല്ലാഹു വാഗ്ദാനം ചെയ്ത പ്രതിഫലം എന്തെന്ന് ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞു തരുമായിരുന്നു. നിവേദകൻ പറയുന്നു: ഞാൻ ചോദിച്ചു: ഇത് നിങ്ങൾ മുഹമ്മദ് നബി(സ)യിൽ നിന്ന് കേട്ടതാണോ? അലി(റ) പറഞ്ഞു: അതെ, കഅ്ബയുടെ രക്ഷിതാവ് തന്നെ സത്യം. അലി(റ) മൂന്നു പ്രാവശ്യം ഇപ്രകാരം പറഞ്ഞു. (മു,ദ,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِب', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 806, 806, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ عَبْدِ اللَّه بْنِ مَسْعُود رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَخْرُجُ فِي آخِرِ الزَّمَانِ قَوْمٌ أَحْدَاثُ الْأَسْنَانِ، سُفَهَاءُ الْأَحْلَامِ، يَقُولُونَ مِنْ خَيْرِ قَوْلِ النَّاسِ، يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ تَرَاقِيَهُمْ، يَمْرُقُونَ مِنَ الْإِسْلَامِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ. فَمَنْ لَقِيَهُمْ فَلْيَقْتُلْهُمْ، فَإِنَّ قَتْلَهُمْ أَجْرٌ عِنْدَ اللَّهِ لِمَنْ قَتَلَهُمْ". (ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ വയസ്സ് കുറഞ്ഞവരും ബുദ്ധിഹീനരുമായ ഒരു കൂട്ടർ പുറപ്പെടും. ജനങ്ങളുടെ സംസാരങ്ങളിൽ ഏറ്റവും ഉത്തമമായ കാര്യങ്ങൾ അവർ പറയും. അവർ ഖുർആൻ പാരായണം ചെയ്യും, പക്ഷേ, അത് അവരുടെ തൊണ്ടക്കുഴികൾക്കപ്പുറം ഇറങ്ങുകയില്ല. വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകുംപോലെ അവർ ഇസ്ലാമിൽനിന്ന് പുറത്തു പോകും. അവരെ കണ്ടുമുട്ടുന്നവർ അവരെ വധിച്ചു കൊള്ളുക. അവരുടെ വധം അവരെ വധിച്ചവർക്ക് അല്ലാഹുവിങ്കൽ പ്രതിഫലമാണ്." (തു,ജ)', 'عَبْدِ اللَّه بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 806, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَعَثَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِذُهَيْبَةٍ فِي تُرْبَتِهَا، فَقَسَمَهَا بَيْنَ أَرْبَعَةٍ: بَيْنَ الْأَقْرَعِ بْنِ حَابِسٍ الْحَنْظَلِيِّ، وَبَيْنَ عُيَيْنَةَ بْنِ بَدْرٍ الْفَزَارِيِّ، وَبَيْنَ زَيْدِ الْخَيْلِ الطَّائِيِّ، وَبَيْنَ عَلْقَمَةَ بْنِ عُلَاثَةَ الْعَامِرِيِّ، قَالَ: فَغَضِبَتْ قُرَيْشٌ وَالْأَنْصَارُ وَقَالَتْ: يُعْطِي صَنَادِيدَ أَهْلِ نَجْدٍ وَيَدَعُنَا، فَقَالَ: "إِنَّمَا أَتَأَلَّفُهُمْ". قَالَ: فَأَقْبَلَ رَجُلٌ غَائِرُ الْعَيْنَيْنِ، مُشْرِفُ الْوَجْنَتَيْنِ، نَاتِئُ الْجَبِينِ، كَثُّ اللِّحْيَةِ، مَحْلُوقٌ، قَالَ: اتَّقِ اللهَ يَا مُحَمَّدُ، فَقَالَ: "مَنْ يُطِيعُ اللهَ إِذَا عَصَيْتُهُ، أَيَأْمَنُنِي اللهُ عَلَى أَهْلِ الْأَرْضِ وَلَا تَأْمَنُونِي". قَالَ: فَسَأَلَ رَجُلٌ قَتْلَهُ، أَحْسِبُهُ خَالِدَ بْنَ الْوَلِيدِ، قَالَ: فَمَنَعَهُ، قَالَ: فَلَمَّا وَلَّى قَالَ: "إِنَّ مِنْ ضِئْضِئِ هَذَا – أَوْ: فِي عَقِبِ هَذَا – قَوْمًا يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ حَنَاجِرَهُمْ، يَمْرُقُونَ مِنَ الْإِسْلَامِ مُرُوقَ السَّهْمِ مِنَ الرَّمِيَّةِ، يَقْتُلُونَ أَهْلَ الْإِسْلَامِ وَيَدَعُونَ أَهْلَ الْأَوْثَانِ، لَئِنْ أَنَا – وَاللهِ – أَدْرَكْتُهُمْ قَتَلْتُهُمْ قَتْلَ عَادٍ". (خ,د)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ): ശുദ്ധീകരിക്കാത്ത അൽപം സ്വർണ്ണക്കഷ്ണങ്ങൾ റസൂൽ(സ)യുടെ പക്കലേക്ക് അലി(റ) അയച്ചുകൊടുത്തു. റസൂൽ(സ) അത് അഖ്റഉബ്നു ഹാബിസുൽ ഹൻളലി(റ), ഉയൈനതുബ്നു ബദ്റുൽ ഫസാരി(റ), സൈദുൽ ഖൈലിത്ത്വാഇൗ(റ), അൽഖമതുബ്നു ഉലാസതുൽ ആമിരീ(റ) എന്നീ നാലുപേർക്ക് വീതിച്ചു നൽകി. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഖുറൈശികളും അൻസാരികളും ദേഷ്യപ്പെട്ടുകൊണ്ട് പറഞ്ഞു: നബി(സ) നജ്ദിലെ പ്രമുഖർക്ക് നൽകുകയും ഞങ്ങളെ ഒഴിവാക്കുകയും ചെയ്യുന്നു. നബി(സ) പറഞ്ഞു: "ഞാൻ അവരെ (ഇസ്ലാമിലേക്ക്) ഇണക്കിച്ചേർക്കുക മാത്രമാണ് ചെയ്യുന്നത്." നിവേദകൻ പറയുന്നു: ഉടനെ കണ്ണുകൾ കുഴിഞ്ഞ, കവിളുകൾ തുടിച്ച, ഉയർന്ന നെറ്റിയും തിങ്ങിയ താടിയുമുള്ള, തല മുണ്ഡനം ചെയ്ത ഒരാൾ വന്നുകൊണ്ട് പറഞ്ഞു: മുഹമ്മദേ, താങ്കൾ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. നബി(സ) പറഞ്ഞു: "ഞാൻ അല്ലാഹുവിന് അനുസരണക്കേട് കാണിക്കുന്നു എങ്കിൽ ആരാണ് അവനെ അനുസരിക്കാനുള്ളത്? ഇഹലോകരുടെ കാര്യത്തിൽ അല്ലാഹു എന്നെ വിശ്വസിക്കുകയും നിങ്ങൾ വിശ്വസിക്കാതിരിക്കുകയും ചെയ്യുന്നുവോ?" അപ്പോൾ ഒരാൾ - അത് ഖാലിദുബ്നുൽ വലീദ്(റ)വായിരുന്നു എന്നാണ് ഞാൻ കരുതുന്നത് - ആ മനുഷ്യനെ വധിക്കാൻ അനുവാദം ചോദിച്ചു. നബി(സ) അദ്ദേഹത്തെ തടഞ്ഞു. ആ മനുഷ്യൻ പോയപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇവന്റെ പരമ്പരയിൽ - അല്ലെങ്കിൽ: ഇവന്റെ പിറകിൽ - ഒരു സമൂഹം വരും. അവർ ഖുർആൻ പാരായണം ചെയ്യുമെങ്കിലും അത് അവരുടെ തൊണ്ടകൾക്കപ്പുറം പ്രവേശിക്കുകയില്ല. വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകുംപോലെ അവർ ഇസ്ലാമിൽനിന്ന് പുറത്തുപോകും. അവർ മുസ്ലിംകളെ വധിക്കുകയും ബിംബാരാധകരെ വെറുതെ വിടുകയും ചെയ്യും. അല്ലാഹുവാണ, ഞാൻ അവരെ കണ്ടുമുട്ടുകയാണെങ്കിൽ ആദ് സമൂഹത്തെ വധിച്ചതു പോലെ അവരെ വധിക്കുകതന്നെ ചെയ്യും." (ബു,ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 807, 807, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ أَبِي سَعِيد الْخُدْرِيِّ وَأَنَسِ بْنِ مَالِك رَضِيَ اللَّهُ عَنْهُمَا، عَنْ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "سَيَكُونُ فِي أُمَّتِي اخْتِلَافٌ وَفُرْقَةٌ، قَوْمٌ يُحْسِنُونَ الْقِيلَ وَيُسِيئُونَ الْفِعْلَ، يَقْرَءُونَ الْقُرْآنَ لَا يُجَاوِزُ تَرَاقِيَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ مُرُوقَ السَّهْمِ مِنَ الرَّمِيَّةِ، لَا يَرْجِعُونَ حَتَّى يَرْتَدَّ عَلَى فُوقِه، هُمْ شَرُّ الْخَلْقِ وَالْخَلِيقَةِ، طُوبَى لِمَنْ قَتَلَهُمْ وَقَتَلُوهُ، يَدْعُونَ إِلَى كِتَابِ اللَّه وَلَيْسُوا مِنْهُ فِي شَيْءٍ، مَنْ قَاتَلَهُمْ كَانَ أَوْلَى بِاللَّه مِنْهُمْ". قَالُوا: يَا رَسُولَ اللَّهِ، مَا سِيمَاهُمْ؟ قَالَ: "التَّحْلِيقُ". وَفِي رِوَايَةٍ: "سِيمَاهُمُ التَّحْلِيقُ وَالتَّسْبِيدُ، فَإِذَا رَأَيْتُمُوهُمْ فَأَنِيمُوهُمْ". (د)', 'അബൂസഈദുൽ ഖുദ്‌രി(റ), അനസുബ്നു മാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിൽ അഭിപ്രായ ഭിന്നതയും അനൈക്യവുമുണ്ടാകും. ഒരു കൂട്ടർ പറഞ്ഞുകേട്ടതിനെ നന്നായി കാണുകയും പ്രവർത്തനങ്ങളെ മോശമാക്കുകയും ചെയ്യും. അവർ ഖുർആൻ പാരായണം ചെയ്യും. പക്ഷേ, അത് അവരുടെ തൊണ്ടക്കുഴികൾക്കപ്പുറം കടക്കുകയില്ല. വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകുംപോലെ അവർ ഇസ്ലാമിൽനിന്ന് പുറത്തുപോകും. അമ്പ് അതിന്റെ ഞാണിലേക്ക് തിരികെ വരുംവരെ അവർ (മതത്തിലേക്ക്) മടങ്ങിവരികയില്ല. അവർ ഏറ്റവും മോശപ്പെട്ട സൃഷ്ടികളും ഏറ്റവും മോശമായ സ്വഭാവമുള്ളവരുമാണ്. അവരെ വധിച്ചവർക്കും അവർ വധിച്ചവർക്കും സന്തോഷവാർത്തയുണ്ട്. അവർ അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിലേക്ക് ക്ഷണിക്കും. പക്ഷേ, അവർക്ക് അതിനോട് യാതൊരു ബന്ധവും ഉണ്ടായിരിക്കുകയില്ല. അവരോട് യുദ്ധം ചെയ്യുന്നവർ അല്ലാഹുവിനോട് അവരേക്കാൾ അടുത്തവർ ആയിരിക്കും." അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അവരുടെ ലക്ഷണമെന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "തല മുണ്ഡനം ചെയ്യൽ." മറ്റൊരു നിവേദനം: "അവരുടെ ലക്ഷണം തല മുണ്ഡനം ചെയ്യലും മുടി കളയലുമാണ്. അവരെ കണ്ടാൽ നിങ്ങൾ വധിച്ചു കളയുക." (ദ)', 'أَبِي سَعِيد الْخُدْرِيِّ وَأَنَسِ بْنِ مَالِك', 'അബൂസഈദുൽ ഖുദ്‌രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 807, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=100), 1, 'وَفِي رِوَايَةٍ: "سِيمَاهُمُ التَّحْلِيقُ وَالتَّسْبِيدُ، فَإِذَا رَأَيْتُمُوهُمْ فَأَنِيمُوهُمْ". (د)', 'മറ്റൊരു നിവേദനം: "അവരുടെ ലക്ഷണം തല മുണ്ഡനം ചെയ്യലും മുടി കളയലുമാണ്. അവരെ കണ്ടാൽ നിങ്ങൾ വധിച്ചു കളയുക." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ سُوَيْد بْنِ غَفَلَةَ قَالَ: قَالَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ: إِذَا حَدَّثْتُكُمْ عَنْ رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدِيثًا: فَلَأَنْ أَخِرَّ مِنَ السَّمَاءِ أَحَبُّ إِلَيَّ مِنْ أَنْ أَكْذِبَ عَلَيْهِ، وَإِذَا حَدَّثْتُكُمْ فِيمَا بَيْنِي وَبَيْنَكُمْ فَإِنَّمَا الْحَرْبُ خَدْعَةٌ، سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَأْتِي فِي آخِرِ الزَّمَانِ قَوْمٌ حُدَثَاءُ الْأَسْنَانِ، سُفَهَاءُ الْأَحْلَامِ، يَقُولُونَ مِنْ قَوْلِ خَيْرِ الْبَرِيَّةِ، يَمْرُقُونَ مِنَ الْإِسْلَامِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، لَا يُجَاوِزُ إِيمَانُهُمْ حَنَاجِرَهُمْ، فَأَيْنَمَا لَقِيتُمُوهُمْ فَاقْتُلُوهُمْ، فَإِنَّ قَتْلَهُمْ أَجْرٌ لِمَنْ قَتَلَهُمْ يَوْمَ الْقِيَامَةِ". (ق,د)', 'സുവൈദുബ്നു ഗഫല(റ): അലി(റ) പറഞ്ഞു: റസൂൽ(സ)യിൽ നിന്നുള്ള വല്ല ഹദീസും ഞാൻ നിങ്ങൾക്ക് പറഞ്ഞു തരുന്നുവെങ്കിൽ, അവിടുത്തെ പേരിൽ കളവു പറയുന്നതിനേക്കാൾ എനക്കിഷ്ടം ആകാശത്തുനിന്ന് ഞാൻ വീഴലാണ്. നമുക്കിടയിലെ വിഷയത്തെ കുറിച്ചാണ് ഞാൻ പറയുന്നതെങ്കിൽ, നിശ്ചയമായും യുദ്ധം വഞ്ചനയാണ്. റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "അന്ത്യനാളിൽ പ്രായം കുറഞ്ഞവരും ബുദ്ധിഹീനരുമായ ഒരു സമൂഹം പുറപ്പെടും. ഏറ്റവും ഉത്തമ സൃഷ്ടികളുടെ സംസാരമവർ സംസാരിക്കും. വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകും പോലെ ഇസ്ലാമിൽനിന്ന് അവർ പുറത്തുപോകും. അവരുടെ വിശ്വാസം തൊണ്ടക്കുഴികൾക്കപ്പുറം കടക്കുകയില്ല. എവിടെ വെച്ച് കണ്ടുമുട്ടിയാലും നിങ്ങൾ അവരെ വധിക്കുക. അവരെ വധിക്കൽ അവരുടെ ഘാതകർക്ക് അന്ത്യനാളിൽ പ്രതിഫലമാണ്." (ബു,മു,ദ)', 'سُوَيْد بْنِ غَفَلَةَ قَالَ', 'സുവൈദുബ്നു ഗഫല(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 808, 808, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَيُّهَا النَّاسُ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَخْرُجُ قَوْمٌ مِنْ أُمَّتِي يَقْرَءُونَ الْقُرْآنَ، لَيْسَتْ قِرَاءَتُكُمْ إِلَى قِرَاءَتِهِمْ شَيْئًا، وَلَا صَلَاتُكُمْ إِلَى صَلَاتِهِمْ شَيْئًا، وَلَا صِيَامُكُمْ إِلَى صِيَامِهِمْ شَيْئًا، يَقْرَءُونَ الْقُرْآنَ يَحْسَبُونَ أَنَّهُ لَهُمْ وَهُوَ عَلَيْهِمْ، لَا تُجَاوِزُ صَلَاتُهُمْ تَرَاقِيَهُمْ، يَمْرُقُونَ مِنَ الْإِسْلَامِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، لَوْ يَعْلَمُ الْجَيْشُ الَّذِينَ يُصِيبُونَهُمْ مَا قُضِيَ لَهُمْ عَلَى لِسَانِ نَبِيِّهِمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَنَكَلُوا عَنِ الْعَمَلِ، وَآيَةُ ذَلِكَ: أَنَّ فِيهِمْ رَجُلًا لَهُ عَضُدٌ وَلَيْسَتْ لَهُ ذِرَاعٌ، عَلَى عَضُدِه مِثْلُ حَلَمَةِ الثَّدْيِ، عَلَيْهِ شَعَرَاتٌ بِيضٌ". أَفَتَذْهَبُونَ إِلَى مُعَاوِيَةَ وَأَهْلِ الشَّامِ وَتَتْرُكُونَ هَؤُلَاءِ يَخْلُفُونَكُمْ فِي ذَرَارِيِّكُمْ وَأَمْوَالِكُمْ؟ وَاللَّه، إِنِّي لَأَرْجُو أَنْ يَكُونُوا هَؤُلَاءِ الْقَوْمَ، فَإِنَّهُمْ قَدْ سَفَكُوا الدَّمَ الْحَرَامَ، وَأَغَارُوا فِي سَرْحِ النَّاسِ، فَسِيرُوا عَلَى اسْمِ اللهِ. قَالَ سَلَمَةُ بْنُ كُهَيْلٍ: فَنَزَّلَنِي زَيْدُ بْنُ وَهْبٍ مَنْزِلًا مَنْزِلًا، حَتَّى مَرَّ بِنَا عَلَى قَنْطَرَةٍ، قَالَ: فَلَمَّا الْتَقَيْنَا – وَعَلَى الْخَوَارِجِ عَبْدُ اللهِ بْنُ وَهْبٍ الرَّاسِبِيُّ – فَقَالَ لَهُمْ: أَلْقُوا الرِّمَاحَ وَسُلُّوا السُّيُوفَ مِنْ جُفُونِهَا، فَإِنِّي أَخَافُ أَنْ يُنَاشِدُوكُمْ كَمَا نَاشَدُوكُمْ يَوْمَ حَرُورَاءَ. قَالَ: فَوَحَّشُوا بِرِمَاحِهِمْ، وَاسْتَلُّوا السُّيُوفَ، وَشَجَرَهُمُ النَّاسُ بِرِمَاحِهِمْ، قَالَ: وَقَتَلُوا بَعْضُهُمْ عَلَى بَعْضِهِمْ، قَالَ: وَمَا أُصِيبَ مِنَ النَّاسِ يَوْمَئِذٍ إِلَّا رَجُلَانِ، فَقَالَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ: الْتَمِسُوا فِيهِمُ الْمُخْدَجَ، فَلَمْ يَجِدُوا، قَالَ: فَقَامَ عَلِيٌّ رَضِيَ اللهُ عَنْهُ بِنَفْسِهِ، حَتَّى أَتَى نَاسًا قَدْ قُتِلَ بَعْضُهُمْ عَلَى بَعْضٍ، فَقَالَ: أَخْرِجُوهُمْ، فَوَجَدُوهُ مِمَّا يَلِي الْأَرْضَ، فَكَبَّرَ وَقَالَ: صَدَقَ اللهُ، وَبَلَّغَ رَسُولُهُ. فَقَامَ إِلَيْهِ عَبِيدَةُ السَّلْمَانِيُّ فَقَالَ: يَا أَمِيرَ الْمُؤْمِنِينَ، وَاللهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، لَقَدْ سَمِعْتَ هَذَا مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَالَ: إِي، وَاللهِ الَّذِي لَا إِلَهَ إِلَّا هُوَ، حَتَّى اسْتَحْلَفَهُ ثَلَاثًا، وَهُوَ يَحْلِفُ. (م,د)', 'അലി(റ) പറയുന്നു: ജനങ്ങളേ, റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "എന്റെ സമുദായത്തിൽ നിന്നുള്ള ഒരു കൂട്ടർ പുറപ്പെടും. അവർ ഖുർആൻ പാരായണം ചെയ്യും. അവരുടെ ഖുർആൻ പാരായണത്തോട് ചേർത്തു നോക്കിയാൽ നിങ്ങളുടെ ഖുർആൻ പാരായണവും, അവരുടെ നമസ്കാരത്തോട് ചേർത്തു നോക്കിയാൽ നിങ്ങളുടെ നമസ്കാരവും, അവരുടെ നോമ്പിനോട് ചേർത്തു നോക്കിയാൽ നിങ്ങളുടെ നോമ്പും വളരെ നിസാരമായിരിക്കും. ഖുർആൻ പാരായണം ചെയ്യുമ്പോൾ അത് തങ്ങൾക്ക് അനുകൂലമാണെന്ന് അവർ കരുതും. എന്നാലത് അവർക്ക് പ്രതികൂലമായിരിക്കും. അവരുടെ നിസ്കാരം തങ്ങളുടെ തൊണ്ടക്കുഴികൾക്കപ്പുറം കടക്കുകയില്ല. വേട്ടമൃഗത്തിന്റെ ശരീരത്തിലൂടെ അമ്പ് തുളച്ച് മറുപുറം കടന്നുപോകുംപോലെ ഇസ്ലാമിൽനിന്ന് അവർ പുറത്തുപോകും. അവരോട് പോരാടുന്ന സൈന്യത്തിന് തങ്ങളുടെ പ്രവാചകന്റെ നാവിലൂടെ വാഗ്ദാനം ചെയ്യപ്പെട്ട പ്രതിഫലം ആ സൈന്യം അറിയുകയാണെങ്കിൽ മറ്റു കർമ്മങ്ങളിൽനിന്ന് അവർ അകന്നു നിൽക്കും. അതിന്റെ ലക്ഷണം അവരുടെ കൂട്ടത്തിൽ മുഴംകൈ ഇല്ലാതെ മേൽകൈ മാത്രമുള്ള ഒരാളുണ്ട് എന്നതാണ്. അദ്ദേഹത്തിന്റെ മേൽകയ്യിനു മേൽ സ്ത്രീകളുടെ മുലക്കണ്ണ് പോലുള്ള ഒരു ഭാഗമുണ്ടാകും. അതിനുമേൽ വെളുത്ത രോമങ്ങളും ഉണ്ടാകും." ഇക്കൂട്ടരെ നിങ്ങളുടെ മുതലുകൾക്കും സന്താനങ്ങൾക്കുമിടയിൽ ഉപേക്ഷിച്ചുകൊണ്ട് നിങ്ങൾ മുആവിയ(റ)വിനോടും ശാമുകാരോടും പോരാടാൻ പോകുന്നുവോ? അല്ലാഹു തന്നെ സത്യം, ഇക്കൂട്ടർ തന്നെയാണ് ആ സമൂഹമെന്ന് ഞാൻ കരുതുന്നു. അവർ നിഷിദ്ധമായ രക്തം ചിന്തുകയും ജനങ്ങളുടെ മൃഗങ്ങളെ കൈവശപ്പെടുത്തുകയും ചെയ്തിരിക്കുന്നു. അതിനാൽ അല്ലാഹുവിന്റെ നാമത്തിൽ നിങ്ങൾ ഇറങ്ങിപ്പുറപ്പെടുക. സലമതുബ്നു കുഹൈൽ(റ) പറയുന്നു: സൈദുബ്നു വഹബ്(റ) എനിക്ക് സൈന്യം തമ്പടിച്ച ഓരോ സ്ഥലവും പറഞ്ഞുതന്നു. അങ്ങനെ ഒരു പാലത്തിനു മുകളിലൂടെ ഞങ്ങളെ കൊണ്ടുപോയി. നിവേദകൻ പറയുന്നു: അങ്ങനെ ഞങ്ങൾ പരസ്പരം പോരടിച്ചപ്പോൾ ഖവാരിജുകളുടെ സൈന്യാധിപനായ അബ്ദുല്ലാഹിബ്നു വഹബുർറാസിബി അവരോട് പറഞ്ഞു: നിങ്ങൾ കുന്തങ്ങൾ എറിയുക, ഉറകളിൽ നിന്ന് വാളുകൾ ഊരുക. ഹറൂറാ ദിവസം അവർ നിങ്ങളെ സത്യം ചെയ്യിച്ച പോലെ സത്യം ചെയ്യിക്കുമോ എന്നു ഞാൻ ഭയപ്പെടുന്നു. നിവേദകൻ പറയുന്നു: അങ്ങനെ അവർ (ദൂരെനിന്ന്) കുന്തങ്ങൾ എറിയുകയും വാളുകൾ ഊരുകുയും ചെയ്തു. ജനങ്ങൾ അവരെ കുന്തങ്ങൾകൊണ്ട് കുത്തി. അങ്ങനെ അവരെ മേൽക്കുമേൽ വധിച്ചിട്ടു. നിവേദകൻ പറയുന്നു: ജനങ്ങളിൽ (അലി(റ)വിന്റെ സൈന്യത്തിൽ) നിന്ന് അന്ന് രണ്ടുപേർ മാത്രമാണ് വധിക്കപ്പെട്ടത്. അലി(റ) പറഞ്ഞു: മുറിയൻ കയ്യുള്ള വ്യക്തിയെ നിങ്ങൾ അവർക്കിടയിൽ തിരയുക. പക്ഷേ, അവർ കണ്ടില്ല. ഉടനെ അലി(റ) എഴുന്നേറ്റ് കൊല്ലപ്പെട്ട് മേൽക്കുമേൽ കിടക്കുന്ന ആളുകളുടെ അടുത്ത് വന്ന് പറഞ്ഞു: അവരെ പുറത്തെടുക്കുക. അങ്ങനെ ഏകദേശം അടിയിൽവെച്ച് അവർ ആ വ്യക്തിയെ കണ്ടെത്തി. അപ്പോൾ അലി(റ) തക്ബീർ ചൊല്ലിക്കൊണ്ട് പറഞ്ഞു: അല്ലാഹു പറഞ്ഞത് വാസ്തവമാണ്, അല്ലാഹുവിന്റെ റസൂൽ(സ) അക്കാര്യം (നമുക്ക്) എത്തിച്ചുതരികയും ചെയ്തിരിക്കുന്നു. ഉടനെ അബീദതുസ്സൽമാനി(റ) അലി(റ)വിന്റെ അടുത്ത് ചെന്ന് ചോദിച്ചു: അമീറുൽ മുഅ്മിനീൻ! അല്ലാഹു തന്നെ സത്യം, അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല, ഇക്കാര്യം താങ്കൾ റസൂൽ(സ)യിൽനിന്ന് കേട്ടുവോ? അലി(റ) പറഞ്ഞു: അതെ, അല്ലാഹു തന്നെ സത്യം, അവനല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല. ഇപ്രകാരം മൂന്നു പ്രാവശ്യം അബീദതുസ്സൽമാനി(റ) സത്യംചെയ്യിക്കുകയും അലി(റ) സത്യംചെയ്ത് പറയുകയും ചെയ്തു. (മു,ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 808, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: اطْلُبُوا الْمُخْدَجَ، فَذَكَرَ الْحَدِيثَ، فَاسْتَخْرَجُوهُ مِنْ تَحْتِ الْقَتْلَى فِي طِينٍ، قَالَ أَبُو الْوَضِيءِ: فَكَأَنِّي أَنْظُرُ إِلَيْه حَبَشِيٌّ عَلَيْه قُرَيْطِقٌ، لَهُ إِحْدَى يَدَيْنِ مِثْلُ ثَدْيِ الْمَرْأَة، عَلَيْهَا شُعَيْرَاتٌ مِثْلُ شُعَيْرَاتِ الَّتِي تَكُونُ عَلَى ذَنَبِ الْيَرْبُوعِ. (د)', 'അലി(റ): മുറിയൻ കയ്യുള്ള വ്യക്തിയെ നിങ്ങൾ അന്വേഷിക്കുക. ശേഷം നിവേദകൻ ഹദീസ് പറഞ്ഞു. അങ്ങനെ കൊല്ലപ്പെട്ടവർക്കിടയിൽ മണ്ണിൽനിന്ന് അവർ ആ വ്യക്തിയെ പുറത്തെടുത്തു. അബുൽവളീഅ്(റ) പറയുന്നു: അനറബീ വസ്ത്രം ധരിച്ച അബ്സീനിയക്കാരനായ അവനെ ഞാൻ ഇപ്പോഴും നോക്കുന്നതു പോലെയുണ്ട്. അവന്റെ ഇരു കരങ്ങളിൽ ഒന്ന് സത്രീകളുടെ മുല പോലെയായിരുന്നു. അതിനുമേൽ പെരുച്ചാഴിയുടെ രോമങ്ങൾ പോലുള്ള രോമങ്ങൾ ഉണ്ടായിരുന്നു. (ദ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ أَبِي مَرْيَمَ الثَّقَفِي قَالَ: إِنْ كَانَ ذَلِكَ الْمُخْدَجُ لَمَعَنَا يَوْمَئِذٍ فِي الْمَسْجِد، نُجَالِسُهُ بِاللَّيْلِ وَالنَّهَارِ، وَكَانَ فَقِيرًا، وَرَأَيْتُهُ مَعَ الْمَسَاكِينِ يَشْهَدُ طَعَامَ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ مَعَ النَّاسِ، وَقَدْ كَسَوْتُهُ بُرْنُسًا لِي. قَالَ أَبُو مَرْيَمَ: وَكَانَ الْمُخْدَجُ يُسَمَّى نَافِعًا ذَا الثُّدَيَّةِ، وَكَانَ فِي يَدِه مِثْلُ ثَدْيِ الْمَرْأَة، عَلَى رَأْسِه حَلَمَةٌ مِثْلُ حَلَمَةِ الثَّدْيِ، عَلَيْه شُعَيْرَاتٌ مِثْلُ سِبَالَةِ السِّنَّوْرِ. (د)', 'അബൂമർയമുസ്സഖഫീ(റ): ആ മുറിയൻ കയ്യുള്ള വ്യക്തി അന്നു പള്ളിയിൽ ഞങ്ങളോടൊപ്പം ഉണ്ടായിരുന്നു. രാപകലുകളിൽ ഞങ്ങൾ അദ്ദേഹത്തോടൊപ്പം ഇരിക്കുമായിരുന്നു. ദരിദ്രനായിരുന്ന അയാൾ ജനങ്ങൾക്കിടയിൽ ദരിദ്രരോടൊപ്പം അലി(റ)വിന്റെ സദ്യയിൽ പങ്കെടുക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അദ്ദേഹത്തിന് ഞാൻ എന്റെ ഒരു തൊപ്പി അണിയിച്ചിരുന്നു. അബൂമർയം(റ) പറയുന്നു: മുറിയൻ കയ്യുള്ള ആ വ്യക്തി നാഫിഅ് ദുസ്സുദയ്യ എന്നായിരുന്നു അറിയപ്പെട്ടിരുന്നത്. അവന്റെ കയ്യിന്മേൽ സ്ത്രീകളുടെ മുലപോലുള്ള ഒരു ഭാഗമുണ്ടായിരുന്നു. അതിന്റെ അഗ്രഭാഗത്ത് മുലക്കണ്ണി പോലോത്ത ഒരു ഭാഗവും അതിനുമേൽ പൂച്ചയുടെ മീശ പോലുള്ള രോമങ്ങളുമുണ്ടായിരുന്നു. (ദ)', 'أَبِي مَرْيَمَ الثَّقَفِي قَالَ', 'അബൂമർയമുസ്സഖഫീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزَالُ النَّاسُ يَتَسَاءَلُونَ حَتَّى يُقَالَ: هَذَا خَلَقَ اللَّهُ الْخَلْقَ، فَمَنْ خَلَقَ اللَّهَ؟ فَمَنْ وَجَدَ مِنْ ذَلِكَ شَيْئًا فَلْيَقُلْ: آمَنْتُ بِاللَّه". (ق,د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ജനങ്ങൾ ചോദ്യമുന്നയിച്ചു കൊണ്ടേയിരിക്കും. അവസാനം ഇപ്രകാരം പോലും ചോദിക്കപ്പെടും: അല്ലാഹുവാണ് സൃഷ്ടികളെ സൃഷ്ടിച്ചത്, എങ്കിൽ ആരാണ് അല്ലാഹുവിനെ സൃഷ്ടിച്ചത്? ഇത്തരത്തിലുള്ള വല്ലതും ആരെങ്കിലും കേൾക്കുന്നുവെങ്കിൽ ''ഞാൻ അല്ലാഹുവിൽ വിശ്വസിച്ചിരിക്കുന്നു'' എന്ന് അവൻ പറഞ്ഞുകൊള്ളട്ടെ." (ബു,മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 810, 810, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ، فَذَكَرَ نَحْوَهُ قَالَ: "فَإِذَا قَالُوا ذَلِكَ فَقُولُوا: {اللَّهُ أَحَدٌ، اللَّهُ الصَّمَدُ، لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} ثُمَّ لِيَتْفُلْ عَنْ يَسَارِه ثَلَاثًا، وَلْيَسْتَعِذْ مِنَ الشَّيْطَانِ". (د)', 'അബൂഹുറൈറ(റ): ''റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു'' എന്ന് പറഞ്ഞ് അബൂഹുറൈറ(റ) ഇങ്ങനെയെന്തോ പറഞ്ഞു: (റസൂൽ(സ) പറഞ്ഞു:) "അവർ അപ്രകാരം ചോദിച്ചാൽ നിങ്ങൾ പറയുക: അല്ലാഹു ഏകനാണ്, അവൻ ഏവർക്കും ആശ്രയമായിട്ടുള്ളവനാണ്, അവൻ (ആർക്കും) ജന്മം നൽകിയിട്ടില്ല, (ആരുടെയും സന്തതിയായി) അവൻ ജനിച്ചിട്ടുമില്ല, അവന് തുല്ല്യനായി മറ്റൊരാളില്ല. ശേഷം അവൻ തന്റെ ഇടതു ഭാഗത്തേക്ക് മൂന്നു പ്രാവശ്യം തുപ്പുകയും പിശാചിൽനിന്ന് കാവൽ ചോദിക്കുകയും ചെയ്തുകൊള്ളട്ടെ." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 810, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنْتُ فِي الْبَطْحَاءِ فِي عِصَابَةٍ فِيهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ، فَمَرَّتْ بِهِمْ سَحَابَةٌ فَنَظَرَ إِلَيْهَا، فَقَالَ: "مَا تُسَمُّونَ هَذِه". قَالُوا: السَّحَابَ، قَالَ: "وَالْمُزْنَ". قَالُوا: وَالْمُزْنَ، قَالَ: "وَالْعَنَانَ". قَالُوا: وَالْعَنَانَ، قَالَ: "هَلْ تَدْرُونَ مَا بُعْدُ مَا بَيْنَ السَّمَاءِ وَالْأَرْضِ". قَالُوا: لَا نَدْرِي، قَالَ: "إِنَّ بُعْدَ مَا بَيْنَهُمَا إِمَّا وَاحِدَةٌ أَوِ اثْنَتَانِ أَوْ ثَلَاثٌ وَسَبْعُونَ سَنَةً، ثُمَّ السَّمَاءُ فَوْقَهَا كَذَلِكَ" حَتَّى عَدَّ سَبْعَ سَمَاوَاتٍ. "ثُمَّ فَوْقَ السَّابِعَةِ بَحْرٌ بَيْنَ أَسْفَلِه وَأَعْلَاهُ مِثْلُ مَا بَيْنَ سَمَاءٍ إِلَى سَمَاءٍ، ثُمَّ فَوْقَ ذَلِكَ ثَمَانِيَةُ أَوْعَالٍ بَيْنَ أَظْلَافِهِمْ وَرُكَبِهِمْ مِثْلُ مَا بَيْنَ سَمَاءٍ إِلَى سَمَاءٍ، ثُمَّ عَلَى ظُهُورِهِمُ الْعَرْشُ: بَيْنَ أَسْفَلِه وَأَعْلَاهُ مِثْلُ مَا بَيْنَ سَمَاءٍ إِلَى سَمَاءٍ، ثُمَّ اللَّهُ تَبَارَكَ وَتَعَالَى فَوْقَ ذَلِكَ". (د,ت,جه)', 'അബ്ബാസുബ്നു അബ്ദിൽ മുത്ത്വലിബ്(റ): റസൂൽ(സ) ഉൾകൊള്ളുന്ന ഒരു സംഘത്തോടൊപ്പം ഞാൻ ബത്ഹാഇൽ (ചരൽ പ്രദേശം) നടക്കുകയായിരുന്നു. അപ്പോൾ അവർക്കു മുകളിൽ ഒരു മേഘം സഞ്ചരിക്കുകയും അതിലേക്ക് നോക്കിക്കൊണ്ട് തിരുമേനി(സ) ഇപ്രകാരം പറയുകയും ചെയ്തു: "ഇതിനെ നിങ്ങൾ എന്താണ് വിളിക്കുക." അവർ പറഞ്ഞു: സഹാബ് (മേഘം). റസൂൽ(സ) ചോദിച്ചു: "മുസ്ന് (മേഘത്തിനുള്ള മറ്റൊരു അറബീ വാക്ക്) എന്നും വിളിക്കില്ലേ?" അവർ പറഞ്ഞു: മുസ്ന് എന്നും വിളിക്കും. റസൂൽ(സ) ചോദിച്ചു: "അനാൻ (മേഘത്തിനുള്ള മറ്റൊരു വാക്ക്) എന്നും വിളിക്കില്ലേ?" അവർ പറഞ്ഞു: അതെ, അനാൻ എന്നും വിളിക്കും. റസൂൽ(സ) ചോദിച്ചു: "ആകാശത്തിനും ഭൂമിക്കും ഇടയിലുള്ള അകലം എത്രയാണെന്ന് നിങ്ങൾക്കറിയുമോ?" അവർ പറഞ്ഞു: ഞങ്ങൾക്കറിയില്ല. റസൂൽ(സ) പറഞ്ഞു: "അവ രണ്ടിനും ഇടയിൽ എഴുപത്തിഒന്നോ എഴുപത്തിരണ്ടോ എഴുപത്തിമൂന്നോ വർഷത്തെ അകലമുണ്ട്. പിന്നെ അതിനു മുകളിൽ അതുപോലെ ആകാശമുണ്ട്." അങ്ങനെ റസൂൽ(സ) ഏഴ് ആകാശങ്ങളെ എണ്ണി. "പിന്നെ ഏഴാം ആകാശത്തിനു മുകളിൽ ഒരു സമുദ്രമുണ്ട്. അതിന്റെ താഴ്ഭാഗത്തിനും മുകൾ ഭാഗത്തിനും ഇടയിലെ അകലം ഒരു ആകാശത്തിൽ നിന്നും മറ്റൊരു ആകാശത്തിലേക്കുള്ള അകലം പോലെയാണ്. പിന്നെ അതിനു മുകളിൽ എട്ട് മാനുകളുണ്ട്³. അവയുടെ കുളമ്പുകൾക്കും മുട്ടുകൾക്കും ഇടയിലെ അകലം രണ്ട് ആകാശങ്ങൾക്കിടയിലേതു പോലെയാണ്. പിന്നെ അവയുടെ മുതുകിലാണ് അർശ് നിലകൊള്ളുന്നത്. അർശിന്റെ താഴ്ഭാഗത്തിനും മുകൾഭാഗത്തിനും ഇടയിലെ അകലം ഒരു ആകാശത്തിൽ നിന്നും മറ്റൊരു ആകാശത്തിലേക്കുള്ള അകലം പോലെയാണ്. പിന്നെ അതിനും മുകളിലാണ് അല്ലാഹു നിലകൊള്ളുന്നത്." (ദ,തു,ജ)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസുബ്നു അബ്ദിൽ മുത്ത്വലിബ്(റ)', '3. മാനുകളുടെ രൂപത്തിലുള്ള മലക്കുകൾ എന്നർത്ഥം.', null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 811, 811, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَعْرَابِيٌّ، فَقَالَ: يَا رَسُولَ اللهِ، جُهِدَتِ الْأَنْفُسُ، وَضَاعَتِ الْعِيَالُ، وَنُهِكَتِ الْأَمْوَالُ، وَهَلَكَتِ الْأَنْعَامُ، فَاسْتَسْقِ اللهَ لَنَا. فَإِنَّا نَسْتَشْفِعُ بِكَ عَلَى اللهِ وَنَسْتَشْفِعُ بِاللهِ عَلَيْكَ. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَيْحَكَ، أَتَدْرِي مَا تَقُولُ". وَسَبَّحَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَمَا زَالَ يُسَبِّحُ حَتَّى عُرِفَ ذَلِكَ فِي وُجُوهِ أَصْحَابِهِ، ثُمَّ قَالَ: "وَيْحَكَ، إِنَّهُ لَا يُسْتَشْفَعُ بِاللهِ عَلَى أَحَدٍ مِنْ خَلْقِهِ، شَأْنُ اللهِ أَعْظَمُ مِنْ ذَلِكَ، وَيْحَكَ أَتَدْرِي مَا اللهُ؟ إِنَّ عَرْشَهُ عَلَى سَمَاوَاتِهِ لَهَكَذَا" وَقَالَ بِأَصَابِعِه مِثْلَ الْقُبَّةِ عَلَيْهِ: "وَإِنَّهُ لَيَئِطُّ بِه أَطِيطَ الرَّحْلِ بِالرَّاكِبِ. إِنَّ اللَّهَ فَوْقَ عَرْشِه، وَعَرْشُهُ فَوْقَ سَمَاوَاتِه". (د)', 'ജൂബൈറുബ്നു മുത്വഇം(റ): ഒരു അഅ്റാബി റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: റസൂലേ, മൃഗങ്ങളെല്ലാം ചത്തൊടുങ്ങുകയും സമ്പത്ത് കുറയുകയും ആശ്രിതർ മരിച്ചു പോവുകയും ജനങ്ങൾ പ്രയാസപ്പെടുകയും ചെയ്തിരിക്കുന്നു. അതിനാൽ അവിടുന്ന് ഞങ്ങൾക്കുവേണ്ടി മഴയെ തേടിയാലും. അങ്ങയെക്കൊണ്ട് ഞങ്ങൾ അല്ലാഹുവിനോട് സഹായമഭ്യർത്ഥിക്കുന്നു, അല്ലാഹുവിനെക്കൊണ്ട് അങ്ങയോടും സഹായമഭ്യർത്ഥിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിനക്ക് നാശം, താൻ എന്താണ് പറയുന്നത് എന്ന് നീ ആലോചിക്കുന്നുണ്ടോ?" എന്നിട്ട് റസൂൽ(സ) തസ്ബീഹ് ചൊല്ലി. തന്റെ അനുചരരുടെ മുഖങ്ങളിലും പ്രശ്നത്തിന്റെ ഗൗരവം തെളിയുന്നതുവരെ റസൂൽ(സ) തസ്ബീഹ് ചൊല്ലിക്കൊണ്ടേയിരുന്നു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "നിനക്ക് നാശം, അല്ലാഹുവിനെക്കൊണ്ട് അവന്റെ സൃഷ്ടികളിൽ ആരോടും സഹായം അഭ്യർത്ഥിക്കാൻ പാടില്ല. അല്ലാഹുവിന്റെ സ്ഥാനം അതിനേക്കാൾ മഹത്വമേറിയതാണ്. നിനക്കു നാശം, അല്ലാഹു എന്തെന്ന് നിനക്കറിയുമോ? അവന്റെ അർശ് (സിംഹാസനം) ആകാശങ്ങൾക്കു മുകളിൽ ഇപ്രകാരമാണ്." എന്നിട്ട് റസൂൽ(സ) തന്റെ വിരലുകൾകൊണ്ട് മുകളിലുള്ള ഖുബ്ബ പോലെ ആംഗ്യം കാണിച്ചു. (ശേഷം പറഞ്ഞു:) "യാത്രക്കാരനെ ചുമക്കുന്നത് കാരണത്താൽ ജീനിയിൽനിന്ന് പുറപ്പെടുന്ന ശബ്ദംപോലെ അല്ലാഹു കാരണമായി ആ അർശ് ശബ്ദം പുറപ്പെടീക്കുന്നു. അല്ലാഹു തന്റെ അർശിനു മുകളിലാണ്. അവന്റെ അർശ് ആകാശങ്ങൾക്കു മുകളിലാണ്." (ദ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജൂബൈറുബ്നു മുത്വഇം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 811, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ جَابِرِ بْنِ عَبْدِ اللَّه رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "أُذِنَ لِي أَنْ أُحَدِّثَ عَنْ مَلَكٍ مِنْ مَلَائِكَةِ اللَّه مِنْ حَمَلَةِ الْعَرْشِ، إِنَّ مَا بَيْنَ شَحْمَةِ أُذُنِه إِلَى عَاتِقِه مَسِيرَةُ سَبْعِ مِائَةِ عَامٍ". (د)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): നബി(സ) പറഞ്ഞു: "അർശിനെ ചുമക്കുന്ന അല്ലാഹുവിന്റെ മലക്കുകളിൽ ഒരു മലക്കിനെക്കുറിച്ച് പറഞ്ഞുതരാൻ എനിക്ക് അനുവാദം നൽകപ്പെട്ടു. ആ മലക്കിന്റെ ചെവിക്കുന്നിക്കും പിരടിക്കുമിടയിൽ എഴുന്നൂറ് വർഷത്തെ യാത്രാദൈർഘ്യമുണ്ട്." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ يَقْرَأُ هَذِه الْآيَةَ: {إِنَّ اللَّهَ يَأْمُرُكُمْ أَنْ تُؤَدُّوا الْأَمَانَاتِ إِلَى أَهْلِهَا} إِلَى قَوْلِه تَعَالَى {سَمِيعًا بَصِيرًا} قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَضَعُ إِبْهَامَهُ عَلَى أُذُنِه وَالَّتِي تَلِيهَا عَلَى عَيْنِه. يَعْنِي: أَنَّ اللَّهَ سَمِيعٌ بَصِيرٌ، يَعْنِي: أَنَّ لِلَّه سَمْعًا وَبَصَرًا. (د)', 'അബൂഹുറൈറ(റ): ''വിശ്വസിച്ചേൽപിച്ച മുതലുകൾ അവയുടെ ഉടമകൾക്ക് തിരിച്ചുനൽകണമെന്ന് അല്ലാഹു നിങ്ങളോട് നിർദേശിക്കുന്നു'' എന്നതുമുതൽ ''അല്ലാഹു എല്ലാം കേൾക്കുന്നവനും കാണുന്നവനുമാണ്'' എന്നതുവരെയുള്ള സൂക്തം ഓതിക്കൊണ്ട് അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) തന്റെ ചൂണ്ടുവിരൽ ചെവിയിലും അതിനോടടുത്ത വിരൽ കണ്ണിനു മുകളിലും വെക്കുന്നത് ഞാൻ കണ്ടു. റസൂൽ(സ) ഉദ്ദേശിക്കുന്നത് അല്ലാഹു (എല്ലാം) കേൾക്കുന്നവനും കാണുന്നവനുമാണ്, അഥവാ അല്ലാഹുവിന് കേൾവിയും കാഴ്ചയുമുണ്ട് എന്നാണ്. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 812, 812, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ جَرِيرِ بْنِ عَبْدِ اللَّه رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا جُلُوسًا عِنْدَ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَنَظَرَ إِلَى الْقَمَرِ لَيْلَةَ الْبَدْرِ، قَالَ: "إِنَّكُمْ سَتَرَوْنَ رَبَّكُمْ كَمَا تَرَوْنَ هَذَا الْقَمَرَ، لَا تُضَامُّونَ فِي رُؤْيَتِه، فَإِنِ اسْتَطَعْتُمْ أَنْ لَا تُغْلَبُوا عَلَى صَلَاةٍ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ غُرُوبِهَا فَافْعَلُوا". ثُمَّ قَرَأَ: {وَسَبِّحْ بِحَمْدِ رَبِّكَ قَبْلَ طُلُوعِ الشَّمْسِ وَقَبْلَ الْغُرُوبِ} [ق: ٣٩]. (ق,د,ت,جه)', 'ജരീറുബ്നു അബ്ദില്ല(റ): ഞങ്ങൾ റസൂൽ(സ)യുടെ അടുത്ത് ഇരിക്കുമ്പോൾ പതിനാലാം രാവിലെ പൂർണ്ണ ചന്ദ്രനിലേക്ക് നോക്കിക്കൊണ്ട് അവിടുന്ന് പറഞ്ഞു: "ഈ ചന്ദ്രനെ കാണുന്നതുപോലെ നിങ്ങൾ തങ്ങളുടെ രക്ഷിതാവിനെയും കാണും. അവനെ കാണുന്നതിൽ നിങ്ങൾക്ക് ഒരു പ്രയാസവും അനുഭവപ്പെടുകയില്ല. അതിനാൽ സൂര്യോദയത്തിനും അസ്തമയത്തിനും മുമ്പ് നിങ്ങൾക്ക് സാധ്യമാകുമെങ്കിൽ ഓരോ നമസ്കാരം നമസ്കരിക്കുക." ശേഷം റസൂൽ(സ) ഈ സൂക്തമോതി: ''സൂര്യോദയത്തിനും അസ്തമയത്തിനും മുമ്പ് നീ തന്റെ രക്ഷിതാവിന്റെ ഔന്നിത്യത്തെ വാഴ്തുക'' (ഖാഫ്: 39). (ബു,മു,ദ,തു,ജ)', 'جَرِيرِ بْنِ عَبْدِ اللَّه', 'ജരീറുബ്നു അബ്ദില്ല(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], 'ق: ٣٩', null, 812, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "تَضَامُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ". قَالُوا: لَا. قَالَ: "فَكَذَلِكَ، لَا تَضَامُّونَ فِي رُؤْيَةِ رَبِّكُمْ يَوْمَ الْقِيَامَةِ". (جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) ചോദിച്ചു: "പതിനാലാം രാവിലെ ചന്ദ്രനെ കാണുന്നതിൽ നിങ്ങൾക്ക് പ്രയാസം അനുഭവപ്പെടാറുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "അപ്രകാരം അന്ത്യനാളിൽ നിങ്ങളുടെ നാഥനെ കാണുന്നതിലും നിങ്ങൾക്ക് പ്രയാസം അനുഭവപ്പെടുകയില്ല." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي سَعِيدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْنَا: يَا رَسُولَ اللَّهِ، أَنَرَى رَبَّنَا؟ قَالَ: "تَضَامُّونَ فِي رُؤْيَةِ الشَّمْسِ فِي الظَّهِيرَةِ فِي غَيْرِ سَحَابٍ". قُلْنَا: لَا. قَالَ: "فَتَضَارُّونَ فِي رُؤْيَةِ الْقَمَرِ لَيْلَةَ الْبَدْرِ فِي غَيْرِ سَحَابٍ". قَالُوا: لَا. قَالَ: "إِنَّكُمْ لَا تَضَارُّونَ فِي رُؤْيَته إِلَّا كَمَا تَضَارُّونَ فِي رُؤْيَتِهمَا". (جه)', 'അബൂസഈദ്(റ): ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ ഞങ്ങളുടെ രക്ഷിതാവിനെ കാണുമോ? റസൂൽ(സ) ചോദിച്ചു: "മേഘമില്ലാത്ത നട്ടുച്ച സമയത്ത് സൂര്യനെ കാണുന്നതിന് നിങ്ങൾക്ക് വല്ല പ്രയാസവും ഉണ്ടാകാറുണ്ടോ?" ഞങ്ങൾ പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) ചോദിച്ചു: "മേഘമില്ലാത്ത പതിനാലാം രാവിൽ ചന്ദ്രനെ കാണുന്നതിന് നിങ്ങൾക്ക് വല്ല പ്രയാസവും ഉണ്ടാകാറുണ്ടോ?" അവർ പറഞ്ഞു: ഇല്ല. റസൂൽ(സ) പറഞ്ഞു: "ഇവരണ്ടും കാണുന്നതിനുള്ള പ്രയാസമല്ലാതെ മറ്റൊന്നും അവനെ കാണുന്നതിനും നിങ്ങൾക്ക് അനുഭവപ്പെടുകയില്ല." (ജ)', 'أَبِي سَعِيدٍ', 'അബൂസഈദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ أَبِي رَزِينٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَنَرَى اللَّهَ يَوْمَ الْقِيَامَةِ؟ وَمَا آيَةُ ذَلِكَ فِي خَلْقِه؟ قَالَ: "يَا أَبَا رَزِينٍ، أَلَيْسَ كُلُّكُمْ يَرَى الْقَمَرَ مُخْلِيًا بِهِ". قَالَ: قُلْتُ: بَلَى. قَالَ: "فَاللَّهُ أَعْظَمُ، وَذَلِكَ آيَةٌ فِي خَلْقِهِ". (د,جه)', 'അബൂറസീൻ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അന്ത്യനാളിൽ ഞങ്ങൾ അല്ലാഹുവിനെ കാണുമോ? അവന്റെ സൃഷ്ടികളിൽ ആ കാഴ്ചക്കുള്ള അടയാളമെന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "അബൂറസീനേ, നിങ്ങളിൽ ഓരോരുത്തരും ഏകാന്തനായി ചന്ദ്രനെ നോക്കിയിരിക്കാറില്ലേ?" ഞാൻ പറഞ്ഞു: അതെ. റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ അല്ലാഹു അത്യുത്തമനാണ്. അതാണ് (ചന്ദ്രനെ കാണുന്നത്) അവന്റെ സൃഷ്ടികളിൽ അതിനുള്ള (അല്ലാഹുവിനെ കാണുന്നതിനുള്ള) അടയാളം." (ദ,ജ)', 'أَبِي رَزِينٍ', 'അബൂറസീൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَبِي رَزِينٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "ضَحِكَ رَبُّنَا مِنْ قُنُوط عباده وَقُرْبِ غِيَرِهِ". قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَوَ يَضْحَكُ الرَّبُّ؟ قَالَ: "نَعَمْ". قُلْتُ: لَنْ نَعْدَمَ مِنْ رَبٍّ يَضْحَكُ خَيْرًا. (جه)', 'അബൂറസീൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "പ്രയാസങ്ങൾ താൻ വേഗത്തിൽ അകറ്റുമായിരുന്നിട്ടും തന്റെ അടിമകൾ നിരാശരാകുന്നത് കാരണത്താൽ നമ്മുടെ രക്ഷിതാവ് ചിരിച്ചു." ഞാൻ ചോദിച്ചു: റസൂലേ, രക്ഷിതാവ് ചിരിക്കുമോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." ഞാൻ പറഞ്ഞു: ചിരിക്കുന്ന രക്ഷിതാവിൽനിന്ന് നമുക്ക് നന്മ ലഭിക്കാതിരിക്കുകയില്ല. (ജ)', 'أَبِي رَزِينٍ', 'അബൂറസീൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 813, 813, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي رَزِينٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَيْنَ كَانَ رَبُّنَا قَبْلَ أَنْ يَخْلُقَ خَلْقَهُ؟ قَالَ: "كَانَ فِي عَمَاءٍ، مَا تَحْتَهُ هَوَاءٌ وَمَا فَوْقَهُ هَوَاءٌ، وَمَا ثَمَّ خَلْقٌ، عَرْشُهُ عَلَى الْمَاءِ". (ت,جه)', 'അബൂറസീൻ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, തന്റെ സൃഷ്ടികളെ പടക്കുംമുമ്പ് നമ്മുടെ രക്ഷിതാവ് എവിടെയായിരുന്നു? റസൂൽ(സ) പറഞ്ഞു: "അവൻ ഇരുണ്ട മേഘത്തിലായിരുന്നു, അവന്റെ താഴെയോ മേലെയോ വായു ഉണ്ടായിരുന്നില്ല. അവിടെ മറ്റു സൃഷ്ടികളൊന്നും ഉണ്ടായിരുന്നില്ല. അവന്റെ അർശ് (സിംഹാസനം) വെള്ളത്തിനു മുകളിലാണ്." (തു,ജ)', 'أَبِي رَزِينٍ', 'അബൂറസീൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 813, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ صَفْوَانَ بْنِ مُحْرِزٍ الْمَازِنِيِّ قَالَ: بَيْنَمَا نَحْنُ مَعَ عَبْدِ اللهِ بْنِ عُمَرَ – رَضِيَ اللهُ عَنْهُمَا – وَهُوَ يَطُوفُ بِالْبَيْتِ إِذْ عَرَضَ لَهُ رَجُلٌ، فَقَالَ: يَا ابْنَ عُمَرَ، كَيْفَ سَمِعْتَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُ فِي النَّجْوَى؟ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يُدْنَى الْمُؤْمِنُ مِنْ رَبِّهِ يَوْمَ الْقِيَامَةِ حَتَّى يَضَعَ عَلَيْهِ كَنَفَهُ، ثُمَّ يُقَرِّرُهُ بِذُنُوبِهِ، فَيَقُولُ: هَلْ تَعْرِفُ؟ فَيَقُولُ: يَا رَبِّ، أَعْرِفُ. حَتَّى إِذَا بَلَغَ مِنْهُ مَا شَاءَ اللهُ أَنْ يَبْلُغَ قَالَ: إِنِّي سَتَرْتُهَا عَلَيْكَ فِي الدُّنْيَا وَأَنَا أَغْفِرُهَا لَكَ الْيَوْمَ. قَالَ: ثُمَّ يُعْطَى صَحِيفَةَ حَسَنَاتِهِ – أَوْ: كِتَابَهُ – بِيَمِينِهِ. قَالَ، وَأَمَّا الْكَافِرُ – أَوِ: الْمُنَافِقُ – فَيُنَادَى عَلَى رُءُوسِ الْأَشْهَادِ: {هَؤُلَاءِ الَّذِينَ كَذَبُوا عَلَى رَبِّهِمْ أَلَا لَعْنَةُ اللهِ عَلَى الظَّالِمِينَ} [هود: ١٨]". (ق,جه)', 'സ്വഫ്വാനുബ്നു മുഹ്‌രിസുൽ മാസിനി(റ): അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) കഅ്ബഃ ത്വവാഫ് ചെയ്യുമ്പോൾ, ഞങ്ങൾ അദ്ദേഹത്തോടൊപ്പമുള്ളയവസരം - ഒരാൾ അദ്ദേഹത്തിന്റെ അടുത്ത് വന്നുകൊണ്ട് ചോദിച്ചു: ഇബ്നുഉമറേ, (അടിമയും അല്ലാഹുവും തമ്മിലുള്ള) സംഭാഷണത്തെ സംബന്ധിച്ച് റസൂൽ(സ) എന്ത് പറയുന്നതാണ് താങ്കൾ കേട്ടത്? ഇബ്നുഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "അന്ത്യനാളിൽ സത്യവിശ്വാസിയെ തന്റെ രക്ഷിതാവിലേക്ക് അടുപ്പിക്കപ്പെടുകയും അല്ലാഹു അവനുമേൽ തന്റെ മറയെ ഇടുകയും ചെയ്യും. പിന്നെ തന്റെ പാപങ്ങളെ മുഴുവൻ അവനെക്കൊണ്ട് സമ്മതിപ്പിക്കും. അല്ലാഹു ചോദിക്കും: നിനക്കിത് ഓർമ്മയില്ലേ? അവൻ പറയും: അതെ, എന്റെ രക്ഷിതാവേ, എനിക്ക് ഓർമ്മയുണ്ട്. അങ്ങനെ അല്ലാഹു ഉദ്ദേശിച്ചയത്രയും കാര്യങ്ങൾ അവനെക്കൊണ്ട് സമ്മതിപ്പിച്ചു കഴിഞ്ഞാൽ അല്ലാഹു പറയും: ഇവയെല്ലാം ഐഹികലേകത്തുവെച്ച് നിന്നെതൊട്ട് ഞാൻ മറച്ചുവെക്കുകയും ഇന്ന് അവയെ പൊറുത്തു തരികയും ചെയ്യുന്നു." റസൂൽ(സ) പറയുന്നു: "ശേഷം അവന്റെ നന്മകളുടെ ഏട് - അല്ലെങ്കിൽ അവന്റെ ഗ്രന്ഥം - വലത്തേ കയ്യിൽ നൽകപ്പെടും. എന്നാൽ സത്യനിഷേധി - അല്ലെങ്കിൽ കപടവിശ്വാസി - യെക്കുറിച്ച് ജനമധ്യത്തിൽവെച്ച് ഇപ്രകാരം വിളിച്ചു പറയപ്പെടും: ''ഇവരാണ് തങ്ങളുടെ രക്ഷിതാവിന്റെ പേരിൽ കള്ളം പറഞ്ഞവർ, അറിയുക! അക്രമികളുടെമേൽ അല്ലാഹുവിന്റെ ശാപം ഉണ്ടായിരിക്കുന്നതാണ്'' (ഹൂദ്: 18)." (ബു,മു,ജ)', 'صَفْوَانَ بْنِ مُحْرِزٍ الْمَازِنِيِّ قَالَ', 'സ്വഫ്വാനുബ്നു മുഹ്‌രിസുൽ മാസിനി(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], 'هود: ١٨', null, 814, 814, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ جَابِر بْن عَبْد اللَّه رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَا أَهْلُ الْجَنَّةِ فِي نَعِيمهِمْ إِذْ سَطَعَ لَهُمْ نُورٌ، فَرَفَعُوا رُءُوسَهُمْ فَإِذَا الرَّبُّ قَدْ أَشْرَفَ عَلَيْهِمْ مِنْ فَوْقِهِمْ، فَقَالَ: السَّلَامُ عَلَيْكُمْ، يَا أَهْلَ الْجَنَّةِ. قَالَ: وَذَلِكَ قَوْلُ اللَّه {سَلَامٌ قَوْلًا مِنْ رَبٍّ رَحِيمٍ} [يس: ٥٨]. قَالَ: فَيَنْظُرُ إِلَيْهِمْ وَيَنْظُرُونَ إِلَيْه، فَلَا يَلْتَفِتُونَ إِلَى شَيْءٍ مِنَ النَّعِيمِ مَا دَامُوا يَنْظُرُونَ إِلَيْهِ حَتَّى يَحْتَجِبَ عَنْهُمْ، وَيَبْقَى نُورُهُ وَبَرَكَتُهُ عَلَيْهِمْ فِي دِيَارِهِمْ". (جه)', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ): റസൂൽ(സ) പറഞ്ഞു: "സ്വർഗ്ഗവാസികൾ സുഖങ്ങളിൽ കഴിയുമ്പോൾ അവർക്കുമേൽ ഒരു പ്രകാശം പരക്കും. അവർ തലയുയർത്തി നോക്കുമ്പോൾ രക്ഷിതാവ് തങ്ങൾക്കു മുകളിൽ പ്രത്യക്ഷപ്പെട്ടിട്ടുണ്ടാകും. അവൻ പറയും: സ്വർഗ്ഗാവകാശികളേ, നിങ്ങളുടെമേൽ രക്ഷയുണ്ടാവട്ടെ. റസൂൽ(സ) പറയുന്നു: ഇതിനെക്കുറിച്ചാണ് ''കാരുണ്യവാനായ രക്ഷിതാവിൽ നിന്നുള്ള സലാം'' (യാസീൻ: 58) എന്ന് അല്ലാഹു പറഞ്ഞിട്ടുള്ളത്. അങ്ങനെ സ്വർഗ്ഗാവകാശികൾ അല്ലാഹുവിലേക്കും അല്ലാഹു സ്വർഗ്ഗാവകാശികളിലേക്കും നോക്കും. അല്ലാഹുവിലേക്ക് നോക്കുന്ന സമയമത്രയും, അഥവാ അവൻ തങ്ങളിൽനിന്ന് മറയുന്നതുവരെ സ്വർഗ്ഗാവകാശികൾ മറ്റൊരു സുഖത്തിലേക്കും തിരിഞ്ഞുനോക്കുകയില്ല. ശേഷം അല്ലാഹുവിന്റെ പ്രകാശവും അനുഗ്രഹവും അവരുടെ വീടുകളിൽ അവശേഷിക്കുകയും ചെയ്യും." (ജ)', 'جَابِر بْن عَبْد اللَّه', 'ജാബിറുബ്നു അബ്ദില്ലാഹ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'يس: ٥٨', null, 814, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَدِيِّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا منْكُمْ منْ أَحَد إِلَّا سَيُكَلِّمُهُ رَبُّهُ، لَيْسَ بَيْنَهُ وَبَيْنَهُ تَرْجُمَانٌ. فَيَنْظُرُ مِنْ عَنْ أَيْمَنَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ، ثُمَّ يَنْظُرُ مِنْ عَنْ أَيْسَرَ مِنْهُ فَلَا يَرَى إِلَّا شَيْئًا قَدَّمَهُ، ثُمَّ يَنْظُرُ أَمَامَهُ فَتَسْتَقْبِلُهُ النَّارُ. فَمَنِ اسْتَطَاعَ مِنْكُمْ أَنْ يَتَّقِيَ النَّارَ وَلَوْ بِشِقِّ تَمْرَةٍ فَلْيَفْعَلْ". (ق,ت,جه)', 'അദിയ്യുബ്നു ഹാതിം(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇടയിൽ ഒരു പരിഭാഷകനുമില്ലാതെ നിങ്ങളിൽ ഓരോരുത്തരോടും തന്റെ രക്ഷിതാവ് സംസാരിക്കുന്നതാണ്. അങ്ങനെ അവൻ തന്റെ വലതുഭാഗത്തേക്ക് നോക്കും. പക്ഷേ, താൻ മുമ്പ് ചെയ്ത കാര്യങ്ങളല്ലാതെ ഒന്നും അവൻ കാണുകയില്ല. ശേഷം തന്റെ ഇടതുഭാഗത്തേക്ക് നോക്കും. അപ്പോഴും താൻ മുമ്പ് ചെയ്ത കാര്യങ്ങളല്ലാതെ ഒന്നും കാണുകയില്ല. ശേഷം തന്റെ മുന്നിലേക്ക് നോക്കുമ്പോൾ നരകമായിരിക്കും അവിടെ ഉണ്ടാവുക. അതിനാൽ ഒരു കാരക്കച്ചീന്തു കൊണ്ടെങ്കിലും നരകത്തെ സൂക്ഷിക്കാൻ നിങ്ങളിൽ ആർക്കെങ്കിലും കഴിയുമെങ്കിൽ അതു ചെയ്തുകൊള്ളുക." (ബു,മു,തു,ജ)', 'عَدِيِّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 815, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ عَبْدِ اللَّهِ بْنِ قَيْسٍ الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "جَنَّتَانِ مِنْ فِضَّةٍ، آنِيَتُهُمَا وَمَا فِيهِمَا. وَجَنَّتَانِ مِنْ ذَهَبٍ، آنِيَتُهُمَا وَمَا فِيهِمَا. وَمَا بَيْنَ الْقَوْمِ وَبَيْنَ أَنْ يَنْظُرُوا إِلَى رَبِّهِمْ تَبَارَكَ وَتَعَالَى إِلَّا رِدَاءُ الْكِبْرِيَاءِ عَلَى وَجْهِه فِي جَنَّةِ عَدْنٍ". (ق,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു ഖൈസുൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് സ്വർഗ്ഗത്തിലെ പാത്രങ്ങളും അവയിലെ സർവ്വ വസ്തുക്കളും വെള്ളിയാണ്. വേറെ രണ്ടു സ്വർഗ്ഗങ്ങളിലെ പാത്രങ്ങളും അവയിലെ സർവ്വ വസ്തുക്കളും സ്വർണ്ണമാണ്. ജനങ്ങൾക്ക് തങ്ങളുടെ രക്ഷിതാവിലേക്ക് നോക്കുന്നതിന് തടസ്സമായി, ''അദ്ൻ'' എന്ന സ്വർഗ്ഗത്തിൽ അല്ലാഹുവിന്റെ തിരുമുഖത്തുണ്ടാകുന്ന, മഹത്വത്തിന്റെ മറ മാത്രമാണുള്ളത്." (ബു,മു,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ قَيْسٍ الْأَشْعَرِيِّ', 'അബ്ദുല്ലാഹിബ്നു ഖൈസുൽ അശ്അരി(റ)', null, null, array['ق','ت','جه']::text[], array['ബു','മു','തു','ജ']::text[], null, null, 815, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنْ صُهَيْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: تَلَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ هَذِهِ الْآيَةَ: {لِلَّذِينَ أَحْسَنُوا الْحُسْنَى وَزِيَادَةٌ} [يونس: ٢٦] وَقَالَ: "إِذَا دَخَلَ أَهْلُ الْجَنَّةِ الْجَنَّةَ، وَأَهْلُ النَّارِ النَّارَ، نَادَى مُنَادٍ: يَا أَهْلَ الْجَنَّةِ، إِنَّ لَكُمْ عِنْدَ اللهِ مَوْعِدًا يُرِيدُ أَنْ يُنْجِزَكُمُوهُ. فَيَقُولُونَ: وَمَا هُوَ؟ أَلَمْ يُثَقِّلِ اللهُ مَوَازِينَنَا وَيُبَيِّضْ وُجُوهَنَا، وَيُدْخِلْنَا الْجَنَّةَ وَيُنْجِنَا مِنَ النَّارِ؟ قَالَ: فَيَكْشِفُ الْحِجَابَ فَيَنْظُرُونَ إِلَيْهِ. فَوَاللهِ، مَا أَعْطَاهُمُ اللهُ شَيْئًا أَحَبَّ إِلَيْهِمْ مِنَ النَّظَرِ، يَعْنِي إِلَيْهِ، وَلَا أَقَرَّ لِأَعْيُنِهِمْ". (م,ت,جه)', 'സ്വുഹൈബ്(റ): ''നന്മ ചെയ്തവർക്ക് ഏറ്റവും ഉത്തമമായ പ്രതിഫലവും കൂടുതൽ നേട്ടവുമുണ്ട്'' (യൂനുസ്: 26) എന്ന സൂക്തം ഓതിക്കൊണ്ട് റസൂൽ(സ) പറഞ്ഞു: "സ്വർഗ്ഗാവകാശികൾ സ്വർഗ്ഗത്തിലും നരകക്കാർ നരകത്തിലും പ്രവേശിച്ചാൽ ഒരാൾ ഇപ്രകാരം വിളിച്ചു പറയും: സ്വർഗ്ഗാവകാശികളേ, നിങ്ങൾക്ക് അല്ലാഹുവിങ്കൽ ഒരു വാഗ്ദാനമുണ്ട്. അത് പൂർത്തീകരിക്കാൻ അവൻ ആഗ്രഹിക്കുന്നു. അവർ ചോദിക്കും: എന്താണത്? അല്ലാഹു ഞങ്ങളുടെ തുലാസിനെ (നന്മയുടെ ഭാഗത്തെ) ഭാരമുള്ളതാക്കുകയും മുഖങ്ങളെ പ്രകാശിപ്പിക്കുകയും ഞങ്ങളെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയും നരകത്തിൽനിന്ന് രക്ഷപ്പെടുത്തുകയും ചെയ്തില്ലെയോ? റസൂൽ(സ) പറയുന്നു: അപ്പോൾ മറ നീങ്ങുകയും അവർ അല്ലാഹുവിലേക്ക് നോക്കുകയും ചെയ്യും. അല്ലാഹുതന്നെ സത്യം, തന്നിലേക്ക് നോക്കുന്നതിനേക്കാൾ സ്വർഗ്ഗാവകാശികൾക്ക് ഏറ്റവും ഇഷ്ടപ്പെട്ടതും കൺകുളിർമ്മയേകുന്നതുമായ ഒരു കാര്യവും അല്ലാഹു അവർക്ക് നൽകിയിട്ടില്ല." (മു,തു,ജ)', 'صُهَيْبٍ', 'സ്വുഹൈബ്(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], 'يونس: ٢٦', null, 815, 815, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: الْحَمْدُ لِلَّهِ الَّذِي وَسِعَ سَمْعُهُ الْأَصْوَاتَ، لَقَدْ جَاءَتِ الْمُجَادِلَةُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَا فِي نَاحِيَةِ الْبَيْتِ، تَشْكُو زَوْجَهَا، وَمَا أَسْمَعُ مَا تَقُولُ، فَأَنْزَلَ اللَّهُ: {قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا} [مجادلة: ١]. (خ,ن,جه)', 'ആഇശ(റ): സർവ്വ ശബ്ദങ്ങളെയും കേൾക്കുന്ന വിധം കേൾവിയുള്ള അല്ലാഹുവിനാണ് സർവ്വ സ്തുതിയും. ഞാൻ വീടിന്റെ ഒരു മൂലയിൽ ഇരിക്കെയാണ് തന്റെ ഭർത്താവിനെ സംബന്ധിച്ച് പരാതി പറഞ്ഞ് റസൂൽ(സ)യോട് തർക്കിച്ച സ്ത്രീ അവിടുത്തെ സമീപത്ത് വന്നത്. അവൾ എന്താണ് പറയുന്നതെന്ന് ഞാൻ കേട്ടിരുന്നില്ല. ഉടനെ അല്ലാഹു ഇപ്രകാരം സൂക്തമിറക്കി: ''തന്റെ ഭർതാവിന്റെ കാര്യത്തിൽ അങ്ങയോട് തർക്കിക്കുകയും അല്ലാഹുവിനോട് സങ്കടം പറയുകയും ചെയ്യുന്നവളുടെ വാക്ക് അല്ലാഹു കേട്ടിട്ടുണ്ട്'' (മുജാദല: 1). (ബു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], 'مجادلة: ١', null, 815, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كَتَبَ رَبُّكُمْ عَلَى نَفْسِه بِيَدِه قَبْلَ أَنْ يَخْلُقَ الْخَلْقَ: رَحْمَتِي سَبَقَتْ غَضَبِي". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങളുടെ രക്ഷിതാവ് സൃഷ്ടികളെയെല്ലാം സൃഷ്ടിക്കുന്നതിന് മുമ്പ് സ്വന്തത്തിനുമേൽ ഇപ്രകാരം എഴുതിവെച്ചു: എന്റെ അനുഗ്രഹം ദേഷ്യത്തേക്കാൾ മുൻകടന്നിരിക്കുന്നു." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا قُتِلَ عَبْدُ اللهِ بْنُ عَمْرِو بْنِ حَرَامٍ – يَوْمَ أُحُدٍ – لَقِينِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "يَا جَابِرُ، أَلَا أُخْبِرُكَ مَا قَالَ اللهُ لِأَبِيكَ". وَفِي رِوَايَةٍ: فَقَالَ: "يَا جَابِرُ، مَا لِي أَرَاكَ مُنْكَسِرًا". قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، اسْتُشْهِدَ أَبِي وَتَرَكَ عِيَالًا وَدَيْنًا. قَالَ: "أَفَلَا أُبَشِّرُكَ بِمَا لَقِيَ اللهُ بِهِ أَبَاكَ". قَالَ: بَلَى، يَا رَسُولَ اللهِ. قَالَ: "مَا كَلَّمَ اللهُ أَحَدًا قَطُّ إِلَّا مِنْ وَرَاءِ حِجَابٍ، وَكَلَّمَ أَبَاكَ كِفَاحًا، فَقَالَ: يَا عَبْدِي، تَمَنَّ عَلَيَّ أُعْطِكَ. قَالَ: يَا رَبِّ، تُحْيِينِي فَأُقْتَلَ فِيكَ ثَانِيَةً. فَقَالَ الرَّبُّ سُبْحَانَهُ: إِنَّهُ سَبَقَ مِنِّي: أَنَّهُمْ إِلَيْهَا لَا يَرْجِعُونَ. قَالَ: يَا رَبِّ، فَأَبْلِغْ مَنْ وَرَائِي قَالَ: فَأَنْزَلَ اللهُ تَعَالَى: {وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ} [آل عمران: ١٦٩]". (ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഉഹ്ദ് യുദ്ധദിവസം അബ്ദുല്ലാഹിബ്നു അംറുബ്നു ഹറാം(റ) കൊല്ലപ്പെട്ടപ്പോൾ റസൂൽ(സ) എന്നെ കണ്ടുമുട്ടുകയും ഇപ്രകാരം പറയുകയും ചെയ്തു: "ജാബിറേ, അല്ലാഹു നിന്റെ പിതാവിനോട് പറഞ്ഞതെന്തെന്ന് ഞാൻ പറഞ്ഞുതരട്ടെയോ?" മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "ജാബിറേ, എന്തുകൊണ്ടാണ് നിനക്ക് മനഃപ്രയാസമുള്ളതായി കാണപ്പെടുന്നത്?" ഞാൻ പറഞ്ഞു: റസൂലേ, തന്റെ ആശ്രിതരെയും കടത്തെയും ഉപേക്ഷിച്ചുകൊണ്ടാണ് എന്റെ പിതാവ് രക്തസാക്ഷിയായത്. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിന്റെ പിതാവിനെ സ്വീകരിച്ചതെങ്ങനെയെന്ന് നിനക്ക് ഞാൻ പറഞ്ഞുതരട്ടെയോ?" ജാബിർ(റ) പറഞ്ഞു: അതെ, റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഏതൊരുത്തനോടും മറക്കപ്പുറത്ത് നിന്നല്ലാതെ സംസാരിച്ചിട്ടില്ല. അവൻ നിന്റെ പിതാവിനോട് നേരിൽ സംസാരിച്ചു. അല്ലാഹു ചോദിച്ചു: എന്റെ ദാസാ, നിന്റെ ആഗ്രഹങ്ങൾ എന്നോട് പറയുക. ഞാൻ തരാം. അദ്ദേഹം പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, നീ എനിക്ക് ജീവൻ തരികയും അങ്ങനെ രണ്ടാം പ്രാവശ്യം നിന്റെ മാർഗ്ഗത്തിൽ ഞാൻ വധിക്കപ്പെടുകയും വേണം. രക്ഷിതാവ് പറഞ്ഞു: സൃഷ്ടികൾ ഒരിക്കലും ഐഹികലോകത്തേക്ക് മടക്കപ്പെടുകയില്ലെന്ന് ഞാൻ മുന്നെ തീരുമാനിച്ചിരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, എങ്കിൽ എന്നെക്കുറിച്ച് എന്റെ പിറകിലുള്ളവർക്ക് അറിയിച്ചുകൊടുക്കുക. അപ്പോൾ അല്ലാഹു ഈ സൂക്തമിറക്കി: ''അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെട്ടവരെ മരിച്ചവരായി അങ്ങ് കണക്കാക്കരുത്. എന്നാൽ അവർ തങ്ങളുടെ രക്ഷിതാവിങ്കൽ ജീവിച്ചിരിക്കുന്നവരാണ്. അവർക്ക് ഉപജീവനം നൽകപ്പെടുന്നു'' (ആലുഇംറാൻ: 169)." (തു,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], 'آل عمران: ١٦٩', null, 816, 816, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=124), 1, 'وَفِي رِوَايَةٍ: فَقَالَ: "يَا جَابِرُ، مَا لِي أَرَاكَ مُنْكَسِرًا". قَالَ: قُلْتُ: يَا رَسُولَ اللهِ، اسْتُشْهِدَ أَبِي وَتَرَكَ عِيَالًا وَدَيْنًا. قَالَ: "أَفَلَا أُبَشِّرُكَ بِمَا لَقِيَ اللهُ بِهِ أَبَاكَ". قَالَ: بَلَى، يَا رَسُولَ اللهِ. قَالَ: "مَا كَلَّمَ اللهُ أَحَدًا قَطُّ إِلَّا مِنْ وَرَاءِ حِجَابٍ، وَكَلَّمَ أَبَاكَ كِفَاحًا، فَقَالَ: يَا عَبْدِي، تَمَنَّ عَلَيَّ أُعْطِكَ. قَالَ: يَا رَبِّ، تُحْيِينِي فَأُقْتَلَ فِيكَ ثَانِيَةً. فَقَالَ الرَّبُّ سُبْحَانَهُ: إِنَّهُ سَبَقَ مِنِّي: أَنَّهُمْ إِلَيْهَا لَا يَرْجِعُونَ. قَالَ: يَا رَبِّ، فَأَبْلِغْ مَنْ وَرَائِي قَالَ: فَأَنْزَلَ اللهُ تَعَالَى: {وَلَا تَحْسَبَنَّ الَّذِينَ قُتِلُوا فِي سَبِيلِ اللهِ أَمْوَاتًا بَلْ أَحْيَاءٌ عِنْدَ رَبِّهِمْ يُرْزَقُونَ} [آل عمران: ١٦٩]". (ت,جه)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "ജാബിറേ, എന്തുകൊണ്ടാണ് നിനക്ക് മനഃപ്രയാസമുള്ളതായി കാണപ്പെടുന്നത്?" ഞാൻ പറഞ്ഞു: റസൂലേ, തന്റെ ആശ്രിതരെയും കടത്തെയും ഉപേക്ഷിച്ചുകൊണ്ടാണ് എന്റെ പിതാവ് രക്തസാക്ഷിയായത്. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിന്റെ പിതാവിനെ സ്വീകരിച്ചതെങ്ങനെയെന്ന് നിനക്ക് ഞാൻ പറഞ്ഞുതരട്ടെയോ?" ജാബിർ(റ) പറഞ്ഞു: അതെ, റസൂലേ. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഏതൊരുത്തനോടും മറക്കപ്പുറത്ത് നിന്നല്ലാതെ സംസാരിച്ചിട്ടില്ല. അവൻ നിന്റെ പിതാവിനോട് നേരിൽ സംസാരിച്ചു. അല്ലാഹു ചോദിച്ചു: എന്റെ ദാസാ, നിന്റെ ആഗ്രഹങ്ങൾ എന്നോട് പറയുക. ഞാൻ തരാം. അദ്ദേഹം പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, നീ എനിക്ക് ജീവൻ തരികയും അങ്ങനെ രണ്ടാം പ്രാവശ്യം നിന്റെ മാർഗ്ഗത്തിൽ ഞാൻ വധിക്കപ്പെടുകയും വേണം. രക്ഷിതാവ് പറഞ്ഞു: സൃഷ്ടികൾ ഒരിക്കലും ഐഹികലോകത്തേക്ക് മടക്കപ്പെടുകയില്ലെന്ന് ഞാൻ മുന്നെ തീരുമാനിച്ചിരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, എങ്കിൽ എന്നെക്കുറിച്ച് എന്റെ പിറകിലുള്ളവർക്ക് അറിയിച്ചുകൊടുക്കുക. അപ്പോൾ അല്ലാഹു ഈ സൂക്തമിറക്കി: ''അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ വധിക്കപ്പെട്ടവരെ മരിച്ചവരായി അങ്ങ് കണക്കാക്കരുത്. എന്നാൽ അവർ തങ്ങളുടെ രക്ഷിതാവിങ്കൽ ജീവിച്ചിരിക്കുന്നവരാണ്. അവർക്ക് ഉപജീവനം നൽകപ്പെടുന്നു'' (ആലുഇംറാൻ: 169)." (തു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ يَضْحَكُ إِلَى رَجُلَيْنِ يَقْتُلُ أَحَدُهُمَا الْآخَرَ، كِلَاهُمَا دَخَلَ الْجَنَّةَ: يُقَاتِلُ هَذَا فِي سَبِيلِ اللَّهِ فَيُسْتَشْهَدُ، ثُمَّ يَتُوبُ اللَّهُ عَلَى قَاتِله فَيُسْلِمُ، فَيُقَاتِلُ فِي سَبِيلِ اللَّهِ فَيُسْتَشْهَدُ". (م,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടാളുകളെ നോക്കി അല്ലാഹു ചിരിക്കും. അവരിലൊരാൾ മറ്റെയാളെ വധിക്കുകയും എന്നിട്ട് രണ്ടുപേരും സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയും ചെയ്യുന്നു. ഒരാൾ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരടിക്കുകയും രക്തസാക്ഷിയാവുകയും ചെയ്യുന്നു. ശേഷം അവന്റെ ഘാതകന്റെ തൗബയെ അല്ലാഹു സ്വീകരിക്കുകയും അവൻ മുസ്ലിമാകുകയും ചെയ്യുന്നു. എന്നിട്ട് അവൻ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ പോരാടുകയും രക്തസാക്ഷിയാവുകയും ചെയ്യുന്നു." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَقْبِضُ اللَّهُ الْأَرْضَ يَوْمَ الْقِيَامَةِ، وَيَطْوِي السَّمَاءَ بِيَمِينه، ثُمَّ يَقُولُ: أَنَا الْمَلِكُ، أَيْنَ مُلُوكُ الْأَرْضِ". (ق,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ അല്ലാഹു ഭൂമിയെ പിടികൂടുകയും ആകാശത്തെ വലംകൈകൊണ്ട് ചുരുട്ടുകയും ചെയ്യും. എന്നിട്ടവൻ പറയും: ഞാനാണ് അധികാരി, ഭൂമിയിലെ രാജാക്കന്മാരെല്ലാം എവിടെ!" (ബു,മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','جه']::text[], array['ബു','മു','ജ']::text[], null, null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَضَى اللهُ أَمْرًا فِي السَّمَاءِ ضَرَبَتِ الْمَلَائِكَةُ أَجْنِحَتَهَا خُضْعَانًا لِقَوْلِهِ، كَأَنَّهُ سِلْسِلَةٌ عَلَى صَفْوَانٍ، فَ{إِذَا فُزِّعَ عَنْ قُلُوبِهِمْ قَالُوا مَاذَا قَالَ رَبُّكُمْ قَالُوا الْحَقَّ وَهُوَ الْعَلِيُّ الْكَبِيرُ} [سبأ: ٢٣]. فَيَسْمَعُهَا مُسْتَرِقُو السَّمْعِ بَعْضُهُمْ فَوْقَ بَعْضٍ، فَيَسْمَعُ الْكَلِمَةَ، فَيُلْقِيَهَا إِلَى مَنْ تَحْتَهُ، فَرُبَّمَا أَدْرَكَهُ الشِّهَابُ قَبْلَ أَنْ يُلْقِيَهَا إِلَى الَّذِي تَحْتَهُ، فَيُلْقِيَهَا عَلَى لِسَانِ الْكَاهِنِ أَوِ السَّاحِرِ، فَرُبَّمَا لَمْ يُدْرِكْ حَتَّى يُلْقِيَهَا، فَيَكْذِبُ مَعَهَا مِائَةَ كَذْبَةٍ، فَتُصَدَّقُ تِلْكَ الْكَلِمَةُ الَّتِي سُمِعَتْ مِنَ السَّمَاءِ". (خ,د,ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ആകാശലോകത്ത് വല്ല കാര്യവും തീരുമാനിച്ചാൽ മലക്കുകൾ അവന്റെ വാക്കിന് കീഴ്പ്പെട്ടുകൊണ്ട് തങ്ങളുടെ ചിറകുകൾ അടിക്കും. അതിന്റെ ശബ്ദം പാറമുകളിൽ ചങ്ങല വീഴുന്നത് പോലെയായിരിക്കും. ''അവരുടെ ഹൃദയങ്ങളിൽ നിന്ന് പരിഭ്രമം നീങ്ങിക്കഴിയുമ്പോൾ അവർ ചോദിക്കും: നിങ്ങളുടെ രക്ഷിതാവ് എന്താണ് പറഞ്ഞത്. അവർ പറയും: സത്യമാണ് (അവൻ പറഞ്ഞത്). അവൻ ഉന്നതനും മഹത്വമുള്ളവനുമാകുന്നു.'' (സബഅ്: 23) റസൂൽ(സ) പറയുന്നു: കട്ടുകേൾക്കുന്ന പിശാചുക്കൾ അത് കേൾക്കും. അവർ ഒരാൾക്കുമീതെ മറ്റൊരാൾ എന്ന രീതിയിലായിരിക്കും നിൽക്കുക. താൻ കേട്ട വാക്കിനെയവൻ തന്റെ താഴെയുള്ളവന് പറഞ്ഞുകൊടുക്കും. താഴെയുള്ളവൻ പറഞ്ഞുകൊടുക്കുകയും അവർ അതിനെ ജ്യേത്സ്യന്റെയോ മാരണക്കാരന്റെയോ നാവിൽ ഇട്ടുകൊടുക്കുകയും ചെയ്യുംമുമ്പ്, ചിലപ്പോൾ തീജ്വാല അവനെ പിടികൂടിയേക്കാം. അല്ലെങ്കിൽ ഇവർക്ക് പറഞ്ഞുകൊടുക്കും മുമ്പ് തീജ്വാല അവരെ പിടികൂടുകയില്ല. അവൻ (ജ്യേത്സ്യൻ അല്ലെങ്കിൽ മാരണക്കാരൻ) അതോടൊപ്പം നൂറ് നുണ പറഞ്ഞുണ്ടാക്കും. എന്നാൽ ആകാശത്തുനിന്ന് കേട്ട ആ വാക്ക് മാത്രമായിരിക്കും സത്യമായിട്ടുണ്ടായിരിക്കുക." (ബു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], 'سبأ: ٢٣', null, 817, 817, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: قَامَ فِينَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِخَمْسِ كَلِمَاتٍ، فَقَالَ: "إِنَّ اللهَ لَا يَنَامُ، وَلَا يَنْبَغِي لَهُ أَنْ يَنَامَ. يَخْفِضُ الْقِسْطَ وَيَرْفَعُهُ. يُرْفَعُ إِلَيْهِ عَمَلُ اللَّيْلِ قَبْلَ عَمَلِ النَّهَارِ. وَعَمَلُ النَّهَارِ قَبْلَ عَمَلِ اللَّيْلِ. حِجَابُهُ النُّورُ، لَوْ كَشَفَهُ – فِي رِوَايَةٍ: كَشَفَهَا – لَأَحْرَقَتْ سُبُحَاتُ وَجْهِهِ مَا انْتَهَى إِلَيْهِ بَصَرُهُ مِنْ خَلْقِهِ". وَفِي رِوَايَةٍ: "كُلَّ شَيْءٍ أَدْرَكَهُ بَصَرُهُ". (م,جه)', 'അബൂമൂസാ(റ): അഞ്ചു കാര്യങ്ങൾ പറഞ്ഞുതരാൻ വേണ്ടി റസൂൽ(സ) ഞങ്ങൾക്കിടയിൽ എഴുന്നേറ്റുനിന്നു. എന്നിട്ട് പറഞ്ഞു: "തീർച്ചയായും അല്ലാഹു ഉറങ്ങുകയില്ല, ഉറങ്ങുക എന്നത് അവന് യോജിച്ചതുമല്ല. അവൻ മീസാനി(തുലാസ്)നെ താഴ്ത്തുകയും ഉയർത്തുകയും ചെയ്യും. പകലിലെ കർമ്മങ്ങൾക്ക് മുന്നെ രാത്രിയിലെ കർമ്മങ്ങളും രാത്രിയിലെ കർമ്മങ്ങൾക്ക് മുമ്പ് പകലിലെ കർമ്മങ്ങളും അവനിലേക്ക് ഉയർത്തപ്പെടും. അവന്റെ മറ പ്രകാശത്തിന്റേതാണ്. ആ മറയെ അവൻ നീക്കിയാൽ തന്റെ കാഴ്ചയെത്തുന്ന അറ്റം വരെയുള്ള സർവ സൃഷ്ടികളെയും അവന്റെ മുഖത്തെ പ്രഭ കരിച്ചുകളയും." മറ്റൊരു നിവേദനം: "അവന്റെ കാഴ്ചയെത്തുന്ന സർവ വസ്തുക്കളെയും." (മു,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസാ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 817, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=128), 1, 'وَفِي رِوَايَةٍ: "كُلَّ شَيْءٍ أَدْرَكَهُ بَصَرُهُ". (م,جه)', 'മറ്റൊരു നിവേദനം: "അവന്റെ കാഴ്ചയെത്തുന്ന സർവ വസ്തുക്കളെയും." (മു,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَمِينُ اللَّهِ مَلْأَى، لَا يَغِيضُهَا شَيْءٌ، سَحَّاءُ اللَّيْلَ وَالنَّهَارَ. وَبِيَده الْأُخْرَى الْمِيزَانُ، يَرْفَعُ الْقِسْطَ وَيَخْفِضُ. قَالَ: أَرَأَيْتَ مَا أَنْفَقَ مُنْذُ خَلَقَ اللَّهُ السَّمَاوَاتِ وَالْأَرْضَ؟ لَمْ يَنْقُصْ مِمَّا فِي يَدَيْهِ شَيْئًا". (ت,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ വലതു കൈ നിറഞ്ഞതാണ്. രാപകലുകളിലെ ദാനമോ മറ്റു വല്ലതുമോ അതിനെ തീർത്തുകളയുകയില്ല. അവന്റെ മറ്റേ കയ്യിലുള്ളത് മീസാൻ(തുലാസ്) ആണ്. തുലാസിനെ അവൻ ഉയർത്തുകയും താഴ്ത്തുകയും ചെയ്യും." റസൂൽ(സ) ചോദിച്ചു: "ആകാശങ്ങളെയും ഭൂമിയെയും സൃഷ്ടിച്ചത് മുതൽ അല്ലാഹു എത്രയാണ് ചെലവഴിച്ചതെന്ന് നിങ്ങൾക്കറിയുമോ? അത് അവന്റെ കരങ്ങളിലുള്ളതിൽ ഒരു കുറവും വരുത്തിയിട്ടില്ല." (തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَلَى الْمِنْبَرِ يَقُولُ: "يَأْخُذُ الْجَبَّارُ سَمَاوَاتِهِ وَأَرْضَهُ بِيَدِهِ – وَقَبَضَ بِيَدِهِ فَجَعَلَ يَقْبِضُهَا وَيَبْسُطُهَا – ثُمَّ يَقُولُ: أَنَا الْجَبَّارُ، أَيْنَ الْجَبَّارُونَ؟ أَيْنَ الْمُتَكَبِّرُونَ". قَالَ: وَيَتَمَيَّلُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ، حَتَّى نَظَرْتُ إِلَى الْمِنْبَرِ يَتَحَرَّكُ مِنْ أَسْفَلِ شَيْءٍ مِنْهُ، حَتَّى إِنِّي أَقُولُ: أَسَاقِطٌ هُوَ بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ (م,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): മിമ്പറിൽ കയറി റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "പരമാധികാരിയായ അല്ലാഹു തന്റെ ആകാശങ്ങളെയും ഭൂമിയെയും കൈകൊണ്ട് പിടിക്കും. തന്റെ കൈകൊണ്ട് പിടിച്ച് അവൻ അവയെ ചുരുട്ടുകയും വിടർത്തുകയും ചെയ്യും. ശേഷം അവൻ പറയും: ഞാനാണ് പരമാധികാരി. എവിടെയാണ് മറ്റു പരമാധികാരികൾ? എവിടെയാണ് അഹന്ത നടിച്ചിരുന്നവർ?" നിവേദകൻ പറയുന്നു: റസൂൽ(സ) തന്റെ വലതുഭാഗത്തേക്കും ഇടതുഭാഗത്തേക്കും ചായുന്നുണ്ടായിരുന്നു. എത്രത്തോളമെന്നാൽ ഞാൻ മിമ്പറിലേക്ക് നോക്കുമ്പോൾ അതിന്റെ താഴ്ഭാഗം പോലും ഇളകുന്നുണ്ടായിരുന്നു. ഞാൻ ഇപ്രകാരം പറയുകപോലും ചെയ്തു: റസൂൽ(സ)യും മിമ്പറും ഒന്നിച്ച് മറിഞ്ഞുവീഴുമോ? (മു,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 818, 818, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنِ النَّوَّاسِ بْنِ سَمْعَانَ الْكِلَابِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ قَلْبٍ إِلَّا بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ، إِنْ شَاءَ أَقَامَهُ وَإِنْ شَاءَ أَزَاغَهُ". وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "يَا مُثَبِّتَ الْقُلُوبِ ثَبِّتْ قُلُوبَنَا عَلَى دِينِكَ". قَالَ: "وَالْمِيزَانُ بِيَدِ الرَّحْمَنِ، يَرْفَعُ أَقْوَامًا وَيَخْفِضُ آخَرِينَ إِلَى يَوْمِ الْقِيَامَةِ". (جه)', 'നവ്വാസുബ്നു സംആനുൽ കിലാബിയ്യി(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "കരുണാവാനായ അല്ലാഹുവിന്റെ വിരലുകളിൽ രണ്ടെണ്ണത്തിന്റെ ഇടയിൽ നിലകൊള്ളുന്നതല്ലാത്ത ഒരു ഹൃദയവുമില്ല. അവനുദ്ദേശിക്കുന്ന പക്ഷം അതിനെ (സത്യത്തിനു മേൽ) നിലനിർത്തും. അവനുദ്ദേശിക്കുന്ന പക്ഷം (സത്യത്തിൽ നിന്ന്) തെറ്റിക്കുകയും ചെയ്യും." റസൂൽ(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "ഹൃദയങ്ങളെ ഉറപ്പിച്ചു നിർത്തുന്ന തമ്പുരാനേ, ഞങ്ങളുടെ ഹൃദയങ്ങളെ നിന്റെ ദീനിൽ ഉറപ്പിച്ചുനിർത്തണേ." റസൂൽ(സ) പറഞ്ഞു: "മീസാൻ (തുലാസ്) അല്ലാഹുവിന്റെ കയ്യിലാണ്. അന്ത്യനാൾ സംഭവിക്കുംവരെ ചിലയാളുകളെ അവൻ ഉയർത്തുകയും മറ്റു ചിലരെ താഴ്ത്തുകയും ചെയ്യും." (ജ)', 'النَّوَّاسِ بْنِ سَمْعَانَ الْكِلَابِيِّ', 'നവ്വാസുബ്നു സംആനുൽ കിലാബിയ്യി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 818, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ أَبِي سَعِيد الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ لَيَضْحَكُ إِلَى ثَلَاثَة: للصَّفِّ فِي الصَّلَاة، وَللرَّجُل يُصَلِّي فِي جَوْفِ اللَّيْلِ، وَللرَّجُل يُقَاتِلُ خَلْفَ الْكَتِيبَة". [ز: في إسناده مقال]. (جه)', 'അബൂസഈദിൽ ഖുദ്‌രി(റ): "മൂന്ന് കാര്യങ്ങളാൽ അല്ലാഹു ചിരിക്കും: നമസ്കാരത്തിന് വേണ്ടി അണി നിൽക്കൽ, രാത്രിയിൽ നിസ്കരിക്കുന്ന വ്യക്തി, ചെറുസൈന്യത്തിന് പിന്നിൽ (വിജയം വരിച്ച ശേഷം) നിന്ന് യുദ്ധം ചെയ്യുന്ന വ്യക്തി എന്നിവയാണവ." ഇതിന്റെ പരമ്പരയെ സംബന്ധിച്ച് ഭിന്നതയുണ്ട്. (ജ)', 'أَبِي سَعِيد الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്‌രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مقال', null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'عَنْ جَابر بْن عَبْد اللَّه رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْرِضُ نَفْسَهُ عَلَى النَّاسِ فِي الْمَوْسِمِ، فَيَقُولُ: "أَلَا رَجُلٌ يَحْمِلُنِي إِلَى قَوْمه، فَإِنَّ قُرَيْشًا قَدْ مَنَعُونِي أَنْ أُبَلِّغَ كَلَامَ رَبِّي". (د,ت,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): ഹജ്ജ് കാലത്ത് റസൂൽ(സ) ജനങ്ങൾക്കിടയിലേക്ക് വന്നുകൊണ്ട് ഇപ്രകാരം പറയുമായിരുന്നു: "എന്നെ തന്റെ സമൂഹത്തിലേക്ക് കൊണ്ടുപോകാൻ തയ്യാറുള്ള വല്ല വ്യക്തിയുമുണ്ടോ. എന്റെ രക്ഷിതാവിന്റെ വചനങ്ങളെ എത്തിച്ചുകൊടുക്കുന്നതിൽ നിന്ന് ഖുറൈശികൾ എന്നെ തടഞ്ഞിരിക്കുകയാണ്." (ദ,തു,ജ)', 'جَابر بْن عَبْد اللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أَبِي الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فِي قَوْلِهِ تَعَالَى: {كُلَّ يَوْمٍ هُوَ فِي شَأْنٍ} [الرحمن: ٢٩] – قَالَ: "مِنْ شَأْنِهِ أَنْ يَغْفِرَ ذَنْبًا، وَيُفَرِّجَ كَرْبًا، وَيَرْفَعَ قَوْمًا، وَيَخْفِضَ آخَرِينَ". (جه)', 'അബൂദ്ദർദാഅ്(റ): ''എല്ലാ ദിവസവും അവൻ കാര്യനിർവഹണത്തിലാണ്'' (അർറഹ്മാൻ: 29) എന്ന സൂക്തത്തെക്കുറിച്ച് നബി(സ) പറഞ്ഞു: "ദോഷങ്ങൾ പൊറുക്കൽ, പ്രയാസങ്ങൾ ദൂരീകരിക്കൽ, ചിലരെ ഉയർത്തൽ, മറ്റു ചിലരെ താഴ്ത്തൽ എന്നിവയെല്ലാം അവന്റെ പ്രവർത്തനങ്ങളിൽ പെട്ടതാണ്." (ജ)', 'أَبِي الدَّرْدَاءِ', 'അബൂദ്ദർദാഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'الرحمن: ٢٩', null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "يَطْوِي اللَّهُ السَّمَاوَاتِ يَوْمَ الْقِيَامَةِ، ثُمَّ يَأْخُذُهُنَّ بِيَده الْيُمْنَى، ثُمَّ يَقُولُ: أَنَا الْمَلِكُ، أَيْنَ الْجَبَّارُونَ؟ أَيْنَ الْمُتَكَبِّرُونَ؟ ثُمَّ يَطْوِي الْأَرَضِينَ، ثُمَّ يَأْخُذُهُنَّ بِيَده الْأُخْرَى، ثُمَّ يَقُولُ: أَنَا الْمَلِكُ، أَيْنَ الْجَبَّارُونَ؟ أَيْنَ الْمُتَكَبِّرُونَ؟". (ق,د,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "അന്ത്യനാളിൽ അല്ലാഹു ആകാശങ്ങളെ ചുരുട്ടും. ശേഷം അവയെ തന്റെ വലതുകയ്യിൽ പിടിച്ചുകൊണ്ട് പറയും: ഞാനാണ് അധികാരി. (മറ്റു) പരമാധികാരികൾ എവിടെ? അഹന്ത നടിച്ചിരുന്നവർ എവിടെ? ശേഷം ഭൂമികളെ അവൻ ചുരുട്ടും. എന്നിട്ട് അവയെ മറ്റേ കയ്യിൽ പിടിക്കും. എന്നിട്ട് പറയും: ഞാനാണ് അധികാരി. മറ്റു പരമാധികാരികൾ എവിടെ? അഹന്ത നടിച്ചിരുന്നവർ എവിടെ?" (ബു,മു,ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','جه']::text[], array['ബു','മു','ദ','ജ']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَنْزِلُ رَبُّنَا كُلَّ لَيْلَة إِلَى سَمَاء الدُّنْيَا حَتَّى يَبْقَى ثُلُثُ اللَّيْلِ الْآخِرُ، فَيَقُولُ: مَنْ يَدْعُونِي فَأَسْتَجِيبَ لَهُ؟ مَنْ يَسْأَلُنِي فَأُعْطِيَهُ؟ مَنْ يَسْتَغْفِرُنِي فَأَغْفِرَ لَهُ". (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ രാത്രിയിലും അവസാനത്തെ മൂന്നിലൊരു ഭാഗം മാത്രം ശേഷിക്കുന്ന സമയത്ത് നമ്മുടെ രക്ഷിതാവ് ഏറ്റവും താഴെയുള്ള ആകാശത്തിലേക്കിറങ്ങി വരും. എന്നിട്ടവൻ ചോദിക്കും: ആരാണ് എന്നോട് പ്രാർത്ഥിക്കുന്നത്, ഞാനവന് ഉത്തരം ചെയ്യാം. ആരാണ് എന്നോട് ചോദിക്കുന്നത്, ഞാനവന് നൽകാം. ആരാണ് എന്നോട് പൊറുക്കലിനെത്തേടുന്നത്, ഞാനവന് പൊറുത്തുകൊടുക്കാം." (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 819, 819, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: وَلَشَأْنِي فِي نَفْسِي كَانَ أَحْقَرَ مِنْ أَنْ يَتَكَلَّمَ اللَّهُ فِيَّ بِأَمْرٍ يُتْلَى. (ق,د)', 'ആഇശ(റ): എന്നെന്നും പാരായണം ചെയ്യപ്പെടുന്ന ഒരു കാര്യം അല്ലാഹു എന്നെക്കുറിച്ച് പറയാൻ മാത്രം ഞാൻ ഉത്തമയല്ല എന്നുതന്നെയായിരുന്നു എന്റെ ചിന്ത. (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ عَامر بْن شَهْرٍ قَالَ: كُنْتُ عِنْدَ النَّجَاشِيِّ فَقَرَأَ ابْنٌ لَهُ آيَةً مِنَ الْإِنْجِيلِ، فَضَحِكْتُ، فَقَالَ: أَتَضْحَكُ مِنْ كَلَامِ اللَّه؟ (د)', 'ആമിറുബ്നു ശഹ്ർ(റ): ഞാൻ നജാശിയുടെ അടുത്തായിരിക്കെ അദ്ദേഹത്തിന്റെ ഒരു പുത്രൻ ഇഞ്ചീലിലെ ഒരു സൂക്തം ഓതി. അപ്പോൾ ഞാൻ ചിരിച്ചു. ഉടനെ നജാശി ചോദിച്ചു: അല്ലാഹുവിന്റെ വചനം കേട്ട് നീ ചിരിക്കുന്നുവോ? (ദ)', 'عَامر بْن شَهْرٍ قَالَ', 'ആമിറുബ്നു ശഹ്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنَ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَوِّذُ الْحَسَنَ وَالْحُسَيْنَ: "أُعِيذُكُمَا بِكَلِمَاتِ اللَّهِ التَّامَّةِ مِنْ كُلِّ شَيْطَانٍ وَهَامَّةٍ، وَمِنْ كُلِّ عَيْنٍ لَامَّةٍ". ثُمَّ يَقُولُ: "كَانَ أَبُوكُمْ يُعَوِّذُ بِهِمَا إِسْمَاعِيلَ وَإِسْحَقَ". (خ,د,ت,جه)', 'ഇബ്നു അബ്ബാസ്(റ): ഹസൻ(റ), ഹുസൈൻ(റ) എന്നിവർക്ക് വേണ്ടി നബി(സ) ഇപ്രകാരം കാവൽതേടാറുണ്ടായിരുന്നു: "അല്ലാഹുവിന്റെ പൂർണ വചനങ്ങൾ കൊണ്ട്, സർവ പിശാചുക്കളിൽ നിന്നും വിഷ ജന്തുക്കളിൽ നിന്നും ബുദ്ധിമുട്ടുണ്ടാക്കുന്ന സർവ നോട്ടങ്ങളിൽ നിന്നും, നിങ്ങൾ രണ്ടുപേർക്കും വേണ്ടി ഞാൻ കാവൽ ചോദിക്കുന്നു." ശേഷം അവിടുന്ന് ഇപ്രകാരം പറയുമായിരുന്നു: "നിങ്ങളുടെ പിതാവ് (ഇബ്റാഹീംനബി) ഇസ്മാഈൽ(അ), ഇസ്ഹാഖ്(അ) എന്നിവർക്കുവേണ്ടി ഇവ രണ്ടുംകൊണ്ട് കാവൽ ചോദിക്കാറുണ്ടായിരുന്നു." (ബു,ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നു അബ്ബാസ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا تَكَلَّمَ اللَّهُ بِالْوَحْيِ سَمِعَ أَهْلُ السَّمَاءِ لِلسَّمَاءِ صَلْصَلَةً كَجَرِّ السِّلْسِلَةِ عَلَى الصَّفَا، فَيُصْعَقُونَ، فَلَا يَزَالُونَ كَذَلِكَ حَتَّى يَأْتِيَهُمْ جِبْرِيلُ، حَتَّى إِذَا جَاءَهُمْ جِبْرِيلُ فُزِّعَ عَنْ قُلُوبِهِمْ، قَالَ: فَيَقُولُونَ: يَا جِبْرِيلُ، مَاذَا قَالَ رَبُّكَ؟ فَيَقُولُ: الْحَقَّ، فَيَقُولُونَ: الْحَقَّ، الْحَقَّ". (خ,د,ت,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ദിവ്യ സന്ദേശവുമായി സംസാരിക്കുമ്പോൾ ആകാശവാസികൾ പാറപ്പുറത്ത് ചങ്ങല വലിക്കുമ്പോഴുള്ളതുപോലോത്ത ശബ്ദം ആകാശത്തിൽ നിന്ന് കേൾക്കുകയും അവർക്ക് ബോധക്ഷയം സംഭവിക്കുകയും ചെയ്യും. ജിബ്രീൽ(അ) തങ്ങളുടെ അടുത്ത് വരുന്നതു വരെ അവർ അതേ അവസ്ഥയിലായിരിക്കും. ജിബ്രീൽ(അ) വന്നാൽ അവരുടെ ഭീതി മാറും. അവർ ചോദിക്കും: ജിബ്രീലേ, എന്താണ് നിന്റെ രക്ഷിതാവ് പറഞ്ഞത്? ജിബ്രീൽ(അ) പറയും: സത്യമാണ് അവൻ പറഞ്ഞത്. അപ്പോൾ അവരും പറയും: സത്യമാണ്, സത്യമാണ് (അവൻ പറഞ്ഞത്)." (ബു,ദ,തു,ജ)', 'عَبْدِ اللَّهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['خ','د','ت','جه']::text[], array['ബു','ദ','തു','ജ']::text[], null, null, 820, 820, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أُرِيدَ مَالُهُ بِغَيْرِ حَقٍّ فَقَاتَلَ فَقُتِلَ فَهُوَ شَهِيدٌ". (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അവകാശത്തോടുകൂടെയല്ലാതെ ഒരുത്തന്റെ മുതൽ (കൈവശപ്പെടുത്താൻ) ആഗ്രഹിക്കപ്പെടുകയും അങ്ങനെ അവൻ പോരാടുകയും കൊല്ലപ്പെടുകയും ചെയ്താൽ അവൻ രക്തസാക്ഷിയാണ്." (ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 820, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنْ سَعِيد بْن زَيْدٍ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ قُتِلَ دُونَ مَاله فَهُوَ شَهِيدٌ، وَمَنْ قُتِلَ دُونَ أَهْله - أَوْ: دُونَ دَمه. أَوْ: دُونَ دينه - فَهُوَ شَهِيدٌ". (د,ت,ن,جه)', 'സഇൗദുബ്നു സൈദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തന്റെ മുതലിന്റെ പേരിൽ (അതിനുവേണ്ടി പോരാടി) ഒരാൾ വധിക്കപ്പെട്ടാൽ അവൻ രക്തസാക്ഷിയാണ്. തന്റെ കുടുംബത്തിന്റെ പേരിൽ - അല്ലെങ്കിൽ രക്തത്തിന്റെ പേരിൽ, അല്ലെങ്കിൽ മതത്തിന്റെ പേരിൽ - (ഇവയെ സംരക്ഷിക്കാനോ നേടിയെടുക്കാനോ ഉള്ള പോരാട്ടത്തിൽ) ഒരാൾ വധിക്കപ്പെട്ടാൽ അവനും രക്തസാക്ഷിയാണ്." (ദ,തു,ന,ജ)', 'سَعِيد بْن زَيْدٍ', 'സഇൗദുബ്നു സൈദ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "الْإِيمَانُ بِضْعٌ وَسَبْعُونَ، أَفْضَلُهَا قَوْلُ لَا إِلَهَ إِلَّا اللَّهُ، وَأَدْنَاهَا إِمَاطَةُ الْعَظْمِ عَنِ الطَّرِيقِ، وَالْحَيَاءُ شُعْبَةٌ مِنَ الْإِيمَانِ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഈമാൻ എഴുപതിൽ പരം ഭാഗങ്ങളാണ്. അതിൽ ഏറ്റവും ഉത്തമം ലാഇലാഹ ഇല്ലല്ലാഹു (അല്ലാഹുവല്ലാതെ ആരാധ്യനല്ല) എന്ന വചനമാണ്. അതിൽ ഏറ്റവും താഴ്ന്നത് വഴിയിൽനിന്ന് എല്ലിൻകഷ്ണം മാറ്റലാണ്. ലജ്ജ ഈമാനിന്റെ ഭാഗമാണ്." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: إِنَّ وَفْدَ عَبْدِ الْقَيْسِ لَمَّا قَدِمُوا عَلَى رَسُول اللَّه صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُمْ بِالْإِيمَانِ بِاللَّهِ، قَالَ: "أَتَدْرُونَ مَا الْإِيمَانُ بِاللَّهِ". قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "شَهَادَةُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامُ الصَّلَاةِ، وَإِيتَاءُ الزَّكَاةِ، وَصَوْمُ رَمَضَانَ، وَأَنْ تُعْطُوا الْخُمُسَ مِنَ الْمَغْنَمِ". (ق,د,ت,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അബ്ദുൽഖൈസിന്റെ സംഘം റസൂൽ(സ)യുടെ അടുത്തെത്തിയപ്പോൾ അവിടുന്ന് അവരോട് അല്ലാഹുവിൽ വിശ്വസിക്കാൻ കൽപിച്ചു. റസൂൽ(സ) ചോദിച്ചു: "അല്ലാഹുവിൽ വിശ്വസിക്കുക എന്നാൽ എന്താണെന്ന് നിങ്ങൾക്ക് അറിയുമോ?" അവർ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് കൂടുതൽ അറിവുള്ളവർ. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ലെന്നും മുഹമ്മദ്(സ) അവന്റെ പ്രവാചകനാണെന്നും സാക്ഷ്യം വഹിക്കലും, നമസ്കാരത്തെ നിലനിർത്തലും, സകാത് (നിർബന്ധ ദാനം) നൽകലും, റമളാൻ മാസം നോമ്പനുഷ്ഠിക്കലും, ഗനീമത്തിൽനിന്ന് നിങ്ങൾ അഞ്ചിലൊന്ന് നൽകലുമാണത്." (ബു,മു,ദ,തു,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "بَيْنَ الْعَبْدِ وَبَيْنَ الْكُفْرِ تَرْكُ الصَّلَاةِ". (م,د,ت,ن,جه)', 'ജാബിർ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരു അടിമക്കും ദൈവനിഷേധത്തിനും (കുഫ്ർ) ഇടയിലെ വ്യത്യാസം നമസ്കാരത്തെ ഉപേക്ഷിക്കലാണ്." (മു,ദ,തു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', '⁴. ഈമാനുണ്ടെങ്കിൽ പാപങ്ങൾ പ്രശ്നമല്ലെന്നും അവിശ്വാസത്തോടൊപ്പം ഒരു സൽകർമ്മത്തിനും ഫലമില്ലെന്നും വിശ്വസിക്കുന്ന വിഭാഗമാണ് മുർജിഅഃ, സൽകർമ്മങ്ങൾ ഈമാനിന്റെ ഭാഗമാണെന്ന ഈ ഹദീസ് അവരുടെ ആദർശത്തെ പൊളിക്കുന്നു.', null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 821, 821, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ قَالَ: "مَا رَأَيْتُ مِنْ نَاقصَات عَقْلٍ وَلَا دِينٍ أَغْلَبَ لذي لُبٍّ منْكُنَّ". قَالَتْ: وَمَا نُقْصَانُ الْعَقْلِ وَالدِّينِ؟ قَالَ: "أَمَّا نُقْصَانُ الْعَقْلِ فَشَهَادَةُ امْرَأَتَيْنِ شَهَادَةُ رَجُلٍ، وَأَمَّا نُقْصَانُ الدِّينِ فَإِنَّ إِحْدَاكُنَّ تُفْطِرُ رَمَضَانَ، وَتُقِيمُ أَيَّامًا لَا تُصَلِّي". (م,د,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ബുദ്ധിയും മതകാര്യവും കുറഞ്ഞവരിൽ, ബുദ്ധിയുള്ളവരെ ജയിച്ചടക്കാൻ നിങ്ങളേക്കാൾ (സ്ത്രീകളേക്കാൾ) കഴിവുള്ള ഒരാളെയും ഞാൻ കണ്ടിട്ടില്ല." (ഒരു) സ്ത്രീ ചോദിച്ചു: ബുദ്ധിയും മതകാര്യവും കുറയുക എന്നാൽ എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "രണ്ട് സ്ത്രീകളുടെ സാക്ഷിത്വം ഒരു പുരുഷന്റെ സാക്ഷിത്വത്തിന് സമാനമാവുക എന്നതാണ് ബുദ്ധി കുറയുക എന്നത്. മതകാര്യം കുറയുക എന്നാൽ നിങ്ങളിൽ ഓരോരുത്തരും റമളാനിൽ നോമ്പനുഷ്ഠിക്കാതിരിക്കുകയും ധാരാളം ദിവസം നമസ്കരിക്കാതിരിക്കുകയും ചെയ്യേണ്ടി വരുന്നു എന്നതാണ്." (മു,ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَمَّا تَوَجَّهَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَى الْكَعْبَةِ قَالُوا: يَا رَسُولَ اللهِ، فَكَيْفَ الَّذِينَ مَاتُوا وَهُمْ يُصَلُّونَ إِلَى بَيْتِ الْمَقْدِسِ؟ فَأَنْزَلَ اللهُ تَعَالَى: {وَمَا كَانَ اللهُ لِيُضِيعَ إِيمَانَكُمْ} [البقرة: ١٤٣]. (د,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) കഅ്ബയിലേക്ക് തിരിയാൻ തുടങ്ങിയപ്പോൾ അവർ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ബൈതുൽ മുഖദ്ദസിലേക്ക് തിരിഞ്ഞ് നമസ്കരിച്ചിരുന്ന സമയങ്ങളിൽ മരിച്ചവരുടെ അവസ്ഥയെന്താണ്? അപ്പോൾ അല്ലാഹു ''അല്ലാഹു നിങ്ങളുടെ ഈമാനിനെ നഷ്ടപ്പെടുത്തുകയില്ല'' (അൽബഖറ: 143) എന്ന സൂക്തമിറക്കി. (ദ,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'البقرة: ١٤٣', null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنْ أَبِي أُمَامَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ أَحَبَّ لِلَّهِ وَأَبْغَضَ لِلَّهِ، وَأَعْطَى لِلَّهِ وَمَنَعَ لِلَّهِ، فَقَد اسْتَكْمَلَ الْإِيمَانَ". (د)', 'അബൂഉമാമ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആരെങ്കിലും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ സ്നേഹിക്കുകയും ദേഷ്യംവെക്കുകയും അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ദാനം ചെയ്യുകയും ദാനം നൽകാതിരിക്കുകയും (അല്ലാഹു തൃപ്തിപ്പെടാത്ത കാര്യത്തിന്) ചെയ്താൽ അവന്റെ വിശ്വാസം പൂർണ്ണമായിരിക്കുന്നു." (ദ)', 'أَبِي أُمَامَةَ', 'അബൂഉമാമ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا". (د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "സത്യവിശ്വാസികളിൽ ഏറ്റവും പൂർണ്ണമായ ഈമാനുള്ളത് അവരിൽ ഏറ്റവും നല്ല സ്വഭാവമുള്ളവനാണ്." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 822, 822, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ سَعْد بْن أَبِي وَقَّاص رَضِيَ اللَّهُ عَنْهُ قَالَ: أَعْطَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رِجَالًا وَلَمْ يُعْط رَجُلًا مِنْهُمْ شَيْئًا، فَقَالَ سَعْدٌ: يَا رَسُولَ اللَّهِ، أَعْطَيْتَ فُلَانًا وَفُلَانًا وَلَمْ تُعْط فُلَانًا شَيْئًا، وَهُوَ مُؤْمِنٌ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَوْ مُسْلِمٌ". حَتَّى أَعَادَهَا سَعْدٌ ثَلَاثًا، وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "أَوْ مُسْلِمٌ". ثُمَّ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنِّي أُعْطِي رِجَالًا وَأَدَعُ مَنْ هُوَ أَحَبُّ إِلَيَّ مِنْهُمْ لَا أُعْطِيهِ شَيْئًا، مَخَافَةَ أَنْ يُكَبُّوا فِي النَّارِ عَلَى وُجُوهِهِمْ". (ق,د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) ധാരാളം ആളുകൾക്ക് (സമ്പത്ത്) നൽകുകയും അവരിൽ ഒരാൾക്ക് ഒന്നും നൽകാതിരിക്കുകയും ചെയ്തു. അപ്പോൾ സഅ്ദ്(റ) ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് ഇന്നവർക്കെല്ലാം നൽകുകയും ഇന്ന വ്യക്തിക്ക് അവൻ മുഅ്മിനാ(സത്യവിശ്വാസിയാ)യിട്ടും ഒന്നും നൽകാതിരിക്കുകയും ചെയ്തല്ലോ? അപ്പോൾ നബി(സ) പറഞ്ഞു: "അവൻ മുസ്ലിമല്ലേ." അപ്പോൾ സഅ്ദ്(റ) ചോദ്യം മൂന്നു പ്രാവശ്യം ആവർത്തിക്കുകയും ഓരോന്നിലും നബി(സ) "അവൻ മുസ്ലിമല്ലേ" എന്ന് ഉത്തരം പറയുകയും ചെയ്തുകൊണ്ടിരുന്നു. ശേഷം നബി(സ) പറഞ്ഞു: "ഞാൻ ധാരാളം പേർക്ക് (സമ്പത്ത്) നൽകുകയും അവരേക്കാൾ എനിക്കിഷ്ടപ്പെട്ടവനെ ഒഴിവാക്കിയിടുകയും ചെയ്യുന്നത് അക്കൂട്ടർ നരകത്തിൽ മുഖംകുത്തി വീഴുന്നത് പേടിച്ചാണ്." (ബു,മു,ദ)', 'سَعْد بْن أَبِي وَقَّاص', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 822, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنِ الزُّهْرِيِّ قَالَ: {قُلْ لَمْ تُؤْمِنُوا وَلَكِنْ قُولُوا أَسْلَمْنَا} [الحجرات: ١٤] قَالَ: نَرَى أَنَّ الْإِسْلَامَ الْكَلِمَةُ وَالْإِيمَانَ الْعَمَلُ. (د)', 'സുഹ്രി(റ): ''അങ്ങ് പറയുക: നിങ്ങൾ മുഅ്മിനുകളായിട്ടില്ല. ഞങ്ങൾ മുസ്ലിംകളായി എന്നുമാത്രം നിങ്ങൾ പറയുക'' (ഹുജുറാത്ത്: 14) എന്നതിനെക്കുറിച്ച് സുഹ്രി(റ) പറയുന്നു: ഇസ്ലാം എന്നാൽ വചനമാണെന്നും ഈമാൻ എന്നാൽ അതിന്റെ കർമ്മമാണെന്നുമാണ് ഞങ്ങളുടെ അഭിപ്രായം. (ദ)', 'الزُّهْرِيِّ قَالَ', 'സുഹ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الحجرات: ١٤', null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ سَعْد بْن أَبِي وَقَّاص رَضِيَ اللَّهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَسَمَ بَيْنَ الْمُسْلِمِينَ قَسْمًا، فَقُلْتُ: أَعْط فُلَانًا فَإِنَّهُ مُؤْمِنٌ. قَالَ: "أَوْ مُسْلِمٌ، إِنِّي لَأُعْطِي الرَّجُلَ الْعَطَاءَ وَغَيْرُهُ أَحَبُّ إِلَيَّ مِنْهُ، مَخَافَةَ أَنْ يُكَبَّ عَلَى وَجْهه". (د)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): നബി(സ) ഒരിക്കൽ മുസ്ലിംകൾക്കിടയിൽ (സമ്പത്ത്) വിഹിതംവെച്ചു. അപ്പോൾ ഞാൻ പറഞ്ഞു: അങ്ങ് ഇന്ന വ്യക്തിക്കുകൂടി നൽകുക, അവൻ മുഅ്മിനാണ്. റസൂൽ(സ) പറഞ്ഞു: "അവൻ മുസ്ലിമല്ലേ. നിശ്ചയം ഞാൻ ഒരാൾക്ക്, അവനേക്കാൾ എനിക്കിഷ്ടപ്പെട്ട മറ്റൊരാൾ ഉണ്ടായിരിക്കെത്തന്നെ, വല്ലതും നൽകുന്നത് അവൻ (നരകത്തിലേക്ക്) മുഖംകുത്തി വീഴാതിരിക്കാൻ വേണ്ടിയാണ്." (ദ)', 'سَعْد بْن أَبِي وَقَّاص', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ". (ق,د,ن,جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) പറഞ്ഞു: "എന്റെ ശേഷം പരസ്പരം പിരടികൾ വെട്ടുന്ന സത്യനിഷേധികളായി നിങ്ങൾ മാറരുത്." (ബു,മു,ദ,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَيُّمَا رَجُلٍ مُسْلِمٍ أَكْفَرَ رَجُلًا مُسْلِمًا: فَإِنْ كَانَ كَافِرًا، وَإِلَّا كَانَ هُوَ الْكَافِرَ". (د)', 'ഇബ്നുഉമർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുസ്ലിമായ ഒരു വ്യക്തി മറ്റൊരു മുസ്ലിമിനെക്കുറിച്ച് കാഫിർ (സത്യനിഷേധി) എന്ന് പറഞ്ഞാൽ യഥാർത്ഥത്തിൽ അവൻ സത്യനിഷേധിയാണെങ്കിൽ അപ്രകാരം തന്നെയായിരിക്കും. അല്ലെങ്കിൽ അവൻ (പറഞ്ഞവൻ) തന്നെ സത്യനിഷേധിയായി മാറും." (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 823, 823, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَرْبَعٌ مَنْ كُنَّ فِيهِ فَهُوَ مُنَافِقٌ خَالِصٌ، وَمَنْ كَانَتْ فِيهِ خَلَّةٌ مِنْهُنَّ كَانَ فِيهِ خَلَّةٌ مِنْ نِفَاقٍ حَتَّى يَدَعَهَا: إِذَا حَدَّثَ كَذَبَ، وَإِذَا وَعَدَ أَخْلَفَ، وَإِذَا عَاهَدَ غَدَرَ، وَإِذَا خَاصَمَ فَجَرَ". (ق,د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറഞ്ഞു: "നാലു കാര്യങ്ങൾ ആരിലെങ്കിലും ഉണ്ടായാൽ അവൻ പൂർണ്ണ കപടവിശ്വാസിയാണ്. അവയിൽ ഒരു കാര്യംമാത്രം ആരിലെങ്കിലുമുണ്ടെങ്കിൽ, അത് ഒഴിവാകുംവരെ, അവനിൽ കാപട്യത്തിന്റെ ഒരു സ്വഭാവമുണ്ടായിരിക്കും: സംസാരിച്ചാൽ കളവ് പറയുക, വാഗ്ദാനം ചെയ്താൽ ലംഘിക്കുക, കരാർ ചെയ്താൽ വഞ്ചിക്കുക, തർക്കിച്ചാൽ മോശമായി സംസാരിക്കുക എന്നിവയാണ് ആ കാര്യങ്ങൾ." (ബു,മു,ദ,തു,ന)', 'عَبْدِ اللَّهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 823, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "لَا يَزْنِي الزَّانِي حِينَ يَزْنِي وَهُوَ مُؤْمِنٌ، وَلَا يَسْرِقُ حِينَ يَسْرِقُ وَهُوَ مُؤْمِنٌ، وَلَا يَشْرَبُ الْخَمْرَ حِينَ يَشْرَبُهَا وَهُوَ مُؤْمِنٌ، وَالتَّوْبَةُ مَعْرُوضَةٌ بَعْدُ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "മുഅ്മിനായ അവസ്ഥയിൽ ഒരാളും വ്യഭിചരിക്കുകയില്ല, മുഅ്മിനായ അവസ്ഥയിൽ ഒരാളും മോഷ്ടിക്കുകയില്ല, മുഅ്മിനായ അവസ്ഥയിൽ ഒരാളും മദ്യപിക്കുകയില്ല. പശ്ചാത്താപം ഇവയ്ക്കെല്ലാം ശേഷമാണ് വെളിവാക്കപ്പെടുന്നത്." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِذَا زَنَى الرَّجُلُ خَرَجَ مِنْهُ الْإِيمَانُ كَانَ عَلَيْهِ كَالظُّلَّةِ، فَإِذَا انْقَطَعَ رَجَعَ إِلَيْهِ الْإِيمَانُ". (د)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ വ്യഭിചരിച്ചാൽ ഈമാൻ അവന്റെ പുറത്ത് പോവുകയും തണൽമേഘം പോലെ അത് അവനുമേൽ നിൽക്കുകയും ചെയ്യും. അവൻ പിന്തിരിഞ്ഞാൽ⁵ ഈമാൻ അവനിലേക്കുതന്നെ മടങ്ങും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُئِلَ عَنْ أَوْلَادِ الْمُشْرِكِينَ، فَقَالَ: "اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". (ق,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ബഹുദൈവാരാധകരുടെ സന്താനങ്ങളെക്കുറിച്ച് (പ്രായം തികയും മുമ്പ് മരിച്ചുപോയ കുട്ടികൾ) നബി(സ)യോട് ചോദിക്കപ്പെട്ടു. അവിടുന്ന് പറഞ്ഞു: "അവർ എന്താണ് പ്രവർത്തിക്കുക എന്ന് അല്ലാഹുവിനാണറിയുക." (ബു,മ,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മ','ദ','ന']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، ذَرَارِيُّ الْمُؤْمِنِينَ؟ فَقَالَ: "هُمْ مِنْ آبَائِهِمْ". فَقُلْتُ: يَا رَسُولَ اللَّهِ، بِلَا عَمَلٍ؟ قَالَ: "اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". قُلْتُ: يَا رَسُولَ اللَّهِ، فَذَرَارِيُّ الْمُشْرِكِينَ؟ قَالَ: "مِنْ آبَائِهِمْ". قُلْتُ: بِلَا عَمَلٍ؟ قَالَ: "اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". (د)', 'ആഇശ(റ): ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, സത്യവിശ്വാസികളുടെ സന്താനങ്ങളെക്കുറിച്ച് (എന്താണ് അവിടുന്ന് പറയുന്നത്)? റസൂൽ(സ) പറഞ്ഞു: "അവർ തങ്ങളുടെ വാപ്പമാരുടെ കൂട്ടത്തിൽ പെട്ടവരാണ്." ഞാൻ ചോദിച്ചു: റസൂലേ, ഒരു കർമ്മവുമില്ലാതെയോ? റസൂൽ(സ) പറഞ്ഞു: "അവർ എന്താണ് പ്രവർത്തിക്കുകയെന്ന് അല്ലാഹുവിനാണറിയുക." ഞാൻ ചോദിച്ചു: റസൂലേ, അപ്പോൾ ബഹുദൈവാരാധകരുടെ സന്താനങ്ങളോ? റസൂൽ(സ) പറഞ്ഞു: "അവർ തങ്ങളുടെ വാപ്പമാരുടെ കൂട്ടത്തിൽ പെട്ടവരാണ്." ഞാൻ ചോദിച്ചു: ഒരു പ്രവർത്തനവുമില്ലാതെയോ? റസൂൽ(സ) പറഞ്ഞു: "അവർ എന്താണ് പ്രവർത്തിക്കുകയെന്ന് അല്ലാഹുവിനാണറിയുക." (ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', '⁵. അല്ലാഹു അവന്റെ പശ്ചാതാപം സ്വീകരിച്ച് അവൻ ആ പാപത്തിൽനിന്ന് ശുദ്ധമായാൽ എന്നർത്ഥം', null, array['د']::text[], array['ദ']::text[], null, null, 824, 824, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: أُتِيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِصَبِيٍّ مِنَ الْأَنْصَارِ يُصَلِّي عَلَيْهِ، قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، طُوبَى لِهَذَا، لَمْ يَعْمَلْ شَرًّا وَلَمْ يَدْرِ بِهِ. فَقَالَ: "أَوْ غَيْرُ ذَلِكَ يَا عَائِشَةُ، إِنَّ اللَّهَ خَلَقَ الْجَنَّةَ وَخَلَقَ لَهَا أَهْلًا، وَخَلَقَهَا لَهُمْ وَهُمْ فِي أَصْلَابِ آبَائِهِمْ. وَخَلَقَ النَّارَ وَخَلَقَ لَهَا أَهْلًا، وَخَلَقَهَا لَهُمْ وَهُمْ فِي أَصْلَابِ آبَائِهِمْ". (م,د,ن,جه)', 'ആഇശ(റ): അൻസ്വാറുകളിലെ ഒരു കുട്ടിയെ, അവന്റെ മേൽ മയ്യിത്ത് നമസ്കരിക്കുന്നതിനു വേണ്ടി, നബി(സ)യുടെ അടുത്ത് കൊണ്ടുവരപ്പെട്ടു. അപ്പോൾ ഞാൻ പറഞ്ഞു: റസൂലേ, ഈ കുട്ടിയുടെ ഭാഗ്യം, അവൻ ഒരു തിന്മയും ചെയ്യുകയോ, തിന്മ എന്തെന്ന് അറിയുകയോ ചെയ്തിട്ടില്ല. റസൂൽ(സ) പറഞ്ഞു: "അതല്ലാത്ത വല്ലതും സംസാരിക്കുക, അല്ലാഹു സ്വർഗ്ഗം പടക്കുകയും അതിന്റെ ആളുകളെ സൃഷ്ടിക്കുകയും ചെയ്തു. തങ്ങളുടെ വാപ്പമാരുടെ മുതുകിലായിരിക്കെത്തന്നെ ആ സ്വർഗ്ഗത്തെ അവൻ അവർക്കുവേണ്ടി സൃഷ്ടിച്ചു. അവൻ നരകത്തെ പടക്കുകയും അതിന്റെ ആളുകളെ സൃഷ്ടിക്കുകയും ചെയ്തു. തങ്ങളുടെ വാപ്പമാരുടെ മുതുകിലായിരിക്കെത്തന്നെ ആ നരകത്തെ അവൻ അവർക്കുവേണ്ടി സൃഷ്ടിച്ചു." (മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 824, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "كُلُّ مَوْلُود يُولَدُ عَلَى الْفِطْرَةِ، فَأَبَوَاهُ يُهَوِّدَانه وَيُنَصِّرَانه، كَمَا تَنَاتَجُ الْإِبِلُ مِنْ بَهِيمَةٍ جَمْعَاءَ، هَلْ تُحِسُّ مِنْ جَدْعَاءَ". قَالُوا: يَا رَسُولَ اللَّهِ، أَفَرَأَيْتَ مَنْ يَمُوتُ وَهُوَ صَغِيرٌ؟ قَالَ: "اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓരോ കുഞ്ഞും ശുദ്ധമായ പ്രകൃതത്തോടെയാണ് പ്രവസവിക്കപ്പെടുന്നത്. അവന്റെ മാതാപിതാക്കളാണ് അവനെ ജൂതനും കൃസ്ത്യാനിയുമാക്കുന്നത്. ഒട്ടകങ്ങൾ കൂട്ടമായി പെറ്റുപെരുകുംപോലെ മൂക്കുമുറിഞ്ഞവയെ അവയ്ക്കിടയിൽ നീ കണ്ടിട്ടുണ്ടോ?" അവർ ചോദിച്ചു: റസൂലേ, കുഞ്ഞായിരിക്കെത്തന്നെ മരിക്കുന്നവനെ സംബന്ധിച്ച് അങ്ങയുടെ അഭിപ്രായമെന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "അവർ എന്താണ് പ്രവർത്തിക്കുക എന്ന് കൂടുതൽ അറിയുന്നവൻ അല്ലാഹുവാണ്." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ مَالك - رَحِمَهُ اللهُ تَعَالَى - قِيلَ لَهُ: إِنَّ أَهْلَ الْأَهْوَاءِ يَحْتَجُّونَ عَلَيْنَا بِهَذَا الْحَدِيثِ، قَالَ مَالِكٌ: احْتَجَّ عَلَيْهِمْ بِآخِرِه، قَالُوا: أَرَأَيْتَ مَنْ يَمُوتُ وَهُوَ صَغِيرٌ؟ قَالَ: "اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ". (د)', 'മാലിക്(റ): സ്വേച്ഛകളെ പിന്തുടരുന്നവർ ഈ ഹദീസിനെ ഞങ്ങൾക്കെതിരായ തെളിവായി ഉദ്ധരിക്കുന്നുവെന്ന് അദ്ദേഹത്തോട് പറയപ്പെട്ടു. മാലിക്(റ) പറഞ്ഞു: അതിന്റെ അവസാന ഭാഗത്തെ അവർക്കെതിരായ തെളിവായി നീയും ഉദ്ധരിക്കുക: സ്വഹാബികൾ ചോദിച്ചു: കുഞ്ഞായിരിക്കെത്തന്നെ മരിക്കുന്നവനെക്കുറിച്ച് അങ്ങയുടെ അഭിപ്രായമെന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "അവർ എന്താണ് പ്രവർത്തിക്കുകയെന്ന് കൂടുതൽ അറിയുന്നവൻ അല്ലാഹുവാണ്." (ദ)', 'مَالك - رَحِمَهُ اللهُ تَعَالَى - قِيلَ لَهُ', 'മാലിക്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ حَمَّادِ بْنِ سَلَمَةَ: يُفَسِّرُ حَدِيثَ: "كُلُّ مَوْلُودٍ يُولَدُ عَلَى الْفِطْرَةِ" قَالَ: هَذَا عِنْدَنَا حَيْثُ أَخَذَ اللهُ عَلَيْهِمُ الْعَهْدَ فِي أَصْلَابِ آبَائِهِمْ، حَيْثُ قَالَ: {أَلَسْتُ بِرَبِّكُمْ قَالُوا بَلَى} [الأعراف: ١٧٢]. (د)', 'ഹമ്മാദുബ്നു സലമ(റ): "എല്ലാ കുട്ടികളും ശുദ്ധപ്രകൃതത്തോടെയാണ് പ്രസവിക്കപ്പെടുന്നത്" എന്ന ഹദീസ് വിശദീകരിച്ചുകൊണ്ട് അദ്ദേഹം പറഞ്ഞു: ഇത് നമ്മുടെ അഭിപ്രായത്തിൽ ''ഞാൻ നിങ്ങളുടെ നാഥൻ അല്ലയോ? അവർ പറഞ്ഞു: അതെ'' (അഅ്റാഫ്: 172) എന്ന് അല്ലാഹു പറഞ്ഞ, തങ്ങളുടെ വാപ്പമാരുടെ മുതുകിലായിരിക്കെത്തന്നെ തങ്ങളിൽനിന്ന് അല്ലാഹു കരാറെടുത്ത അവസ്ഥയാണ്. (ദ)', 'حَمَّادِ بْنِ سَلَمَةَ', 'ഹമ്മാദുബ്നു സലമ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'الأعراف: ١٧٢', null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْوَائِدَةُ وَالْمَوْءُودَةُ فِي النَّارِ". (د)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ജീവനോടെ കുഴിച്ചിട്ട സത്രീയും കുഴിച്ചു മൂടപ്പെട്ടവളും നരകത്തിലാണ്." (ദ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 825, 825, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا قَالَ: يَا رَسُولَ اللَّهِ، أَيْنَ أَبِي؟ قَالَ: "أَبُوكَ فِي النَّارِ". فَلَمَّا قَفَّى قَالَ: "إِنَّ أَبِي وَأَبَاكَ فِي النَّارِ". (م,د)', 'അനസ്(റ): ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്റെ വാപ്പ എവിടെയാണ്? റസൂൽ(സ) പറഞ്ഞു: "നിന്റെ പിതാവ് നരകത്തിലാണ്." അവൻ തിരിഞ്ഞു നടന്നപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "എന്റെ പിതാവും നിന്റെ പിതാവും നരകത്തിലാണ്." (മു,ദ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ الشَّيْطَانَ يَجْرِي مِن ابْنِ آدَمَ مَجْرَى الدَّمِ". (م,د)', 'അനസുബ്നുമാലിക്(റ): റസൂൽ(സ) പറഞ്ഞു: "മനുഷ്യശരീരത്തിൽ രക്തം സഞ്ചരിക്കുന്ന ഇടങ്ങളിൽ എല്ലാം പിശാചും സഞ്ചരിക്കും." (മു,ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നുമാലിക്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنْ عُمَرَ بْنِ الْخَطَّابِ، رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَا تُجَالِسُوا أَهْلَ الْقَدَرِ، وَلَا تُفَاتِحُوهُمُ الْحَدِيثَ". (د)', 'ഉമറുബ്നുൽ ഖത്വാബ്(റ)വിൽനിന്ന് അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ ഖദ്റിന്റെ ആളുകളോടൊപ്പം (ഖദ്റിനെ നിഷേധിക്കുന്നവരോടൊപ്പം) ഇരിക്കുകയോ അവരോട് സംസാരിച്ച് തുടങ്ങുകയോ ചെയ്യരുത്." (ദ)', 'أَبِي هُرَيْرَةَ', 'ഉമറുബ്നുൽ ഖത്വാബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا عَلَى سَرِيَّة، وَكَانَ يَقْرَأُ لأَصْحَابه فِي صَلَاتهِمْ فَيَخْتِمُ بِقُلْ هُوَ اللَّهُ أَحَدٌ، فَلَمَّا رَجَعُوا ذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "سَلُوهُ: لأَيِّ شَيْءٍ يَصْنَعُ ذَلِكَ؟" فَسَأَلُوهُ، فَقَالَ: لِأَنَّهَا صِفَةُ الرَّحْمَنِ، وَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "أَخْبِرُوهُ: أَنَّ اللَّهَ يُحِبُّهُ". (خ)', 'ആഇശ(റ): ഒരു യുദ്ധസംഘത്തിന്റെ നായകനായി നബി(സ) ഒരാളെ പറഞ്ഞയച്ചു. തന്റെ കൂടെയുള്ളവർക്ക് ഇമാമായി നമസ്കരിക്കുമ്പോൾ അദ്ദേഹം ഖുർആൻ പാരായണം ചെയ്യുകയും അവസാനമായി ''ഖുൽഹുവല്ലാഹു അഹദ്'' (പറയുക! അവൻ അല്ലാഹു ഏകനാണ്) എന്ന് തുടങ്ങുന്ന അധ്യായം (സൂറതുൽ ഇഖ്ലാസ്) ഓതുകയും ചെയ്യുമായിരുന്നു. അങ്ങനെ അവർ മടങ്ങിവന്നപ്പോൾ ഈ വിവരം റസൂൽ(സ)യോട് പറഞ്ഞു. റസൂൽ(സ) പറഞ്ഞു: "എന്തുകൊണ്ടാണ് അപ്രകാരം ചെയ്യുന്നതെന്ന് നിങ്ങൾ അദ്ദേഹത്തോട് ചോദിക്കുക." അവർ ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: കാരണം അവ കരുണാവാനായ അല്ലാഹുവിന്റെ വിശേഷണങ്ങളാണ്. അവ പാരായണം ചെയ്യുന്നത് ഞാനിഷ്ടപ്പെടുന്നു. റസൂൽ(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു അവനെ സ്നേഹിക്കുന്നുവെന്ന് നിങ്ങൾ അവനോട് പറയുക." (ബു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "مَا أَحَدٌ أَصْبَرُ عَلَى أَذًى سَمِعَهُ مِنَ اللَّهِ، يَدَّعُونَ لَهُ الْوَلَدَ، ثُمَّ يُعَافِيهِمْ وَيَرْزُقُهُمْ". (خ)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "താൻ കേൾക്കുന്ന ആക്ഷേപങ്ങളുടെ മേൽ അല്ലാഹുവിന്റെയത്ര ക്ഷമ കൈകൊള്ളുന്ന മറ്റൊരുത്തനുമില്ല. അല്ലാഹുവിന് സന്താനമുണ്ടെന്ന് അവർ വാദിക്കുന്നു. എന്നിട്ടും അവൻ അവർക്ക് സുഖവും ജീവിതോപാധിയും നൽകുന്നു." (ബു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 826, 826, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: "أَعُوذُ بِعِزَّتِكَ الَّذِي لَا إِلَهَ إِلَّا أَنْتَ الَّذِي لَا يَمُوتُ، وَالْجِنُّ وَالْإِنْسُ يَمُوتُونَ". (خ)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "താനല്ലാതെ മറ്റൊരു ആരാധ്യനുമില്ലാത്തവനും മരിക്കാത്തവനുമായ നിന്റെ ഔന്നിത്യംകൊണ്ട് ഞാൻ കാവൽ ചോദിക്കുന്നു. മനുഷ്യരും ജിന്നുകളുമെല്ലാം മരിച്ചു പോകുന്നവരാണ്." (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "لَمَّا خَلَقَ اللَّهُ الْخَلْقَ كَتَبَ فِي كِتَابه، وَهُوَ يَكْتُبُ عَلَى نَفْسه، وَهُوَ وَضْعٌ عِنْدَهُ عَلَى الْعَرْشِ: إِنَّ رَحْمَتِي تَغْلِبُ غَضَبِي". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു സൃഷ്ടികളെയെല്ലാം സൃഷ്ടിച്ചപ്പോൾ തന്റെ ഗ്രന്ഥത്തിൽ ഒരു കാര്യം എഴുതിവെച്ചു. താൻ സ്വീകരിച്ച കാര്യങ്ങളെയെല്ലാം എഴുതി അവൻ തന്റെ സമീപത്ത് അർശിനുമേൽ വെക്കും. ''എന്റെ കരുണ കോപത്തെ കവച്ചുവെക്കും'' എന്നതാണ് ആ കാര്യം." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَقُولُ اللهُ تَعَالَى: أَنَا عِنْدَ ظَنِّ عَبْدِي بِي، وَأَنَا مَعَهُ إِذَا ذَكَرَنِي، فَإِنْ ذَكَرَنِي فِي نَفْسِهِ ذَكَرْتُهُ فِي نَفْسِي، وَإِنْ ذَكَرَنِي فِي مَلَإٍ ذَكَرْتُهُ فِي مَلَإٍ خَيْرٍ مِنْهُمْ، وَإِنْ تَقَرَّبَ إِلَيَّ بِشِبْرٍ تَقَرَّبْتُ إِلَيْهِ ذِرَاعًا، وَإِنْ تَقَرَّبَ إِلَيَّ ذِرَاعًا تَقَرَّبْتُ إِلَيْهِ بَاعًا، وَإِنْ أَتَانِي يَمْشِي أَتَيْتُهُ هَرْوَلَةً". (خ)', 'അബൂഹുറൈറ(റ): അല്ലാഹു പറയുന്നതായി നബി(സ) പറഞ്ഞു: "എന്നെക്കുറിച്ച് എന്റെ അടിമയ്ക്കുള്ള ധാരണ എവിടെയാണോ അവിടെയായിരിക്കും ഞാൻ. എന്നെ ഓർക്കുമ്പോഴെല്ലാം ഞാൻ അവനോടൊപ്പം ഉണ്ടായിരിക്കും. എന്നെ സ്മരിച്ചത് അവന്റെ മനസ്സു കൊണ്ടാണെങ്കിൽ എന്റെ മനസ്സുകൊണ്ട് ഞാൻ അവനെ സ്മരിക്കും. ഒരു കൂട്ടത്തിൽ വെച്ച് അവൻ എന്നെ സ്മരിച്ചാൽ അതിനേക്കാൾ ഉത്തമമായ കൂട്ടത്തിൽവെച്ച് ഞാൻ അവനെയും സ്മരിക്കും. അവൻ എന്നിലേക്ക് ഒരു ചാൺ അടുത്താൽ ഒരു മുഴം ഞാൻ അങ്ങോട്ട് അടുക്കും. ഒരു മുഴം എന്നിലേക്ക് അടുത്താൽ ഞാൻ ഒരു മാറ് (രണ്ടു കൈകൾ നീട്ടിയാലുള്ള ദൂരം) അവനിലേക്കടുക്കും. അവൻ എന്റെയടുത്തേക്ക് നടന്നു വന്നാൽ ഞാൻ അവന്റെ അടുത്തേക്ക് ഓടിച്ചെല്ലും." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَقُولُ اللَّهُ عَزَّ وَجَلَّ: إِذَا أَرَادَ عَبْدِي أَنْ يَعْمَلَ سَيِّئَةً فَلَا تَكْتُبُوهَا عَلَيْهِ حَتَّى يَعْمَلَهَا، فَإِنْ عَمِلَهَا فَاكْتُبُوهَا بِمِثْلِهَا، وَإِنْ تَرَكَهَا مِنْ أَجْلِي فَاكْتُبُوهَا لَهُ حَسَنَةً. وَإِذَا أَرَادَ أَنْ يَعْمَلَ حَسَنَةً فَلَمْ يَعْمَلْهَا فَاكْتُبُوهَا لَهُ حَسَنَةً، فَإِنْ عَمِلَهَا فَاكْتُبُوهَا لَهُ بِعَشْرِ أَمْثَالِهَا إِلَى سَبْعِ مِائَةٍ". (خ)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു പറയുന്നു: എന്റെ അടിമ ഒരു തിന്മ പ്രവർത്തിക്കാൻ ഉദ്ദേശിച്ചാൽ അവൻ അത് പ്രവർത്തിക്കുംവരെ അവന്റെ പേരിൽ അത് നിങ്ങൾ എഴുതരുത്. പ്രവർത്തിച്ച് കഴിഞ്ഞാൽ ഒരു തിന്മ മാത്രമായി രേഖപ്പെടുത്തുക. എന്നെ ഓർത്ത് അവൻ ആ തിന്മയെ ഉപേക്ഷിച്ചാൽ അത് അവന്റെ പേരിൽ ഒരു നന്മയായി രേഖപ്പെടുത്തുക. ഇനി ഒരു നന്മ ചെയ്യാൻ അവൻ ഉദ്ദേശിക്കുകയും അത് ചെയ്യാതിരിക്കുകയും ചെയ്താൽ അത് അവന്റെ പേരിൽ ഒരു നന്മയായി രേഖപ്പെടുത്തുക. അതവൻ പ്രവർത്തിച്ചാൽ പത്തു മുതൽ എഴുന്നൂറ് വരെ ഇരട്ടിയായി അത് അവന്റെ പേരിൽ രേഖപ്പെടുത്തുക." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 827, 827, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِنَّ عَبْدًا أَصَابَ ذَنْبًا، وَرُبَّمَا قَالَ: أَذْنَبَ ذَنْبًا، فَقَالَ: رَبِّ أَذْنَبْتُ، وَرُبَّمَا قَالَ: أَصَبْتُ فَاغْفِرْ، فَقَالَ رَبُّهُ: أَعَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِه، غَفَرْتُ لِعَبْدِي، ثُمَّ مَكَثَ مَا شَاءَ اللَّهُ، ثُمَّ أَصَابَ ذَنْبًا أَوْ أَذْنَبَ ذَنْبًا، فَقَالَ: رَبِّ، أَذْنَبْتُ أَوْ أَصَبْتُ آخَرَ فَاغْفِرْهُ، فَقَالَ: أَعَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا يَغْفِرُ الذَّنْبَ وَيَأْخُذُ بِه، غَفَرْتُ لِعَبْدِي، ثُمَّ مَكَثَ مَا شَاءَ اللَّهُ، ثُمَّ أَذْنَبَ ذَنْبًا، وَرُبَّمَا قَالَ: أَصَابَ ذَنْبًا، فَقَالَ: رَبِّ أَصَبْتُ، أَوْ قَالَ: أَذْنَبْتُ آخَرَ فَاغْفِرْهُ لِي، فَقَالَ: أَعَلِمَ عَبْدِي أَنَّ لَهُ رَبًّا، يَغْفِرُ الذَّنْبَ، وَيَأْخُذُ بِه، غَفَرْتُ لِعَبْدِي ثَلَاثًا، فَلْيَعْمَلْ مَا شَاءَ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "നിശ്ചയം ഒരു അടിമ (വ്യക്തി) ഒരു തെറ്റ് ചെയ്തിട്ട് പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, ഞാനൊരു തെറ്റ് ചെയ്തിരിക്കുന്നു. അപ്പോൾ അവന്റെ രക്ഷിതാവ് പറഞ്ഞു: തനിക്ക് പാപങ്ങൾ പൊറുക്കുകയും ശിക്ഷിക്കുകയും ചെയ്യുന്ന ഒരു രക്ഷിതാവുണ്ടെന്ന് എന്റെ അടിമ മനസ്സിലാക്കിയിട്ടുണ്ടോ? എന്റെ അടിമക്ക് ഞാനിതാ പൊറുത്തു കൊടുത്തിരിക്കുന്നു. ശേഷം കുറേകാലം കഴിഞ്ഞു. വീണ്ടും അവനൊരു തെറ്റ് ചെയ്തു. അവൻ പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, ഞാൻ മറ്റൊരു തെറ്റുകൂടി ചെയ്തിരിക്കുന്നു, എനിക്ക് നീയതു പൊറുത്തു തന്നാലും. അല്ലാഹു പറയും: പാപം പൊറുക്കുകയും ശിക്ഷിക്കുകയും ചെയ്യുന്ന ഒരു രക്ഷിതാവ് തനിക്ക് ഉണ്ടെന്ന് എന്റെ അടിമ മനസ്സിലാക്കിയിട്ടുണ്ടോ, ഞാൻ അവന് പൊറുത്തുകൊടുത്തിരിക്കുന്നു. വീണ്ടും കുറേകാലം കഴിഞ്ഞു. അവൻ വേറെ തെറ്റുകൂടി ചെയ്തു. അവൻ പറഞ്ഞു: എന്റെ രക്ഷിതാവേ, ഞാൻ മറ്റൊരു തെറ്റുകൂടി ചെയ്തിരിക്കുന്നു. എനിക്ക് നീയതു പൊറുത്തുതന്നാലും. രക്ഷിതാവ് പറയും: പാപങ്ങൾ പൊറുക്കുകയും ശിക്ഷിക്കുകയും ചെയ്യുന്ന ഒരു രക്ഷിതാവ് തനിക്കുണ്ട് എന്ന് എന്റെ അടിമ മനസ്സിലാക്കിയിട്ടുണ്ടോ, എന്റെ അടിമക്ക് ഞാൻ മൂന്നു പ്രാവശ്യം പൊറുത്തുകൊടുത്തിരിക്കുന്നു. അതിനാൽ താനുദ്ദേശിച്ച പ്രകാരം അവൻ പ്രവർത്തിച്ചുകൊള്ളട്ടെ." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 827, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا كَانَ يَوْمُ الْقِيَامَةِ شُفِّعْتُ، فَقُلْتُ: يَا رَبِّ، أَدْخل الْجَنَّةَ مَنْ كَانَ فِي قَلْبه خَرْدَلَةٌ، فَيَدْخُلُونَ. ثُمَّ أَقُولُ: أَدْخِلِ الْجَنَّةَ مَنْ كَانَ فِي قَلْبه أَدْنَى شَيْءٍ، فَقَالَ أَنَسٌ: كَأَنِّي أَنْظُرُ إِلَى أَصَابِعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (خ)', 'അനസ്(റ): നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അന്ത്യനാളിൽ എനിക്ക് ശിപാർശക്ക് അനുവാദം ലഭിക്കും അപ്പോൾ ഞാൻ പറയും: എന്റെ രക്ഷിതാവേ, ഒരു കടുക് മണിയോളമെങ്കിലും സത്യവിശ്വാസം ഹൃദയത്തിലുള്ളവനെ നീ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കേണമേ. അങ്ങനെ അവരെല്ലാം സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കും. ശേഷം ഞാൻ പറയും: ഏറ്റവും കുറഞ്ഞ തോതിൽ (സത്യവിശ്വാസം) ഹൃദയത്തിൽ ഉള്ളവരെയെല്ലാം നീ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കേണമേ." അനസ്(റ) പറയുന്നു: അങ്ങനെ പറഞ്ഞ സമയത്ത് നബി(സ) കൈകൊണ്ട് ആംഗ്യംകാണിച്ച കാഴ്ച ഞാനിപ്പോഴും കാണുന്നതു പോലെയുണ്ട്. (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 828, 828, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ ذِكْرُ حَدِيث الشَّفَاعَة، وَقَدْ تَقَدَّمَ مُطَوَّلًا مِنْ رِوَايَةِ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، وَزَادَ هُنَا فِي آخِره: فَيَأْتُونَ عِيسَى فَيَقُولُ: لَسْتُ لَهَا، وَلَكِنْ عَلَيْكُمْ بِمُحَمَّد صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَأْتُونِي، فَأَقُولُ: أَنَا لَهَا، فَأَسْتَأْذِنُ عَلَى رَبِّي فَيُؤْذَنُ لِي، وَيُلْهِمُنِي مَحَامِدَ أَحْمَدُهُ بِهَا، لَا تَحْضُرُنِي الْآنَ، فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِد وَأَخِرُّ لَهُ سَاجِدًا، فَيَقُولُ: يَا مُحَمَّدُ، ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ لَكَ، وَسَلْ تُعْطَ، وَاشْفَعْ تُشَفَّعْ، فَأَقُولُ: يَا رَبِّ، أُمَّتِي، أُمَّتِي. فَيَقُولُ: انْطَلِقْ، فَأَخْرِجْ مِنْهَا مَنْ كَانَ فِي قَلْبه مِثْقَالُ شَعِيرَةٍ مِنْ إِيمَانٍ، فَأَنْطَلِقُ فَأَفْعَلُ، ثُمَّ أَعُودُ فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ، ثُمَّ أَخِرُّ لَهُ سَاجِدًا، فَيُقَالُ: يَا مُحَمَّدُ، ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ لَكَ، وَسَلْ تُعْطَ، وَاشْفَعْ تُشَفَّعْ، فَأَقُولُ: يَا رَبِّ، أُمَّتِي، أُمَّتِي. فَيَقُولُ: انْطَلِقْ، فَأَخْرِجْ مِنْهَا مَنْ كَانَ فِي قَلْبِهِ مِثْقَالُ ذَرَّةٍ أَوْ خَرْدَلَةٍ مِنْ إِيمَانٍ، فَأَنْطَلِقُ فَأَفْعَلُ، ثُمَّ أَعُودُ فَأَحْمَدُهُ بِتِلْكَ الْمَحَامِدِ، ثُمَّ أَخِرُّ لَهُ سَاجِدًا، فَيَقُولُ: يَا مُحَمَّدُ، ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ لَكَ، وَسَلْ تُعْطَ، وَاشْفَعْ تُشَفَّعْ، فَأَقُولُ: يَا رَبِّ، أُمَّتِي، أُمَّتِي. فَيَقُولُ: انْطَلِقْ، فَأَخْرِجْ مَنْ كَانَ فِي قَلْبِهِ أَدْنَى أَدْنَى أَدْنَى مِثْقَالِ حَبَّةِ خَرْدَلٍ مِنْ إِيمَانٍ، فَأَخْرِجْهُ مِنَ النَّارِ، فَأَنْطَلِقُ فَأَفْعَلُ". (خ)', 'അനസ്(റ): അദ്ദേഹം ശഫാഅത്തിനെ സംബന്ധിച്ചുള്ള ഹദീസ് റിപ്പോർട്ട് ചെയ്യുന്നു. അബൂഹുറൈറ(റ)വിന്റെ രിവായതിൽ വിസ്തൃത രൂപത്തിൽ അത് മുമ്പ് വന്നിട്ടുണ്ട്. ഈ രിവായത്തിന്റെ അവസാനത്തിൽ ഇതുകൂടി പറഞ്ഞിട്ടുണ്ട്: "അപ്പോൾ അവർ ഈസാ(അ)മിന്റെ അടുക്കൽ ചെല്ലും. ഈസാ(അ) പറയും: ഞാനതിന് അർഹനല്ല. നിങ്ങൾ മുഹമ്മദ്(സ)യുടെ അടുത്ത് ചെല്ലുക. അപ്പോൾ അവർ എന്റെ അടുത്ത് വരും. ഞാൻ പറയും: ഞാനതിന് അർഹനായ ആൾ തന്നെയാണ്. തുടർന്ന് ഞാൻ എന്റെ രക്ഷിതാവിനോട് (ശിപാർശക്കു വേണ്ടി) അനുവാദം ചോദിക്കുകയും എനിക്ക് സമ്മതം ലഭിക്കുകയും ചെയ്യും. ഞാൻ അല്ലാഹുവിനെ സ്തുതിക്കാനുള്ള വാക്കുകൾ അവൻ എനിക്ക് തോന്നിപ്പിച്ചു തരും. ആ വാക്കുകൾ എനിക്കിപ്പോൾ ഓർമ്മ വരുന്നില്ല. ആ വാക്കുകളിൽ ഞാൻ. അവനെ സ്തുതിക്കുകയും ശേഷം അവന്റെ മുന്നിൽ സുജൂദിൽ വീഴുകയും ചെയ്യും. അപ്പോൾ അവൻ പറയും: മുഹമ്മദേ, അങ്ങ് തലയുയർത്തി വേണ്ടത് ആവശ്യപ്പെടുക, അങ്ങയുടെ വാക്ക് സ്വീകരിക്കപ്പെടും. ചോദിച്ചുകൊള്ളുക, അങ്ങേയ്ക്ക് വേണ്ടത് നൽകപ്പെടും. ശിപാർശ ചെയ്യുക, അങ്ങയുടെ ശിപാർശ സ്വീകരിക്കപ്പെടും. ഞാൻ പറയും: രക്ഷിതാവേ, എന്റെ സമുദായത്തിന്റെ കാര്യം, എന്റെ സമുദായത്തിന്റെ കാര്യം! അന്നേരം അവൻ പറയും: അങ്ങു പോയി ഹൃദയത്തിൽ ഒരു ബാർളി മണിയുടെ അത്രയെങ്കിലും സത്യവിശ്വാസമുള്ളവരെ നരകത്തിൽ നിന്ന് മോചിപ്പിക്കുക. ഞാൻ പോയി അങ്ങനെ ചെയ്യും. ശേഷം തിരിച്ചുവന്ന് ആ സ്തുതി വാക്കുകൾകൊണ്ട് അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവന്റെ മുന്നിൽ സുജൂദിൽ വീഴുകയും ചെയ്യും. അപ്പോൾ ഇപ്രകാരം പറയപ്പെടും: മുഹമ്മദേ, അങ്ങ് തലയുയർത്തി വേണ്ടത് ആവശ്യപ്പെടുക, അങ്ങയുടെ വാക്ക് സ്വീകരിക്കപ്പെടും. ചോദിച്ചുകൊൾക, അങ്ങേയ്ക്ക് നൽകപ്പെടും. ശിപാർശ ചെയ്യുക, അങ്ങയുടെ ശിപാർശ സ്വീകരിക്കപ്പെടും. ഞാൻ പറയും: രക്ഷിതാവേ, എന്റെ സമുദായത്തിന്റെ കാര്യം, എന്റെ സമുദായത്തിന്റെ കാര്യം! അന്നേരം അവൻ പറയും: അങ്ങുപോയി ഹൃദയത്തിൽ ഒരു അണുവോളം എങ്കിലും സത്യവിശ്വാസമുള്ളവരെ നരകത്തിൽനിന്ന് മോചിപ്പിക്കുക. ഞാൻ പോയി അപ്രകാരം ചെയ്യും. ശേഷം തിരിച്ചു വന്ന് ആ സതുതിവാക്കുകൾ കൊണ്ട് അല്ലാഹുവിനെ സ്തുതിക്കുകയും അവനു മുന്നിൽ ഞാൻ സുജൂദിൽ വീഴുകയും ചെയ്യും. അപ്പോൾ അവൻ പറയും: മുഹമ്മദേ, അങ്ങ് തലയുയർത്തി വേണ്ടത് ആവശ്യപ്പെടുക. അങ്ങയുടെ വാക്ക് സ്വീകരിക്കപ്പെടും. ചോദിച്ചുകൊള്ളുക, വേണ്ടത് നൽകപ്പെടും. ശിപാർശ ചെയ്യുക, അങ്ങയുടെ ശിപാർശ സ്വീകരിക്കപ്പെടും. ഞാൻ പറയും: രക്ഷിതാവേ, എന്റെ സമുദായത്തിന്റെ കാര്യം, എന്റെ സമുദായത്തിന്റെ കാര്യം! അപ്പോൾ അവൻ പറയും: അങ്ങുപോയി ഒരു കടുക് മണിയേക്കാൾ വളരെ വളരെ വളരെ കുറവായ സത്യവിശ്വാസം ഹൃദയത്തിലുള്ളവരെയെല്ലാം നരകത്തിൽ നിന്ന് മോചിപ്പിക്കുക. അങ്ങനെ ഞാൻ പോയി അപ്രകാരം ചെയ്യും." (ബു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 828, 829, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'وَفي رِوَايَةٍ عَنْهُ: "ثُمَّ أَعُودُ الرَّابعَةَ فَأَحْمَدُهُ بتلْكَ الْمَحَامد، ثُمَّ أَخرُّ لَهُ سَاجدًا، فَيُقَالُ: يَا مُحَمَّدُ، ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ، وَسَلْ تُعْطَهْ، وَاشْفَعْ تُشَفَّعْ. فَأَقُولُ: يَا رَبِّ، ائْذَنْ لي فيمَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، فَيَقُولُ: وَعزَّتي وَجَلَالي وَكِبْرِيَائي وَعَظَمَتي، لَأُخْرِجَنَّ منْهَا مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ". (خ)', 'അനസ്(റ)വിൽനിന്ന് തന്നെയുള്ള മറ്റൊരു നിവേദനത്തിൽ പറയുന്നു: "ശേഷം ഞാൻ നാലാം പ്രാവശ്യവും മടങ്ങിച്ചെന്ന് ആ സ്തുതി വാക്കുകൾകൊണ്ട് അല്ലാഹുവിനെ സ്തുതിക്കുകയും തുടർന്ന് അവനു മുന്നിൽ സുജൂദിൽ വീഴുകയും ചെയ്യും. അപ്പോൾ ഇപ്രകാരം പറയപ്പെടും: മുഹമ്മദേ, അങ്ങ് തലയുയർത്തി വേണ്ടത് ആവശ്യപ്പെടുക. അങ്ങയുടെ വാക്ക് സ്വീകരിക്കപ്പെടും. ചോദിക്കുക, വേണ്ടത് നൽകപ്പെടും. ശിപാർശ ചെയ്യുക, അങ്ങയുടെ ശിപാർശ സ്വീകരിക്കപ്പെടും. ഞാൻ പറയും: രക്ഷിതാവേ, ലാഇലാഹഇല്ലല്ലാഹു (അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല) എന്ന് പറഞ്ഞവരെയെല്ലാം നരകത്തിൽ നിന്ന് മോചിപ്പിക്കാൻ എനിക്ക് അനുവാദം നൽകുക. അല്ലാഹു പറയും: എന്റെ പ്രതാപത്തെയും മഹത്വത്തെയും യശസ്സിനെയും തന്നെ സത്യം, അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല എന്ന് പറഞ്ഞവരെയെല്ലാം ഞാൻ അതിൽനിന്ന് മോചിപ്പിക്കുക തന്നെചെയ്യും." (ബു)', null, 'അനസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 829, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=177), 1, 'وَفِي رِوَايَةٍ عَنْهُ: "ثُمَّ أَعُودُ الرَّابعَةَ فَأَحْمَدُهُ بتلْكَ الْمَحَامد، ثُمَّ أَخرُّ لَهُ سَاجدًا، فَيُقَالُ: يَا مُحَمَّدُ، ارْفَعْ رَأْسَكَ، وَقُلْ يُسْمَعْ، وَسَلْ تُعْطَهْ، وَاشْفَعْ تُشَفَّعْ. فَأَقُولُ: يَا رَبِّ، ائْذَنْ لي فيمَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ، فَيَقُولُ: وَعزَّتي وَجَلَالي وَكِبْرِيَائي وَعَظَمَتي، لَأُخْرِجَنَّ منْهَا مَنْ قَالَ: لَا إِلَهَ إِلَّا اللَّهُ". (خ)', 'മറ്റൊരു നിവേദനത്തിൽ പറയുന്നു: "ശേഷം ഞാൻ നാലാം പ്രാവശ്യവും മടങ്ങിച്ചെന്ന് ആ സ്തുതി വാക്കുകൾകൊണ്ട് അല്ലാഹുവിനെ സ്തുതിക്കുകയും തുടർന്ന് അവനു മുന്നിൽ സുജൂദിൽ വീഴുകയും ചെയ്യും. അപ്പോൾ ഇപ്രകാരം പറയപ്പെടും: മുഹമ്മദേ, അങ്ങ് തലയുയർത്തി വേണ്ടത് ആവശ്യപ്പെടുക. അങ്ങയുടെ വാക്ക് സ്വീകരിക്കപ്പെടും. ചോദിക്കുക, വേണ്ടത് നൽകപ്പെടും. ശിപാർശ ചെയ്യുക, അങ്ങയുടെ ശിപാർശ സ്വീകരിക്കപ്പെടും. ഞാൻ പറയും: രക്ഷിതാവേ, ലാഇലാഹഇല്ലല്ലാഹു (അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല) എന്ന് പറഞ്ഞവരെയെല്ലാം നരകത്തിൽ നിന്ന് മോചിപ്പിക്കാൻ എനിക്ക് അനുവാദം നൽകുക. അല്ലാഹു പറയും: എന്റെ പ്രതാപത്തെയും മഹത്വത്തെയും യശസ്സിനെയും തന്നെ സത്യം, അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ല എന്ന് പറഞ്ഞവരെയെല്ലാം ഞാൻ അതിൽനിന്ന് മോചിപ്പിക്കുക തന്നെചെയ്യും." (ബു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنْ أَبي هُرَيْرَةَ رَضيَ اللَّهُ عَنْهُ قَال: قَال النَّبيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "كَلمَتَان حَبيبَتَان إِلَى الرَّحْمَنِ، خَفيفَتَان عَلَى اللِّسَان، ثَقيلَتَان في الْميزَان، سُبْحَانَ اللَّه وَبحَمْده، سُبْحَانَ اللَّه الْعَظيم". (خ)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "രണ്ടു വാക്യങ്ങൾ അല്ലാഹുവിന് വളരെ ഇഷ്ടപ്പെടുന്നതാണ്, അവ നാവുകൊണ്ട് ഉച്ചരിക്കാൻ വളരെ ലഘുവാണ്. (പക്ഷേ,) തുലാസിൽ വളരെ കനം തൂങ്ങുന്നവയാണ്. സുബ്ഹാനല്ലാഹി വബിഹംദിഹി (അല്ലാഹുവിനെ സ്തുതിക്കുന്നതോടൊപ്പം അവന്റെ പരിശുദ്ധതയെ ഞാനിതാ വാഴ്തുന്നു), സുബ്ഹാനല്ലാഹിൽ അളീം (മഹത്വമുള്ളവനായ അല്ലാഹുവിന്റെ പരിശുദ്ധതയെ ഞാനിതാ വാഴ്തുന്നു) എന്നീ വാക്യങ്ങളാണവ." (ബു)', 'أَبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ أَبي هُرَيْرَةَ رَضيَ اللَّهُ عَنْهُ قَالَ: جَاءَ مُشْركُو قُرَيْشٍ يُخَاصمُونَ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ في الْقَدْرِ، فَنَزَلَتْ: {يَوْمَ يُسْحَبُونَ في النَّارِ عَلَى وُجُوههِمْ ذُوقُوا مَسَّ سَقَرَ إِنَّا كُلَّ شَيْءٍ خَلَقْنَاهُ بِقَدَرٍ} [القمر: ٤٨, ٤٩]. (م,ت,جه)', 'അബൂഹുറൈറ(റ): ഖദ്‌രി(ദൈവവിധി)ന്റെ വിഷയത്തിൽ റസൂൽ(സ)യോട് തർക്കത്തിലേർപ്പെടാൻ വേണ്ടി ഖുറൈശികളിലെ ബഹുദൈവവിശ്വാസികൾ വന്നു. അപ്പോൾ ഈ സൂക്തം അവതരിച്ചു: ''മുഖം നിലത്ത് കുത്തിയ നിലയിൽ അവർ നരാകാഗ്നിയിൽ വലിച്ചിഴക്കപ്പെടുന്ന ദിവസം (അവരോട് പറയപ്പെടും): നിങ്ങൾ നരകത്തിന്റെ സ്പർശനം അനുഭവിച്ചുകൊള്ളുക. തീർച്ചയായും ഏതു വസ്തുവിനെയും പ്രത്യേക വ്യവസ്ഥ പ്രകാരമാണ് നാം സൃഷ്ടിച്ചിട്ടുള്ളത്'' (അൽഖഹ്ഫ്: 48, 49). (മു,തു,ജ)', 'أَبي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], 'القمر: ٤٨, ٤٩', null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنْ عَبْد اللَّه بْنِ عَمْرٍو رَضيَ اللَّهُ عَنْهُمَا قَالَ: سَمعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "قَدَّرَ اللَّهُ الْمَقَاديرَ قَبْلَ أَنْ يَخْلُقَ السَّمَاوَات وَالْأَرْضَ بخَمْسينَ أَلْفَ سَنَةٍ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആകാശങ്ങളെയും ഭൂമിയെയും സൃഷ്ടിക്കുന്നതിന് അമ്പതിനായിരും വർഷംമുമ്പ് അല്ലാഹു സർവ്വ കാര്യങ്ങളെയും നിശ്ചയിച്ചുവെച്ചു." (തു)', 'عَبْد اللَّه بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ عَبْد اللَّه بْنِ عَمْرِو بْنِ الْعَاصِ رَضيَ اللَّهُ عَنْهُمَا قَالَ: سَمعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "كَتَبَ اللَّهُ مَقَاديرَ الْخَلَائق قَبْلَ أَنْ يَخْلُقَ السَّمَاوَاتِ وَالْأَرْضَ بخَمْسينَ أَلْفَ سَنَةٍ، قَالَ: وَعَرْشُهُ عَلَى الْمَاءِ". (م)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ആകാശങ്ങളെയും ഭൂമിയെയും സൃഷ്ടിക്കുന്നതിനു അമ്പതിനായിരം വർഷം മുമ്പ് അല്ലാഹു സൃഷ്ടികളുടെ കാര്യങ്ങളെല്ലാം കണക്കാക്കി വെച്ചു." റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവിന്റെ അർശ് വെള്ളത്തിനു മുകളിലാണ്." (മു)', 'عَبْد اللَّه بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 830, 830, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ طَاوُسٍ أَنَّهُ قَالَ: أَدْرَكْتُ نَاسًا منْ أَصْحَاب رَسُول اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُونَ: كُلُّ شَيْءٍ بقَدَرٍ. قَالَ: وَسَمعْتُ عَبْدَ اللَّه بْنَ عُمَرَ رَضيَ اللَّهُ عَنْهُمَا يَقُولُ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "كُلُّ شَيْءٍ بقَدَرٍ، حَتَّى الْعَجْزُ وَالْكَيْسُ". أَو: "الْكَيْسُ وَالْعَجْزُ". (م)', 'താഊസ്(റ): റസൂൽ(സ)യുടെ അനുചരരിൽ കുറേയാളുകൾ ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: എല്ലാം മുന്നെ നിശ്ചയിച്ചതു പ്രകാരമാണ്. അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) പറയുന്നത് ഞാൻ കേട്ടു: റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ കാര്യങ്ങളും മുൻനിശ്ചയപ്രകാരമാണ്. അശക്തതയും കഴിവുംപോലും അപ്രകാരമാണ്." അല്ലെങ്കിൽ: "കഴിവും അശക്തതയുംപോലും." (മു)', 'طَاوُسٍ أَنَّهُ قَالَ', 'താഊസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 830, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ عَبْد الله عَمْرو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ عَلَى أَصْحَابه وَهُمْ يَخْتَصِمُونَ فِي الْقَدَرِ، فَكَأَنَّمَا يُفْقَأُ فِي وَجْهه حَبُّ الرُّمَّان مِنَ الْغَضَب، فَقَالَ: "بِهَذَا أُمِرْتُمْ أَوْ لِهَذَا خُلِقْتُمْ؟ تَضْرِبُونَ الْقُرْآنَ بَعْضَهُ بِبَعْضٍ، بِهَذَا هَلَكَت الْأُمَمُ قَبْلَكُمْ".
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ وَنَحْنُ نَتَنَازَعُ فِي الْقَدَرِ، فَغَضبَ حَتَّى احْمَرَّ وَجْهُهُ، حَتَّى كَأَنَّمَا فُقِئَ فِي وَجْنَتَيْه الرُّمَّانُ، فَقَالَ: "أَبِهَذَا أُمِرْتُمْ أَمْ بِهَذَا أُرْسِلْتُ إِلَيْكُمْ؟ إِنَّمَا هَلَكَ مَنْ كَانَ قَبْلَكُمْ حِينَ تَنَازَعُوا فِي هَذَا الْأَمْرِ، عَزَمْتُ عَلَيْكُمْ أَلَّا تَتَنَازَعُوا فِيه". (ت)', 'അബൂഹുറൈറ(റ): ഖദ്‌റിനെക്കുറിച്ച് തർക്കിച്ചു കൊണ്ടിരിക്കുമ്പോൾ റസൂൽ(സ) ഞങ്ങളുടെ അടുത്ത് വന്നു. ദേഷ്യം കാരണത്താൽ റുമ്മാൻ പഴത്തിന്റെ കുരു പൊട്ടിച്ചതു പോലെ അവിടുത്തെ മുഖം ചുവന്നിരുന്നു. അവിടുന്ന് പറഞ്ഞു: "ഇതു ചെയ്യാനാണോ നിങ്ങളോട് കൽപിക്കപ്പെട്ടത്, ഇതിനു വേണ്ടിയാണോ ഞാൻ നിങ്ങളിലേക്ക് നിയോഗിക്കപ്പെട്ടത്? ഇക്കാര്യത്തിൽ തർക്കിച്ചപ്പോഴാണ് നിങ്ങളുടെ മുമ്പുള്ളവർ നശിച്ചത്. ഈ വിഷയത്തിൽ തർക്കിക്കരുതെന്ന് ഞാൻ നിങ്ങളോട് തീർത്ത് പറയുന്നു." (തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 831, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "الْمُؤْمِنُ الْقَوِيُّ خَيْرٌ وَأَحَبُّ إِلَى اللَّه مِنَ الْمُؤْمِنِ الضَّعِيف، وَفِي كُلٍّ خَيْرٌ. احْرِصْ عَلَى مَا يَنْفَعُكَ، وَاسْتَعِنْ بِاللَّه وَلَا تَعْجَزْ، فَإِنْ أَصَابَكَ شَيْءٌ فَلَا تَقُلْ: لَوْ أَنِّي فَعَلْتُ كَذَا وَكَذَا، وَلَكِنْ قُلْ: قَدَّرَ اللَّهُ، وَمَا شَاءَ فَعَلَ. فَإِنَّ لَوْ تَفْتَحُ عَمَلَ الشَّيْطَانِ". (م,جه)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ശക്തനായ സത്യവിശ്വാസി ബലഹീനനായ സത്യവിശ്വാസിയേക്കാൾ ഉത്തമനും അല്ലാഹുവിന് ഇഷ്ടപ്പെട്ടവനുമാണ്. എല്ലാ കാര്യത്തിലും നന്മയുണ്ട്. തനിക്ക് ഉപകാരപ്പെടുന്നവയെ നീ ആഗ്രഹിക്കുകയും അല്ലാഹുവിനോട് സഹായമഭ്യർത്ഥിക്കുകയും ചെയ്യുക. നീ അശക്തത കാണിക്കരുത്. വല്ലതും പറ്റിയാൽ, ഞാൻ അപ്രകാരം ചെയ്തിരുന്നെങ്കിൽ എന്ന് പറയരുത്. അല്ലാഹു നിശ്ചയിച്ച കാര്യമാണത്, അവൻ ഉദ്ദേശിക്കുന്നത് അവൻ പ്രവർത്തിക്കും എന്നു മാത്രം പറയുക. ''അങ്ങനെ ചെയ്തിരുന്നെങ്കിൽ'' എന്ന വാക്ക് പിശാചിന്റെ പ്രവർത്തനത്തെ തുറക്കുന്നതാണ്." (മു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 831, 831, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللَّهُ عَنْهُ قَالَ لِابْنِه: يَا بُنَيَّ، إِنَّكَ لَنْ تَجِدَ طَعْمَ حَقِيقَةِ الْإِيمَانِ حَتَّى تَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ الْقَلَمَ، فَقَالَ لَهُ: اكْتُبْ، قَالَ: رَبِّ، وَمَاذَا أَكْتُبُ؟ قَالَ: اكْتُبْ مَقَادِيرَ كُلِّ شَيْءٍ حَتَّى تَقُومَ السَّاعَةُ". يَا بُنَيَّ، إِنِّي سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "مَنْ مَاتَ عَلَى غَيْرِ هَذَا فَلَيْسَ مِنِّي". (د)', 'ഉബാദതുബ്നു സ്വാമിത്(റ): അദ്ദേഹം തന്റെ പുത്രനോട് പറഞ്ഞു: എന്റെ കുഞ്ഞുമകനേ, നിനക്ക് വന്ന കാര്യങ്ങളെല്ലാം നിന്നിൽനിന്ന് അകന്നു പോകാൻ പറ്റാത്തവയും നിന്നിൽ നിന്ന് അകന്നു പോയവയെല്ലാം നിനക്ക് സംഭവിക്കാൻ പറ്റാത്തവയുമാണ് എന്ന് മനസ്സിലാക്കുംവരെ നിനക്ക് ഈമാനിന്റെ യാഥാർത്ഥ്യം രുചിച്ചറിയാൻ കഴിയില്ല. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു ആദ്യമായി സൃഷ്ടിച്ചത് ഖലമിനെ(പേന)യാണ്. അല്ലാഹു അതിനോട് പറഞ്ഞു: നീ എഴുതുക. ഖലം ചോദിച്ചു: രക്ഷിതാവേ, ഞാൻ എന്താണ് എഴുതേണ്ടത്? അല്ലാഹു പറഞ്ഞു: അന്ത്യനാൾവരെ ഉണ്ടാകുന്ന സർവ്വ വസ്തുക്കളുടെയും കണക്കുകൾ നീ എഴുതുക." എന്റെ കുഞ്ഞുമകനേ, റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഈ വിശ്വാസത്തിലല്ലാതെ മരിച്ചവൻ എന്നിൽ പെട്ടവനല്ല." (ദ)', 'عُبَادَةَ بْنِ الصَّامِتِ', 'ഉബാദതുബ്നു സ്വാമിത്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 831, 832, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ جَابِرِ بْنِ عَبْد اللَّه رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "لَا يُؤْمِنُ عَبْدٌ حَتَّى يُؤْمِنَ بِالْقَدَرِ خَيْرِه وَشَرِّه، حَتَّى يَعْلَمَ أَنَّ مَا أَصَابَهُ لَمْ يَكُنْ لِيُخْطِئَهُ، وَأَنَّ مَا أَخْطَأَهُ لَمْ يَكُنْ لِيُصِيبَهُ". (ت)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "നന്മ തിന്മകളടങ്ങുന്ന ഖദ്‌റിൽ വിശ്വസിക്കുംവരെയും, തനിക്ക് സംഭവിച്ച കാര്യം തന്നിൽനിന്ന് അകന്നു പോകാൻ പറ്റാത്തതും തന്നിൽ നിന്ന് അകന്നു പോയ കാര്യം തനിക്ക് സംഭവിക്കാൻ പറ്റാത്തതുമാണെന്ന് മനസ്സിലാക്കുംവരെയു ഒരു അടിമ സത്യവിശ്വാസിയാവുകയില്ല." (തു)', 'جَابِرِ بْنِ عَبْد اللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 832, 832, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "لَا يُؤْمِنُ عَبْدٌ حَتَّى يُؤْمِنَ بِأَرْبَعِ: يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي مُحَمَّدٌ رَسُولُ اللَّه، بَعَثَنِي بِالْحَقِّ، وَيُؤْمِنُ بِالْمَوْتِ، وَبِالْبَعْثِ بَعْدَ الْمَوْتِ، وَيُؤْمِنُ بِالْقَدَرِ". (ت,جه)', 'അലി(റ): റസൂൽ(സ) പറഞ്ഞു: "നാല് കാര്യങ്ങളിൽ വിശ്വസിക്കുംവരെ ഒരു അടിമയും സത്യവിശ്വാസി ആവുകയില്ല: അല്ലാഹുവല്ലാത്ത ആരാധ്യനില്ലെന്നും അവൻ സത്യവുമായി നിയോഗിച്ച അവന്റെ റസൂലായ മുഹമ്മദാണ് ഞാനെന്നും സാക്ഷ്യം വഹിക്കൽ, മരണത്തിൽ വിശ്വസിക്കൽ, മരണത്തിനു ശേഷമുള്ള പുനർജന്മത്തിൽ വിശ്വസിക്കൽ, ഖദ്‌റിൽ വിശ്വസിക്കൽ എന്നിവയാണവ." (തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 832, 832, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، عَنْ عُمَرَ بْنِ الْخَطَّابِ – رَضِيَ اللَّهُ عَنْهُمَا – قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ طَلَعَ عَلَيْنَا رَجُلٌ، شَدِيدُ بَيَاضِ الثِّيَابِ، شَدِيدُ سَوَادِ الشَّعْرِ لَا يُرَى عَلَيْهِ أَثَرُ السَّفَرِ، وَلَا نَعْرِفُهُ، حَتَّى جَلَسَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَسْنَدَ رُكْبَتَيْهِ إِلَى رُكْبَتَيْهِ، وَوَضَعَ كَفَّيْهِ عَلَى فَخِذَيْهِ، وَقَالَ: يَا مُحَمَّدُ، أَخْبِرْنِي عَنِ الْإِسْلَامِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْإِسْلَامُ: أَنْ تَشْهَدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَتُقِيمَ الصَّلَاةَ، وَتُؤْتِيَ الزَّكَاةَ، وَتَصُومَ رَمَضَانَ، وَتَحُجَّ الْبَيْتَ إِنِ اسْتَطَعْتَ إِلَيْهِ سَبِيلًا". قَالَ: صَدَقْتَ، قَالَ: فَعَجِبْنَا لَهُ يَسْأَلُهُ وَيُصَدِّقُهُ، قَالَ: فَأَخْبِرْنِي عَنِ الْإِيمَانِ، قَالَ: "أَنْ تُؤْمِنَ بِاللَّهِ، وَمَلَائِكَتِهِ، وَكُتُبِهِ، وَرُسُلِهِ، وَالْيَوْمِ الْآخِرِ، وَتُؤْمِنَ بِالْقَدَرِ خَيْرِهِ وَشَرِّهِ". قَالَ: صَدَقْتَ، قَالَ: فَأَخْبِرْنِي عَنِ الْإِحْسَانِ، قَالَ: "أَنْ تَعْبُدَ اللَّهَ كَأَنَّكَ تَرَاهُ، فَإِنْ لَمْ تَكُنْ تَرَاهُ فَإِنَّهُ يَرَاكَ". قَالَ: فَأَخْبِرْنِي عَنِ السَّاعَةِ، قَالَ: "مَا الْمَسْئُولُ عَنْهَا بِأَعْلَمَ مِنَ السَّائِلِ". قَالَ: فَأَخْبِرْنِي عَنْ أَمَارَاتِهَا، قَالَ: "أَنْ تَلِدَ الْأَمَةُ رَبَّتَهَا، وَأَنْ تَرَى الْحُفَاةَ الْعُرَاةَ الْعَالَةَ رِعَاءَ الشَّاءِ يَتَطَاوَلُونَ فِي الْبُنْيَانِ". قَالَ: ثُمَّ انْطَلَقَ، فَلَبِثْتُ ثَلَاثًا. ثُمَّ قَالَ: "يَا عُمَرُ، هَلْ تَدْرِي مَنِ السَّائِلُ؟" قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: "فَإِنَّهُ جِبْرِيلُ، أَتَاكُمْ يُعَلِّمُكُمْ دِينَكُمْ". وَفِي رِوَايَةِ زَادَ: قَالَ: وَسَأَلَهُ رَجُلٌ مِنْ مُزَيْنَةَ، أَوْ جُهَيْنَةَ، فَقَالَ: يَا رَسُولَ اللَّهِ، فِيمَا نَعْمَلُ، أَفِي شَيْءٍ قَدْ خَلَا – أَوْ مَضَى – أَوْ فِي شَيْءٍ يُسْتَأْنَفُ الْآنَ؟ قَالَ: "فِي شَيْءٍ قَدْ خَلَا وَمَضَى". فَقَالَ الرَّجُلُ، أَوْ بَعْضُ الْقَوْمِ: فَفِيمَ الْعَمَلُ؟ قَالَ: "إِنَّ أَهْلَ الْجَنَّةِ يُيَسَّرُونَ لِعَمَلِ أَهْلِ الْجَنَّةِ، وَأَهْلَ النَّارِ يُيَسَّرُونَ لِعَمَلِ أَهْلِ النَّارِ".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=189), 1, 'وَفِي رِوَايَةٍ زَادَ: قَالَ: وَسَأَلَهُ رَجُلٌ مِنْ مُزَيْنَةَ، أَوْ جُهَيْنَةَ، فَقَالَ: يَا رَسُولَ اللَّهِ، فِيمَا نَعْمَلُ، أَفِي شَيْءٍ قَدْ خَلَا – أَوْ مَضَى – أَوْ فِي شَيْءٍ يُسْتَأْنَفُ الْآنَ؟ قَالَ: "فِي شَيْءٍ قَدْ خَلَا وَمَضَى". فَقَالَ الرَّجُلُ، أَوْ بَعْضُ الْقَوْمِ: فَفِيمَ الْعَمَلُ؟ قَالَ: "إِنَّ أَهْلَ الْجَنَّةِ يُيَسَّرُونَ لِعَمَلِ أَهْلِ الْجَنَّةِ، وَأَهْلَ النَّارِ يُيَسَّرُونَ لِعَمَلِ أَهْلِ النَّارِ".', 'മറ്റൊരു നിവേദനത്തിൽ ഇപ്രകാരം കൂടിയുണ്ട്. ഉമർ(റ) പറയുന്നു: മുസൈന ഗോത്രത്തിൽപെട്ട, അല്ലെങ്കിൽ ജുഹൈന ഗോത്രത്തിൽപെട്ട ഒരാൾ റസൂൽ(സ)യോട് ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, എന്ത് അടിസ്ഥാനപ്പടുത്തിയാണ് ഞങ്ങൾ കർമ്മം ചെയ്യുന്നത്? കഴിഞ്ഞുപോയ ഒരു കാര്യത്തെ (ദൈവനിശ്ചയത്തെ) അടിസ്ഥാനപ്പെടുത്തിയോ അതോ ഇപ്പോഴും പുതുതായി ഉണ്ടായിക്കൊണ്ടിരിക്കുന്ന കാര്യത്തെ അടിസ്ഥാനപ്പെടുത്തിയോ? റസൂൽ(സ) പറഞ്ഞു: "കഴിഞ്ഞുപോയ കാര്യത്തിന്റെ അടിസ്ഥാനത്തിൽ." അപ്പോൾ ഒരാൾ ചോദിച്ചു: എങ്കിൽ കർമ്മത്തിന്റെ അടിസ്ഥാനമെന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "സ്വർഗ്ഗാവകാശികൾക്ക് സ്വർഗ്ഗാവകാശികളുടേതായ പ്രവർത്തനങ്ങളും നരകാവകാശികൾക്ക് നരകാവകാശികളുടേതായ പ്രവർത്തനങ്ങളും എളുപ്പമാക്കപ്പെടും."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=189), 2, 'وَفِي رِوَايَةٍ: قَالَ: فَمَا الْإِسْلَامُ؟ قَالَ: "إِقَامُ الصَّلَاةِ، وَإِيتَاءُ الزَّكَاةِ، وَحَجُّ الْبَيْتِ، وَصَوْمُ شَهْرِ رَمَضَانَ، وَالِاغْتِسَالُ مِنَ الْجَنَابَةِ". (م,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനം: ആഗതൻ ചോദിച്ചു: ഇസ്ലാം എന്താണ്? റസൂൽ(സ) പറഞ്ഞു: "നിസ്കാരം നിലനിർത്തൽ, സകാത് (നിർബന്ധ ദാനം) നൽകൽ, കഅ്ബത്തിങ്ങൽ ചെന്ന് ഹജ്ജ് ചെയ്യൽ, റമളാൻ മാസം നോമ്പനുഷ്ഠിക്കൽ, വലിയ അശുദ്ധിയുണ്ടായാൽ കുളിക്കൽ എന്നിവയാണത്." (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنْ أَبِي ذَرٍّ وَأَبِي هُرَيْرَةَ – رَضِيَ اللَّهُ عَنْهُمَا – قَالَا: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَجْلِسُ بَيْنَ ظَهْرَيْ أَصْحَابِهِ، فَيَجِيءُ الْغَرِيبُ فَلَا يَدْرِي أَيُّهُمْ هُوَ حَتَّى يَسْأَلَ، فَطَلَبْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نَجْعَلَ لَهُ مَجْلِسًا يَعْرِفُهُ الْغَرِيبُ إِذَا أَتَاهُ، قَالَ: فَبَنَيْنَا لَهُ دُكَّانًا مِنْ طِينٍ، فَجَلَسَ عَلَيْهِ، وَكُنَّا نَجْلِسُ بِجَنْبَتَيْهِ، وَذَكَرَ نَحْوَ هَذَا الْخَبَرِ: فَأَقْبَلَ رَجُلٌ، فَذَكَرَ هَيْئَتَهُ، حَتَّى سَلَّمَ مِنْ طَرَفِ السِّمَاطِ، فَقَالَ: السَّلَامُ عَلَيْكَ يَا مُحَمَّدُ، قَالَ: فَرَدَّ عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. (م,د,ن,جه)', 'അബൂദർറ്(റ), അബൂഹുറൈറ(റ): റസൂൽ(സ) തന്റെ അനുചരരുടെ ഇടയിൽതന്നെ ഇരിക്കുകയാണ് ചെയ്തിരുന്നത്. അപരിചിതർ വന്നാൽ ചോദിച്ചറിയാതെ റസൂൽ(സ)യെ തിരിച്ചറിയാൻ കഴിയാത്ത അവസ്ഥയാണുണ്ടായിരുന്നത്. അപരിചിതർ വന്നാൽ റസൂൽ(സ)യെ മനസ്സിലാക്കാൻ കഴിയുംവിധം അവിടുത്തേക്ക് പ്രത്യേക ഇരിപ്പിടം ഉണ്ടാക്കണമെന്ന് ഞങ്ങൾ റസൂൽ(സ)യോട് ആവശ്യപ്പെട്ടു. നിവേദകൻ പറയുന്നു: അങ്ങനെ നബി(സ)ക്കുവേണ്ടി ഞങ്ങൾ മണ്ണുകൊണ്ടുള്ള ഒരു ഉയർന്ന സ്ഥലമുണ്ടാക്കി. നബി(സ) അതിനു മുകളിലും ഞങ്ങൾ അതിന്റെ ഇരുവശങ്ങളിലുമായാണ് ഇരുന്നിരുന്നത്..... ശേഷം നിവദകൻ മുമ്പുള്ള ഹദീസുപോലെ വിവരിച്ചുകൊണ്ട് പറഞ്ഞു: അങ്ങനെ ഒരാൾ വന്നു, ആഗതന്റെ രൂപം വിശദീകരിച്ച ശേഷം നിവേദകൻ പറഞ്ഞു: ജനങ്ങൾ ഇരിക്കുന്ന ഭാഗത്തുനിന്ന് അദ്ദേഹം ഇപ്രകാരം സലാം ചൊല്ലി: മുഹമ്മദേ, അങ്ങയുടെ മേൽ അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാവട്ടെ. റസൂൽ(സ) അയാളുടെമേൽ സലാം മടക്കി. (മു,ദ,ന,ജ)', 'أَبِي ذَرٍّ وَأَبِي هُرَيْرَةَ –', 'അബൂദർറ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنْ عَدِيٍّ بْنِ حَاتِمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَقَالَ: "يَا عَدِيَّ بْنَ حَاتِمٍ، أَسْلِمْ تَسْلَمْ". قُلْتُ: وَمَا الْإِسْلَامُ؟ فَقَالَ: "تَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي رَسُولُ اللَّه، وَتُؤْمِنُ بِالْأَقْدَارِ كُلِّهَا: لِخَيْرِهَا وَشَرِّهَا، حُلْوِهَا وَمُرِّهَا". [ز: في إسناده ضعيف]. (جه)', 'അദിയ്യുബ്നു ഹാതിം(റ): ഞാൻ നബി(സ)യുടെ അടുത്ത് ചെന്നപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അദിയ്യുബ്നു ഹാതിമേ, നീ ഇസ്ലാം സ്വീകരിക്കുക, എങ്കിൽ നിനക്ക് രക്ഷപ്പെടാം." ഞാൻ ചോദിച്ചു: ഇസ്ലാം എന്നാൽ എന്താണ്? അപ്പോൾ റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹുവല്ലാതെ മറ്റൊരു ആരാധ്യനില്ലെന്നും ഞാൻ അല്ലാഹുവിന്റെ റസൂലാണെന്നും താങ്കൾ സാക്ഷ്യം വഹിക്കൽ, നന്മതിന്മകളും രസകരവും വിരസവുമായ കാര്യങ്ങളും അടങ്ങുന്ന സർവ്വ ഖദ്‌റുകളിലും (ദൈവനിശ്ചയങ്ങൾ) വിശ്വസിക്കൽ എന്നിവയാണത്." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'عَدِيٍّ بْنِ حَاتِمٍ', 'അദിയ്യുബ്നു ഹാതിം(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: جَاءَ رَجُلٌ مِنَ الْأَنْصَارِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ، فَقَالَ: يَا رَسُول اللَّه، إِنَّ لِي جَارِيَةً أَعْزِلُ عَنْهَا؟ قَالَ: "سَيَأْتِيهَا مَا قُدِّرَ لَهَا". فَأَتَاهُ بَعْدَ ذَلِكَ فَقَالَ: قَدْ حَمَلَتِ الْجَارِيَةُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَا قُدِّرَ لِنَفْسٍ شَيْءٌ إِلَّا هِيَ كَائِنَةٌ". (جه)', 'ജാബിർ(റ): അൻസാരിയായ ഒരാൾ നബി(സ)യുടെ അടുത്ത് ചെന്ന് പറഞ്ഞു: റസൂലേ, എനിക്ക് ഒരു അടിമസ്ത്രീയുണ്ട്. അവളോട് ബന്ധപ്പെടുമ്പോൾ ഇന്ദ്രിയം യോനിയിൽ പ്രവേശിക്കാതെ ഞാൻ സൂക്ഷിക്കുന്നു. റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നിശ്ചയിച്ച കാര്യം അവളുടെ വിഷയത്തിൽ സംഭവിക്കും." ശേഷം ആ വ്യക്തി റസൂൽ(സ)യുടെ അടുത്ത് വന്ന് പറഞ്ഞു: ആ അടിമസ്ത്രീ ഗർഭം ധരിച്ചിരിക്കുന്നു. നബി(സ) പറഞ്ഞു: "ഏതു വസ്തുവിനും നിശ്ചയിക്കപ്പെട്ട കാര്യം സംഭവിക്കുക തന്നെചെയ്യും." (ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 834, 834, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ ثَوْبَانَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "لَا يَزِيدُ فِي الْعُمْرِ إِلَّا الْبِرُّ، وَلَا يَرُدُّ الْقَدَرَ إِلَّا الدُّعَاءُ، وَإِنَّ الرَّجُلَ لَيُحْرَمُ الرِّزْقَ بِخَطِيئَةٍ يَعْمَلُهَا". (ت,جه)', 'സൗബാൻ(റ): റസൂൽ(സ) പറഞ്ഞു: "നന്മ മാത്രമേ ആയുസിനെ അതികരിപ്പിക്കൂ, പ്രാർത്ഥന മാത്രമേ ദൈവനിശ്ചയത്തെ തടയൂ, താൻ ചെയ്യുന്ന പാപം കാരണത്താൽ ഒരാൾക്ക് തന്റെ ഉപജീവനം തടയപ്പെട്ടേക്കാം." (തു,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 834, 835, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ سُرَاقَةَ بْنِ جُعْشُمٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قُلْتُ: يَا رَسُولَ اللَّه، الْعَمَلُ فِيمَا جَفَّ بِه الْقَلَمُ وَجَرَتْ بِه الْمَقَادِيرُ، أَمْ فِي أَمْرٍ مُسْتَقْبَلٍ؟ قَالَ: "بَلْ فِيمَا جَفَّ بِه الْقَلَمُ وَجَرَتْ بِه الْمَقَادِيرُ، وَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ". [ز: في إسناده مقال]. (جه)', 'സുറാഖതുബ്നു ജുഅ്ശും(റ): ഞാൻ ചോദിച്ചു: റസൂലേ, അല്ലാഹു നിശ്ചയിച്ച് കഴിയുകയും പേന (ഖലം) എഴുതിത്തീരുകയും ചെയ്ത കാര്യത്തിന്റെ അടിസ്ഥാനത്തിലാണോ അതോ വരാനിരിക്കുന്ന കാര്യത്തിന്റെ അടിസ്ഥാനത്തിലാണോ പ്രവർത്തനങ്ങൾ സംഭവിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "എന്നാൽ അല്ലാഹു നിശ്ചയിച്ച് വെക്കുകയും ഖലം എഴുതിക്കഴിയുകയും ചെയ്ത കാര്യത്തിന്റെ അടിസ്ഥാനത്തിൽ തന്നെ(യാണ് അവ സംഭവിക്കുന്നത്), തങ്ങളുടെ സൃഷ്ടിപ്പുകൊണ്ട് ഉദ്ദേശിക്കപ്പെട്ട കാര്യം എല്ലാവർക്കും എളുപ്പമാക്കപ്പെടുന്നതാണ്." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'سُرَاقَةَ بْنِ جُعْشُمٍ', 'സുറാഖതുബ്നു ജുഅ്ശും(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مقال', null, 835, 835, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ عَبْدِ اللَّهِ بْنِ فَيْرُوزٍ الدَّيْلَمِيِّ قَالَ: وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ هَذَا الْقَدَرِ، خَشِيتُ أَنْ يُفْسِدَ عَلَيَّ دِينِي وَأَمْرِي، فَأَتَيْتُ أُبَيَّ بْنَ كَعْبٍ رَضِيَ اللَّهُ عَنْهُ، فَقُلْتُ: أَبَا الْمُنْذِرِ، إِنَّهُ قَدْ وَقَعَ فِي نَفْسِي شَيْءٌ مِنْ هَذَا الْقَدَرِ، فَخَشِيتُ عَلَى دِينِي وَأَمْرِي، فَحَدِّثْنِي مِنْ ذَلِكَ بِشَيْءٍ، لَعَلَّ اللَّهَ أَنْ يَنْفَعَنِي بِهِ. فَقَالَ: لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَاوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ، وَلَوْ رَحِمَهُمْ لَكَانَتْ رَحْمَتُهُ خَيْرًا لَهُمْ مِنْ أَعْمَالِهِمْ. وَلَوْ كَانَ لَكَ مِثْلُ جَبَلِ أُحُدٍ ذَهَبًا – أَوْ مِثْلُ جَبَلِ أُحُدٍ – تُنْفِقُهُ فِي سَبِيلِ اللَّهِ، مَا قُبِلَ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ، فَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَأَنَّ مَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، وَأَنَّكَ إِنْ مُتَّ عَلَى غَيْرِ هَذَا دَخَلْتَ النَّارَ. وَلَا عَلَيْكَ أَنْ تَأْتِيَ أَخِي عَبْدَ اللَّهِ بْنَ مَسْعُودٍ – رَضِيَ اللَّهُ عَنْهُ – فَتَسْأَلَهُ. فَأَتَيْتُ عَبْدَ اللَّهِ فَسَأَلْتُهُ، فَذَكَرَ مِثْلَ مَا قَالَ أُبَيٌّ، وَقَالَ لِي: وَلَا عَلَيْكَ أَنْ تَأْتِيَ حُذَيْفَةَ، فَأَتَيْتُ حُذَيْفَةَ فَسَأَلْتُهُ، فَقَالَ مِثْلَ مَا قَالَا، وَقَالَ: ائْتِ زَيْدَ بْنَ ثَابِتٍ – رَضِيَ اللَّهُ عَنْهُ – فَاسْأَلْهُ. فَأَتَيْتُ زَيْدَ بْنَ ثَابِتٍ فَسَأَلْتُهُ، فَقَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "لَوْ أَنَّ اللَّهَ عَذَّبَ أَهْلَ سَمَاوَاتِهِ وَأَهْلَ أَرْضِهِ لَعَذَّبَهُمْ وَهُوَ غَيْرُ ظَالِمٍ لَهُمْ، وَلَوْ رَحِمَهُمْ لَكَانَتْ رَحْمَتُهُ خَيْرًا لَهُمْ مِنْ أَعْمَالِهِمْ. وَلَوْ كَانَ لَكَ مِثْلُ أُحُدٍ ذَهَبًا – أَوْ مِثْلُ جَبَلِ أُحُدٍ ذَهَبًا – تُنْفِقُهُ فِي سَبِيلِ اللَّهِ، مَا قَبِلَهُ مِنْكَ حَتَّى تُؤْمِنَ بِالْقَدَرِ كُلِّهِ، فَتَعْلَمَ أَنَّ مَا أَصَابَكَ لَمْ يَكُنْ لِيُخْطِئَكَ، وَمَا أَخْطَأَكَ لَمْ يَكُنْ لِيُصِيبَكَ، وَأَنَّكَ إِنْ مُتَّ عَلَى غَيْرِ هَذَا دَخَلْتَ النَّارَ". (د,جه)', 'അബ്ദുല്ലാഹിബ്നു ഫൈറൂസുദ്ദൈലമി(റ): ഖദ്‌റി(ദൈവനിശ്ചയം)നെ സംബന്ധിച്ചുള്ള ഒരു സംശയം എന്റെ ചിന്തയിലുദിച്ചു. അത് എന്റെ മതത്തെയും കാര്യങ്ങളെയുമെല്ലാം നാശത്തിലാക്കുമെന്ന് ഞാൻ ഭയന്നു. ഞാൻ ഉബയ്യുബ്നു കഅ്ബ്(റ)വിന്റെ അടുത്ത് ചെന്ന് പറഞ്ഞു: അബുൽമുൻദിറേ! ഖദ്‌റിനെ സംബന്ധിച്ചുള്ള ഒരു സംശയം എന്റെ മനസ്സിൽ ഉദിച്ചിരിക്കുന്നു. അതു കാരണത്താൽ എന്റെ മതത്തിലും മറ്റു കാര്യത്തിലുമെല്ലാം ഭയം അനുഭവപ്പെടുന്നു. അതിനാൽ അക്കാര്യത്തെക്കുറിച്ച് വല്ലതും പറഞ്ഞു തരിക. അല്ലാഹു അത് എനിക്ക് ഉപകാരമുള്ളതാക്കിയേക്കാം. ഉബയ്യുബ്നു കഅ്ബ്(റ) പറഞ്ഞു: ആകാശഭൂമികളിലുള്ളവരെ മുഴുവൻ അല്ലാഹു ശിക്ഷിക്കുകയാണെങ്കിൽ പോലും അവൻ ചെയ്യുന്നത് അവരോടുള്ള അക്രമമാവുകയില്ല. അവൻ അവർക്ക് അനുഗ്രഹം ചെയ്യുന്നുവെങ്കിൽ അവരുടെ കർമ്മങ്ങളേക്കാൾ ഉത്തമമായ അനുഗ്രഹമായിരിക്കും അത്. നിനക്ക് ഉഹ്ദ് പർവ്വതത്തിന്റെ അത്ര സ്വർണ്ണം ഉണ്ടാവുകയും അവയെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കുകയും ചെയ്യുന്നുവെങ്കിൽ പോലും ഖദ്‌റിനെ (ദൈവനിശ്ചയത്തെ) വിശ്വസിക്കുംവരെ നിന്നിൽനിന്ന് അവ സ്വീകരിക്കപ്പെടുകയില്ല. ഖദ്‌റിൽ വിശ്വസിച്ചാൽ, നിനക്ക് സംഭവിച്ചതെല്ലാം നിന്നിൽനിന്ന് മാറിപ്പോകാത്തതാണെന്നും, നിന്നിൽനിന്ന് അകന്നു പോയതെല്ലാം നിനക്ക് സംഭവിക്കാൻ പറ്റാത്തതാണെന്നും, ഈ വിശ്വാസത്തോടെ അല്ലാതെ മരിച്ചാൽ നീ നരകത്തിൽ പ്രവേശിക്കുമെന്നും നിനക്ക് മനസ്സിലാകും. ഇനി എന്റെ സുഹൃത്തായ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ അടുത്ത് ചെന്ന് ഇക്കാര്യം ചോദിക്കുക. അങ്ങനെ ഞാൻ അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)വിന്റെ അടുത്ത് ചെന്ന് അദ്ദേഹത്തോട് ചോദിച്ചു. ഉബയ്യ്(റ) പറഞ്ഞതുതന്നെ അദ്ദേഹവും പറഞ്ഞു. ശേഷം അദ്ദേഹം പറഞ്ഞു: ഇനി നീ ഹുദൈഫ(റ)വിന്റെ അടുത്ത് ചെല്ലുക. ഞാൻ ഹുദൈഫ(റ)വിന്റെ അടുത്ത് ചെന്ന് അക്കാര്യം ചോദിച്ചു. മുന്നെ രണ്ടുപേർ പറഞ്ഞതു തന്നെ അദ്ദേഹവും പറഞ്ഞു. ശേഷം പറഞ്ഞു: ഇനി നീ സൈദുബ്നു സാബിത്(റ)വിന്റെ അടുത്ത് ചെന്ന് ചോദിക്കുക. ഞാൻ സൈദുബ്നു സാബിത്(റ)വിന്റെ അടുത്ത് ചെന്ന് അക്കാര്യം ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "ആകാശ ഭൂമികളിലുള്ളവരെ മുഴുവൻ അല്ലാഹു ശിക്ഷിക്കുകയാണെങ്കിൽ പോലും അവൻ ചെയ്യുന്നത് അവരോടുള്ള അക്രമമാവുകയില്ല. അവൻ അവർക്ക് അനുഗ്രഹം ചെയ്യുന്നുവെങ്കിൽ അവരുടെ കർമ്മങ്ങളേക്കാൾ ഉത്തമമായ അനുഗ്രഹമായിരിക്കുമത്. നിനക്ക് ഉഹ്ദ് പർവ്വതത്തിന്റെ അത്ര സ്വർണ്ണമുണ്ടാവുകയും അവയെ അല്ലാഹുവിന്റെ മാർഗ്ഗത്തിൽ ചെലവഴിക്കുകയും ചെയ്യുന്നുവെങ്കിൽ പോലും ഖദ്‌റിൽ വിശ്വസിക്കുംവരെ നിന്നിൽനിന്ന് അവൻ അത് സ്വീകരിക്കുകയില്ല. ഖദ്‌റിൽ വിശ്വസിച്ചാൽ, നിനക്ക് സംഭവിച്ചതെല്ലാം നിന്നിൽനിന്ന് മാറിപ്പോകാത്തതാണെന്നും, നിന്നിൽനിന്ന് അകന്നു പോയതെല്ലാം നിനക്ക് സംഭവിക്കാൻ പറ്റാത്തതാണെന്നും, ഈ വിശ്വാസത്തോടെയല്ലാതെ മരിച്ചാൽ നീ നരകത്തിൽ പ്രവേശിക്കുമെന്നും നിനക്ക് മനസ്സിലാകും." (ദ,ജ)', 'عَبْدِ اللَّهِ بْنِ فَيْرُوزٍ الدَّيْلَمِيِّ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ഫൈറൂസുദ്ദൈലമി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 835, 836, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا فِي جَنَازَةٍ فِي بَقِيعِ الْغَرْقَدِ، فَأَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَعَدَ وَقَعَدْنَا حَوْلَهُ، وَمَعَهُ مِخْصَرَةٌ، فَنَكَّسَ، فَجَعَلَ يَنْكُتُ بِمِخْصَرَتِهِ، ثُمَّ قَالَ: "مَا مِنْكُمْ مِنْ أَحَدٍ، مَا مِنْ نَفْسٍ مَنْفُوسَةٍ إِلَّا وَقَدْ كَتَبَ اللَّهُ مَكَانَهَا مِنَ الْجَنَّةِ وَالنَّارِ، وَإِلَّا وَقَدْ كُتِبَتْ شَقِيَّةً أَوْ سَعِيدَةً". قَالَ: فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، أَفَلَا نَمْكُثُ عَلَى كِتَابِنَا وَنَدَعُ الْعَمَلَ؟ فَقَالَ: "مَنْ كَانَ مِنْ أَهْلِ السَّعَادَةِ فَسَيَصِيرُ إِلَى عَمَلِ أَهْلِ السَّعَادَةِ، وَمَنْ كَانَ مِنْ أَهْلِ الشَّقَاوَةِ فَسَيَصِيرُ إِلَى عَمَلِ أَهْلِ الشَّقَاوَةِ. فَقَالَ: اعْمَلُوا فَكُلٌّ مُيَسَّرٌ. أَمَّا أَهْلُ السَّعَادَةِ فَيُيَسَّرُونَ لِعَمَلِ أَهْلِ السَّعَادَةِ، وَأَمَّا أَهْلُ الشَّقَاوَةِ فَيُيَسَّرُونَ لِعَمَلِ أَهْلِ الشَّقَاوَةِ. ثُمَّ قَرَأَ: {فَأَمَّا مَنْ أَعْطَى وَاتَّقَى. وَصَدَّقَ بِالْحُسْنَى. فَسَنُيَسِّرُهُ لِلْيُسْرَى. وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى. وَكَذَّبَ بِالْحُسْنَى. فَسَنُيَسِّرُهُ لِلْعُسْرَى} [الليل: ٥ – ١٠]". (ق,د,ت,جه)', 'അലി(റ): ഞങ്ങൾ ബഖീഉൽ ഗർഖദിൽ ഒരു മയ്യിത്ത് സംസ്കരണത്തിൽ പങ്കെടുക്കുന്ന സമയത്ത് റസൂൽ(സ) വന്നു. റസൂൽ(സ) ഇരിക്കുകയും ഞങ്ങൾ അവിടുത്തെ ചുറ്റും ഇരിക്കുകയും ചെയ്തു. അവിടുത്തെ (കയ്യിൽ) ഒരു ഊന്നുവടിയുണ്ടായിരുന്നു. തല താഴ്ത്തിയിരുന്ന് ആ വടികൊണ്ട് ഭൂമിയിൽ ചില വരകൾ വരച്ചുകൊണ്ട് അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളിൽ ഓരോരുത്തരുടെയും, എന്നല്ല സൃഷ്ടിക്കപ്പെട്ട ഓരോ ആത്മാവിന്റെയും സ്വർഗ്ഗനരകങ്ങളിലുള്ള സ്ഥലങ്ങളെ അല്ലാഹു നിശ്ചയിച്ചു കഴിഞ്ഞിരിക്കുന്നു. അവ വിജയിക്കുന്നവയാണോ പരാജയപ്പെടുന്നവയാണോ എന്നും നിശ്ചയിക്കപ്പെട്ടിരിക്കുന്നു." നിവേദകൻ പറയുന്നു: അപ്പോൾ ഒരാൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങളെക്കുറിച്ചുള്ള ദൈവനിശ്ചയങ്ങളെ ആശ്രയിച്ച് കർമ്മങ്ങളെ ഞങ്ങൾ ഉപേക്ഷിക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "വിജയത്തിന്റെ ആളുകൾ അവരുടേതായ കർമ്മങ്ങളിലേക്ക് എത്തിച്ചേരും, പരാജയത്തിന്റെ ആളുകൾ അവരുടേതായ കർമ്മങ്ങളിലേക്കും എത്തിച്ചേരും." റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ കർമ്മം ചെയ്യുക, എല്ലാവർക്കും കാര്യങ്ങൾ എളുപ്പമാക്കപ്പെടും. വിജയത്തിന്റെ ആളുകൾക്ക് വിജയികളുടേതായ കർമ്മങ്ങൾ എളുപ്പമാക്കപ്പെടും. പരാജയത്തിന്റെ ആളുകൾക്ക് പരാജിതരുടേതായ കർമ്മങ്ങൾ എളുപ്പമാക്കപ്പെടും." ശേഷം റസൂൽ(സ) ഈ സൂക്തം ഓതി: ''ദാനം നൽകുകയും സൂക്ഷ്മത പുലർത്തുകയും നന്മയെ വാസ്തവമാക്കുകയും ചെയ്തവന് സൗഖ്യത്തെ നാം എളുപ്പമാക്കിക്കൊടുക്കും. പിശുക്ക് കാണിക്കുകയും സ്വയംപര്യാപ്തത നടിക്കുകയും നന്മയെ കളവാക്കുകയും ചെയ്തവന് വിഷമത്തെ നാം എളുപ്പമാക്കിക്കൊടുക്കും'' (അല്ലൈൽ: 5 - 10)." (ബു,മു,ദ,തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], 'الليل: ٥ – ١٠', null, 836, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ عُمَرُ رَضِيَ اللَّهُ عَنْهُ: يَا رَسُولَ اللَّه، أَرَأَيْتَ مَا نَعْمَلُ: فِيه أَمْرٌ مُبْتَدَعٌ، أَوْ مُبْتَدَأٌ، أَوْ فِيمَا قَدْ فُرِغَ مِنْهُ؟ فَقَالَ: "فِيمَا قَدْ فُرِغَ مِنْهُ، يَا ابْنَ الْخَطَّاب، وَكُلٌّ مُيَسَّرٌ: أَمَّا مَنْ كَانَ مِنْ أَهْلِ السَّعَادَة فَإِنَّهُ يَعْمَلُ لِلسَّعَادَة، وَأَمَّا مَنْ كَانَ مِنْ أَهْلِ الشَّقَاء فَإِنَّهُ يَعْمَلُ لِلشَّقَاء". (ت)', 'ഇബ്നുഉമർ(റ): ഉമർ(റ) പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ ചെയ്യുന്നവയിൽ പുതുതായി ഉൽഭവിക്കുന്ന (അല്ലാഹു മുമ്പ് നിശ്ചയിക്കാത്ത) കാര്യങ്ങളുണ്ടോ, അതോ അവ അല്ലാഹു നിശ്ചയിച്ചു കഴിഞ്ഞവയാണോ എന്ന് അങ്ങ് പറഞ്ഞുതരിക. റസൂൽ(സ) പറഞ്ഞു: "ഖത്താബിന്റെ പുത്രാ! അവ മുമ്പ് നിശ്ചയിച്ചു കഴിഞ്ഞവയിൽ പെട്ടതാണ്. എല്ലാവർക്കും കാര്യങ്ങൾ എളുപ്പമാക്കപ്പെടുന്നതാണ്. വിജയത്തിന്റെ ആളുകൾ വിജയത്തിനായുള്ള കർമ്മങ്ങൾ ചെയ്യും. പരാജയത്തിന്റെ ആളുകൾ പരാജയത്തിനായുള്ള കർമ്മങ്ങൾ ചെയ്യും." (തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ اللَّهَ خَلَقَ آدَمَ مِنْ قَبْضَةٍ قَبَضَهَا مِنْ جَمِيعِ الْأَرْضِ، فَجَاءَ بَنُو آدَمَ عَلَى قَدْرِ الْأَرْضِ: جَاءَ مِنْهُمُ الْأَحْمَرُ، وَالْأَبْيَضُ، وَالْأَسْوَدُ، وَبَيْنَ ذَلِكَ. وَالسَّهْلُ، وَالْحَزْنُ، وَالْخَبِيثُ، وَالطَّيِّبُ". (د,ت)', 'അബൂമൂസൽ അശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "ഭൂമിയിൽ നിന്ന് ഒട്ടാകെ എടുത്ത ഒരു പിടി മണ്ണിൽ നിന്നാണ് അല്ലാഹു ആദം(അ)മിനെ സൃഷ്ടിച്ചത്. അതിനാൽ ആദമിന്റെ സന്തതികൾ ഭൂമിക്കനുസൃതമായി (വ്യത്യസ്തരായി) വന്നു. അവരിൽ ചുവന്നവരും വെളുത്തവരും കറുത്തവരും അതിനിടയിലുള്ളവരും മൃദുല സ്വഭാവക്കാരും പരുക്കൻ സ്വഭാവക്കാരും നല്ലവരും ചീത്തവരുമെല്ലാം ഉണ്ടായി." (ദ,തു)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽ അശ്അരി(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنْ عَبْد الله بْنِ الشِّخِّيرِ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "مُثِّلَ ابْنُ آدَمَ، وَإِلَى جَنْبِه تسْعٌ وَتسْعُونَ مَنِيَّةً، إِنْ أَخْطَأَتْهُ الْمَنَايَا، وَقَعَ فِي الْهَرَمِ حَتَّى يَمُوتَ". حسن. (ت)', 'അബ്ദുല്ലാഹിബ്നുശ്ശിഖ്ഖീർ(റ): റസൂൽ(സ) പറഞ്ഞു: "മനുഷ്യൻ ഉപമിക്കപ്പെട്ടത് ഇപ്രകാരമാണ്: അവന്റെ ചുറ്റുഭാഗത്ത് തൊണ്ണൂറ്റൊമ്പത് വിപത്തുകൾ (മരണകാരണങ്ങൾ) ഉണ്ടാകും. ആ വിപത്തുകൾ അവനിൽ നിന്നൊഴിഞ്ഞാൽ അവൻ വാർധക്യത്തിൽ പ്രവേശിക്കുകയും അങ്ങനെ മരണമടയുകയും ചെയ്യും." ഹദീസ് ഹസനാണ്. (തു)', 'عَبْد الله بْنِ الشِّخِّيرِ', 'അബ്ദുല്ലാഹിബ്നുശ്ശിഖ്ഖീർ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مِنْ سَعَادَة ابْنِ آدَمَ رِضَاهُ بِمَا قَضَى اللَّهُ لَهُ، وَمِنْ شَقَاوَة ابْنِ آدَمَ تَرْكُهُ اسْتخَارَةَ اللَّه، وَمِنْ شَقَاوَة ابْنِ آدَمَ سَخَطُهُ بِمَا قَضَى اللَّهُ لَهُ". (ت)', 'സഅ്ദുബ്നു അബീവഖാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു തനിക്ക് നിശ്ചയിച്ച കാര്യത്തിൽ തൃപ്തിപ്പെടൽ ഒരു മനുഷ്യന്റെ വിജയലക്ഷണമാണ്. അല്ലാഹുവിനോട് നന്മയെ തേടലിനെ ഒഴിവാക്കുക എന്നത് ഒരു മനുഷ്യന്റെ പരാജയ ലക്ഷണമാണ്. അല്ലാഹു വിധിച്ച കാര്യത്തെ വെറുക്കുക എന്നതും ഒരു മനുഷ്യന്റെ പരാജയ ലക്ഷണമാണ്." (തു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദുബ്നു അബീവഖാസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 837, 837, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ: سُئِلَ عَنْ هَذِه الْآيَة: {وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ} [الأعراف: ١٧٢]. فَقَالَ عُمَرُ: سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ سُئِلَ عَنْهَا، فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ خَلَقَ آدَمَ، ثُمَّ مَسَحَ ظَهْرَهُ بِيَمِينِه، فَاسْتَخْرَجَ مِنْهُ ذُرِّيَّةً، فَقَالَ: خَلَقْتُ هَؤُلَاءِ لِلْجَنَّة وَبِعَمَلِ أَهْلِ الْجَنَّة يَعْمَلُونَ. ثُمَّ مَسَحَ ظَهْرَهُ فَاسْتَخْرَجَ مِنْهُ ذُرِّيَّةً، فَقَالَ: خَلَقْتُ هَؤُلَاءِ لِلنَّارِ وَبِعَمَلِ أَهْلِ النَّارِ يَعْمَلُونَ". فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّه، فَفِيمَ الْعَمَلُ؟ فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا خَلَقَ الْعَبْدَ لِلْجَنَّة اسْتَعْمَلَهُ بِعَمَلِ أَهْلِ الْجَنَّة، حَتَّى يَمُوتَ عَلَى عَمَلٍ مِنْ أَعْمَالِ أَهْلِ الْجَنَّة، فَيُدْخلَهُ بِه الْجَنَّةَ. وَإِذَا خَلَقَ الْعَبْدَ لِلنَّارِ اسْتَعْمَلَهُ بِعَمَلِ أَهْلِ النَّارِ، حَتَّى يَمُوتَ عَلَى عَمَلٍ مِنْ أَعْمَالِ أَهْلِ النَّارِ، فَيُدْخلَهُ بِه النَّارَ". (د,ت)', 'ഉമറുബ്നു ഖത്താബ്(റ): ''തങ്ങളുടെ മുതുകുകളിൽ വെച്ച് മനുഷ്യരോട് അങ്ങയുടെ നാഥൻ കരാർ ചെയ്തപ്പോൾ'' (അഅ്റാഫ്: 172) എന്ന സൂക്തത്തെക്കുറിച്ച് ചോദിക്കപ്പെട്ടപ്പോൾ ഉമർ(റ) പറഞ്ഞു: റസൂൽ(സ)യോട് ഇതേക്കുറിച്ച് ചോദിക്കപ്പെടുന്നത് ഞാൻ കേട്ടു. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "അല്ലാഹു ആദം(അ)മിനെ സൃഷ്ടിച്ചു. ശേഷം തന്റെ വലതുകൈകൊണ്ട് ആദം(അ)മിന്റെ മുതുകിൽ തടവുകയും അതിൽ നിന്ന് കുറേ സന്താനങ്ങളോട് പുറത്തുവരാൻ ആവശ്യപ്പെടുകയും ചെയ്തു. എന്നിട്ട് അല്ലാഹു പറഞ്ഞു: ഇവരെ ഞാൻ സ്വർഗ്ഗത്തിനു വേണ്ടിയാണ് സൃഷ്ടിച്ചിരിക്കുന്നത്. സ്വർഗ്ഗാവകാശികളുടെ കർമ്മം അവർ പ്രവർത്തിക്കുകയും ചെയ്യും. ശേഷം വീണ്ടും ആദം(അ)മിന്റെ മുതുക് തടവുകയും അതിൽ നിന്ന് കുറേ സന്താനങ്ങളോട് പുറത്തുവരാൻ ആവശ്യപ്പെടുകയും ചെയ്തു. എന്നിട്ട് അല്ലാഹു പറഞ്ഞു: ഇവരെ ഞാൻ നരകത്തിന് വേണ്ടിയാണ് സൃഷ്ടിച്ചിരിക്കുന്നത്. നരകാവകാശികളുടെ കർമ്മം അവർ പ്രവർത്തിക്കുകയും ചെയ്യും." അപ്പോൾ ഒരാൾ ചോദിച്ചു: റസൂലേ, എങ്കിൽ എന്ത് അനുസൃതമായാണ് കർമ്മങ്ങൾ സംഭവിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഒരു അടിമയെ സ്വർഗ്ഗത്തിനുവേണ്ടി സൃഷ്ടിച്ചാൽ സ്വർഗ്ഗാവകാശികളുടെ കർമ്മവുമായാണ് അവനെ നിയോഗിക്കുക. അങ്ങനെ സ്വർഗ്ഗാവകാശികളുടെ കർമ്മങ്ങളിൽ ഒരു കർമ്മം ചെയ്യുന്നവനായി അവൻ മരണപ്പെടുകയും അത് കാരണത്താൽ അല്ലാഹു അവനെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുകയും ചെയ്യും. അല്ലാഹു ഒരു അടിമയെ നരകത്തിന് വേണ്ടി സൃഷ്ടിക്കുന്നുവെങ്കിൽ നരകാവകാശികളുടെ കർമ്മവുമായാണ് അവനെ നിയോഗിക്കുക. അങ്ങനെ നരകാവകാശികളുടെ കർമ്മങ്ങളിൽ ഒരു കർമ്മം ചെയ്യുന്നവനായി അവൻ മരണപ്പെടുകയും അത് കാരണത്താൽ അല്ലാഹു അവനെ നരകത്തിൽ പ്രവേശിപ്പിക്കുകയും ചെയ്യും." (ദ,തു)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നു ഖത്താബ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], 'الأعراف: ١٧٢', null, 837, 838, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ أَبِي الْأَسْوَدِ الدِّيلِيِّ قَالَ: قَالَ لِي عِمْرَانُ بْنُ الْحُصَيْنِ رَضِيَ اللَّهُ عَنْهُمْ: أَرَأَيْتَ مَا يَعْمَلُ النَّاسُ الْيَوْمَ وَيَكْدَحُونَ فِيه، أَشَيْءٌ قُضِيَ عَلَيْهِمْ وَمَضَى عَلَيْهِمْ مِنْ قَدَرِ مَا سَبَقَ، أَوْ فِيمَا يُسْتَقْبَلُونَ بِه مِمَّا أَتَاهُمْ بِه نَبِيُّهُمْ وَثَبَتَت الْحُجَّةُ عَلَيْهِمْ؟ فَقُلْتُ: بَلْ شَيْءٌ قُضِيَ عَلَيْهِمْ وَمَضَى عَلَيْهِمْ، قَالَ: فَقَالَ: أَفَلَا يَكُونُ ظُلْمًا؟ قَالَ: فَفَزِعْتُ مِنْ ذَلِكَ فَزَعًا شَدِيدًا وَقُلْتُ: كُلٌّ شَيْءٍ خَلْقُ اللَّه وَملْكُ يَده، فَلَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ. فَقَالَ لِي: يَرْحَمُكَ اللَّهُ، إِنِّي لَمْ أُرِدْ بِمَا سَأَلْتُكَ إِلَّا لِأَحْزِرَ عَقْلَكَ، إِنَّ رَجُلَيْنِ مِنْ مُزَيْنَةَ أَتَيَا رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَقَالَا: يَا رَسُولَ اللَّه، أَرَأَيْتَ مَا يَعْمَلُ النَّاسُ الْيَوْمَ وَيَكْدَحُونَ فِيه، أَشَيْءٌ قُضِيَ عَلَيْهِمْ وَمَضَى فِيهِمْ مِنْ قَدَرٍ قَدْ سَبَقَ، أَوْ فِيمَا يُسْتَقْبَلُونَ بِه مِمَّا أَتَاهُمْ بِه نَبِيُّهُمْ وَثَبَتَت الْحُجَّةُ عَلَيْهِمْ؟ فَقَالَ: "لَا، بَلْ شَيْءٌ قُضِيَ عَلَيْهِمْ وَمَضَى فِيهِمْ، وَتَصْدِيقُ ذَلِكَ فِي كِتَابِ اللَّه عَزَّ وَجَلَّ: {وَنَفْسٍ وَمَا سَوَّاهَا. فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا} [الشَّمس: ٧, ٨]". (م)', 'അബുൽ അസ്വദുദ്ദിയലി(റ): ഇംറാനുബ്നു ഹുസൈൻ(റ) എന്നോട് ചോദിച്ചു: ജനങ്ങൾ ഇന്ന് പ്രവർത്തിക്കുകയും പരിശ്രമിക്കുകയും ചെയ്യുന്ന കാര്യം അവരുടെ മേൽ നിശ്ചയിക്കപ്പെടുകയും ആദ്യമേയുള്ള ദൈവനിശ്ചയത്തിൽ തീരുമാനിക്കപ്പെടുകയും ചെയ്തവയാണോ അതോ, തങ്ങളുടെ പ്രവാചകൻ കൊണ്ടുവരികയും അതുമുഖേന തങ്ങൾക്ക് ന്യായം നഷ്ടപ്പെടുകയും ചെയ്ത കാര്യങ്ങളാണോ അവർ അഭിമുഖീകരിക്കുന്നത്? ഞാൻ പറഞ്ഞു: അവർക്ക് നിശ്ചയിക്കപ്പെടുകയും തീരുമാനിക്കപ്പെടുകയും ചെയ്ത കാര്യങ്ങളാണ്. ഇംറാൻ(റ) ചോദിച്ചു: അത് അക്രമമാവുകയില്ലേ? അതുകേട്ട് എനിക്ക് ശക്തമായ ഭയം തോന്നി. ഞാൻ പറഞ്ഞു: എല്ലാം അല്ലാഹുവിന്റെ സൃഷ്ടികളും അവന്റെ ഉടമസ്ഥതയിലുള്ളവയുമാണ്. താൻ ചെയ്യുന്ന കാര്യങ്ങളെക്കുറിച്ച് അവനോട് ചോദ്യം ചെയ്യപ്പെടില്ല. സൃഷ്ടികളാണ് ചോദ്യം ചെയ്യപ്പെടുന്നവർ. അദ്ദേഹമെന്നോട് പറഞ്ഞു: അല്ലാഹു അങ്ങേക്ക് അനുഗ്രഹം ചെയ്യട്ടെ. താങ്കളുടെ ബുദ്ധി പരിശോധിക്കാൻ വേണ്ടി മാത്രമാണ് ഞാനീ ചോദ്യം ചോദിച്ചത്. മുസൈന ഗോത്രത്തിൽപ്പെട്ട രണ്ടാളുകൾ റസൂൽ(സ)യുടെ അടുത്തുവന്ന് ചോദിച്ചു: റസൂലേ, ജനങ്ങൾ ഇന്ന് പ്രവർത്തിക്കുകയും പരിശ്രമിക്കുകയും ചെയ്യുന്ന കാര്യം അവർക്ക് നിശ്ചയിക്കപ്പെടുകയും ആദ്യമേയുള്ള ദൈവനിശ്ചയത്തിൽ തീരുമാനിക്കപ്പെടുകയും ചെയ്തവയാണോ അതോ, തങ്ങളുടെ പ്രവാചകൻ കൊണ്ടുവരികയും അതുമുഖേന തങ്ങൾക്ക് ന്യായം നഷ്ടപ്പെടുകയും ചെയ്ത കാര്യങ്ങളാണോ അവർ അഭിമുഖീകരിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "അല്ല, അവർക്ക് നിശ്ചയിക്കപ്പെടുകയും തീരുമാനിക്കപ്പെടുകയും ചെയ്ത കാര്യങ്ങളാണ്. ഇക്കാര്യത്തെ അല്ലാഹുവിന്റെ ഗ്രന്ഥം തന്നെ സാക്ഷ്യപ്പെടുത്തുന്നു: ''ആത്മാവിനെ തന്നെ സത്യം, അവയെ രൂപപ്പെടുത്തുകയും ശേഷം അവയുടെ തിന്മയെയും ഭക്തിയെയും അവയ്ക്ക് തോന്നിപ്പിക്കുകയും ചെയ്യുന്നവൻ തന്നെ സത്യം'' (അശ്ശംസ്: 7,8)." (മു)', 'أَبِي الْأَسْوَدِ الدِّيلِيِّ قَالَ', 'അബുൽ അസ്വദുദ്ദിയലി(റ)', null, null, array['م']::text[], array['മു']::text[], 'الشَّمس: ٧, ٨', null, 838, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ عَبْد اللَّه بْنِ مَسْعُود رَضِيَ اللَّهُ عَنْهُ قَالَ: حَدَّثَنَا رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ، وَهُوَ الصَّادِقُ الْمَصْدُوقُ: "إِنَّ أَحَدَكُمْ يُجْمَعُ خَلْقُهُ فِي بَطْنِ أُمِّه فِي أَرْبَعِينَ يَوْمًا، ثُمَّ يَكُونُ عَلَقَةً مثْلَ ذَلِكَ، ثُمَّ يَكُونُ مُضْغَةً مثل ذَلِكَ، ثُمَّ يُرْسِلُ اللَّهُ إِلَيْه الْمَلَكَ فَيَنْفُخُ فِيه الرُّوحَ، وَيُؤْمَرُ بِأَرْبَعِ: يَكْتُبُ رِزْقَهُ، وَأَجَلَهُ، وَعَمَلَهُ، وَشَقِيٌّ أَوْ سَعِيدٌ. فَوَالَّذِي لَا إِلَهَ غَيْرُهُ: إِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ الْجَنَّة، حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ، ثُمَّ يَسْبِقُ عَلَيْه الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ النَّارِ، فَيَدْخُلُهَا. وَإِنَّ أَحَدَكُمْ لَيَعْمَلُ بِعَمَلِ أَهْلِ النَّارِ، حَتَّى مَا يَكُونُ بَيْنَهُ وَبَيْنَهَا إِلَّا ذِرَاعٌ، ثُمَّ يَسْبِقُ عَلَيْه الْكِتَابُ فَيُخْتَمُ لَهُ بِعَمَلِ أَهْلِ الْجَنَّة، فَيَدْخُلُهَا". (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): സത്യസന്ധനും വിശ്വസ്തനുമായ റസൂൽ(സ) ഞങ്ങളോട് പറഞ്ഞു; "നിങ്ങളിൽ ഓരോരുത്തരുടെയും സൃഷ്ടിപ്പിന്റെ തുടക്കത്തിൽ മാതാവിന്റെ വയറ്റിൽ നാൽപത് ദിവസം അവന്റെ സൃഷ്ടിവസ്തു ഒരുമിച്ചുകൂട്ടപ്പെടും. ശേഷം നാൽപത് ദിവസം അത് രക്തപിണ്ഡമായി കഴിയും. ശേഷം നാൽപത് ദിവസം മാംസക്കഷ്ണമായും കഴിയും. അതിനു ശേഷം അല്ലാഹു അതിലേക്ക് മലക്കിനെ പറഞ്ഞയക്കും. മലക്ക് അതിൽ ആത്മാവിനെ ഊതും. ആ വ്യക്തിയുടെ ജീവിതോപാധി, ആയുസ്സ്, പ്രവർത്തനം, അവൻ പരാജിതനാണോ വിജയിയാണോ എന്ന കാര്യം എന്നീ നാല് കാര്യങ്ങൾ (രേഖപ്പെടുത്താൻ) മലക്കിനോട് കൽപിക്കപ്പെടും. അല്ലാഹു തന്നെ സത്യം, അവനല്ലാതെ മറ്റൊരു ആരാധ്യനുമില്ല, നിങ്ങളിലൊരാൾ സ്വർഗ്ഗാവകാശികളുടെ കർമ്മം ചെയ്യുകയും അങ്ങനെ തനിക്കും സ്വർഗ്ഗത്തിനുമിടയിൽ ഒരു മുഴം മാത്രം അവശേഷിക്കുകയും ചെയ്യുമ്പോൾ അല്ലാഹുവിന്റെ നിശ്ചയത്തിലുള്ള കാര്യം അവന് മുന്നിൽ വരികയും അവന്റെ അവസാന കർമ്മത്തെ നരകക്കാരുടെ കർമ്മമാക്കി മാറ്റുകയും അവൻ നരകത്തിൽ പ്രവേശിക്കുകയും ചെയ്തേക്കാം. നിങ്ങളിലൊരാൾ നരകാവകാശികളുടെ കർമ്മം ചെയ്യുകയും അങ്ങനെ തനിക്കും നരകത്തിനുമിടയിൽ ഒരു മുഴം മാത്രം അവശേഷിക്കുകയും ചെയ്യുമ്പോൾ അല്ലാഹുവിന്റെ നിശ്ചയത്തിലുള്ള കാര്യം അവനു മുന്നിൽ വരികയും അവന്റെ അവസാന കർമ്മത്തെ സ്വർഗ്ഗക്കാരുടെ കർമ്മമാക്കി മാറ്റുകയും അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുകയും ചെയ്തേക്കാം." (ബു,മു,ദ,തു,ന,ജ)', 'عَبْد اللَّه بْنِ مَسْعُود', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 839, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَن رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "إِنَّ الرَّجُلَ لَيَعْمَلُ الزَّمَنَ الطَّوِيلَ بِعَمَلِ أَهْلِ الْجَنَّة، ثُمَّ يُخْتَمُ لَهُ عَمَلُهُ بِعَمَلِ أَهْلِ النَّارِ، وَإِنَّ الرَّجُلَ لَيَعْمَلُ الزَّمَنَ الطَّوِيلَ بِعَمَلِ أَهْلِ النَّارِ، ثُمَّ يُخْتَمُ لَهُ عَمَلُهُ بِعَمَلِ أَهْلِ الْجَنَّة". (م)', 'അബൂഹുറൈറ(റ): നിശ്ചയം റസൂൽ(സ) പറഞ്ഞു: "ഒരാൾ ദീർഘകാലം സ്വർഗ്ഗാവകാശികളുടെ കർമ്മം ചെയ്യുകയും ശേഷം നരകക്കാരുടെ കർമ്മവുമായി അവന്റെ കർമ്മങ്ങൾ അവസാനിപ്പിക്കപ്പെടുകയും ചെയ്തേക്കാം. നിശ്ചയം ഒരാൾ ദീർഘകാലം നരകാവകാശികളുടെ കർമ്മം ചെയ്യുകയും ശേഷം സ്വർഗ്ഗക്കാരുടെ കർമ്മവുമായി അവന്റെ കർമ്മങ്ങൾ അവസാനിപ്പിക്കപ്പെടുകയും ചെയ്തേക്കാം." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 839, 839, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ عَبْد الله بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَتْ أُمُّ حَبِيبَةَ رَضِيَ اللَّهُ عَنْهَا: اللَّهُمَّ مَتِّعْنِي بِزَوْجِي رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَبِأَبِي أَبِي سُفْيَانَ، وَبِأَخِي مُعَاوِيَةَ. فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّكِ سَأَلْتِ اللَّهَ عَزَّ وَجَلَّ لِآجَالٍ مَضْرُوبَةٍ، وَآثَارٍ مَوْطُوءَةٍ، وَأَرْزَاقٍ مَقْسُومَةٍ، لَا يُعَجِّلُ شَيْئًا مِنْهَا قَبْلَ حِلِّهِ، وَلَا يُؤَخِّرُ مِنْهَا شَيْئًا بَعْدَ حِلِّهِ، وَلَوْ سَأَلْتِ اللَّهَ أَنْ يُعَافِيَكِ مِنْ عَذَابٍ فِي النَّارِ وَعَذَابٍ فِي الْقَبْرِ، لَكَانَ خَيْرًا لَكِ". قَالَ: فَقَالَ رَجُلٌ: يَا رَسُولَ اللَّهِ، الْقِرَدَةُ وَالْخَنَازِيرُ هِيَ مِمَّا مُسِخَ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "إِنَّ اللَّهَ عَزَّ وَجَلَّ لَمْ يُهْلِكْ قَوْمًا – أَوْ يُعَذِّبْ قَوْمًا – فَيَجْعَلَ لَهُمْ نَسْلًا، وَإِنَّ الْقِرَدَةَ وَالْخَنَازِيرَ كَانُوا قَبْلَ ذَلِكَ". (م)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഉമ്മുഹബീബ(റ) ഇപ്രകാരം പ്രാർത്ഥിച്ചു: അല്ലാഹുവേ, എന്റെ ഭർത്താവായ റസൂൽ(സ), എന്റെ പിതാവായ അബൂസുഫ്യാൻ(റ), എന്റെ സഹോദരനായ മുആവിയ(റ) എന്നിവരോടൊപ്പം ദീർഘകാലം സൗഖ്യത്തിൽ കഴിയാൻ നീ എന്നെ അനുഗ്രഹിക്കണേ. അപ്പോൾ റസൂൽ(സ) മഹതിയോട് പറഞ്ഞു: "നീ അല്ലാഹുവിനോട് ചോദിച്ചത് നിശ്ചയിക്കപ്പെട്ടുകഴിഞ്ഞ ആയുസ്സുകളെയും നിർണയിക്കപ്പെട്ടു കഴിഞ്ഞ കണക്കുകളെയും വീതിക്കപ്പെട്ട ജീവിതോപാധികളെയുമാണ്. സമയമാകും മുമ്പ് അവയിൽ ഒന്നിനെയും അല്ലാഹു നൽകുകയില്ല. സമയമായതിന് ശേഷം അവയിൽ ഒന്നിനെയും അവൻ തടഞ്ഞുവെക്കുകയുമില്ല. നരകത്തിലെ ശിക്ഷയിൽ നിന്നും ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും അഭയം നൽകണമെന്നാണ് നീ അല്ലാഹുവിനോട് പ്രാർത്ഥിച്ചിരുന്നെങ്കിൽ അതായിരുന്നു നിനക്കുത്തമം." നിവേദകൻ പറയുന്നു: അപ്പോൾ ഒരാൾ ചോദിച്ചു: റസൂലേ, കുരങ്ങുകളും പന്നികളുമെല്ലാം രൂപം മറിക്കപ്പെട്ടവരിൽ പെട്ടതാണോ? റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു നശിപ്പിച്ച - അല്ലെങ്കിൽ ശിക്ഷിച്ച - സമൂഹത്തിനൊന്നും അവൻ സന്താനപരമ്പര നൽകിയിട്ടില്ല. കുരങ്ങുകളും പന്നികളുമെല്ലാം അതിനുമുമ്പ് തന്നെയുണ്ടായിരുന്നു." (മു)', 'عَبْد الله بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 839, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ حُذَيْفَةَ بْنِ أَسِيدٍ رَضِيَ اللَّهُ عَنْهُ – يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ – قَالَ: "يَدْخُلُ الْمَلَكُ عَلَى النُّطْفَةِ بَعْدَ مَا تَسْتَقِرُّ فِي الرَّحِمِ بِأَرْبَعِينَ أَوْ خَمْسَةٍ وَأَرْبَعِينَ لَيْلَةً، فَيَقُولُ: يَا رَبِّ، أَشَقِيٌّ أَوْ سَعِيدٌ؟ فَيُكْتَبَانِ، فَيَقُولُ: أَيْ رَبِّ، أَذَكَرٌ أَوْ أُنْثَى؟ فَيُكْتَبَانِ، وَيُكْتَبُ عَمَلُهُ، وَأَثَرُهُ، وَأَجَلُهُ، وَرِزْقُهُ، ثُمَّ تُطْوَى الصُّحُفُ، فَلَا يُزَادُ فِيهَا وَلَا يُنْقَصُ". (م)', 'നബി(സ) പറഞ്ഞതായി ഹുദൈഫതുബ്നു അസീദ്(റ): അവിടുന്ന് പറഞ്ഞു: "ഇന്ദ്രിയം ഗർഭാശയത്തിലുറച്ച് നാൽപതോ നാൽപത്തഞ്ചോ ദിവസത്തിന് ശേഷം മലക് അതിൽ പ്രവേശിക്കുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്യും. എന്റെ റബ്ബേ, ഇവൻ പരാജിതനാണോ വിജയിയാണോ? അങ്ങനെ അവ രണ്ടും രേഖപ്പെടുത്തപ്പെടും. മലക് ചോദിക്കും: എന്റെ റബ്ബേ, ഇത് പുരുഷനാണോ സ്ത്രീയാണോ? അങ്ങനെ അവയും രേഖപ്പെടുത്തപ്പെടും. ശേഷം അവന്റെ പ്രവർത്തനവും കണക്കും ആയുസ്സും ജീവിതോപാധിയുമെല്ലാം രേഖപ്പെടുത്തപ്പെടും. എന്നിട്ട് (രേഖപ്പെടുത്തപ്പെട്ട) ഏട് അടക്കപ്പെടും. ആ നിശ്ചയത്തിൽ പിന്നീട് ഏറ്റക്കുറച്ചിലുകൾ ഉണ്ടാവുകയില്ല." (മു)', 'حُذَيْفَةَ بْنِ أَسِيدٍ', 'നബി(സ) പറഞ്ഞതായി ഹുദൈഫതുബ്നു അസീദ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 840, 840, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ عَامِرِ بْنِ وَاثِلَةَ حَدَّثَهُ: أَنَّهُ سَمِعَ عَبْدَ اللَّه بْنَ مَسْعُود رَضِيَ اللَّهُ عَنْهُ يَقُولُ: الشَّقِيُّ مَنْ شَقِيَ فِي بَطْنِ أُمِّه، وَالسَّعِيدُ مَنْ وُعِظَ بِغَيْرِه. فَأَتَى رَجُلًا مِنْ أَصْحَابِ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يُقَالُ لَهُ حُذَيْفَةُ بْنُ أَسِيد الْغفَارِيُّ، فَحَدَّثَهُ بِذَلِكَ مِنْ قَوْلِ ابْنِ مَسْعُود، فَقَالَ: وَكَيْفَ يَشْقَى رَجُلٌ بِغَيْرِ عَمَلٍ؟ فَقَالَ لَهُ الرَّجُلُ: أَتَعْجَبُ مِنْ ذَلِكَ؟ فَإِنِّي سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "إِذَا مَرَّ بِالنُّطْفَة ثنْتَان وَأَرْبَعُونَ لَيْلَةً، بَعَثَ اللَّهُ إِلَيْهَا مَلَكًا، فَصَوَّرَهَا، وَخَلَقَ سَمْعَهَا وَبَصَرَهَا وَجلْدَهَا وَلَحْمَهَا وَعظَامَهَا، ثُمَّ قَالَ: يَا رَبِّ، أَذَكَرٌ أَمْ أُنْثَى؟ فَيَقْضِي رَبُّكَ مَا شَاءَ، وَيَكْتُبُ الْمَلَكُ. ثُمَّ يَقُولُ: يَا رَبِّ، أَجَلُهُ؟ فَيَقُولُ رَبُّكَ مَا شَاءَ، وَيَكْتُبُ الْمَلَكُ. ثُمَّ يَقُولُ: يَا رَبِّ؟ رِزْقُهُ؟ فَيَقْضِي رَبُّكَ مَا شَاءَ، وَيَكْتُبُ الْمَلَكُ. ثُمَّ يَخْرُجُ الْمَلَكُ بِالصَّحِيفَة فِي يَده، فَلَا يَزِيدُ عَلَى مَا أُمِرَ وَلَا يَنْقُصُ". وَزَادَ فِي رِوَايَة: "أَسَوِيٌّ أَوْ غَيْرُ سَوِيٌّ؟ فَيَجْعَلُهُ اللَّهُ سَوِيًّا أَوْ غَيْرَ سَوِيٌّ". (م)', 'ആമിറുബ്നു വാസില(റ): അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) ഇപ്രകാരം പറയുന്നത് അദ്ദേഹം കേട്ടു: പരാജിതൻ സ്വന്തം മാതാവിന്റെ വയറ്റിൽ വെച്ചുതന്നെ പരാജയപ്പെട്ടവനാണ്. മറ്റുള്ളവരാൽ ഉപദേശിക്കപ്പെടുന്നവനാണ് വിജയി. ഉടനെ ആമിർ(റ) റസൂൽ(സ)യുടെ അനുചരരിൽപ്പെട്ട ഹുദൈഫതുബ്നു അസീദുൽ ഗിഫാരി(റ) എന്ന് പേരുള്ള ആളുടെ അടുത്തുചെല്ലുകയും ഇബ്നുമസ്ഊദ്(റ)വിൽ നിന്ന് താൻ കേട്ട കാര്യത്തെക്കുറിച്ച് പറയുകയും ഇപ്രകാരം ചോദിക്കുകയും ചെയ്തു: ഒരു കർമ്മവും ചെയ്യാതെ എങ്ങനെയാണൊരാൾ പരാജിതനാവുക? അപ്പോൾ ആ വ്യക്തി പറഞ്ഞു: അതിൽ നിനക്ക് അത്ഭുതം തോന്നുന്നുവോ? റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഇന്ദ്രിയം പ്രവേശിച്ച് നാൽപത്തിരണ്ട് ദിവസം കഴിഞ്ഞാൽ അല്ലാഹു അതിലേക്ക് ഒരു മലക്കിനെ പറഞ്ഞയക്കും. മലക്ക് അതിനെ രൂപപ്പെടുത്തുകയും അതിന്റെ കേൾവിയെയും കാഴ്ചയെയും തൊലിയെയും മാംസത്തെയും എല്ലുകളെയും സൃഷ്ടിക്കുകയും ചെയ്യും. ശേഷം ചോദിക്കും: എന്റെ റബ്ബേ, ഇത് സ്ത്രീയാണോ പുരുഷനാണോ? അപ്പോൾ നിന്റെ നാഥൻ താനുദ്ദേശിച്ചത് വിധിക്കുകയും മലക്ക് അത് രേഖപ്പെടുത്തുകയും ചെയ്യും. ശേഷം ചോദിക്കും: എന്റെ റബ്ബേ, ഇവന്റെ ആയുസ്സോ? അപ്പോൾ നിന്റെ റബ്ബ് താനുദ്ദേശിച്ചത് പറയുകയും മലക്ക് അത് രേഖപ്പെടുത്തുകയും ചെയ്യും. ശേഷം മലക്ക് ചോദിക്കും: എന്റെ റബ്ബേ, അവന്റെ ജീവിതോപാധിയോ? അപ്പോൾ നിന്റെ റബ്ബ് താനുദ്ദേശിച്ചത് വിധിക്കുകയും മലക്ക് അത് രേഖപ്പെടുത്തുകയും ചെയ്യും. ശേഷം ആ ഏട് തന്റെ കയ്യിൽ പിടിച്ച് പുറത്തു പോകും. പിന്നീട് അതിൽ ഒരു ഏറ്റക്കുറച്ചിലും വരുത്തുകയില്ല." മറ്റൊരു നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്: "അവൻ അംഗവൈകല്യമില്ലാത്തവനാണോ അതോ അംഗവൈകല്യമുള്ളവനാണോ? അപ്പോൾ അല്ലാഹു അവനെ അംഗവൈകല്യമില്ലാത്തവനോ ഉള്ളവനോ ആക്കി മാറ്റും." (മു)', 'عَامِرِ بْنِ وَاثِلَةَ حَدَّثَهُ', 'ആമിറുബ്നു വാസില(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 840, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=207), 1, null, 'മറ്റൊരു നിവേദനത്തിൽ ഇതുകൂടിയുണ്ട്: "അവൻ അംഗവൈകല്യമില്ലാത്തവനാണോ അതോ അംഗവൈകല്യമുള്ളവനാണോ? അപ്പോൾ അല്ലാഹു അവനെ അംഗവൈകല്യമില്ലാത്തവനോ ഉള്ളവനോ ആക്കി മാറ്റും." (മു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "مَنْ تَكَلَّمَ فِي شَيْءٍ مِنَ الْقَدَرِ سُئِلَ عَنْهُ يَوْمَ الْقِيَامَة، وَمَنْ لَمْ يَتَكَلَّمْ فِيه لَمْ يُسْأَلْ عَنْهُ". [ز: في إسناده ضعيف]. (جه)', 'ആഇശ(റ): റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "ദൈവനിശ്ചയത്തിലെ വല്ല കാര്യത്തെക്കുറിച്ചും ഒരാൾ സംസാരിച്ചാൽ അന്ത്യനാളിൽ അതിനെക്കുറിച്ച് അവൻ ചോദിക്കപ്പെടും. അതിനെക്കുറിച്ച് സംസാരിക്കാത്തവനോട് അതേക്കുറിച്ച് ചോദിക്കപ്പെടുകയുമില്ല." ഇതിന്റെ പരമ്പരയിൽ ബലഹീനനുണ്ട്. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده ضعيف', null, 841, 841, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "احْتَجَّ آدَمُ وَمُوسَى عَلَيْهِمَا السَّلَامُ عِنْدَ رَبِّهِمَا، فَحَجَّ آدَمُ مُوسَى. قَالَ مُوسَى: أَنْتَ آدَمُ الَّذِي خَلَقَكَ اللَّهُ بِيَده، وَنَفَخَ فِيكَ مِنْ رُوحه، وَأَسْجَدَ لَكَ مَلَائِكَتَهُ، وَأَسْكَنَكَ فِي جَنَّته، ثُمَّ أَهْبَطْتَ النَّاسَ بِخَطِيئَتِكَ إِلَى الْأَرْضِ؟ فَقَالَ آدَمُ: أَنْتَ مُوسَى الَّذِي اصْطَفَاكَ اللَّهُ بِرِسَالَته وَبِكَلَامه، وَأَعْطَاكَ الْأَلْوَاحَ فِيهَا تِبْيَانُ كُلِّ شَيْءٍ، وَقَرَّبَكَ نَجِيًّا، فَبِكَمْ وَجَدْتَ اللَّهَ كَتَبَ التَّوْرَاةَ قَبْلَ أَنْ أُخْلَقَ؟ قَالَ مُوسَى: بِأَرْبَعِينَ عَامًا. قَالَ آدَمُ: فَهَلْ وَجَدْتَ فِيهَا {وَعَصَى آدَمُ رَبَّهُ فَغَوَى} [طه: ١٢١]. قَالَ: نَعَمْ. قَالَ: أَفَتَلُومُنِي عَلَى أَنْ عَمِلْتُ عَمَلًا كَتَبَهُ اللَّهُ عَلَيَّ أَنْ أَعْمَلَهُ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً". قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "فَحَجَّ آدَمُ مُوسَى". (م)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആദം(അ)മും മൂസാ(അ)മും തങ്ങളുടെ നാഥന്റെ സന്നിധിയിൽ വെച്ച് തർക്കിച്ചു. അങ്ങനെ ആദം(അ) മൂസാ(അ)നെ ഉത്തരം മുട്ടിച്ചു. മൂസാ(അ) ചോദിച്ചു: അല്ലാഹു സ്വന്തം കരങ്ങൾകൊണ്ട് സൃഷ്ടിച്ച ആദം(അ) അല്ലേ താങ്കൾ? അല്ലാഹു താങ്കളിൽ സ്വന്തം ആത്മാവിനെ ഊതുകയും താങ്കൾക്ക് തന്റെ മലക്കുകളെക്കൊണ്ട് സാഷ്ടാംഗം ചെയ്യിക്കുകയും താങ്കളെ തന്റെ സ്വർഗ്ഗത്തിൽ പാർപ്പിക്കുകയും ചെയ്തില്ലേ, എന്നിട്ടും താങ്കളുടെ പിഴവുകൊണ്ട് താങ്കൾ ജനങ്ങളെ ഭൂമിയിലേക്കിറക്കിയില്ലേ? ആദം(അ) പറഞ്ഞു: അല്ലാഹു തന്റെ പ്രവാചകത്വത്തിനും സംസാരത്തിനും വേണ്ടി പ്രത്യേകം തെരഞ്ഞെടുത്ത മൂസാ(അ) അല്ലേ താങ്കൾ. സർവ്വ വസ്തുക്കളെക്കുറിച്ചും വിശദീകരണമുള്ള എഴുത്തുപലകകളെ അവൻ താങ്കൾക്ക് നൽകുകയും താങ്കളെ തന്റെ വിശ്വസ്ത സ്നേഹിതനാക്കുകയും ചെയ്തില്ലേ? എന്നെ സൃഷ്ടിക്കുന്നതിന് എത്ര മുമ്പ് അല്ലാഹു തൗറാത്ത്.എഴുതി എന്നാണ് താങ്കൾക്ക് വിവരം ലഭിച്ചത്? മൂസാ(അ) പറഞ്ഞു: നാൽപത് വർഷം മുമ്പ്? ആദം(അ) ചോദിച്ചു: അതിൽ ''ആദം തന്റെ നാഥന് എതിർ ചെയ്യുകയും അങ്ങനെ വഴികേടിലാവുകയും ചെയ്തു'' എന്ന് താങ്കൾ കണ്ടിട്ടില്ലേയോ? മൂസാ(അ) പറഞ്ഞു: അതെ. ആദം(അ) പറഞ്ഞു: എന്നെ സൃഷ്ടിക്കുന്നതിന് നാൽപത് വർഷം മുമ്പുതന്നെ ഞാൻ ·പ്രവർത്തിക്കുമെന്ന് അല്ലാഹു നിശ്ചയിച്ചുവെച്ച കാര്യത്തിലാണോ താങ്കൾ എന്നെ ആക്ഷേപിക്കുന്നത്?" റസൂൽ(സ) പറഞ്ഞു: "അങ്ങനെ ആദം(അ) മൂസാ(അ)നെ ഉത്തരംമുട്ടിച്ചു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'طه: ١٢١', null, 841, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "احْتَجَّ آدَمُ وَمُوسَى عَلَيْهِمَا السَّلَامُ، فَقَالَ لَهُ مُوسَى: يَا آدَمُ، أَنْتَ أَبُونَا، خَيَّبْتَنَا وَأَخْرَجْتَنَا مِنَ الْجَنَّة بِذَنْبِكَ، فَقَالَ لَهُ آدَمُ: يَا مُوسَى، اصْطَفَاكَ اللَّهُ بِكَلَامِه، وَخَطَّ لَكَ التَّوْرَاةَ بِيَده، أَتَلُومُنِي عَلَى أَمْرٍ قَدَّرَهُ اللَّهُ عَلَيَّ قَبْلَ أَنْ يَخْلُقَنِي بِأَرْبَعِينَ سَنَةً؟ فَحَجَّ آدَمُ مُوسَى، فَحَجَّ آدَمُ مُوسَى، فَحَجَّ آدَمُ مُوسَى" ثَلَاثًا. (ق,د,ت,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആദം(അ)മും മൂസാ(അ)മും തർക്കിച്ചു. മൂസാ(അ) പറഞ്ഞു: ആദമേ, താങ്കൾ ഞങ്ങളുടെ പിതാവല്ലേ, താങ്കൾ തന്റെ പാപംകൊണ്ട് ഞങ്ങളെ പരാജയപ്പെടുത്തുകയും സ്വർഗ്ഗത്തിൽ നിന്ന് പുറത്താക്കുകയും ചെയ്തില്ലേ? ആദം(അ) മൂസാ(അ)മിനോട് പറഞ്ഞു: മൂസാ, അല്ലാഹു താങ്കളെ തന്നോട് സംസാരിക്കാൻ വേണ്ടി തെരഞ്ഞെടുക്കുകയും താങ്കൾക്കുവേണ്ടി സ്വന്തമായി തൗറാത്ത് എഴുതിത്തരികയും ചെയ്തില്ലേ! എന്നിട്ടും എന്നെ സൃഷ്ടിക്കുന്നതിന് നാൽപത് വർഷം മുമ്പ് അല്ലാഹു നിശ്ചയിച്ചുവെച്ച കാര്യത്തിന്റെ പേരിൽ താങ്കൾ എന്നെ ആക്ഷേപിക്കുന്നുവോ? അങ്ങനെ ആദം(അ) മൂസാ(അ)നെ ഉത്തരം മുട്ടിച്ചു. അങ്ങനെ ആദം(അ) മൂസാ(അ)നെ ഉത്തരംമുട്ടിച്ചു. അങ്ങനെ ആദം(അ) മൂസാ(അ)മിനെ ഉത്തരംമുട്ടിച്ചു." നബി(സ) അപ്രകാരം മൂന്ന് പ്രാവശ്യം പറഞ്ഞു. (ബു,മു,ദ,തു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], null, null, 842, 842, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ مُوسَى قَالَ: يَا رَبِّ، أَرِنَا آدَمَ الَّذِي أَخْرَجَنَا وَنَفْسَهُ مِنَ الْجَنَّة. فَأَرَاهُ اللَّهُ آدَمَ، فَقَالَ: أَنْتَ أَبُونَا آدَمُ؟ فَقَالَ لَهُ آدَمُ: نَعَمْ، قَالَ: أَنْتَ الَّذِي نَفَخَ اللَّهُ فِيكَ مِنْ رُوحه، وَعَلَّمَكَ الْأَسْمَاءَ كُلَّهَا، وَأَمَرَ الْمَلَائِكَةَ فَسَجَدُوا لَكَ؟ قَالَ: نَعَمْ، قَالَ: فَمَا حَمَلَكَ عَلَى أَنْ أَخْرَجْتَنَا وَنَفْسَكَ مِنَ الْجَنَّة؟ فَقَالَ لَهُ آدَمُ: وَمَنْ أَنْتَ؟ قَالَ: أَنَا مُوسَى، قَالَ: أَنْتَ نَبِيُّ بَنِي إِسْرَائِيلَ الَّذِي كَلَّمَكَ اللَّهُ مِنْ وَرَاءِ الْحِجَاب، لَمْ يَجْعَلْ بَيْنَكَ وَبَيْنَهُ رَسُولًا مِنْ خَلْقِه؟ قَالَ: نَعَمْ. قَالَ: أَفَمَا وَجَدْتَ أَنَّ ذَلِكَ كَانَ فِي كِتَابِ اللَّه قَبْلَ أَنْ أُخْلَقَ؟ قَالَ: نَعَمْ. قَالَ: فِيمَ تَلُومُنِي فِي شَيْءٍ سَبَقَ مِنَ اللَّه تَعَالَى فِيه الْقَضَاءُ قَبْلِي؟" قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ عِنْدَ ذَلِكَ: "فَحَجَّ آدَمُ مُوسَى، فَحَجَّ آدَمُ مُوسَى". (د)', 'ഉമറുബ്നുൽ ഖത്താബ്(റ): റസൂൽ(സ) പറഞ്ഞു: "തീർച്ചയായും മൂസാ(അ) പറഞ്ഞു: ഞങ്ങളെയും സ്വന്തത്തെയും സ്വർഗ്ഗത്തിൽ നിന്ന് പുറത്താക്കിയ ആദം(അ)നെ റബ്ബേ എനിക്ക് കാണിച്ചുതരിക. അല്ലാഹു മൂസാ(അ)ന് ആദം(അ)നെ കാണിച്ചുകൊടുത്തു. മൂസാ(അ) ചോദിച്ചു: ഞങ്ങളുടെ പിതാവ് ആദം(അ) അല്ലേ താങ്കൾ? ആദം(അ) പറഞ്ഞു: അതെ. മൂസാ(അ) ചോദിച്ചു: അല്ലാഹു തന്റെ ആത്മാവിനെ താങ്കളിൽ ഊതുകയും നാമങ്ങൾ മുഴുവൻ താങ്കൾക്ക് പഠിപ്പിച്ചുതരികയും ചെയ്തില്ലേ? അവൻ മലക്കുകളോട് താങ്കൾക്ക് സാഷ്ടാംഗം ചെയ്യാൻ കൽപിക്കുകയും അങ്ങനെ അവർ സാഷ്ടാംഗം ചെയ്യുകയും ചെയ്തില്ലേ? ആദം(അ) പറഞ്ഞു: അതെ. മൂസാ(അ) ചോദിച്ചു: എന്നിട്ടും സ്വന്തത്തെയും ഞങ്ങളെയും സ്വർഗ്ഗത്തിൽ നിന്ന് പുറത്തുകൊണ്ടുവരാൻ താങ്കളെ എന്താണ് പ്രേരിപ്പിച്ചത്? ആദം(അ) ചോദിച്ചു: താങ്കൾ ആരാണ്? മൂസാ(അ) പറഞ്ഞു: ഞാൻ മൂസാ(അ)മാണ്. ആദം(അ) ചോദിച്ചു: അല്ലാഹു തനിക്കും താങ്കൾക്കുമിടയിൽ തന്റെ സൃഷ്ടികളിൽപ്പെട്ട ഒരു ദൂതനെയും നിശ്ചയിക്കാതെ മറയ്ക്കപ്പുറത്ത് നിന്ന് നേരിട്ട് സംസാരിച്ച ഇസ്റാഈൗല്യരിലെ പ്രവാചകനല്ലേ താങ്കൾ? മൂസാ(അ) പറഞ്ഞു: അതെ. ആദം(അ) ചോദിച്ചു: അക്കാര്യം (താങ്കൾ ആദ്യം പറഞ്ഞത്) എന്നെ സൃഷ്ടിക്കുന്നതിന് മുമ്പുതന്നെ അല്ലാഹുവിന്റെ നിശ്ചയത്തിലുണ്ടായിരുന്നതാണെന്ന് താങ്കൾ മനസ്സിലാക്കിയിട്ടില്ലേ? മൂസാ(അ) പറഞ്ഞു: അതെ. ആദം(അ) ചോദിച്ചു: എനിക്ക് മുമ്പുതന്നെ അല്ലാഹു നിശ്ചയിച്ചുവെച്ച ഒരു കാര്യത്തിന്റെ പേരിൽ പിന്നെ എന്തിനാണ് താങ്കൾ എന്നെ ആക്ഷേപിക്കുന്നത്?" എന്നിട്ട് റസൂൽ(സ) പറഞ്ഞു: "അങ്ങനെ ആദം(അ) മൂസാ(അ)നെ ഉത്തരം മുട്ടിച്ചു, ആദം(അ) മൂസാ(അ)നെ ഉത്തരം മുട്ടിച്ചു." (ദ)', 'عُمَرَ بْنِ الْخَطَّابِ', 'ഉമറുബ്നുൽ ഖത്താബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 842, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ عَبْد اللَّه بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ وَفِي يَده كِتَابَان، فَقَالَ: "أَتَدْرُونَ مَا هَذَان الْكِتَابَان". فَقُلْنَا: لَا، يَا رَسُولَ اللَّه، إِلَّا أَنْ تُخْبِرَنَا. فَقَالَ لِلَّذِي فِي يَده الْيُمْنَى: "هَذَا كِتَابٌ مِنْ رَبِّ الْعَالَمِينَ، فِيه أَسْمَاءُ أَهْلِ الْجَنَّة وَأَسْمَاءُ آبَائِهِمْ وَقَبَائِلِهِمْ، ثُمَّ أُجْمِلَ عَلَى آخِرِهِمْ، فَلَا يُزَادُ فِيهِمْ وَلَا يُنْقَصُ مِنْهُمْ أَبَدًا". ثُمَّ قَالَ لِلَّذِي فِي شمَاله: "هَذَا كِتَابٌ مِنْ رَبِّ الْعَالَمِينَ، فِيه أَسْمَاءُ أَهْلِ النَّارِ وَأَسْمَاءُ آبَائِهِمْ وَقَبَائِلِهِمْ، ثُمَّ أُجْمِلَ عَلَى آخِرِهِمْ، فَلَا يُزَادُ فِيهِمْ وَلَا يُنْقَصُ مِنْهُمْ أَبَدًا". فَقَالَ أَصْحَابُهُ: فَفِيمَ الْعَمَلُ يَا رَسُولَ اللَّه، إِنْ كَانَ أَمْرٌ قَدْ فُرِغَ مِنْهُ؟ فَقَالَ: "سَدِّدُوا وَقَارِبُوا، فَإِنَّ صَاحِبَ الْجَنَّة يُخْتَمُ لَهُ بِعَمَلِ أَهْلِ الْجَنَّة، وَإِنْ عَملَ أَيَّ عَمَلٍ. وَإِنَّ صَاحِبَ النَّارِ يُخْتَمُ لَهُ بِعَمَلِ أَهْلِ النَّارِ، وَإِنْ عَملَ أَيَّ عَمَلٍ". ثُمَّ قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ بِيَدَيْه فَنَبَذَهُمَا، ثُمَّ قَالَ: "فَرَغَ رَبُّكُمْ مِنَ الْعبَاد: فَرِيقٌ فِي الْجَنَّة، وَفَرِيقٌ فِي السَّعِيرِ". (ت)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): തന്റെ കയ്യിൽ രണ്ട് ഗ്രന്ഥങ്ങളുമെടുത്ത് റസൂൽ(സ) ഞങ്ങളുടെ അടുത്തുവന്ന് ചോദിച്ചു: "ഈ രണ്ട് ഗ്രന്ഥങ്ങളുമേതെന്ന് നിങ്ങൾക്കറിയുമോ?" ഞങ്ങൾ പറഞ്ഞു: ഇല്ല, റസൂലേ. അവിടുന്ന് പറഞ്ഞുതന്നാലല്ലാതെ അറിയുകയില്ല. അപ്പോൾ റസൂൽ(സ) തന്റെ വലത്തേ കയ്യിലെ ഗ്രന്ഥത്തെക്കുറിച്ച് പറഞ്ഞു: "ഇത് ലോകരക്ഷിതാവായ അല്ലാഹുവിൽ നിന്നുള്ള ഗ്രന്ഥമാണ്. അതിൽ സ്വർഗ്ഗാവകാശികളുടെയും അവരുടെ പിതാക്കന്മാരുടെയും അവരുടെ ഗോത്രത്തിന്റെയും നാമങ്ങളുണ്ട്. അവരിലെ അവസാനത്തവന്റെ വിവരംപോലും അതിൽ രേഖപ്പെടുത്തപ്പെട്ടിട്ടുണ്ട്. ഇനി ഒരിക്കലും അവരുടെ എണ്ണത്തിൽ ഏറ്റക്കുറച്ചിലുകൾ നടത്തപ്പെടുകയില്ല." ശേഷം റസൂൽ(സ) തന്റെ ഇടത്തേ കയ്യിലുള്ള ഗ്രന്ഥത്തെക്കുറിച്ച് പറഞ്ഞു: "ഇത് ലോകരക്ഷിതാവിൽ നിന്നുള്ള ഗ്രന്ഥമാണ്. അതിൽ നരകാവകാശികളുടെയും അവരുടെ പിതാക്കന്മാരുടെയും ഗോത്രങ്ങളുടെയും നാമങ്ങളുണ്ട്. അവരിലെ അവസാനത്തവന്റെ വിവരംപോലും അതിൽ രേഖപ്പെടുത്തപ്പെട്ടിട്ടുണ്ട്. ഇനി ഒരിക്കലും അവരുടെ എണ്ണത്തിൽ ഏറ്റക്കുറച്ചിലുകൾ നടത്തപ്പെടുകയില്ല." സ്വഹാബികൾ ചോദിച്ചു: റസൂലേ, അത് മുമ്പുതന്നെ തീരുമാനിച്ച് കഴിഞ്ഞ കാര്യമാണെങ്കിൽ എന്ത് അടസ്ഥാനത്തിലാണ് കർമ്മങ്ങൾ ചെയ്യേണ്ടത്? റസൂൽ(സ) പറഞ്ഞു: "നിങ്ങൾ നന്മ ചെയ്യുകയും വിവേകപൂർവം നീങ്ങുകയും ചെയ്യുക. നിശ്ചയം സ്വർഗ്ഗാവകാശി എന്ത് കർമ്മം ചെയ്യുന്നെങ്കിലും സ്വർഗ്ഗാവകാശികളുടെ പ്രവർത്തനവുമായാണ് അവന്റെ കർമ്മങ്ങൾ അവസാനിപ്പിക്കപ്പെടുക. നരകാവകാശി എന്ത് കർമ്മം ചെയ്യുന്നെങ്കിലും നരകാവകാശികളുടെ പ്രവർത്തനവുമായാണ് അവന്റെ കർമ്മങ്ങൾ അവസാനിപ്പിക്കപ്പെടുക." ശേഷം റസൂൽ(സ) കൈകൊണ്ട് ആംഗ്യം കാണിക്കുകയും ആ ഗ്രന്ഥങ്ങൾ വലിച്ചെറിയുകയും ചെയ്തു. ശേഷം അവിടുന്ന് പറഞ്ഞു: "നിങ്ങളുടെ രക്ഷിതാവ് അടിമകളിൽ നിന്ന് (അവരുടെ കാര്യത്തിൽ നിന്ന്) വിരമിച്ചിരിക്കുന്നു. ഒരു കൂട്ടർ സ്വർഗ്ഗത്തിലും മറ്റൊരു കൂട്ടർ നരകത്തിലുമാണ്." (തു)', 'عَبْد اللَّه بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 843, 843, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِذَا أَرَادَ اللَّهُ بِعَبْدٍ خَيْرًا اسْتَعْمَلَهُ". فَقِيلَ: كَيْفَ يَسْتَعْملُهُ، يَا رَسُولَ اللَّه؟ قَالَ: "يُوَفِّقُهُ لِعَمَلٍ صَالِحٍ قَبْلَ الْمَوْتِ". (ت)', 'അനസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "അല്ലാഹു ഒരു അടിമയ്ക്ക് നന്മയുദ്ദേശിച്ചാൽ അവനെ ആ നന്മക്കായി ഉപയോഗിക്കും." റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, എപ്രകാരമാണ് അല്ലാഹു അവനെ ഉപയോഗിക്കുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "മരണത്തിന് മുമ്പ് സൽകർമ്മം ചെയ്യാനുള്ള അവസരം അല്ലാഹു അവന് നൽകും." (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 843, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا جُلُوسًا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ وَبِيَده عُودٌ، فَنَكَتَ فِي الْأَرْضِ، ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ: "مَا مِنْكُمْ مِنْ أَحَد إِلَّا وَقَدْ كُتِبَ مَقْعَدُهُ مِنَ الْجَنَّة وَمَقْعَدُهُ مِنَ النَّارِ". قِيلَ: يَا رَسُولَ اللَّه، أَفَلَا نَتَّكِلُ؟ قَالَ: "لَا، اعْمَلُوا وَلَا تَتَّكِلُوا، فَكُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ". ثُمَّ قَرَأَ: {فَأَمَّا مَنْ أَعْطَى وَاتَّقَى. وَصَدَّقَ بِالْحُسْنَى. فَسَنُيَسِّرُهُ لِلْيُسْرَى. وَأَمَّا مَنْ بَخِلَ وَاسْتَغْنَى. وَكَذَّبَ بِالْحُسْنَى. فَسَنُيَسِّرُهُ لِلْعُسْرَى} [اللَّيل: ٥ - ١٠]. (ق,د,ت,جه)', 'അലി(റ): ഞങ്ങൾ നബി(സ)യുടെ സമീപത്ത് ഇരിക്കുകയായിരുന്നു. അവിടുത്തെ കയ്യിൽ ഒരു വടിയുണ്ടായിരുന്നു. അവിടുന്ന് നിലത്ത് വടികൊണ്ട് കുത്തുകയും ശേഷം തലയുയർത്തി ഇപ്രകാരം പറയുകയും ചെയ്തു: "നിങ്ങളിൽ ഓരോരുത്തരുടെയും നരകത്തിലെയും സ്വർഗ്ഗത്തിലെയും ഇരിപ്പിടം നിശ്ചയിക്കപ്പെട്ടു കഴിഞ്ഞിരിക്കുന്നു." റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ റസൂലേ, ഞങ്ങൾ ആ നിശ്ചയത്തിൽ വിശ്വാസമർപ്പിച്ചു ജീവിക്കട്ടെയോ? റസൂൽ(സ) പറഞ്ഞു: "അരുത്, നിങ്ങൾ കർമ്മം ചെയ്യുക. ദൈവനിശ്ചയത്തിൽ മാത്രം വിശ്വാസമർപ്പിച്ച് ജീവിക്കരുത്. തന്നെ എന്തിനാണോ സൃഷ്ടിച്ചിരിക്കുന്നത്, അത് ഏതൊരുത്തന്നും എളുപ്പമാക്കപ്പെടുന്നതാണ്." ശേഷം റസൂൽ(സ) ഈ സൂക്തമോതി: ''ഏതൊരുത്തനാണോ ദാനം നൽകുകയും സൂക്ഷ്മത പാലിക്കുകയും ഏറ്റവും ഉത്തമമായതിനെ സത്യപ്പെടുത്തുകയും ചെയ്യുന്നത്, അവന് നാം ഏറ്റവും എളുപ്പമായതിലേക്ക് സൗകര്യപ്പെടുത്തിക്കൊടുക്കുന്നതാണ്. ഏതൊരുത്തനാണോ പിശുക്ക് കാണിക്കുകയും സ്വയംപര്യാപ്തത നടിക്കുകയും ഏറ്റവും ഉത്തമമായതിനെ നിഷേധിക്കുകയും ചെയ്യുന്നത്, അവന് നാം ഏറ്റവും പ്രയാസമുള്ളതിലേക്ക് സൗകര്യപ്പെടുത്തിക്കൊടുക്കുന്നതാണ്.'' (ബു,മു,ദ,തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت','جه']::text[], array['ബു','മു','ദ','തു','ജ']::text[], 'اللَّيل: ٥ - ١٠', null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قِيلَ لِرَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: يَا رَسُولَ اللَّه، أَعُلِمَ أَهْلُ الْجَنَّة مِنْ أَهْلِ النَّارِ؟ قَالَ: "نَعَمْ". قَالَ: فَفِيمَ يَعْمَلُ الْعَامِلُونَ؟ قَالَ: "كُلٌّ مُيَسَّرٌ لِمَا خُلِقَ لَهُ". (ق,د)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: റസൂലേ, നരകാവകാശികളിൽ നിന്ന് സ്വർഗ്ഗാവകാശികളെ വേർത്തിരിച്ച് നിശ്ചയിച്ചുകഴിഞ്ഞിട്ടുണ്ടോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ." ചോദ്യകർത്താവ് ചോദിച്ചു: പിന്നെ എന്തടിസ്ഥാനത്തിലാണ് ജനങ്ങൾ കർമ്മം ചെയ്യുന്നത്? റസൂൽ(സ) പറഞ്ഞു: "താൻ സൃഷ്ടിക്കപ്പെട്ട കാര്യം ഏതൊരുത്തന്നും സൗകര്യപ്പെടുത്തിക്കൊടുക്കപ്പെടുന്നതാണ്." (ബു,മു,ദ)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَقَدْ خَطَبَنَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ خُطْبَةً، مَا تَرَكَ فِيهَا شَيْئًا إِلَى قِيَامِ السَّاعَة إِلَّا ذَكَرَهُ، عَلمَهُ مَنْ عَلمَهُ، وَجَهلَهُ مَنْ جَهلَهُ، إِنْ كُنْتُ لَأَرَى الشَّيْءَ قَدْ نَسِيتُ، فَأَعْرِفُ مَا يَعْرِفُ الرَّجُلُ إِذَا غَابَ عَنْهُ، فَرَآهُ فَعَرَفَهُ. (خ)', 'ഹുദൈഫ(റ): റസൂൽ(സ) ഞങ്ങളോട് ഒരു പ്രസംഗം നടത്തി. അന്ത്യനാൾ വരെയുള്ള സർവ കാര്യങ്ങളെക്കുറിച്ചും അവിടുന്ന് ആ പ്രസംഗത്തിൽ പ്രതിപാദിച്ചു. മനസ്സിലാക്കേണ്ടവരെല്ലാം അക്കാര്യങ്ങൾ മനസ്സിലാക്കുകയും അല്ലാത്തവർ മനസ്സിലാക്കാതെ പോവുകയും ചെയ്തു. അപ്രത്യക്ഷനായിപ്പോയ വ്യക്തിയെ ഒരാൾ കാണുകയും തിരിച്ചറിയുകയും ചെയ്യുന്നതുപോലെ അവയിൽ നിന്ന് മറന്നുപോയിരുന്ന കാര്യങ്ങളെ ഞാൻ കാണുകയും തിരിച്ചറിയുകയും ചെയ്യുമായിരുന്നു. (ബു)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنْ مَطَرِ بْنِ عُكَامِسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِذَا قَضَى اللَّهُ لِعَبْدٍ أَنْ يَمُوتَ بِأَرْضٍ جَعَلَ لَهُ إِلَيْهَا حَاجَةً". حسن. (ت)', 'മത്വറുബ്നു ഉക്കാമിസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "വല്ല അടിമയുടെ കാര്യത്തിലും അവന് ഇന്ന സ്ഥലത്തുവെച്ച് മരിക്കണമെന്ന് അല്ലാഹു വിധിച്ചാൽ ആ സ്ഥലത്തെത്തിപ്പെടാൻ അല്ലാഹു അവന് വല്ല ആവശ്യവുമുണ്ടാക്കുന്നതാണ്." ഹദീസ് ഹസനാണ്. (തു)', 'مَطَرِ بْنِ عُكَامِسٍ', 'മത്വറുബ്നു ഉക്കാമിസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 844, 844, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَامَ فِينَا رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَقَالَ: "لَا يُعْدِي شَيْءٌ شَيْئًا". فَقَالَ أَعْرَابِيٌّ: يَا رَسُولَ اللَّه، الْبَعِيرُ الْجَرِبُ الْحَشَفَةُ بِذَنَبِه، فَتَجْرَبُ الْإِبِلُ كُلُّهَا؟ فَقَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "فَمَنْ أَجْرَبَ الْأَوَّلَ؟ لَا عَدْوَى وَلَا صَفَرَ، خَلَقَ اللَّهُ كُلَّ نَفْسٍ وَكَتَبَ حَيَاتَهَا وَرِزْقَهَا وَمَصَائِبَهَا". (ت,جه)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂൽ(സ) ഞങ്ങളുടെ മുന്നിൽ എഴുന്നേറ്റുകൊണ്ട് പറഞ്ഞു: "ഒരു വസ്തുവും മറ്റൊരു വസ്തുവിലേക്ക് രോഗം പടർത്തുകയില്ല." അപ്പോൾ ഒരു അഅ്റാബി ചോദിച്ചു: റസൂലേ, വാല് കാരണത്താൽ ലിംഗാഗ്രത്തിൽ ചൊറിപിടിച്ച ഒട്ടകം കാരണം മുഴുവൻ ഒട്ടകങ്ങൾക്കും ചൊറി പിടിക്കാറുണ്ടല്ലോ? റസൂൽ(സ) ചോദിച്ചു: "എങ്കിൽ ആദ്യത്തെ ഒട്ടകത്തിന് ചൊറിയുണ്ടാക്കിയതാരാണ്? പകർച്ചവ്യാധിയോ പകർച്ചക്ക് കാരണമാകുന്ന പ്രത്യേക രോഗമോ ഇല്ല. അല്ലാഹു സർവ്വ ആത്മാവുകളെയും സൃഷ്ടിക്കുകയും അവയുടെ ജീവിതത്തെയും ജീവിതോപാധികളെയും പ്രയാസങ്ങളെയും നിശ്ചയിച്ചു വെക്കുകയും ചെയ്തു." (തു,ജ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ أَبِي خُزَامَةَ بْنِ يَعْمُرِ السَّعْدِي رَضِيَ اللَّهُ عَنْهُ: أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّه، أَرَأَيْتَ رُقًى نَسْتَرْقِيهَا، وَدَوَاءً نَتَدَاوَى بِه، وَتُقَاةً نَتَّقِيهَا، هَلْ تَرُدُّ مِنْ قَدَرِ اللَّه شَيْئًا؟ فَقَالَ: "هِيَ مِنْ قَدَرِ اللَّه". (ت,جه)', 'അബൂഖുസാമതുബ്നു യഅ്മുറുസ്സഅ്ദീ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്ത് വന്ന് ചോദിച്ചു: റസൂലേ, ഞങ്ങൾ മന്ത്രിച്ചു കെട്ടുന്ന നൂലും ചികിത്സക്കായി ഉപയോഗിക്കുന്ന മരുന്നും ഞങ്ങൾ സ്വീകരിക്കുന്ന മറ്റു രക്ഷാമാർഗ്ഗങ്ങളുമെല്ലാം അല്ലാഹുവിന്റെ നിശ്ചയത്തിൽപെട്ട വല്ലതിനെയും തടയുമോ? റസൂൽ(സ) പറഞ്ഞു: "അവയും അല്ലാഹുവിന്റെ നിശ്ചയത്തിൽ പെട്ടവയാണ്." (തു,ജ)', 'أَبِي خُزَامَةَ بْنِ يَعْمُرِ السَّعْدِي', 'അബൂഖുസാമതുബ്നു യഅ്മുറുസ്സഅ്ദീ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ: أَنَّهُ كَانَ يَقُولُ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَا مِنْ مَوْلُود إِلَّا يُولَدُ عَلَى الْفطْرَة، فَأَبَوَاهُ يُهَوِّدَانه وَيُنَصِّرَانه وَيُمَجِّسَانه، كَمَا تُنْتَجُ الْبَهِيمَةُ بَهِيمَةً جَمْعَاءَ، هَلْ تُحِسُّونَ فِيهَا مِنْ جَدْعَاءَ". ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ: وَاقْرَءُوا إِنْ شِئْتُمْ: {فِطْرَةَ اللَّه الَّتِي فَطَرَ النَّاسَ عَلَيْهَا لَا تَبْدِيلَ لِخَلْقِ اللَّه} [الرّوم: ٣٥] الْآيَةَ. (م)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: റസൂൽ(സ) പറഞ്ഞു: "ഓരോ കുട്ടിയും ശുദ്ധപ്രകൃതവുമായാണ് ജനിക്കുന്നത്. തന്റെ മാതാപിതാക്കളാണ് അവനെ ജൂതനും ക്രസ്ത്യാനിയും മജൂസിയുമെല്ലാം ആക്കി മാറ്റുന്നത്. മൃഗങ്ങൾ പെറ്റുപെരുകുന്നതുപോലെ മൂക്കുമുറിഞ്ഞവയെ അവയിൽ നിങ്ങൾ കാണാറുണ്ടോ?" ശേഷം അബൂഹുറൈറ(റ) പറയുന്നു: നിങ്ങൾ (ഇക്കാര്യത്തിനു തെളിവായി) വേണമെങ്കിൽ ഈ സൂക്തം ഓതുക: ''അല്ലാഹു ജനങ്ങളെ ഏതൊരു പ്രകൃതിയിൽ സൃഷ്ടിച്ചിരിക്കുന്നുവോ ആ പ്രകൃതിയനുസരിച്ച് ജീവിക്കുക, അല്ലാഹുവിന്റെ സൃഷ്ടിവ്യവസ്ഥക്ക് യാതൊരു മാറ്റവുമില്ല.'' (റൂം: 35). (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], 'الرّوم: ٣٥', null, 845, 845, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "كُلُّ مَوْلُود يُولَدُ عَلَى الْمِلَّة، فَأَبَوَاهُ يُهَوِّدَانه أَوْ يُنَصِّرَانه أَوْ يُشَرِّكَانه". قِيلَ: يَا رَسُولَ اللَّه، فَمَنْ هَلَكَ قَبْلَ ذَلِكَ؟ قَالَ: "اللَّهُ أَعْلَمُ بِمَا كَانُوا عَاملِينَ بِه". (ق,د,ت)', 'അബൂഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഓരോ കുട്ടിയും (ശുദ്ധപ്രകൃതത്തിനനുസൃതമായ) യഥാർത്ഥ മതത്തിലാണ് ജനിച്ചു വീഴുന്നത്. തന്റെ മാതാപിതാക്കളാണ് അവനെ ജൂതനും ക്രസ്ത്യാനിയും ബഹുദൈവാരാധകനും ആക്കിമാറ്റുന്നത്." റസൂൽ(സ)യോട് ചോദിക്കപ്പെട്ടു: റസൂലേ, അതിനുമുമ്പ് (പ്രായപൂർത്തിയാകും മുമ്പ്) തന്നെ മരിച്ചുപോകുന്നവരോ? റസൂൽ(സ) പറഞ്ഞു: "അവർ പ്രവർത്തിക്കാൻ പോകുന്നത് എന്താണെന്ന് നന്നായി അറിയുന്നവനാണ് അല്ലാഹു." (ബു,മു,ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], null, null, 845, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دُعِيَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ إِلَى جَنَازَة صَبِيٍّ مِنَ الْأَنْصَارِ، فَقُلْتُ: يَا رَسُولَ اللَّه، طُوبَى لِهَذَا، عُصْفُورٌ مِنْ عَصَافِيرِ الْجَنَّة، لَمْ يَعْمَلِ السُّوءَ وَلَمْ يُدْرِكْهُ. قَالَ: "أَوَ غَيْرَ ذَلِكَ يَا عَائِشَةُ؟ إِنَّ اللَّهَ خَلَقَ لِلْجَنَّة أَهْلًا، خَلَقَهُمْ لَهَا وَهُمْ فِي أَصْلَابِ آبَائِهِمْ، وَخَلَقَ لِلنَّارِ أَهْلًا، خَلَقَهُمْ لَهَا وَهُمْ فِي أَصْلَابِ آبَائِهِمْ". (م,جه)', 'സത്യവിശ്വാസികളുടെ മാതാവായ ആഇശ(റ): അൻസ്വാരികളിലെ ഒരു കുട്ടിയുടെ മയ്യിത്ത് പരിപാലനത്തിലേക്ക് റസൂൽ(സ) ക്ഷണിക്കപ്പെട്ടു. ഞാൻ പറഞ്ഞു: റസൂലേ, ഈ കുട്ടിയുടെ സൗഭാഗ്യം, സ്വർഗ്ഗീയ കുരുവികളിലെ ഒരു കുരുവിയാണവൻ. അവൻ തിന്മ ചെയ്തിട്ടില്ല. അതിന് അവന് അവസരം ലഭിച്ചിട്ടുമില്ല. റസൂൽ(സ) പറഞ്ഞു: "ആഇശാ, അതല്ലാത്തതൊന്നും പറയാനില്ലേ? നിശ്ചയം അല്ലാഹു സ്വർഗ്ഗത്തിനായി ചിലയാളുകളെ സൃഷ്ടിച്ചിരിക്കുന്നു. തങ്ങളുടെ പിതാക്കളുടെ മുതുകിൽ ആയിരിക്കെത്തന്നെ അവരെ അതിനാണ് സൃഷ്ടിച്ചിരിക്കുന്നത്. നരകത്തിനായും അവൻ ചിലയാളുകളെ സൃഷ്ടിച്ചിരിക്കുന്നു. തങ്ങളുടെ പിതാക്കളുടെ മുതുകിലായിരിക്കെത്തന്നെ അവരെ അതിനാണ് സൃഷ്ടിച്ചിരിക്കുന്നത്." (മു,ജ)', 'عَائِشَةَ أُمِّ الْمُؤْمِنِينَ', 'സത്യവിശ്വാസികളുടെ മാതാവായ ആഇശ(റ)', null, null, array['م','جه']::text[], array['മു','ജ']::text[], null, null, 846, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنِ ابْنِ عَبَّاسٍ، عَنْ أُبَيِّ بْنِ كَعْبٍ - رَضِيَ اللَّهُ عَنْهُمْ - قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: "الْغُلَامُ الَّذِي قَتَلَهُ الْخَضِرُ طُبِعَ كَافِرًا، وَلَوْ عَاشَ لَأَرْهَقَ أَبَوَيْهِ طُغْيَانًا وَكُفْرًا". وَفِي رِوَايَةٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي قَوْلِهِ: {وَأَمَّا الْغُلَامُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ} [الكهف: ٨٠]: "وَكَانَ طُبِعَ يَوْمَ طُبِعَ كَافِرًا". وَفِي رِوَايَةٍ قَالَ: "أَبْصَرَ الْخَضِرُ غُلَامًا يَلْعَبُ مَعَ الصِّبْيَانِ، فَتَنَاوَلَ رَأْسَهُ فَقَلَعَهُ، فَقَالَ مُوسَى: {أَقَتَلْتَ نَفْسًا زَكِيَّةً} الْآيَةَ". (ق,د,ت)', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)വിൽനിന്ന് ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "ഖളിർ(അ) കൊന്ന കുട്ടി സത്യനിഷേധിയായി മുദ്രയടിക്കപ്പെട്ടവനായിരുന്നു. അവൻ ജീവിച്ചിരുന്നെങ്കിൽ തന്റെ മാതാപിതാക്കളെ അവൻ അതിക്രമത്തിലും അവിശ്വാസത്തിലും അകപ്പെടുത്തുമായിരുന്നു." മറ്റൊരു നിവേദനം: ''ആ കുട്ടിയുടെ കാര്യമെന്തെന്നാൽ, അവന്റെ മാതാപിതാക്കൾ സത്യവിശ്വാസികളായിരുന്നു'' (അൽകഹ്ഫ്: 80) എന്ന സൂക്തത്തെ സംബന്ധിച്ച് റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മുദ്രണം ചെയ്യപ്പെട്ട ദിവസംതന്നെ അവൻ സത്യനിഷേധിയായി മുദ്രണം ചെയ്യപ്പെട്ടവനായിരുന്നു." മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "കുട്ടികളോടൊന്നിച്ച് കളിച്ചുകൊണ്ടിരിക്കുന്ന ഒരു കുട്ടിയെ ഖളിർ(അ) കണ്ടു. അങ്ങനെ അദ്ദേഹം അവന്റെ തല പിടിച്ച് പറിച്ചെടുത്തു. അപ്പോൾ മൂസാ(അ) ചോദിച്ചു: ''പരിശുദ്ധമായ ഒരു ശരീരത്തെ താങ്കൾ വധിക്കുന്നുവോ'' (അൽകഹ്ഫ്)." (ബു,മു,ദ,തു)', 'ابْنِ عَبَّاسٍ، عَنْ أُبَيِّ بْنِ كَعْبٍ -', 'ഉബയ്യുബ്നു കഅ്ബ്(റ)', null, null, array['ق','د','ت']::text[], array['ബു','മു','ദ','തു']::text[], 'الكهف: ٨٠', null, 846, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=223), 1, 'وَفِي رِوَايَةٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي قَوْلِهِ: {وَأَمَّا الْغُلَامُ فَكَانَ أَبَوَاهُ مُؤْمِنَيْنِ} [الكهف: ٨٠]: "وَكَانَ طُبِعَ يَوْمَ طُبِعَ كَافِرًا".', 'മറ്റൊരു നിവേദനം: ''ആ കുട്ടിയുടെ കാര്യമെന്തെന്നാൽ, അവന്റെ മാതാപിതാക്കൾ സത്യവിശ്വാസികളായിരുന്നു'' (അൽകഹ്ഫ്: 80) എന്ന സൂക്തത്തെ സംബന്ധിച്ച് റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "മുദ്രണം ചെയ്യപ്പെട്ട ദിവസംതന്നെ അവൻ സത്യനിഷേധിയായി മുദ്രണം ചെയ്യപ്പെട്ടവനായിരുന്നു."');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=223), 2, 'وَفِي رِوَايَةٍ قَالَ: "أَبْصَرَ الْخَضِرُ غُلَامًا يَلْعَبُ مَعَ الصِّبْيَانِ، فَتَنَاوَلَ رَأْسَهُ فَقَلَعَهُ، فَقَالَ مُوسَى: {أَقَتَلْتَ نَفْسًا زَكِيَّةً} الْآيَةَ". (ق,د,ت)', 'മറ്റൊരു നിവേദനം: റസൂൽ(സ) പറഞ്ഞു: "കുട്ടികളോടൊന്നിച്ച് കളിച്ചുകൊണ്ടിരിക്കുന്ന ഒരു കുട്ടിയെ ഖളിർ(അ) കണ്ടു. അങ്ങനെ അദ്ദേഹം അവന്റെ തല പിടിച്ച് പറിച്ചെടുത്തു. അപ്പോൾ മൂസാ(അ) ചോദിച്ചു: ''പരിശുദ്ധമായ ഒരു ശരീരത്തെ താങ്കൾ വധിക്കുന്നുവോ'' (അൽകഹ്ഫ്)." (ബു,മു,ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: سُئِلَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ عَنْ أَطْفَالِ الْمُشْرِكِينَ؟ قَالَ: "اللَّهُ أَعْلَمُ بِمَا كَانُوا عَاملِينَ إِذْ خَلَقَهُمْ". (م)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ)യോട് ബഹുദൈവാരാധകരുടെ സന്താനങ്ങളെക്കുറിച്ച് ചോദിക്കപ്പെട്ടു. റസൂൽ(സ) പറഞ്ഞു: "അവർ എന്താണ് പ്രവർത്തിക്കുകയെന്ന് അവരെ സൃഷ്ടിച്ചപ്പോൾ തന്നെ അല്ലാഹുവിന് നന്നായി അറിയാമായിരുന്നു." (മു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 846, 846, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "كُتِبَ عَلَى ابْنِ آدَمَ نَصِيبُهُ مِنَ الزِّنَا، مُدْرِكٌ ذَلِكَ لَا مَحَالَةَ، فَالْعَيْنَان زِنَاهُمَا النَّظَرُ، وَالْأُذُنَان زِنَاهُمَا الْاسْتمَاعُ، وَاللِّسَانُ زِنَاهُ الْكَلَامُ، وَالْيَدُ زِنَاهَا الْبَطْشُ، وَالرِّجْلُ زِنَاهَا الْخُطَا، وَالْقَلْبُ يَهْوَى وَيَتَمَنَّى، وَيُصَدِّقُ ذَلِكَ الْفَرْجُ وَيُكَذِّبُهُ". (م)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "വ്യഭിചാരത്തിൽ നിന്നുള്ള തന്റെ വിഹിതം മനുഷ്യനുമേൽ നിശ്ചയിക്കപ്പെട്ടു കഴിഞ്ഞിരിക്കുന്നു. നിസ്സംശയം അവൻ അത് എത്തിക്കുക തന്നെചെയ്യും. രണ്ട് കണ്ണുകളുടെ വ്യഭിചാരം നോട്ടമാണ്. ചെവികളുടെ വ്യഭിചാരം കേൾവിയാണ്. നാവിന്റെ വ്യഭിചാരം സംസാരമാണ്. കയ്യിന്റെ വ്യഭിചാരം പിടുത്തമാണ്. കാലിന്റെ വ്യഭിചാരം നടത്തമാണ്. ഹൃദയം ആഗ്രഹിക്കുകയും കൊതിക്കുകയും ചെയ്യുന്നു. ഗുഹ്യഭാഗം അക്കാര്യത്തെ വാസ്തവമാക്കുകയോ കളവാക്കുകയോ (പ്രവർത്തിക്കുകയോ പ്രവർത്തിക്കാതിരിക്കുകയോ) ചെയ്യുന്നു." (മു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 846, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "لَا يَأْتِ ابْنَ آدَمَ النَّذْرُ بِشَيْءٍ لَمْ يَكُنْ قَدْ قَدَّرْتُهُ، وَلَكِنْ يُلْقِيه الْقَدَرُ وَقَدْ قَدَّرْتُهُ لَهُ، أَسْتَخْرِجُ بِه مِنَ الْبَخِيلِ". (خ)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഞാൻ നിശ്ചയിച്ചു വെച്ചതല്ലാതെ ഒരു നേട്ടവും നേർച്ച കാരണത്താൽ മനുഷ്യന് കൈവരികയില്ല. എന്റെ നിശ്ചയം തന്നെയാണ് (താൻ നിർവ്വഹിക്കുന്ന നേർച്ചയിലേക്ക് അവനെ നയിക്കുന്നത്). പിശുക്കന്റെ ധനം ചെലവ് ചെയ്യിക്കാൻ ഞാൻ സ്വീകരിക്കുന്ന മാർഗ്ഗമാണത്." (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنْ أَبِي سَعِيد الْخُدْرِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ قَالَ: "مَا اسْتُخْلِفَ خَلِيفَةٌ إِلَّا لَهُ بِطَانَتَان: بِطَانَةٌ تَأْمُرُهُ بِالْخَيْرِ وَتَحُضُّهُ عَلَيْه، وَبِطَانَةٌ تَأْمُرُهُ بِالشَّرِّ وَتَحُضُّهُ عَلَيْه، وَالْمَعْصُومُ مَنْ عَصَمَ اللَّهُ". (خ)', 'അബൂസഇൗദുൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "രണ്ട് ഉറ്റ മിത്രങ്ങളില്ലാതെ ഒരു പ്രതിനിധിയും നിയോഗിക്കപ്പെട്ടിട്ടില്ല. അതിൽ ഒരു മിത്രം അവനെ നന്മകൊണ്ട് കൽപിക്കുകയും അതിലേക്ക് പ്രേരണ നൽകുകയും ചെയ്യും. മറ്റൊരു മിത്രം അവനെ തിന്മകൊണ്ട് കൽപിക്കുകയും അതിലേക്ക് പ്രേരണ നൽകുകയും ചെയ്യും. പാപത്തിൽനിന്ന് സംരക്ഷണം നൽകപ്പെട്ടവൻ (മഅ്സൂം) എന്നാൽ അല്ലാഹു സംരക്ഷണം നൽകിയവനാണ്." (ബു)', 'أَبِي سَعِيد الْخُدْرِيِّ', 'അബൂസഇൗദുൽ ഖുദ്രി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ: "يَا مُقَلِّبَ الْقُلُوب، ثَبِّتْ قَلْبِي عَلَى دِينِكَ". فَقُلْتُ: يَا رَسُولَ اللَّه، آمَنَّا بِكَ وَبِمَا جِئْتَ بِه، فَهَلْ تَخَافُ عَلَيْنَا؟ قَالَ: "نَعَمْ، إِنَّ الْقُلُوبَ بَيْنَ أُصْبُعَيْنِ مِنْ أَصَابِعِ اللَّه، يُقَلِّبُهَا كَيْفَ يَشَاءُ". حسن. (ت)', 'അനസ്(റ): റസൂൽ(സ) ധാരാളമായി ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "ഹൃദയങ്ങളെ മാറ്റിമറിക്കുന്നവനേ, എന്റെ ഹൃദയത്തെ നിന്റെ ദീനിൽ നീ ഉറപ്പിച്ചു നിർത്തണേ." ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങയിലും അവിടുന്ന് കൊണ്ടുവന്ന കാര്യത്തിലും ഞങ്ങൾ വിശ്വസിച്ചിരിക്കുന്നു. അവിടുന്ന് ഞങ്ങളുടെ കാര്യത്തിൽ ഭയപ്പെടുന്നുവോ? റസൂൽ(സ) പറഞ്ഞു: "അതെ, നിശ്ചയമായും ഹൃദയങ്ങൾ കരുണാവാനായ അല്ലാഹുവിന്റെ വിരലുകളിൽ രണ്ടെണ്ണത്തിനിടയിലാണ്. താനുദ്ദേശിക്കും വിധം അവൻ അവയെ മാറ്റിമറിക്കുന്നു." ഹദീസ് ഹസനാണ്. (തു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 847, 847, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ عَبْد اللَّه بْنِ عَمْرِو بْنِ الْعَاصِ رَضِيَ اللَّهُ عَنْهُمَا: أَنَّهُ سَمِعَ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "إِنَّ قُلُوبَ بَنِي آدَمَ كُلَّهَا بَيْنَ إِصْبَعَيْنِ مِنْ أَصَابِعِ الرَّحْمَنِ كَقَلْبٍ وَاحِد، يُصَرِّفُهُ حَيْثُ يَشَاءُ". ثُمَّ قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "اللَّهُمَّ مُصَرِّفَ الْقُلُوب، صَرِّفْ قُلُوبَنَا عَلَى طَاعَتِكَ". (م)', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): റസൂൽ(സ) ഇപ്രകാരം പറയുന്നത് അദ്ദേഹം കേട്ടു: "മനുഷ്യരുടെ ഹൃദയങ്ങൾ മുഴുവൻ കരുണാവാനായ അല്ലാഹുവിന്റെ വിരലുകളിൽ രണ്ടെണ്ണത്തിന്റെ ഇടയിൽ, ഒരൊറ്റ ഹൃദയംപോലെ നിലകൊള്ളുന്നു. താൻ ഉദ്ദേശിക്കുംവിധം അവൻ അവയെ തിരിച്ചുകൊണ്ടിരിക്കുന്നു." ശേഷം റസൂൽ(സ) പറഞ്ഞു: "ഹൃദയങ്ങളെ തിരിക്കുന്ന അല്ലാഹുവേ, ഞങ്ങളുടെ ഹൃദയങ്ങളെ നിന്റെ അനുസരണയിലേക്ക് തിരിക്കണേ." (മു)', 'عَبْد اللَّه بْنِ عَمْرِو بْنِ الْعَاصِ', 'അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 847, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ عَبْدِاللَّه بْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَثِيرًا مِمَّا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَحْلِفُ: "لَا، وَمُقَلِّبِ الْقُلُوبِ". (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) ധാരാളമായി ഇപ്രകാരം സത്യംചെയ്യാറുണ്ടായിരുന്നു: "ഹൃദയങ്ങളെ മാറ്റിമറിക്കുന്നവനെതന്നെ സത്യം." (ബു)', 'عَبْدِاللَّه بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "مَثَلُ الْقَلْبِ مَثَلُ الرِّيشَة، تُقَلِّبُهَا الرِّيَاحُ بِفَلَاةٍ". (جه)', 'അബൂമൂസൽഅശ്അരി(റ): റസൂൽ(സ) പറഞ്ഞു: "മരുഭൂമിയിൽ വെച്ച് കാറ്റ് ഇളക്കിമറിച്ചുകൊണ്ടിരിക്കുന്ന ഒരു തൂവൽപോലെയാണ് ഹൃദയത്തിന്റെ ഉപമ." (ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമൂസൽഅശ്അരി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "سِتَّةٌ لَعَنْتُهُمْ، وَلَعَنَهُمُ اللَّهُ وَكُلُّ نَبِيٍّ كَانَ: الزَّائِدُ فِي كِتَابِ اللَّه، وَالْمُكَذِّبُ بِقَدْرِ اللَّه، وَالْمُتَسَلِّطُ بِالْجَبَرُوت: لِيُعِزَّ بِذَلِكَ مَنْ أَذَلَّ اللَّهُ وَيُذِلَّ مَنْ أَعَزَّ اللَّهُ، وَالْمُسْتَحِلُّ لِحُرُمِ اللَّه، وَالْمُسْتَحِلُّ مِنْ عِتْرَتِي مَا حَرَّمَ اللَّهُ، وَالتَّارِكُ لِسُنَّتِي". (ت)', 'ആഇശ(റ): റസൂൽ(സ) പറഞ്ഞു: "ആറ് വിഭാഗത്തെ ഞാൻ ശപിച്ചിരിക്കുന്നു, അല്ലാഹുവും കഴിഞ്ഞുപോയ പ്രവാചകന്മാരും അവരെ ശപിച്ചിരിക്കുന്നു: അല്ലാഹുവിന്റെ ഗ്രന്ഥത്തിൽ അതിലില്ലാത്തത് ചേർത്തുകൊടുക്കുന്നവൻ, അല്ലാഹുവിന്റെ ഖദ്റിനെ (നിശ്ചയത്തെ) കളവാക്കുന്നവൻ, അല്ലാഹു അഭിമാനം നൽകിയവരെ നിന്ദിക്കാനും അവൻ നിന്ദിച്ചവരെ അഭിമാനമുള്ളവരാക്കുവാനും വേണ്ടി അഹങ്കാരത്തോടെ അധികാരം കയ്യാളുന്നവൻ, അല്ലാഹു നിഷിദ്ധമാക്കിയവയെ അനുവദനീയമാക്കുന്നവൻ, എന്റെ കുടുംബത്തിൽനിന്ന് അല്ലാഹു നിഷിദ്ധമാക്കിയവയെ അനുവദനീയമാക്കുന്നവൻ, എന്റെ ചര്യയെ ഉപേക്ഷിക്കുന്നവൻ (എന്നിവരാണവർ)." (തു)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 848, 848, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ عَبْدِ الْوَاحِدِ بْنِ سُلَيْمٍ قَالَ: قَدِمْتُ مَكَّةَ، فَلَقِيتُ عَطَاءَ بْنَ أَبِي رَبَاحٍ، فَقُلْتُ لَهُ: يَا أَبَا مُحَمَّد، إِنَّ أَهْلَ الْبَصْرَة يَقُولُونَ فِي الْقَدَرِ؟ قَالَ: يَا بُنَيَّ أَتَقْرَأُ الْقُرْآنَ؟ قُلْتُ: نَعَمْ. قَالَ: فَاقْرَأِ الزُّخْرُفَ. قَالَ: فَقَرَأْتُ: {حم. وَالْكِتَابِ الْمُبِينِ. إِنَّا جَعَلْنَاهُ قُرْآنًا عَرَبِيًّا لَعَلَّكُمْ تَعْقِلُونَ. وَإِنَّهُ فِي أُمِّ الْكِتَابِ لَدَيْنَا لَعَلِيٌّ حَكِيمٌ} [الزّخرف: ١ - ٤]. فَقَالَ: أَتَدْرِي مَا أُمُّ الْكِتَابِ؟ قُلْتُ: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: فَإِنَّهُ كِتَابٌ كَتَبَهُ اللَّهُ قَبْلَ أَنْ يَخْلُقَ السَّمَاوَات وَقَبْلَ أَنْ يَخْلُقَ الْأَرْضَ، فِيه: إِنَّ فِرْعَوْنَ مِنْ أَهْلِ النَّارِ، وَفِيه: {تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ}. قَالَ عَطَاءٌ: فَلَقِيتُ الْوَلِيدَ بْنَ عُبَادَةَ بْنِ الصَّامِت - رَضِيَ اللَّهُ عَنْهُ - صَاحِبَ رَسُولِ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ، فَسَأَلْتُهُ: مَا كَانَ وَصِيَّةُ أَبِيكَ عِنْدَ الْمَوْتِ؟ قَالَ: دَعَانِي أَبِي فَقَالَ لِي: يَا بُنَيَّ، اتَّقِ اللَّهَ، وَاعْلَمْ أَنَّكَ لَنْ تَتَّقِيَ اللَّهَ حَتَّى تُؤْمِنَ بِاللَّه وَتُؤْمِنَ بِالْقَدَرِ كُلِّه خَيْرِه وَشَرِّه، فَإِنْ مُتَّ عَلَى غَيْرِ هَذَا دَخَلْتَ النَّارَ، إِنِّي سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "إِنَّ أَوَّلَ مَا خَلَقَ اللَّهُ الْقَلَمَ، فَقَالَ: اكْتُبْ. فَقَالَ: مَا أَكْتُبُ؟ قَالَ: اكْتُبِ الْقَدَرَ: مَا كَانَ وَمَا هُوَ كَائِنٌ إِلَى الْأَبَدِ". (ت)', 'അബ്ദുൽവാഹിദുബ്നു സുലൈം(റ): ഞാൻ മക്കയിൽ വന്നു. അപ്പോൾ അതാഉബ്നു അബീറബാഹ്(റ)വിനെ കണ്ടുമുട്ടി. ഞാനദ്ദേഹത്തോട് ചോദിച്ചു: അബൂമുഹമ്മദേ, തീർച്ചയായും ബസ്വറക്കാർ ഖദ്‌രി(ദൈവനിശ്ചയം)ന്റെ വിഷയത്തിൽ എന്തോ പറയുന്നുണ്ടല്ലോ? അദ്ദേഹം ചോദിച്ചു: കുഞ്ഞുമോനേ, നിനക്ക് ഖുർആൻ ഓതാനറിയില്ലേ? ഞാൻ പറഞ്ഞു: അതെ. അദ്ദേഹം പറഞ്ഞു: എങ്കിൽ നീ സുഖ്റുഫ് സൂറത്ത് ഓതുക. നിവേദകൻ പറയുന്നു: അപ്പോൾ ഞാൻ ഇപ്രകാരം ഓതി: ''ഹാമീം, വിശദമാക്കുന്ന വേദഗ്രന്ഥം തന്നെ സത്യം, തീർച്ചയായും നാം ഇതിനെ അറബി ഭാഷയിലുള്ള ഖുർആൻ ആക്കിയിരിക്കുന്നത് നിങ്ങൾ ചിന്തിക്കാൻ വേണ്ടിയാണ്. തീർച്ചയായും അത് ഉമ്മുൽകിതാബിൽ (മൂലഗ്രന്ഥത്തിൽ), നമ്മുടെ അടുക്കൽ ഉന്നതവും വിജ്ഞാനസമ്പന്നവും തന്നെയാകുന്നു.'' (സുഖ്റുഫ്: 1 - 4) അദ്ദേഹം ചോദിച്ചു: എന്താണ് ഉമ്മുൽകിതാബെന്ന് നിനക്ക് അറിയുമോ? ഞാൻ പറഞ്ഞു: അല്ലാഹുവും അവന്റെ റസൂലുമാണ് കൂടുതൽ അറിവുള്ളവർ. അദ്ദേഹം പറഞ്ഞു: അല്ലാഹു ഭൂമിയെ സൃഷ്ടിക്കുംമുമ്പ്, ആകാശങ്ങളെ സൃഷ്ടിക്കുംമുമ്പ് രേഖപ്പെടുത്തിവെച്ച ഗ്രന്ഥമാണത്. ''ഫിർഔൻ നരകാവകാശികളിൽ പെട്ടവനാണ്'' എന്ന് അതിലുണ്ട്. ''അബൂലഹബിന്റെ ഇരു കരങ്ങളും നശിക്കട്ടെ, അത് നശിക്കുകതന്നെ ചെയ്തിരിക്കുന്നു'' എന്നതും അതിലുണ്ട്. അതാഅ്(റ) പറയുന്നു: റസൂൽ(സ)യുടെ അനുചരനായിരുന്ന ഉബാദതുബ്നു സ്വാമിത്(റ)വിന്റെ മകൻ വലീദ്(റ)വിനെ ഞാൻ കണ്ടുമുട്ടി. ഞാൻ അദ്ദേഹത്തോട് ചോദിച്ചു: മരണ സമയത്ത് താങ്കളുടെ പിതാവിന്റെ വസ്വിയ്യത്ത് എന്തായിരുന്നു? അദ്ദേഹം പറഞ്ഞു: എന്റെ പിതാവ് എന്നെ വിളിച്ചുകൊണ്ട് പറഞ്ഞു: മോനേ, നീ അല്ലാഹുവിനെ സൂക്ഷിക്കുക. അറിയുക, അല്ലാഹുവിൽ വിശ്വസിക്കുംവരെയും, നന്മയും തിന്മയുമായ മുഴുവൻ ഖദ്റിലും (ദൈവനിശ്ചയത്തിൽ) വിശ്വസിക്കുംവരെയും നീ അല്ലാഹുവിന് തഖ്‌വ ചെയ്തവനാകില്ല. ഈ അവസ്ഥയിലല്ലാതെ മരിച്ചാൽ നീ നരകത്തിൽ പ്രവേശിക്കും. റസൂൽ(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു ആദ്യമായി സൃഷ്ടിച്ചത് ഖലമി(പേന)നെയാണ്. അവൻ അതിനോട് പറഞ്ഞു: നീ എഴുതുക. അത് ചോദിച്ചു: ഞാൻ എന്താണ് എഴുതേണ്ടത്? അല്ലാഹു പറഞ്ഞു: നീ ഇതുവരെ ഉണ്ടായതും എന്നന്നേക്കും ഉണ്ടാകാനുള്ളതുമായ ഖദ്ർ(ദൈവനിശ്ചയം) എഴുതുക." (തു)', 'عَبْدِ الْوَاحِدِ بْنِ سُلَيْمٍ قَالَ', 'അബ്ദുൽവാഹിദുബ്നു സുലൈം(റ)', null, null, array['ت']::text[], array['തു']::text[], 'الزّخرف: ١ - ٤', null, 848, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ حُذَيْفَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "لِكُلِّ أُمَّة مَجُوسٌ، وَمَجُوسُ هَذِه الْأُمَّة الَّذِينَ يَقُولُونَ لَا قَدَرَ، مَنْ مَاتَ مِنْهُمْ فَلَا تَشْهَدُوا جَنَازَتَهُ، وَمَنْ مَرِضَ مِنْهُمْ فَلَا تَعُودُوهُمْ، وَهُمْ شيعَةُ الدَّجَّال، وَحَقٌّ عَلَى اللَّه أَنْ يُلْحِقَهُمْ بِالدَّجَّالِ". (د)', 'ഹുദൈഫ(റ): റസൂൽ(സ) പറഞ്ഞു: "എല്ലാ സമുദായത്തിനും മജൂസികളുണ്ട്. ഈ സമുദായത്തിലെ മജൂസികൾ ഖദ്ർ (ദൈവനിശ്ചയം) ഇല്ലെന്ന് പറയുന്നവരാണ്. അവരിൽ ആരെങ്കിലും മരിച്ചാൽ അവരുടെ ജനാസ നിങ്ങൾ കാണരുത്. അവരിൽ ആരെങ്കിലും രോഗിയായാൽ നിങ്ങൾ അവരെ സന്ദർശിക്കരുത്. അവർ ദജ്ജാലിന്റെ വാഭാഗമാണ്. അവരെ ദജ്ജാലിനോട് ചേർക്കൽ അല്ലാഹുവിന്റെ കടമയാണ്." (ദ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 849, 849, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا: جَاءَهُ رَجُلٌ فَقَالَ: إِنَّ فُلَانًا يَقْرَأُ عَلَيْكَ السَّلَامَ. فَقَالَ لَهُ: إِنَّهُ بَلَغَنِي أَنَّهُ قَدْ أَحْدَثَ، فَإِنْ كَانَ قَدْ أَحْدَثَ فَلَا تُقْرِئْهُ مِنِّي السَّلَامَ، فَإِنِّي سَمِعْتُ رَسُولَ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ يَقُولُ: "يَكُونُ فِي هَذِه الْأُمَّة - أَوْ: فِي أُمَّتِي - خَسْفٌ أَوْ مَسْخٌ أَوْ قَذْفٌ، فِي أَهْلِ الْقَدَرِ". وَفِي رِوَايَة: "يَكُونُ فِي أُمَّتِي خَسْفٌ وَمَسْخٌ، وَذَلِكَ فِي الْمُكَذِّبِينَ بِالْقَدَرِ". (د,ت)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹത്തിന്റെ അടുക്കൽ ഒരാൾ വന്നുകൊണ്ട് പറഞ്ഞു: ഇന്ന വ്യക്തി അങ്ങയോട് സലാം പറഞ്ഞിട്ടുണ്ട്. ഇബ്നുഉമർ(റ) പറഞ്ഞു: അവൻ പുതുതായി എന്തോ (വിശ്വാസം) ഉണ്ടാക്കിയിട്ടുണ്ടെന്ന് ഞാൻ അറിഞ്ഞു. അങ്ങനെയാണെങ്കിൽ അവനോട് നീ എന്റെ സലാം പറയേണ്ടതില്ല. റസൂൽ( സ) പറയുന്നത് ഞാൻ കേട്ടു: "ഈ സമുദായത്തിൽ - അല്ലെങ്കിൽ: എന്റെ സമുദായത്തിൽ - ഖദ്‌രിയ്യാക്കളിൽ (ഖദ്ർ നിഷേധികൾ) ഭൂമി വിഴുങ്ങലും കോലം മറിക്കലും കല്ലേറും എല്ലാം ഉണ്ടാകും." മറ്റൊരു നിവേദനം: "എന്റെ സമുദായത്തിൽ ഭൂമി വിഴുങ്ങലും കോലം മറിക്കലുമെല്ലാം ഉണ്ടാകും. ഖദ്‌റിനെ കളവാക്കുന്നവരിലാകും അതെല്ലാം സംഭവിക്കുക." (ദ,തു)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 849, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=4 and b.book_no=13 and h.hadith_no=235), 1, 'وَفِي رِوَايَةٍ: "يَكُونُ فِي أُمَّتِي خَسْفٌ وَمَسْخٌ، وَذَلِكَ فِي الْمُكَذِّبِينَ بِالْقَدَرِ". (د,ت)', 'മറ്റൊരു നിവേദനം: "എന്റെ സമുദായത്തിൽ ഭൂമി വിഴുങ്ങലും കോലം മറിക്കലുമെല്ലാം ഉണ്ടാകും. ഖദ്‌റിനെ കളവാക്കുന്നവരിലാകും അതെല്ലാം സംഭവിക്കുക." (ദ,തു)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ جَابِرِ بْنِ عَبْد اللَّه رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "إِنَّ مَجُوسَ هَذِه الْأُمَّة الْمُكَذِّبُونَ بِأَقْدَارِ اللَّه، إِنْ مَرِضُوا فَلَا تَعُودُوهُمْ، وَإِنْ مَاتُوا فَلَا تَشْهَدُوهُمْ، وَإِنْ لَقِيتُمُوهُمْ فَلَا تُسَلِّمُوا عَلَيْهِمْ". (د,جه)', 'ജാബിറുബ്നു അബ്ദില്ല(റ): റസൂൽ(സ) പറഞ്ഞു: "ഈ സമുദായത്തിലെ മജൂസികളെന്നാൽ അല്ലാഹുവിന്റെ ഖദ്‌റുകളെ നിഷേധിക്കുന്നവരാണ്. അവർ രോഗികളായാൽ നിങ്ങൾ അവരെ സന്ദർശിക്കരുത്. അവർ മരിച്ചാൽ നിങ്ങൾ അവിടെ പോകരുത്. അവരെ കണ്ടുമുട്ടിയാൽ നിങ്ങൾ അവരോട് സലാം പറയരുത്." (ദ,ജ)', 'جَابِرِ بْنِ عَبْد اللَّه', 'ജാബിറുബ്നു അബ്ദില്ല(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّه صَلَّى اللَّهُ عَلَيْه وَسَلَّمَ: "صِنْفَانِ مِنْ أُمَّتِي لَيْسَ لَهُمَا فِي الْإِسْلَامِ نَصِيبٌ: الْمُرْجِئَةُ وَالْقَدَرِيَّةُ". (ت)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) പറഞ്ഞു: "എന്റെ സമുദായത്തിലെ രണ്ടു വിഭാഗങ്ങൾക്ക് ഇസ്ലാമിൽ ഒരു വിഹിതവുമില്ല: മുർജിഅ്⁶യും ഖദ്‌രിയ്യാക്കളും (ഖദ്‌റിനെ നിഷേധിക്കുന്ന വിഭാഗം) ആണവർ." (തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', '⁶. ഈമാനുണ്ടെങ്കിൽ പാപങ്ങൾ പ്രശ്നമല്ലെന്നും അവിശ്വാസത്തോടൊപ്പം ഒരു സൽകർമ്മത്തിനും ഫലമില്ലെന്നും വിശ്വസിക്കുന്ന വിഭാഗം.', null, array['ت']::text[], array['തു']::text[], null, null, 850, 850, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=4 and b.book_no=13 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
